INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很好，导游解说很精彩', 5, '2026-04-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_79082ce37b4f' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很好，导游解说很精彩' AND c.create_time = '2026-04-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '假期去的，人确实有点多', 5, '2026-04-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_de4f43357746' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '假期去的，人确实有点多' AND c.create_time = '2026-04-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '**呆过的，不错', 5, '2026-04-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f5c1baf45933' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '**呆过的，不错' AND c.create_time = '2026-04-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '邓老师讲解得很棒。千年学府，百年大学。对孩子来说是增强文化自豪感，又是很好的爱国主义教育。御书楼里4万多册图书的尽失，是遗憾，更是要要好好学习，努力前进的一股动力。', 5, '2026-04-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6e6f2d9138df' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '邓老师讲解得很棒。千年学府，百年大学。对孩子来说是增强文化自豪感，又是很好的爱国主义教育。御书楼里4万多册图书的尽失，是遗憾，更是要要好好学习，努力前进的一股动力。' AND c.create_time = '2026-04-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '值得一去，文化历史氛围浓厚', 5, '2026-04-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_987352a2c74a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '值得一去，文化历史氛围浓厚' AND c.create_time = '2026-04-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲的非常详细，很棒！', 5, '2026-04-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲的非常详细，很棒！' AND c.create_time = '2026-04-04 00:00:00');
