INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '胡老师是一个学识渊博，非常有风度的人。他的节奏把握非常好，讲解娓娓道来，信息量非常大，和岳麓千年书院的风格真的非常搭，就像老师带着研究生研学的感觉😁', 5, '2026-01-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_48328c9d9490' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '胡老师是一个学识渊博，非常有风度的人。他的节奏把握非常好，讲解娓娓道来，信息量非常大，和岳麓千年书院的风格真的非常搭，就像老师带着研究生研学的感觉😁' AND c.create_time = '2026-01-03 00:00:00');
