INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '张导的评价非常细致，每个景点都讲解的非常到位。对我年迈的母亲也很照顾。 并且提前给我打电话，延迟了一点碰面时间以避开一个大型旅游团，从而使我们有更好的参观体验。 非常好的一次讲解体验。', 5, '2025-12-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '张导的评价非常细致，每个景点都讲解的非常到位。对我年迈的母亲也很照顾。 并且提前给我打电话，延迟了一点碰面时间以避开一个大型旅游团，从而使我们有更好的参观体验。 非常好的一次讲解体验。' AND c.create_time = '2025-12-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '设计精美的建筑群,拥有中国建筑的创意和历史瑰宝,更具体地说,长沙的学术历史。 建议早点去,因为我去的时候早上11点就很拥挤了。 您可以在抵达时购买门票。', 5, '2025-12-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da2a84ee69d7' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '设计精美的建筑群,拥有中国建筑的创意和历史瑰宝,更具体地说,长沙的学术历史。 建议早点去,因为我去的时候早上11点就很拥挤了。 您可以在抵达时购买门票。' AND c.create_time = '2025-12-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '真是有底蕴，有历史，有文化的红色景点。重温朱熹、王阳明、毛泽东主席这些中国历史上重量级人物生活学习传道解惑的地方。来这里一定要找位讲解，不然就是白来。携程平台上的讲解感觉挺专业。喜欢这里的开放式的理念，更喜欢这里每一处的文化元素。我们当代中国学习应该继续传承古人留给我们的精华。湘地为什么出人才我也终于找到了根本原因。', 5, '2025-12-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c515d968ea65' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '真是有底蕴，有历史，有文化的红色景点。重温朱熹、王阳明、毛泽东主席这些中国历史上重量级人物生活学习传道解惑的地方。来这里一定要找位讲解，不然就是白来。携程平台上的讲解感觉挺专业。喜欢这里的开放式的理念，更喜欢这里每一处的文化元素。我们当代中国学习应该继续传承古人留给我们的精华。湘地为什么出人才我也终于找到了根本原因。' AND c.create_time = '2025-12-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中國四大古書院唯一還在辦學的書院，在湖南大學校區裡面，書院目前是歷史考古相關學系的上課所在，歷經數個朝代及戰爭洗禮仍然屹立不搖，在這個地方也孕育出許多文人學者及政治家，走在歷史名人曾走過的道上廊下，感受到濃濃的曾經的繁盛，很值得來。 導遊小哥服務周到講解到位，深度講解各種遺跡的故事，讓人聽得津津有味彷彿身歷其境，回味無窮，不虛此行。👍', 5, '2025-11-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7c7844c4ce37' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中國四大古書院唯一還在辦學的書院，在湖南大學校區裡面，書院目前是歷史考古相關學系的上課所在，歷經數個朝代及戰爭洗禮仍然屹立不搖，在這個地方也孕育出許多文人學者及政治家，走在歷史名人曾走過的道上廊下，感受到濃濃的曾經的繁盛，很值得來。 導遊小哥服務周到講解到位，深度講解各種遺跡的故事，讓人聽得津津有味彷彿身歷其境，回味無窮，不虛此行。👍' AND c.create_time = '2025-11-27 00:00:00');
