INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '十一过去的，人特别多，人山人海。讲解的小姐姐很出色，讲解的特别细致。孩子学习到了很多知识。院子里桂花很香。', 4, '2025-10-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_94482d494b4b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '十一过去的，人特别多，人山人海。讲解的小姐姐很出色，讲解的特别细致。孩子学习到了很多知识。院子里桂花很香。' AND c.create_time = '2025-10-06 00:00:00');
