INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '一早去的岳麓山，讲解老师提前一天就和我们联系了，约好了集合地点，讲解细致入微，不听讲解，等于白来，看人头了。一早人还是很多爱晚亭只远远看了看，爬山景色不错，麓山寺清幽，出来门口有几个摆摊的青年，20块套圈套得两个小瓷碗，挺好看的。爬山走走停停还好不累，看了蔡锷墓，黄兴墓，下山做缆车，中午刚好人不多，没用等，下到山下，看东门的人流庆幸早起。秋季的岳麓山上一路都是桂花香，清爽宜人。', 5, '2025-10-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_88009d113caa' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '一早去的岳麓山，讲解老师提前一天就和我们联系了，约好了集合地点，讲解细致入微，不听讲解，等于白来，看人头了。一早人还是很多爱晚亭只远远看了看，爬山景色不错，麓山寺清幽，出来门口有几个摆摊的青年，20块套圈套得两个小瓷碗，挺好看的。爬山走走停停还好不累，看了蔡锷墓，黄兴墓，下山做缆车，中午刚好人不多，没用等，下到山下，看东门的人流庆幸早起。秋季的岳麓山上一路都是桂花香，清爽宜人。' AND c.create_time = '2025-10-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲解一小时。无趣味，以牌匾说明为主。知识性较差。', 2, '2025-10-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲解一小时。无趣味，以牌匾说明为主。知识性较差。' AND c.create_time = '2025-10-06 00:00:00');
