INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院还是值得一去的，有古香古色。能够懂的湖南近代的教育体系的了解。时间充足的话可以每一间都要好好欣赏。', 5, '2025-08-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6daf5f2c6b36' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院还是值得一去的，有古香古色。能够懂的湖南近代的教育体系的了解。时间充足的话可以每一间都要好好欣赏。' AND c.create_time = '2025-08-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '带家里小孩子感受悻悻学子，导游邓邓小姐姐人很好哦。看到我带着两个孩子，一直都非常照顾我哦。辛苦啦', 5, '2025-08-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '带家里小孩子感受悻悻学子，导游邓邓小姐姐人很好哦。看到我带着两个孩子，一直都非常照顾我哦。辛苦啦' AND c.create_time = '2025-08-28 00:00:00');
