INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院：是中国古代四大书院之一，创建于北宋开宝九年(976年)，位于湖南省长沙市岳麓山脚下，现为湖南大学的历史与哲学学院。岳麓书院历经千年发展，北宋时期由潭州太守朱洞创建，南宋时期朱熹与张栻在此开展“朱张会讲”，成为理学重要传播地。清末改为湖南高等学堂，1926年正式定名湖南大学，沿用至今。', 5, '2025-08-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_59350ba07acf' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院：是中国古代四大书院之一，创建于北宋开宝九年(976年)，位于湖南省长沙市岳麓山脚下，现为湖南大学的历史与哲学学院。岳麓书院历经千年发展，北宋时期由潭州太守朱洞创建，南宋时期朱熹与张栻在此开展“朱张会讲”，成为理学重要传播地。清末改为湖南高等学堂，1926年正式定名湖南大学，沿用至今。' AND c.create_time = '2025-08-15 00:00:00');
