INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院面积很大，景区门口有讲解接待处，可以拼团听讲解，大约45分钟，讲的是中轴线和文庙。书院的西门靠近爱晚亭，东门就是湖南大学。 岳麓书院依山而建，是中国古代四大书院之一，距今一千年历史依然保存完好，也是漫漫中华文明长河教育的缩影。院内景观雅致，建筑也很宏伟。', 5, '2025-08-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_20ea74b08065' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院面积很大，景区门口有讲解接待处，可以拼团听讲解，大约45分钟，讲的是中轴线和文庙。书院的西门靠近爱晚亭，东门就是湖南大学。 岳麓书院依山而建，是中国古代四大书院之一，距今一千年历史依然保存完好，也是漫漫中华文明长河教育的缩影。院内景观雅致，建筑也很宏伟。' AND c.create_time = '2025-08-06 00:00:00');
