INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '给我们分一个超级大团里了，乌压压一群人【客观说的啊，我们走过去，别的游客都在说这个旅游团好多人呀】，也没带去爱晚亭，就在岳麓书院远远讲了一下', 1, '2025-08-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '给我们分一个超级大团里了，乌压压一群人【客观说的啊，我们走过去，别的游客都在说这个旅游团好多人呀】，也没带去爱晚亭，就在岳麓书院远远讲了一下' AND c.create_time = '2025-08-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '服务非常好，很周到', 5, '2025-08-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_69990d038b9b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '服务非常好，很周到' AND c.create_time = '2025-08-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '导游老师非常专业，很有耐心，讲解幽默风趣，大热天的辛苦了！', 5, '2025-08-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '导游老师非常专业，很有耐心，讲解幽默风趣，大热天的辛苦了！' AND c.create_time = '2025-08-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '我们是从岳麓山那里进去的，但是从那里还要再预约一次十分麻烦。整体感觉有点无聊。进去之后发现9月10日之前某些地方正在施工根本进不去，在外面也没有提醒。导致我们从头到尾只用了20几分钟就看完了景点（也可能是我们没有报导游团的原因）。在景区中本想报一个导游团结果根本没有，只能在外面报。到景区后发现某些导游根本不专业，口音很重，语速飞快，普通话不标准，叽里咕噜根本不知道说的什么（说的是一半普通话一半湖南话）但是景点的景色还是可以的，很有意义。但是景点出去后路非常绕，全是楼。我们打开地图才勉强找到路。总体评价还是很好的，建议9月10日之后去。', 4, '2025-07-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3d73a542687a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '我们是从岳麓山那里进去的，但是从那里还要再预约一次十分麻烦。整体感觉有点无聊。进去之后发现9月10日之前某些地方正在施工根本进不去，在外面也没有提醒。导致我们从头到尾只用了20几分钟就看完了景点（也可能是我们没有报导游团的原因）。在景区中本想报一个导游团结果根本没有，只能在外面报。到景区后发现某些导游根本不专业，口音很重，语速飞快，普通话不标准，叽里咕噜根本不知道说的什么（说的是一半普通话一半湖南话）但是景点的景色还是可以的，很有意义。但是景点出去后路非常绕，全是楼。我们打开地图才勉强找到路。总体评价还是很好的，建议9月10日之后去。' AND c.create_time = '2025-07-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '到了长沙，岳麓书院总也是要去一下的，中国四大书院之一。有了毛主席的加持，更加要去了，然后门票是40元，价格还可以。湖南大学有些课程还是在岳麓书院里面上的，最好请个导游能够了解一下整个岳麓书院的历史，不然的话走马观花其实也看不出个啥。', 5, '2025-07-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2e701faf4fcb' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '到了长沙，岳麓书院总也是要去一下的，中国四大书院之一。有了毛主席的加持，更加要去了，然后门票是40元，价格还可以。湖南大学有些课程还是在岳麓书院里面上的，最好请个导游能够了解一下整个岳麓书院的历史，不然的话走马观花其实也看不出个啥。' AND c.create_time = '2025-07-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲解生动有趣，节奏紧凑，适合孩子听', 5, '2025-07-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e786565aac0d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲解生动有趣，节奏紧凑，适合孩子听' AND c.create_time = '2025-07-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国四大书院之一，真的很羡慕湖南大学学子的学习环境。岳麓书院环境清幽，背靠岳麓山，清凉清静，远离闹市，适合静下心来学习。作为一处旅游景点，可玩性也很高。有种苏州园林的感觉，内部有孔子等，老子等塑像，值得一来', 5, '2025-07-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_bda256671d0e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国四大书院之一，真的很羡慕湖南大学学子的学习环境。岳麓书院环境清幽，背靠岳麓山，清凉清静，远离闹市，适合静下心来学习。作为一处旅游景点，可玩性也很高。有种苏州园林的感觉，内部有孔子等，老子等塑像，值得一来' AND c.create_time = '2025-07-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年书院值得前往参观。建议找个讲解可以更有趣味。从书院出来建议坐车到山顶，风景非常不错。还可以选择坐缆车下山。', 5, '2025-07-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7cf0f413871e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年书院值得前往参观。建议找个讲解可以更有趣味。从书院出来建议坐车到山顶，风景非常不错。还可以选择坐缆车下山。' AND c.create_time = '2025-07-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '体验很差，在路边拉散客，能凑多少凑多少，凑了快50人团。路边散客比在平台订还便宜。为什么要在平台订了。', 1, '2025-07-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_50b83bd58f5e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '体验很差，在路边拉散客，能凑多少凑多少，凑了快50人团。路边散客比在平台订还便宜。为什么要在平台订了。' AND c.create_time = '2025-07-26 00:00:00');
