INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '导游专业，讲解详尽', 5, '2025-07-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '导游专业，讲解详尽' AND c.create_time = '2025-07-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院作为中国四大书院之一，历史超千年，建筑古色古香，与自然山水完美融合，红墙黑瓦、参天古木，一步一景，景色绝美。书院文化底蕴深厚，丰富的展览、生动的讲解，还有“朱张会讲”等历史典故，能让你沉浸式感受湖湘文化魅力。门票价格合理，学生还能享受优惠，性价比不错。', 5, '2025-07-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c208df70f826' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院作为中国四大书院之一，历史超千年，建筑古色古香，与自然山水完美融合，红墙黑瓦、参天古木，一步一景，景色绝美。书院文化底蕴深厚，丰富的展览、生动的讲解，还有“朱张会讲”等历史典故，能让你沉浸式感受湖湘文化魅力。门票价格合理，学生还能享受优惠，性价比不错。' AND c.create_time = '2025-07-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '不错 负责专业', 5, '2025-07-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4a2e21407758' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '不错 负责专业' AND c.create_time = '2025-07-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年学府，传承至今，再次游览，仍能够感受到古人治学之严谨，钻研学问之刻苦，对比当下，还有什么理由不珍惜如此美好之环境，学无止境，孜孜不倦，勤学善思，受益匪浅', 5, '2025-07-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_51ffef1d9ad1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年学府，传承至今，再次游览，仍能够感受到古人治学之严谨，钻研学问之刻苦，对比当下，还有什么理由不珍惜如此美好之环境，学无止境，孜孜不倦，勤学善思，受益匪浅' AND c.create_time = '2025-07-21 00:00:00');
