INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院环境优美，非常不错，还在附近打卡了爱晚亭和湖南大学', 5, '2025-07-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a4ebd397c949' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院环境优美，非常不错，还在附近打卡了爱晚亭和湖南大学' AND c.create_time = '2025-07-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '虽然知道是拼团，但是完全没想到居然被拼了个40人以上的超大团，直接被干崩溃了。乌泱泱一群人走到哪儿堵到哪儿，甚至已经都开始讲解了，还在拉路边的游客不停入团，图片中只是一部分人，还有不少人没能挤进去。已经看不到导游的人了，只有个旗子在飘扬。这种情况下讲得再好，也没有心思再去听了，大坑，慎选。', 1, '2025-07-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '虽然知道是拼团，但是完全没想到居然被拼了个40人以上的超大团，直接被干崩溃了。乌泱泱一群人走到哪儿堵到哪儿，甚至已经都开始讲解了，还在拉路边的游客不停入团，图片中只是一部分人，还有不少人没能挤进去。已经看不到导游的人了，只有个旗子在飘扬。这种情况下讲得再好，也没有心思再去听了，大坑，慎选。' AND c.create_time = '2025-07-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很少给一个景区打差评，这个绝对是让人无语的。景区主打一个，开车的滚蛋，需要帮助的滚蛋。攻略做了也是白做，让你绕啊绕啊，还没问个路，保安主打一个赶紧滚。 银龄经济，在他们眼里算个屁！！！', 1, '2025-07-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ef79f89b03ce' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很少给一个景区打差评，这个绝对是让人无语的。景区主打一个，开车的滚蛋，需要帮助的滚蛋。攻略做了也是白做，让你绕啊绕啊，还没问个路，保安主打一个赶紧滚。 银龄经济，在他们眼里算个屁！！！' AND c.create_time = '2025-07-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲解深入浅出，带娃参观学习，报上讲解团，印象深刻，领悟更深。', 5, '2025-07-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲解深入浅出，带娃参观学习，报上讲解团，印象深刻，领悟更深。' AND c.create_time = '2025-07-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '包团的导游讲解小姐姐服务非常好，很负责任，因为天气炎热，小朋友有些闹腾，讲解员都很耐心，还帮忙一起安抚小朋友，很有爱心，值得点赞！', 5, '2025-07-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f87d81b36b30' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '包团的导游讲解小姐姐服务非常好，很负责任，因为天气炎热，小朋友有些闹腾，讲解员都很耐心，还帮忙一起安抚小朋友，很有爱心，值得点赞！' AND c.create_time = '2025-07-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，位于湖南省长沙市岳麓区岳麓山东侧山脚（岳麓山景区南门附近），为中国古代“四大书院”之一，也是长沙极具标志性的文化景点，是湖湘文化的典型代表。 一条山路，一院讲堂，一江书香。从长沙橘子洲头回首望去，青翠岳麓如古人铺展的素笺，风从湘江边卷来，把潇湘书声卷进树影婆娑的书院间。岳麓书院，这座千年不熄的学府，仿佛就是那枚钤印，在山水湖南的文脉上，轻轻一盖，便是中国读书人的心安处。', 5, '2025-07-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3d7c90e3907d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，位于湖南省长沙市岳麓区岳麓山东侧山脚（岳麓山景区南门附近），为中国古代“四大书院”之一，也是长沙极具标志性的文化景点，是湖湘文化的典型代表。 一条山路，一院讲堂，一江书香。从长沙橘子洲头回首望去，青翠岳麓如古人铺展的素笺，风从湘江边卷来，把潇湘书声卷进树影婆娑的书院间。岳麓书院，这座千年不熄的学府，仿佛就是那枚钤印，在山水湖南的文脉上，轻轻一盖，便是中国读书人的心安处。' AND c.create_time = '2025-07-05 00:00:00');
