INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '最好请导游，全是历史人文文化，听介绍才知道意义', 5, '2025-07-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '最好请导游，全是历史人文文化，听介绍才知道意义' AND c.create_time = '2025-07-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院值得一览，山清水秀，人文历史悠久，小张导游还是湖南大学哲学院学生，介绍母校历史信手拈来，还是很不错的。', 5, '2025-07-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e94ef563867e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院值得一览，山清水秀，人文历史悠久，小张导游还是湖南大学哲学院学生，介绍母校历史信手拈来，还是很不错的。' AND c.create_time = '2025-07-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【景色】景色宜人，岳麓书院值得，门口有很多讲解，可以谈价格，里面孩子可以学到很多，一定要花钱请讲解员，不然进去会感觉没啥可逛，连着就能到爱晚亭，和直接进入岳麓山，不走主干道爬山的话，有很多道，能听到鸟鸣潺水声，很治愈', 5, '2025-07-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e6081362d82e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【景色】景色宜人，岳麓书院值得，门口有很多讲解，可以谈价格，里面孩子可以学到很多，一定要花钱请讲解员，不然进去会感觉没啥可逛，连着就能到爱晚亭，和直接进入岳麓山，不走主干道爬山的话，有很多道，能听到鸟鸣潺水声，很治愈' AND c.create_time = '2025-07-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲解员水平高，清晰详细', 5, '2025-06-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ab4602215c03' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲解员水平高，清晰详细' AND c.create_time = '2025-06-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '游览这个景点，一定要提前做一些功课，里面都是文人墨客艺术大家的知识点。书院里面的景色也很美，曲径通幽，让人肃然起敬。', 4, '2025-06-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_efdd26dc6e4b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '游览这个景点，一定要提前做一些功课，里面都是文人墨客艺术大家的知识点。书院里面的景色也很美，曲径通幽，让人肃然起敬。' AND c.create_time = '2025-06-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '踏入岳麓书院，仿佛穿越时空。古色古香的建筑群落静谧矗立，赫曦台、讲堂的飞檐斗拱诉说岁月沧桑，朱熹手书的“忠孝廉节”碑刻刚劲有力，令人驻足沉思。漫步回廊，轻抚斑驳砖墙，似乎能触摸到千年来学子们苦读的身影。随处可见的楹联匾额，字字珠玑，满是文化沉淀。在这清幽之地，既惊叹于古建筑之美，更被浓厚的文化氛围深深感染，心灵也随之沉静，真切感受到传统文化的震撼与魅力。', 5, '2025-06-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7ad7f59c3744' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '踏入岳麓书院，仿佛穿越时空。古色古香的建筑群落静谧矗立，赫曦台、讲堂的飞檐斗拱诉说岁月沧桑，朱熹手书的“忠孝廉节”碑刻刚劲有力，令人驻足沉思。漫步回廊，轻抚斑驳砖墙，似乎能触摸到千年来学子们苦读的身影。随处可见的楹联匾额，字字珠玑，满是文化沉淀。在这清幽之地，既惊叹于古建筑之美，更被浓厚的文化氛围深深感染，心灵也随之沉静，真切感受到传统文化的震撼与魅力。' AND c.create_time = '2025-06-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很值得去的地方！', 5, '2025-06-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很值得去的地方！' AND c.create_time = '2025-06-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '不虚此行的选择，岳麓书院、湖南大学融为一体，极具特色。悠久的历史，厚重的文化，辈出的人才，让人折服。不亲临现场，无法体会。', 5, '2025-06-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c0d9e3e3559b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '不虚此行的选择，岳麓书院、湖南大学融为一体，极具特色。悠久的历史，厚重的文化，辈出的人才，让人折服。不亲临现场，无法体会。' AND c.create_time = '2025-06-21 00:00:00');
