INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '导游很尽心，讲解的非常详细，虽然本人是湖南人，30岁才第一次来爱晚亭，五一假期人好多啊啊啊', 5, '2025-06-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7447e0278a8a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '导游很尽心，讲解的非常详细，虽然本人是湖南人，30岁才第一次来爱晚亭，五一假期人好多啊啊啊' AND c.create_time = '2025-06-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '作为&quot;千年学府&quot;，岳麓书院完美展现了湖湘文化的厚重底蕴。古色古香的建筑群保存完好，院落间处处可见楹联碑刻，文脉气息扑面而来。在讲堂、御书楼等核心区域，能深刻感受古代书院的教育氛围。建议跟随讲解员游览，那些关于朱熹、张栻讲学的历史故事让参观体验更生动。唯一遗憾的是部分展室文物说明较简略。整体而言，这里既是文化圣地，也是拍照出片的绝佳取景地，非常值得细细品味！', 5, '2025-06-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e6edab40f5cd' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '作为&quot;千年学府&quot;，岳麓书院完美展现了湖湘文化的厚重底蕴。古色古香的建筑群保存完好，院落间处处可见楹联碑刻，文脉气息扑面而来。在讲堂、御书楼等核心区域，能深刻感受古代书院的教育氛围。建议跟随讲解员游览，那些关于朱熹、张栻讲学的历史故事让参观体验更生动。唯一遗憾的是部分展室文物说明较简略。整体而言，这里既是文化圣地，也是拍照出片的绝佳取景地，非常值得细细品味！' AND c.create_time = '2025-06-10 00:00:00');
