INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年学府，岳麓书院。湖湘文脉，渊源流长。穿越千年，体验古人智慧，赓续传统文化，很受教育和启发', 5, '2025-06-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1c931b392358' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年学府，岳麓书院。湖湘文脉，渊源流长。穿越千年，体验古人智慧，赓续传统文化，很受教育和启发' AND c.create_time = '2025-06-04 00:00:00');
