INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '总结** &amp;gt; **“古韵为骨，文脉为魂”**——岳麓书院远非普通景点： &amp;gt; ✅ **历史控必****：从朱熹会讲到***足迹，步步皆史诗； &amp;gt; ✅ **建筑迷可细品**：明清园林与碑刻宝藏相映生辉； &amp;gt; ✅ **浮躁心灵的沉淀地**：古木清泉间，重拾对学问与家国的敬畏。', 5, '2025-06-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dbfd2d75fefa' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '总结** &amp;gt; **“古韵为骨，文脉为魂”**——岳麓书院远非普通景点： &amp;gt; ✅ **历史控必****：从朱熹会讲到***足迹，步步皆史诗； &amp;gt; ✅ **建筑迷可细品**：明清园林与碑刻宝藏相映生辉； &amp;gt; ✅ **浮躁心灵的沉淀地**：古木清泉间，重拾对学问与家国的敬畏。' AND c.create_time = '2025-06-03 00:00:00');
