INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '该景区风景优美，环境整洁，设施完善，服务人员热情周到。自然景观与人文历史融合巧妙，文化底蕴深厚，游览路线规划合理。公共区域指示清晰，交通便利，餐饮购物配套齐全，兼具教育性与娱乐性。总体体验极佳，适合亲子游、摄影采风及文化爱好者，性价比高，值得推荐！', 5, '2025-05-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '该景区风景优美，环境整洁，设施完善，服务人员热情周到。自然景观与人文历史融合巧妙，文化底蕴深厚，游览路线规划合理。公共区域指示清晰，交通便利，餐饮购物配套齐全，兼具教育性与娱乐性。总体体验极佳，适合亲子游、摄影采风及文化爱好者，性价比高，值得推荐！' AND c.create_time = '2025-05-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖南省长沙市岳麓书院是中国历史上赫赫闻名的四大书院之一，位于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，是世界上最古老的学府之一。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。', 5, '2025-05-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5aa372885dd6' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖南省长沙市岳麓书院是中国历史上赫赫闻名的四大书院之一，位于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，是世界上最古老的学府之一。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。' AND c.create_time = '2025-05-20 00:00:00');
