INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '四大书院，惟楚有才，书院功不可没，很值得一去。讲解的导游知识储备很充足，讲解的很不错。', 5, '2025-05-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5a84e9fbffb6' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '四大书院，惟楚有才，书院功不可没，很值得一去。讲解的导游知识储备很充足，讲解的很不错。' AND c.create_time = '2025-05-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于湖南长沙岳麓山下，是中国古代四大书院之一，也是中国现存最古老的书院。创建于北宋年间，历经多次兴废，至今仍保存完好。书院以其悠久的历史、深厚的文化底蕴和严谨的学风而闻名。历代名师在此讲学，培养了众多人才。岳麓书院不仅是学术研究的场所，也是湖湘文化的代表，加上书院内的古朴亭台楼阁建筑和园林景致，吸引着无数游客前来参观游览。', 4, '2025-05-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0e70e0c0426e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于湖南长沙岳麓山下，是中国古代四大书院之一，也是中国现存最古老的书院。创建于北宋年间，历经多次兴废，至今仍保存完好。书院以其悠久的历史、深厚的文化底蕴和严谨的学风而闻名。历代名师在此讲学，培养了众多人才。岳麓书院不仅是学术研究的场所，也是湖湘文化的代表，加上书院内的古朴亭台楼阁建筑和园林景致，吸引着无数游客前来参观游览。' AND c.create_time = '2025-05-05 00:00:00');
