INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这儿很值得推荐，里面讲了岳麓书院的历史、名人、还有一个介绍书院的博物馆，里面展览了一些文物，可以涨不少知识！我建议请一个导游，能更好理解。', 5, '2025-05-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这儿很值得推荐，里面讲了岳麓书院的历史、名人、还有一个介绍书院的博物馆，里面展览了一些文物，可以涨不少知识！我建议请一个导游，能更好理解。' AND c.create_time = '2025-05-05 00:00:00');
