INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '国家级5A的风景名胜区岳麓位于湘江畔。🏔️虽然只有300高。但是非常闻名。一座岳麓山，半部近化史。1949年前享受国葬的27人中有6位葬于此。蔡锷、黄兴就葬在岳麓山。山中有著名的爱晚亭。山下是千年学府岳麓书院。真的值得去走走。', 5, '2025-04-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4e143c49d59b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '国家级5A的风景名胜区岳麓位于湘江畔。🏔️虽然只有300高。但是非常闻名。一座岳麓山，半部近化史。1949年前享受国葬的27人中有6位葬于此。蔡锷、黄兴就葬在岳麓山。山中有著名的爱晚亭。山下是千年学府岳麓书院。真的值得去走走。' AND c.create_time = '2025-04-18 00:00:00');
