INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '于湖湘大地，有一处承载千年文化灵韵的圣地——岳麓书院。它坐落于岳麓山东麓，枕山带水，亭台楼阁错落有致，飞檐斗拱古朴典雅，宛如一部立体的历史典籍。 自北宋开宝九年始建，岳麓书院历经朝代更迭，弦歌不绝。朱熹、张栻在此论道，思想碰撞出的火花，照亮了湖湘文化前行的道路；王夫之、魏源等鸿儒硕学从这里走出，他们的思想如璀璨星辰，在历史的天空中闪耀。漫步书院，崇道祠、明伦堂、御书楼等建筑依次映入眼帘，每一处都弥漫着浓厚的文化气息。墙壁上的诗词题刻，字迹隽永，诉说着往昔的辉煌。 如今，这里不仅是湖湘文化的摇篮，更向世人敞开怀抱，提供研学、游览的优质服务。当您踏入这方圣地，仿佛穿越千年，聆听着先辈的教诲，在书香墨韵中领略中华传统的深厚底蕴，收获一场震撼心灵的文化洗礼 。', 5, '2025-03-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a1bef757ab06' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '于湖湘大地，有一处承载千年文化灵韵的圣地——岳麓书院。它坐落于岳麓山东麓，枕山带水，亭台楼阁错落有致，飞檐斗拱古朴典雅，宛如一部立体的历史典籍。 自北宋开宝九年始建，岳麓书院历经朝代更迭，弦歌不绝。朱熹、张栻在此论道，思想碰撞出的火花，照亮了湖湘文化前行的道路；王夫之、魏源等鸿儒硕学从这里走出，他们的思想如璀璨星辰，在历史的天空中闪耀。漫步书院，崇道祠、明伦堂、御书楼等建筑依次映入眼帘，每一处都弥漫着浓厚的文化气息。墙壁上的诗词题刻，字迹隽永，诉说着往昔的辉煌。 如今，这里不仅是湖湘文化的摇篮，更向世人敞开怀抱，提供研学、游览的优质服务。当您踏入这方圣地，仿佛穿越千年，聆听着先辈的教诲，在书香墨韵中领略中华传统的深厚底蕴，收获一场震撼心灵的文化洗礼 。' AND c.create_time = '2025-03-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲的挺好的，老师很专业也很幽默。获得了不少知识，跟着去爬山也锻炼了身体，俯瞰了湘江和长沙全景。感受到了文化气息很不错。大家也都很有礼貌，很不错的体验。', 5, '2025-03-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f5c26c85984d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲的挺好的，老师很专业也很幽默。获得了不少知识，跟着去爬山也锻炼了身体，俯瞰了湘江和长沙全景。感受到了文化气息很不错。大家也都很有礼貌，很不错的体验。' AND c.create_time = '2025-03-30 00:00:00');
