INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲解的非常好。推荐！', 5, '2025-02-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲解的非常好。推荐！' AND c.create_time = '2025-02-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '导游老师非常专业，提前打电话询问我们的位置，并且告诉我没吃饭可以先去旁边小吃街，虽然是当地导游，但是普通话很标准，孩子也都能听明白。导游老师讲解内容对于引导孩子教育很有帮助，孩子也听的相当认真。正常规定时长就是一小时，不知不觉导游老师讲了70多分钟。总之就是非常满意，我下次还会在携程上找讲解项目的。', 5, '2025-02-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4d5953152ac5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '导游老师非常专业，提前打电话询问我们的位置，并且告诉我没吃饭可以先去旁边小吃街，虽然是当地导游，但是普通话很标准，孩子也都能听明白。导游老师讲解内容对于引导孩子教育很有帮助，孩子也听的相当认真。正常规定时长就是一小时，不知不觉导游老师讲了70多分钟。总之就是非常满意，我下次还会在携程上找讲解项目的。' AND c.create_time = '2025-02-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, 'P停车： 特别不好停车，交通管制，周围都是学校内部停车场，最后我们只能把车停到商场，然后再打车过去 参观体验： 大学校内的景点，院子设计很有情调，每个地方都有介绍，想慢慢看，但是人太多，是在耐不下性子。有解说的人偶尔听听，也算沾沾学识气儿', 4, '2025-02-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e3da2f440456' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = 'P停车： 特别不好停车，交通管制，周围都是学校内部停车场，最后我们只能把车停到商场，然后再打车过去 参观体验： 大学校内的景点，院子设计很有情调，每个地方都有介绍，想慢慢看，但是人太多，是在耐不下性子。有解说的人偶尔听听，也算沾沾学识气儿' AND c.create_time = '2025-02-18 00:00:00');
