INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '我们上午爬的岳麓山，坐车上山，走着下山。山顶有家茶店，花茶好喝，茶杯上有个小茶壶很有特色。下午带小孩子去岳麓书院，建议请个讲解，不然看不出门门道道。', 5, '2025-02-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '我们上午爬的岳麓山，坐车上山，走着下山。山顶有家茶店，花茶好喝，茶杯上有个小茶壶很有特色。下午带小孩子去岳麓书院，建议请个讲解，不然看不出门门道道。' AND c.create_time = '2025-02-13 00:00:00');
