INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是值得看的，也是值得请讲解的，不然就是走马观花了。带着老人孩子毫不犹豫的选择了私家团打包，不用自己提前预约，人按时到就好，其他导游都给安排好。导游讲解得很细，我感觉意犹未尽，这个价格如果时间再长些，讲得内容更多些就更好了。', 4, '2025-02-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_eb04881466a2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是值得看的，也是值得请讲解的，不然就是走马观花了。带着老人孩子毫不犹豫的选择了私家团打包，不用自己提前预约，人按时到就好，其他导游都给安排好。导游讲解得很细，我感觉意犹未尽，这个价格如果时间再长些，讲得内容更多些就更好了。' AND c.create_time = '2025-02-09 00:00:00');
