INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山和书院的景色不错，导游安排也还好，但是毕竟春节期间人太多，一切都要排好长好长的队，多少会影响到体验感。橘子洲也很漂亮，游船70分钟，夜晚风景特别好。', 5, '2025-02-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b112a93744c4' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山和书院的景色不错，导游安排也还好，但是毕竟春节期间人太多，一切都要排好长好长的队，多少会影响到体验感。橘子洲也很漂亮，游船70分钟，夜晚风景特别好。' AND c.create_time = '2025-02-05 00:00:00');
