INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '避雷啊！！！前一天一直没有联系。晚上8点开始沟通到半夜，一直找借口，第二天8点多都没有导游联系本人，最后我们被转卖给了现场的30人以上临时团。“挂羊头卖狗肉！！” 广场上拼团到处都有,自由组团很便宜。 唯一值得欣慰的是拼团的导游很好，姚导讲的认真。', 2, '2025-02-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d2deafd50aa8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '避雷啊！！！前一天一直没有联系。晚上8点开始沟通到半夜，一直找借口，第二天8点多都没有导游联系本人，最后我们被转卖给了现场的30人以上临时团。“挂羊头卖狗肉！！” 广场上拼团到处都有,自由组团很便宜。 唯一值得欣慰的是拼团的导游很好，姚导讲的认真。' AND c.create_time = '2025-02-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '邓导游很优秀👍', 5, '2025-02-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f6249754de27' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '邓导游很优秀👍' AND c.create_time = '2025-02-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '景色其实不错的，评分是给平台和景区门票低分。原因是这样的。景区有写：退伍证件可以免费入园，办理免票，我们从外地来旅游不太确定订票流程，就通过携程订票，联系了导游，希望导游可以帮我们退掉一个门票费用，导游说我们自行联系平台，携程客服说景区不退门票，免费票当日已发放完，意思我们如果退掉订单也是进不去的，我们到现场的时候出示证件就给办理免费入园了。其他城市景区都是符合免票时都给退的门票，或者导游帮助办理买票的，', 1, '2025-02-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '景色其实不错的，评分是给平台和景区门票低分。原因是这样的。景区有写：退伍证件可以免费入园，办理免票，我们从外地来旅游不太确定订票流程，就通过携程订票，联系了导游，希望导游可以帮我们退掉一个门票费用，导游说我们自行联系平台，携程客服说景区不退门票，免费票当日已发放完，意思我们如果退掉订单也是进不去的，我们到现场的时候出示证件就给办理免费入园了。其他城市景区都是符合免票时都给退的门票，或者导游帮助办理买票的，' AND c.create_time = '2025-02-01 00:00:00');
