INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '花花导游很负责，讲解很到位。让我们对书院的历史，发展，以及现阶段的地位，有了更加深刻的认识。', 5, '2025-01-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '花花导游很负责，讲解很到位。让我们对书院的历史，发展，以及现阶段的地位，有了更加深刻的认识。' AND c.create_time = '2025-01-31 00:00:00');
