INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '本来不想评价，但是想想忍不下这口气，讲解小哥对不起了，你讲得很好，本来应该给你五颗星，但是没有单独评价的地方，进门实在让我非常生气，下着大雨，两边门口排队半小时，全身淋湿，带着小孩，两边门口都不给进，互相推诿，真的是气死了，开开心心的去玩，结果给整成这个心情，搞得家里人都淋感冒了，岳麓书院的景区该整顿了，太他X乱了，哪有这样的，卖票了，刷身份证识别就行了啊，还这个门不给进那个门不给进，排了一次又一次，去他X的，不好意思，忍不住冒粗口了，实在是忍了很久还是忍不了，以后不来了，真是什么好心情都没了，湖南长沙，再也不见', 1, '2025-01-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_373fcf07af1a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '本来不想评价，但是想想忍不下这口气，讲解小哥对不起了，你讲得很好，本来应该给你五颗星，但是没有单独评价的地方，进门实在让我非常生气，下着大雨，两边门口排队半小时，全身淋湿，带着小孩，两边门口都不给进，互相推诿，真的是气死了，开开心心的去玩，结果给整成这个心情，搞得家里人都淋感冒了，岳麓书院的景区该整顿了，太他X乱了，哪有这样的，卖票了，刷身份证识别就行了啊，还这个门不给进那个门不给进，排了一次又一次，去他X的，不好意思，忍不住冒粗口了，实在是忍了很久还是忍不了，以后不来了，真是什么好心情都没了，湖南长沙，再也不见' AND c.create_time = '2025-01-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院历史悠久文化厚重，谭卓导游讲解的很好，卓卓导游知识底蕴深厚，语言精美清晰，受益匪浅，不虚此行。', 5, '2025-01-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院历史悠久文化厚重，谭卓导游讲解的很好，卓卓导游知识底蕴深厚，语言精美清晰，受益匪浅，不虚此行。' AND c.create_time = '2025-01-31 00:00:00');
