INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '请客户比较方便，朋友出行无需此消费', 5, '2025-01-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_936c11b1075c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '请客户比较方便，朋友出行无需此消费' AND c.create_time = '2025-01-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '携程商家一般，产品明细写的不清楚，后来想让提前来说景区游客少会提前闭园。不过一码归一码，导游很给力，李导知识渊博，幽默，讲解两个小时，收获满满，必须给点个👍', 4, '2025-01-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '携程商家一般，产品明细写的不清楚，后来想让提前来说景区游客少会提前闭园。不过一码归一码，导游很给力，李导知识渊博，幽默，讲解两个小时，收获满满，必须给点个👍' AND c.create_time = '2025-01-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '李导讲解详实热情，从岳麓书院的历史到人物，涨了不少见识。带孩子体验，点赞👍👍👍，', 5, '2025-01-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dbc23a465b57' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '李导讲解详实热情，从岳麓书院的历史到人物，涨了不少见识。带孩子体验，点赞👍👍👍，' AND c.create_time = '2025-01-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '踏入岳麓书院的那一刻，就像一头撞进了历史的温柔怀抱，周身都被古朴的气息所萦绕。 书院的建筑错落有致，飞檐斗拱好似展翅欲飞的鲲鹏，庄重又不失灵动。青石板路被岁月打磨得光滑，每一步都像是在与往昔对话。抬眼望去，庭院里的参天古树，枝叶繁茂，阳光透过缝隙洒下，形成一片片金色的光斑，微风拂过，光影摇曳，仿佛在诉说着这里千年来的故事。 再看那一间间陈列室，珍贵的文物、泛黄的古籍，静静躺在展柜中，它们是书院发展的见证者。驻足细看，那些古老的文字、精美的字画，无不展现着先辈们的智慧与才情，让人不禁感叹中华文化的博大精深。 在岳麓书院，除了能感受浓厚的历史文化氛围，还能体会到这里的人文气息。讲解员们绘声绘色的讲述，让那些书本上的人物鲜活起来，仿佛能看到朱熹、张栻在此讲学论道，学子们围坐四周，听得如痴如醉。 不过，书院里游客较多，有时会稍显嘈杂，在一定程度上影响沉浸式体验。但这也侧面反映出它的魅力，吸引着来自五湖四海的人前来探寻。总之，岳麓书院是一场不容错过的文化盛宴，值得每一个热爱历史文化的人亲身感受。', 5, '2025-01-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dce72d0b14d1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '踏入岳麓书院的那一刻，就像一头撞进了历史的温柔怀抱，周身都被古朴的气息所萦绕。 书院的建筑错落有致，飞檐斗拱好似展翅欲飞的鲲鹏，庄重又不失灵动。青石板路被岁月打磨得光滑，每一步都像是在与往昔对话。抬眼望去，庭院里的参天古树，枝叶繁茂，阳光透过缝隙洒下，形成一片片金色的光斑，微风拂过，光影摇曳，仿佛在诉说着这里千年来的故事。 再看那一间间陈列室，珍贵的文物、泛黄的古籍，静静躺在展柜中，它们是书院发展的见证者。驻足细看，那些古老的文字、精美的字画，无不展现着先辈们的智慧与才情，让人不禁感叹中华文化的博大精深。 在岳麓书院，除了能感受浓厚的历史文化氛围，还能体会到这里的人文气息。讲解员们绘声绘色的讲述，让那些书本上的人物鲜活起来，仿佛能看到朱熹、张栻在此讲学论道，学子们围坐四周，听得如痴如醉。 不过，书院里游客较多，有时会稍显嘈杂，在一定程度上影响沉浸式体验。但这也侧面反映出它的魅力，吸引着来自五湖四海的人前来探寻。总之，岳麓书院是一场不容错过的文化盛宴，值得每一个热爱历史文化的人亲身感受。' AND c.create_time = '2025-01-25 00:00:00');
