INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '因为时间比较匆忙，所以走马观花的逛了一下。文化气息很浓，时间充足的话值得细细游览', 5, '2025-01-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_23e7626d873f' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '因为时间比较匆忙，所以走马观花的逛了一下。文化气息很浓，时间充足的话值得细细游览' AND c.create_time = '2025-01-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山去过挺多次了，景色一般，就爱晚亭那里漂亮点。山上很多革命名人墓地。推荐买岳麓书院带解说的门票，我们的讲解员挺专业的，讲解完从一条小路上山，几分钟就到爱晚亭了', 4, '2025-01-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_661c5bf0788d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山去过挺多次了，景色一般，就爱晚亭那里漂亮点。山上很多革命名人墓地。推荐买岳麓书院带解说的门票，我们的讲解员挺专业的，讲解完从一条小路上山，几分钟就到爱晚亭了' AND c.create_time = '2025-01-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是有上千年历史的高等学府，有千年学府之称，是古代四大书院之一，也是湖南大学的前身，无论老师或学生，都出了很多名人。 门口的岳麓书院四个字，是由宋神宗御笔亲题，里面还有毛泽东住过的地方。 这是1个十分值得一去的景点。', 5, '2025-01-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_aa03564e8276' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是有上千年历史的高等学府，有千年学府之称，是古代四大书院之一，也是湖南大学的前身，无论老师或学生，都出了很多名人。 门口的岳麓书院四个字，是由宋神宗御笔亲题，里面还有毛泽东住过的地方。 这是1个十分值得一去的景点。' AND c.create_time = '2025-01-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '酒店服务热情，卫生干净整洁，房间温馨宽敞，酒店位置优越，客房清洁人员也很亲切，前台小姐姐很热情，房间价格也很实惠，性价比高！得到的不仅是一次舒适愉悦的入住体验，还有人间烟火，这就是我对这家酒店的评价，超赞！', 5, '2025-01-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ef11ae95768a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '酒店服务热情，卫生干净整洁，房间温馨宽敞，酒店位置优越，客房清洁人员也很亲切，前台小姐姐很热情，房间价格也很实惠，性价比高！得到的不仅是一次舒适愉悦的入住体验，还有人间烟火，这就是我对这家酒店的评价，超赞！' AND c.create_time = '2025-01-05 00:00:00');
