INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '我和我的她去了岳麓书院， 景色美好， 时间太紧凑，后山没去', 5, '2024-12-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3808b330276f' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '我和我的她去了岳麓书院， 景色美好， 时间太紧凑，后山没去' AND c.create_time = '2024-12-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，位于湖南省长沙市湘江西岸的岳麓山脚下，是中国历史上著名的四大书院之一。这里不仅是古代学者讲学的地方，也是湖湘文化的重要发源地。漫步在古朴的院落中，仿佛能听到历史的回声，感受到浓厚的文化氛围。每一砖一瓦都透露出岁月的痕迹，让人不禁对古人的智慧和才情肃然起敬。无论是对历史文化感兴趣的游客，还是喜欢安静阅读的朋友，岳麓书院都是一个不可多得的好去处。在这里，你可以暂时忘却都市的喧嚣，静下心来感受中国传统文化的魅力。', 5, '2024-12-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1639ea041ae0' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，位于湖南省长沙市湘江西岸的岳麓山脚下，是中国历史上著名的四大书院之一。这里不仅是古代学者讲学的地方，也是湖湘文化的重要发源地。漫步在古朴的院落中，仿佛能听到历史的回声，感受到浓厚的文化氛围。每一砖一瓦都透露出岁月的痕迹，让人不禁对古人的智慧和才情肃然起敬。无论是对历史文化感兴趣的游客，还是喜欢安静阅读的朋友，岳麓书院都是一个不可多得的好去处。在这里，你可以暂时忘却都市的喧嚣，静下心来感受中国传统文化的魅力。' AND c.create_time = '2024-12-23 00:00:00');
