INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '传说中四大书院 我觉得很不错哦', 5, '2024-12-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8b1f227ca20a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '传说中四大书院 我觉得很不错哦' AND c.create_time = '2024-12-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院历史上闻名的四大书院之一，位于长沙湘江西岸的岳麓山下，这里青砖黛瓦，古树参天，景色优美，一片宁静，处散发着浓浓的书香气息，有兴趣的朋友一定要来看看哟！', 4, '2024-12-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5d9d46ad0c05' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院历史上闻名的四大书院之一，位于长沙湘江西岸的岳麓山下，这里青砖黛瓦，古树参天，景色优美，一片宁静，处散发着浓浓的书香气息，有兴趣的朋友一定要来看看哟！' AND c.create_time = '2024-12-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这里是中国历史上很牛的学校，就连清华北大来了都要喊他做祖师爷。它也是我国一座到现在还在招收学生教书育人的千年高等学府。这里就是湖南长沙的岳麓书院。 里面有三件是一定要看的宝物，特别是那十八条的学规，一定会让您和孩子受益匪浅。 ① 岳麓书院门口的一副集句联（p1-2） 惟楚有才，于斯为盛，什么意思呢？并不说只有楚国才有人才，因为这个惟字呢在这里是语气助词的意思，所以他想表达的是楚有才这三个字，就是说楚地人才辈出，而这里的人才较为兴盛。而事实上也是如此，从岳麓书院走出去的学生呢，那都是贤达俊杰，特别是清朝之后，更是达到了顶峰。比如征新疆的左宗棠，半个圣人的曾国藩，戊戌六君子的谭嗣同，还有中国近代民族革命家黄兴、蔡鄂等等，都是岳麓书院的高徒。还有毛教员也曾居住在岳麓书院的半学斋（p7-8） 〇岳麓书院为何能够培养出这么多的大家？ 书院创办于公元976年的北宋时期，他经历了南宋、元明清等多个朝代。到1926年的时候，在书院旧址上扩建，正式定名为湖南大学。到现在已经有一千多年的历史。', 4, '2024-12-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4e4739670474' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这里是中国历史上很牛的学校，就连清华北大来了都要喊他做祖师爷。它也是我国一座到现在还在招收学生教书育人的千年高等学府。这里就是湖南长沙的岳麓书院。 里面有三件是一定要看的宝物，特别是那十八条的学规，一定会让您和孩子受益匪浅。 ① 岳麓书院门口的一副集句联（p1-2） 惟楚有才，于斯为盛，什么意思呢？并不说只有楚国才有人才，因为这个惟字呢在这里是语气助词的意思，所以他想表达的是楚有才这三个字，就是说楚地人才辈出，而这里的人才较为兴盛。而事实上也是如此，从岳麓书院走出去的学生呢，那都是贤达俊杰，特别是清朝之后，更是达到了顶峰。比如征新疆的左宗棠，半个圣人的曾国藩，戊戌六君子的谭嗣同，还有中国近代民族革命家黄兴、蔡鄂等等，都是岳麓书院的高徒。还有毛教员也曾居住在岳麓书院的半学斋（p7-8） 〇岳麓书院为何能够培养出这么多的大家？ 书院创办于公元976年的北宋时期，他经历了南宋、元明清等多个朝代。到1926年的时候，在书院旧址上扩建，正式定名为湖南大学。到现在已经有一千多年的历史。' AND c.create_time = '2024-12-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是千年学府，历史悠久。 建筑古朴典雅，充满文化气息。 在这里能感受到浓厚的学术氛围。 总的来说，岳麓书院是个文化底蕴深厚的地方。', 5, '2024-12-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9e91398754fc' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是千年学府，历史悠久。 建筑古朴典雅，充满文化气息。 在这里能感受到浓厚的学术氛围。 总的来说，岳麓书院是个文化底蕴深厚的地方。' AND c.create_time = '2024-12-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院坐落在岳麓山脚下，从湖南大学一侧上山离得较近，称为中国四大书院之一。周边景色秀丽，山水环抱，书院内楼阁清新，古朴自然。适合打卡拍照，参观游学，记得提前预约，避免无法入园参观，可同岳麓山一同游览，大概花费半天时间', 5, '2024-12-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7498d93b1f02' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院坐落在岳麓山脚下，从湖南大学一侧上山离得较近，称为中国四大书院之一。周边景色秀丽，山水环抱，书院内楼阁清新，古朴自然。适合打卡拍照，参观游学，记得提前预约，避免无法入园参观，可同岳麓山一同游览，大概花费半天时间' AND c.create_time = '2024-12-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲解一般，比较重历史，缺了点趣味性', 3, '2024-12-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲解一般，比较重历史，缺了点趣味性' AND c.create_time = '2024-12-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖南大学岳麓书院（Yuelu Academy, Hunan University）是湖南大学下设的二级学院。 976年，北宋潭州太守朱洞创建岳麓书院于岳麓山下，历经宋、元、明、清等朝代的变迁。1903年，岳麓书院改制，成立湖南高等学堂。1926年，湖南大学在书院正式成立。1979年，开始岳麓书院修复工作。1984年，成立岳麓书院文化研究所。2005年，改岳麓书院文化研究所为湖南大学岳麓书院。', 5, '2024-12-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖南大学岳麓书院（Yuelu Academy, Hunan University）是湖南大学下设的二级学院。 976年，北宋潭州太守朱洞创建岳麓书院于岳麓山下，历经宋、元、明、清等朝代的变迁。1903年，岳麓书院改制，成立湖南高等学堂。1926年，湖南大学在书院正式成立。1979年，开始岳麓书院修复工作。1984年，成立岳麓书院文化研究所。2005年，改岳麓书院文化研究所为湖南大学岳麓书院。' AND c.create_time = '2024-12-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于长沙岳麓山脚下，是中国历史上有名的四大书院之一，这里青砖黛瓦，古树参天，院落碑石，廊台亭榭，鸟语花香，优雅宁靜，风景秀美，长廊上摆放着许多名人字画，这座“千年学府”处处散发着浓厚的书香气息，穿行其中韵味无穷。 开放时间 ：5/1-10/31 每天07:30-18:00开放放11/1-4/30 每天08:00-17:30开放', 4, '2024-12-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5d9d46ad0c05' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于长沙岳麓山脚下，是中国历史上有名的四大书院之一，这里青砖黛瓦，古树参天，院落碑石，廊台亭榭，鸟语花香，优雅宁靜，风景秀美，长廊上摆放着许多名人字画，这座“千年学府”处处散发着浓厚的书香气息，穿行其中韵味无穷。 开放时间 ：5/1-10/31 每天07:30-18:00开放放11/1-4/30 每天08:00-17:30开放' AND c.create_time = '2024-12-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '南门进东门出：岳麓山南大门进入，经岳麓书院、爱晚亭、舍利塔、古麓山寺等景点到达山顶，再经古炮台、观光长廊等从岳麓山东大门出，可全面游览景点且不走回头路.', 5, '2024-12-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_807e8203a68a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '南门进东门出：岳麓山南大门进入，经岳麓书院、爱晚亭、舍利塔、古麓山寺等景点到达山顶，再经古炮台、观光长廊等从岳麓山东大门出，可全面游览景点且不走回头路.' AND c.create_time = '2024-12-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '萌芽于唐末五代，北宋开宝九年正式创建，大中祥符八年，宋真宗赵恒御赐“岳麓书院”匾额，成为讲学、藏书、祭祀之所，是中国古代四大书院之一 。', 5, '2024-11-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '萌芽于唐末五代，北宋开宝九年正式创建，大中祥符八年，宋真宗赵恒御赐“岳麓书院”匾额，成为讲学、藏书、祭祀之所，是中国古代四大书院之一 。' AND c.create_time = '2024-11-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是***当年在这里学习时的地方，还有和夫人***相识相知相爱的爱晚亭，书香氛围浓厚，历史韵味悠长！非常值得推荐去看一看…', 5, '2024-11-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9af1587b9710' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是***当年在这里学习时的地方，还有和夫人***相识相知相爱的爱晚亭，书香氛围浓厚，历史韵味悠长！非常值得推荐去看一看…' AND c.create_time = '2024-11-13 00:00:00');
