INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '导游的讲解很全面也很生动！岳麓书院千年学府，很深的文化底蕴和历史背景！今天的岳麓书院不仅是湖南大学的文史哲人才培养和研究基地，湖南省旅游胜地，更是整个长沙市的文化窗口和文化名片。感谢导游把一张这么好的名片介绍给了我们', 5, '2024-10-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f11ae15168a1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '导游的讲解很全面也很生动！岳麓书院千年学府，很深的文化底蕴和历史背景！今天的岳麓书院不仅是湖南大学的文史哲人才培养和研究基地，湖南省旅游胜地，更是整个长沙市的文化窗口和文化名片。感谢导游把一张这么好的名片介绍给了我们' AND c.create_time = '2024-10-27 00:00:00');
