INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '导游态度很好，人挺幽默的，讲的很全面、生动，各种典故历史他都知道。虽然是拼团但人不多，体验感很好。讲解时井井有条，路线挺经典的，景色宜人。我们有问题都解答的很详细，感觉收获很多。同时感到了楚文化的博大精深和古圣先贤的智慧。惟楚有才，于斯为盛。的文化自信溢于言表。', 5, '2024-08-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0a4d891637be' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '导游态度很好，人挺幽默的，讲的很全面、生动，各种典故历史他都知道。虽然是拼团但人不多，体验感很好。讲解时井井有条，路线挺经典的，景色宜人。我们有问题都解答的很详细，感觉收获很多。同时感到了楚文化的博大精深和古圣先贤的智慧。惟楚有才，于斯为盛。的文化自信溢于言表。' AND c.create_time = '2024-08-05 00:00:00');
