INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院门票40元，讲解10元，还是很值得的 门票需要提前预约，一般情况还是很容易预约的，讲解就需要到现场进门后再购买讲解票🎫，讲解时间段需要看现场人流定，基本最后一批就是16:30 如果没有讲解自己看的话估计觉得没什么意思，花点小钱很有必要[愉快] 进了岳麓书院，从北门出可以走栈道，下雨天☔️也有遮挡，通向爱晚亭、岳麓山，就不用另外预约岳麓山的门票。', 5, '2024-06-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0ea27a04cd9a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院门票40元，讲解10元，还是很值得的 门票需要提前预约，一般情况还是很容易预约的，讲解就需要到现场进门后再购买讲解票🎫，讲解时间段需要看现场人流定，基本最后一批就是16:30 如果没有讲解自己看的话估计觉得没什么意思，花点小钱很有必要[愉快] 进了岳麓书院，从北门出可以走栈道，下雨天☔️也有遮挡，通向爱晚亭、岳麓山，就不用另外预约岳麓山的门票。' AND c.create_time = '2024-06-07 00:00:00');
