INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '预订5月2日下午二点半入场加人工讲解晚去了一个小时，到岳麓山院景区刷不了身份证也没有入园码当日进不了景区，景区验票人员说：他们没在携程上卖票，说我网上买的是假票！！5月3日我自己到****公众号又买了票才入园游玩。我携程提交退票申请，卖家说我已经用了该票，不给退票！事实我真的没用这三张票！携程客服说也联系不上卖票的商家，目前一分钱都没有退！大家千万不要在这家买票，真的遇到骗子了！！！携程客服刚开始说联系不上卖家让我等等，5月12日携程客服三百六十度大变给我发了信息说：“一直联系不上我，他们不再跟进我的退票申请了”坑！！！有图为证，最后一张图是我从****公众号买的5.3日的入园票。', 1, '2024-05-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1a91e658d7fe' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '预订5月2日下午二点半入场加人工讲解晚去了一个小时，到岳麓山院景区刷不了身份证也没有入园码当日进不了景区，景区验票人员说：他们没在携程上卖票，说我网上买的是假票！！5月3日我自己到****公众号又买了票才入园游玩。我携程提交退票申请，卖家说我已经用了该票，不给退票！事实我真的没用这三张票！携程客服说也联系不上卖票的商家，目前一分钱都没有退！大家千万不要在这家买票，真的遇到骗子了！！！携程客服刚开始说联系不上卖家让我等等，5月12日携程客服三百六十度大变给我发了信息说：“一直联系不上我，他们不再跟进我的退票申请了”坑！！！有图为证，最后一张图是我从****公众号买的5.3日的入园票。' AND c.create_time = '2024-05-12 00:00:00');
