INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '阿楚讲解真是太棒了！简直让人眼前一亮，仿佛置身于一个充满历史和文化气息的世界。 知识储备丰富！无论是关于景点的历史背景，还是关于文化习俗的讲解，都能娓娓道来，让我们听得如痴如醉。 我要特别提一下阿楚的专业素养和服务态度。她始终保持着微笑和耐心，无论我们提出什么问题，都能一一解答，让我们感受到了真正的关心和尊重。', 5, '2024-04-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '阿楚讲解真是太棒了！简直让人眼前一亮，仿佛置身于一个充满历史和文化气息的世界。 知识储备丰富！无论是关于景点的历史背景，还是关于文化习俗的讲解，都能娓娓道来，让我们听得如痴如醉。 我要特别提一下阿楚的专业素养和服务态度。她始终保持着微笑和耐心，无论我们提出什么问题，都能一一解答，让我们感受到了真正的关心和尊重。' AND c.create_time = '2024-04-02 00:00:00');
