INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，千年学府，圣人精神，延绵不绝。几次长沙没来，这次终于得偿所愿！湖南大学的研究生可以到御书楼还有文庙里学习！这是什么神仙大学！太惊讶了，太赞叹了！书院出了很多名人，伟大的革命先驱，毛主席，李达，何叔衡等等。', 5, '2024-02-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_441d7564aab0' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，千年学府，圣人精神，延绵不绝。几次长沙没来，这次终于得偿所愿！湖南大学的研究生可以到御书楼还有文庙里学习！这是什么神仙大学！太惊讶了，太赞叹了！书院出了很多名人，伟大的革命先驱，毛主席，李达，何叔衡等等。' AND c.create_time = '2024-02-27 00:00:00');
