INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院之行收获满满，讲解员小姐姐，特别好，语速语调都让人特别的亲切，讲解的也特别细致，中国四大书院之一不虚此行！', 5, '2024-01-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ebb9ff41edf5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院之行收获满满，讲解员小姐姐，特别好，语速语调都让人特别的亲切，讲解的也特别细致，中国四大书院之一不虚此行！' AND c.create_time = '2024-01-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '我为自己明智选择携程的讲解点赞！要表扬自己是因为讲解太好了。自己十月也来过，但没讲解的情况下只能走马观花，但这次带小孩来，希望他们会留下点什么。果然，讲解员很细致讲了每一处主要细节，赫曦台，门匾，对联，处处有文化，点点有底蕴。值得推荐！', 5, '2024-01-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '我为自己明智选择携程的讲解点赞！要表扬自己是因为讲解太好了。自己十月也来过，但没讲解的情况下只能走马观花，但这次带小孩来，希望他们会留下点什么。果然，讲解员很细致讲了每一处主要细节，赫曦台，门匾，对联，处处有文化，点点有底蕴。值得推荐！' AND c.create_time = '2024-01-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '冯江平讲解员很敬业了。一直滔滔不绝，讲了两个小时。我们获得到了很多，受益匪浅，都讲解的仔细认真，，我们也听得津津有味，体验刚好，点赞。', 5, '2024-01-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_726309b7bb1f' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '冯江平讲解员很敬业了。一直滔滔不绝，讲了两个小时。我们获得到了很多，受益匪浅，都讲解的仔细认真，，我们也听得津津有味，体验刚好，点赞。' AND c.create_time = '2024-01-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '20231217下午： 1、岳麓书院是中国古代四大书院之一，始建于北宋开宝九年（976年），被誉为“千年学府”，倚靠长沙市区内人文名山岳麓山，自古是湖湘地区人才的摇篮，民国十五年（1926年）更名为湖南大学，成功实现古代书院的现代转型。书院正门朝东，内分5条东西路。 ①地址：湖南省长沙市岳麓区麓山路273号 ②交通：公交直达，开车不好停 ③旺季：无 ④用时：3小时 ⑤票价：40元 2、中路主轴自东向西有： ①赫曦台：始建于南宋乾道三年（1167年），原位于山顶名为赫曦，意为观日，后毁，清乾隆五十五年（1790年）重建于现址，清道光元年（1821年）改为现名，台上屏风有书院地图和名人题词 ②大门：始建于北宋、复建于明正德四年（1509年），原名中门、黉门，将军门式构造，匾额为北宋大中祥符八年（1015年）宋真宗召见书院讲师周式时御赐 ③二门：长廊门洞 ④讲堂：书院主讲堂，讲桌四周立有严、肃、孝、节、廉、忠、齐、整8个大字 ⑤御书楼：始建于北宋咸平二年（999年），原名书楼、尊经阁，清康熙二十六年（1687年）巡抚丁思孔增建，清代中后期藏书最多14730卷 ⑥屈子祠：始建于清嘉庆元年（1796年），又称三闾大夫祠，主祀战国时期楚国诗人屈原，2006年从书院北迁于此。内是两层四合院，只开放正堂，其余厢房是研究用房 ⑦西门区域：高颜值的竹林亭廊 3、主轴偏北侧一路，自东向西有： ①半学斋（岳麓书院历史陈列馆）：东西向长形厢房，原为省立湖南大学筹备处，毛泽东在民国六年至八年（1917-1919年）曾2次住此，屋内详尽介绍了书院的历史沿革 ②湘水校经堂：清道光十一年（1831年）由湖南巡抚吴荣光与讲师欧阳厚均仿照清代著名书院学海堂所建，以汉学为主，门额为吴荣光手书，晚清名臣左宗棠曾师从此堂 ③船山祠：始建于清光绪元年（1875年），主祀书院学生、著名思想家王夫之，因其号为船山而得名 ④慎斋祠：始建于清乾隆四十七年（1782年），又称罗山长祠（山长：学院讲师），主祀讲师罗典，因其号为慎斋而得名，其任职期间学院人才辈出 ⑤六君子堂：始建于明嘉靖五年（1526年）、重建于清嘉庆十七年（1812年），又称慕道祠，因主祀宋代潭州知州朱洞、知州李允则、讲师周式、安抚使刘珙、明代通判陈钢、同知杨茂元6位对有功于书院的人而得名…… 字数超限，在最后一张图片里继续', 5, '2024-01-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_506707a09f1d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '20231217下午： 1、岳麓书院是中国古代四大书院之一，始建于北宋开宝九年（976年），被誉为“千年学府”，倚靠长沙市区内人文名山岳麓山，自古是湖湘地区人才的摇篮，民国十五年（1926年）更名为湖南大学，成功实现古代书院的现代转型。书院正门朝东，内分5条东西路。 ①地址：湖南省长沙市岳麓区麓山路273号 ②交通：公交直达，开车不好停 ③旺季：无 ④用时：3小时 ⑤票价：40元 2、中路主轴自东向西有： ①赫曦台：始建于南宋乾道三年（1167年），原位于山顶名为赫曦，意为观日，后毁，清乾隆五十五年（1790年）重建于现址，清道光元年（1821年）改为现名，台上屏风有书院地图和名人题词 ②大门：始建于北宋、复建于明正德四年（1509年），原名中门、黉门，将军门式构造，匾额为北宋大中祥符八年（1015年）宋真宗召见书院讲师周式时御赐 ③二门：长廊门洞 ④讲堂：书院主讲堂，讲桌四周立有严、肃、孝、节、廉、忠、齐、整8个大字 ⑤御书楼：始建于北宋咸平二年（999年），原名书楼、尊经阁，清康熙二十六年（1687年）巡抚丁思孔增建，清代中后期藏书最多14730卷 ⑥屈子祠：始建于清嘉庆元年（1796年），又称三闾大夫祠，主祀战国时期楚国诗人屈原，2006年从书院北迁于此。内是两层四合院，只开放正堂，其余厢房是研究用房 ⑦西门区域：高颜值的竹林亭廊 3、主轴偏北侧一路，自东向西有： ①半学斋（岳麓书院历史陈列馆）：东西向长形厢房，原为省立湖南大学筹备处，毛泽东在民国六年至八年（1917-1919年）曾2次住此，屋内详尽介绍了书院的历史沿革 ②湘水校经堂：清道光十一年（1831年）由湖南巡抚吴荣光与讲师欧阳厚均仿照清代著名书院学海堂所建，以汉学为主，门额为吴荣光手书，晚清名臣左宗棠曾师从此堂 ③船山祠：始建于清光绪元年（1875年），主祀书院学生、著名思想家王夫之，因其号为船山而得名 ④慎斋祠：始建于清乾隆四十七年（1782年），又称罗山长祠（山长：学院讲师），主祀讲师罗典，因其号为慎斋而得名，其任职期间学院人才辈出 ⑤六君子堂：始建于明嘉靖五年（1526年）、重建于清嘉庆十七年（1812年），又称慕道祠，因主祀宋代潭州知州朱洞、知州李允则、讲师周式、安抚使刘珙、明代通判陈钢、同知杨茂元6位对有功于书院的人而得名…… 字数超限，在最后一张图片里继续' AND c.create_time = '2024-01-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲解员杨导非常认真负责任，并且讲解内容很详实、精彩，能学到很多知识。尽管爱晚亭不属于讲解范畴，杨导也讲解了，还解答了行程中的其他疑问，小朋友听得很感兴趣。', 5, '2024-01-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3e2542bf6d9a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲解员杨导非常认真负责任，并且讲解内容很详实、精彩，能学到很多知识。尽管爱晚亭不属于讲解范畴，杨导也讲解了，还解答了行程中的其他疑问，小朋友听得很感兴趣。' AND c.create_time = '2024-01-01 00:00:00');
