INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '预约了下午4点的讲解，到下午3:50都没有任何导游联系，于是又打了几次携程客服电话，回复等待导游联系或者联系不到第三方机构，问题没有解决。直到下午4:10才接到导游短信通知集合。导游组织管理存在巨大缺陷。本来已经比约定时间晚了很多，导游还在不停等人并临时加人，直到下午5:00都没有进去景点。最终进入景点已经过了下午5:30！导游讲解带有较重地方口音，有些时候听不清楚在说什么。体验感真的是有史以来最差的一次！大家谨慎选择这个项目！', 3, '2023-10-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_933b3d4edb24' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '预约了下午4点的讲解，到下午3:50都没有任何导游联系，于是又打了几次携程客服电话，回复等待导游联系或者联系不到第三方机构，问题没有解决。直到下午4:10才接到导游短信通知集合。导游组织管理存在巨大缺陷。本来已经比约定时间晚了很多，导游还在不停等人并临时加人，直到下午5:00都没有进去景点。最终进入景点已经过了下午5:30！导游讲解带有较重地方口音，有些时候听不清楚在说什么。体验感真的是有史以来最差的一次！大家谨慎选择这个项目！' AND c.create_time = '2023-10-05 00:00:00');
