INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国古代四大书院之一，非常有看点', 5, '2023-09-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_89df62cd7797' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国古代四大书院之一，非常有看点' AND c.create_time = '2023-09-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '我们请的讲解老师，老师知识储备量很大，出口成章，说话声音也好听。我一直跟在老师左右听，老师把每个匾额上的题字和对联都一字一字讲解给我们听，很有耐心，我们听得也津津有味，给讲解老师一个大大赞！岳麓书院里面很舒服，无论外面多热，书院有古树，枝繁叶茂，所以书院很凉快，坐在里面就有求学的意愿，整体环境给我就是两个字——舒服！', 5, '2023-09-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e1afcb3d75cc' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '我们请的讲解老师，老师知识储备量很大，出口成章，说话声音也好听。我一直跟在老师左右听，老师把每个匾额上的题字和对联都一字一字讲解给我们听，很有耐心，我们听得也津津有味，给讲解老师一个大大赞！岳麓书院里面很舒服，无论外面多热，书院有古树，枝繁叶茂，所以书院很凉快，坐在里面就有求学的意愿，整体环境给我就是两个字——舒服！' AND c.create_time = '2023-09-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于长沙湘江西岸的岳麓山脚下，湖南大学校园内。作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。到长沙一定要去参观。', 5, '2023-09-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_222895c82720' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于长沙湘江西岸的岳麓山脚下，湖南大学校园内。作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。到长沙一定要去参观。' AND c.create_time = '2023-09-11 00:00:00');
