INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '导游小妹妹感觉就是为了完成任务一样，一点都没有服务意识，解说的感觉就是把想让我们知道的读完就好。看过抖音解说岳麓书院的，差的不是一点点，可能是我们这个解说服务太便宜了吧', 3, '2023-07-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_eb91b5bdb676' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '导游小妹妹感觉就是为了完成任务一样，一点都没有服务意识，解说的感觉就是把想让我们知道的读完就好。看过抖音解说岳麓书院的，差的不是一点点，可能是我们这个解说服务太便宜了吧' AND c.create_time = '2023-07-23 00:00:00');
