INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '35度去岳麓书院挺不爽的，建筑里空调弱，游客很多室内也热。 地铁坐到湖南大学走过去的，门票40，听工作人员在喊13:30有讲解一人40元。本来想玩好这里再去岳麓山上。然而这里就把我们热得不行纷纷没精打采，就改去了李自健美术馆，空调房就精神了。 从西门离开岳麓书院下山时有条小吃街，也是人头济济。', 4, '2023-07-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b0c9d5680bad' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '35度去岳麓书院挺不爽的，建筑里空调弱，游客很多室内也热。 地铁坐到湖南大学走过去的，门票40，听工作人员在喊13:30有讲解一人40元。本来想玩好这里再去岳麓山上。然而这里就把我们热得不行纷纷没精打采，就改去了李自健美术馆，空调房就精神了。 从西门离开岳麓书院下山时有条小吃街，也是人头济济。' AND c.create_time = '2023-07-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '布局非常复杂的一个景区，跟迷宫一样，里面内容丰富，以建筑为主，有少部分实物。值得一游。不足之处就是水池子水都臭了，有点熏人。', 4, '2023-07-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d7b3ddc922ec' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '布局非常复杂的一个景区，跟迷宫一样，里面内容丰富，以建筑为主，有少部分实物。值得一游。不足之处就是水池子水都臭了，有点熏人。' AND c.create_time = '2023-07-22 00:00:00');
