INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '三千年的历史长河中，这座城市的文明如火，公元953年左右成立的岳麓学院，是北宋四大学院之一，相当于现在的一流研究生院。 岳麓书院坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存。', 4, '2023-07-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0eb199cf9a93' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '三千年的历史长河中，这座城市的文明如火，公元953年左右成立的岳麓学院，是北宋四大学院之一，相当于现在的一流研究生院。 岳麓书院坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存。' AND c.create_time = '2023-07-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '导游讲解的内容紧密结合历史，也充满了趣味性。可惜由于今天的时间及行程安排没有认真的游览到书院内的其他地方。书院内风景也是挺美的。', 4, '2023-07-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_972bdeadd597' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '导游讲解的内容紧密结合历史，也充满了趣味性。可惜由于今天的时间及行程安排没有认真的游览到书院内的其他地方。书院内风景也是挺美的。' AND c.create_time = '2023-07-16 00:00:00');
