INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是历史上赫赫闻名的四大书院之一，坐落在长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。长沙打卡地之一！', 5, '2023-07-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f44e72950268' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是历史上赫赫闻名的四大书院之一，坐落在长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。长沙打卡地之一！' AND c.create_time = '2023-07-15 00:00:00');
