INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '陪外地朋友去了一次，还是挺值得逛逛的。看完介绍才能感知到，长沙真的自古以来就很重视教育。', 5, '2023-07-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c0df7f9e5fe8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '陪外地朋友去了一次，还是挺值得逛逛的。看完介绍才能感知到，长沙真的自古以来就很重视教育。' AND c.create_time = '2023-07-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。 岳麓书院历经千年而弦歌不绝，学脉延绵。北宋开宝九年（公元976年），潭州太守朱洞在僧人办学的基础上，由官府捐资兴建，正式创立岳麓书院。北宋祥符八年（公元1015年），宋真宗召见岳麓山长周式，御笔赐书“岳麓书院”四字门额。嗣后，历经南宋、元、明、清各代，至清末光绪廿九年（公元1903年），岳麓书院与湖南省城大学堂合并改制为湖南高等学堂，沿用书院旧址。中华民国15年（公元1926年），湖南高等学堂正式定名湖南大学，仍就书院基址扩建至今。岳麓山自古就是文化名山。西晋以前为道士活动地，曾建有万寿宫、崇真观等。西晋武帝泰始四年（268年）麓山寺创立，至今仍保存完好。东晋陶侃曾建杉庵读书于此。六朝建道林寺。唐代马燧建“道林精舍”。唐末五代智璇等二僧为“思儒者之道”，在麓山寺下，“割地建屋”，建起了“以居士类”的学舍，岳麓书院就是在智办学的基础上“因袭增拓”而诞生的。', 5, '2023-07-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c9e1059d1fb2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。 岳麓书院历经千年而弦歌不绝，学脉延绵。北宋开宝九年（公元976年），潭州太守朱洞在僧人办学的基础上，由官府捐资兴建，正式创立岳麓书院。北宋祥符八年（公元1015年），宋真宗召见岳麓山长周式，御笔赐书“岳麓书院”四字门额。嗣后，历经南宋、元、明、清各代，至清末光绪廿九年（公元1903年），岳麓书院与湖南省城大学堂合并改制为湖南高等学堂，沿用书院旧址。中华民国15年（公元1926年），湖南高等学堂正式定名湖南大学，仍就书院基址扩建至今。岳麓山自古就是文化名山。西晋以前为道士活动地，曾建有万寿宫、崇真观等。西晋武帝泰始四年（268年）麓山寺创立，至今仍保存完好。东晋陶侃曾建杉庵读书于此。六朝建道林寺。唐代马燧建“道林精舍”。唐末五代智璇等二僧为“思儒者之道”，在麓山寺下，“割地建屋”，建起了“以居士类”的学舍，岳麓书院就是在智办学的基础上“因袭增拓”而诞生的。' AND c.create_time = '2023-07-10 00:00:00');
