INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院在岳麓山下，眺望橘子洲，充满了书院气，可以打卡拍照！', 4, '2023-07-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7dce78eb569a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院在岳麓山下，眺望橘子洲，充满了书院气，可以打卡拍照！' AND c.create_time = '2023-07-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院从橘子洲湖南博物馆一样，也是长沙著名景点，景区内景色幽静，风景宜人，是四大书院之一，景区内最高树龄高达820年 。 导游非常热情，讲解到位，带领我们游览了整个景区，这是真是受益匪浅，学到了很多知识！', 5, '2023-07-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c8a032d75802' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院从橘子洲湖南博物馆一样，也是长沙著名景点，景区内景色幽静，风景宜人，是四大书院之一，景区内最高树龄高达820年 。 导游非常热情，讲解到位，带领我们游览了整个景区，这是真是受益匪浅，学到了很多知识！' AND c.create_time = '2023-07-07 00:00:00');
