INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '导游讲解的不好，非常随意，基本都在照着书院里展馆的文字介绍读，没什么额外讲解，而且走得很快，假期里游览的人很多，稍不留意就看不见导游人了，非常敷衍，草草了事，也就讲了三四处，全程最多1小时，结束的时候问了导游爱晚亭在哪个方位，还指错路了。', 2, '2023-07-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2ad0d6540616' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '导游讲解的不好，非常随意，基本都在照着书院里展馆的文字介绍读，没什么额外讲解，而且走得很快，假期里游览的人很多，稍不留意就看不见导游人了，非常敷衍，草草了事，也就讲了三四处，全程最多1小时，结束的时候问了导游爱晚亭在哪个方位，还指错路了。' AND c.create_time = '2023-07-05 00:00:00');
