INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '去湖南长沙怎么能不去岳麓书院走一趟呢！一踏进这里，就自然而然的有一股书香气息洋溢着，似乎使人畅游在知识的海洋里一样，瞬间有文化了！', 4, '2023-06-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e6b15b1b4081' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '去湖南长沙怎么能不去岳麓书院走一趟呢！一踏进这里，就自然而然的有一股书香气息洋溢着，似乎使人畅游在知识的海洋里一样，瞬间有文化了！' AND c.create_time = '2023-06-30 00:00:00');
