INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '买的是中高级导游，先是联系了我一个导游后来又离约定时间半小时临时又换了个小姑娘，虽然态度不错，但是专业度根本不是中高级，这个不该导游事，就是旅行社完全没按照约定的安排。而且买的是2小时讲解，1个半小时就结束了。非常失望，这种不负责的机构和与价格不匹配的服务，差评。', 2, '2023-06-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_35394121b106' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '买的是中高级导游，先是联系了我一个导游后来又离约定时间半小时临时又换了个小姑娘，虽然态度不错，但是专业度根本不是中高级，这个不该导游事，就是旅行社完全没按照约定的安排。而且买的是2小时讲解，1个半小时就结束了。非常失望，这种不负责的机构和与价格不匹配的服务，差评。' AND c.create_time = '2023-06-26 00:00:00');
