INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于湖南省长沙市，坐地铁2号线，到溁湾镇下，三号口出站，根据导航再走一段路，走到岳麓山（东门）注意一定是东门，因为东门才有索道上山，南门只有观光车！', 4, '2023-06-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cb262584446d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于湖南省长沙市，坐地铁2号线，到溁湾镇下，三号口出站，根据导航再走一段路，走到岳麓山（东门）注意一定是东门，因为东门才有索道上山，南门只有观光车！' AND c.create_time = '2023-06-03 00:00:00');
