INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院坐落在长沙岳麓山上，它是中国古代四大书院之一，值得一看。', 5, '2023-05-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c48a36093ee6' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院坐落在长沙岳麓山上，它是中国古代四大书院之一，值得一看。' AND c.create_time = '2023-05-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '太坑爹！从橘子洲玩完出来，一点半在车上订的两点二十的票，往过开的时候接到导游电话，才给说定位不对，重新定位后发现路程变远已经有点来不及，就问导游说不听讲解了自己转可以吗，说是可以就继续往过开，结果方圆五公里以内压根没有社会车辆停车场，由于带着孩子实在没有精力再折腾了，最后就没去，想要退票一毛钱都不给退了，啥破规定，最起码不退讲解费用也应该退部分票价啊，太扯了！', 1, '2023-05-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_007b7f45a3f7' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '太坑爹！从橘子洲玩完出来，一点半在车上订的两点二十的票，往过开的时候接到导游电话，才给说定位不对，重新定位后发现路程变远已经有点来不及，就问导游说不听讲解了自己转可以吗，说是可以就继续往过开，结果方圆五公里以内压根没有社会车辆停车场，由于带着孩子实在没有精力再折腾了，最后就没去，想要退票一毛钱都不给退了，啥破规定，最起码不退讲解费用也应该退部分票价啊，太扯了！' AND c.create_time = '2023-05-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上四大书院之一，坐落于历史文化名城长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑被完整保存。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。', 5, '2023-05-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_861818c3561a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上四大书院之一，坐落于历史文化名城长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑被完整保存。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。' AND c.create_time = '2023-05-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '坐落在岳麓山上，值得一去的地方', 5, '2023-05-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7fce30e163d8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '坐落在岳麓山上，值得一去的地方' AND c.create_time = '2023-05-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '环境很好，去得比较早，人不是很多，就更有氛围了，不错下次还来！古代的最高学府！', 4, '2023-05-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6bedeb500b3e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '环境很好，去得比较早，人不是很多，就更有氛围了，不错下次还来！古代的最高学府！' AND c.create_time = '2023-05-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '感谢冯江平美女带领我们对书院的精彩讲解，经验非常丰富，深入浅出，耐心解答，干货很多，听得意犹未尽，绝对值得二刷的岳麓书院', 5, '2023-05-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_178631add1d8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '感谢冯江平美女带领我们对书院的精彩讲解，经验非常丰富，深入浅出，耐心解答，干货很多，听得意犹未尽，绝对值得二刷的岳麓书院' AND c.create_time = '2023-05-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，去湖南旅游必须打卡。人文知识丰富，最好有讲解员陪同解说。书院离湖南大学很近，时不时地会看到行色匆匆的大学生和老师，也算是旅游中有特色的啦。', 5, '2023-05-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cf11b4860213' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，去湖南旅游必须打卡。人文知识丰富，最好有讲解员陪同解说。书院离湖南大学很近，时不时地会看到行色匆匆的大学生和老师，也算是旅游中有特色的啦。' AND c.create_time = '2023-05-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '大名鼎鼎的岳麓书院 在岳麓山景区 岳麓山景区不收费 岳麓书院是要收费的 40元一位 位于岳麓山南门 必到点之一。', 5, '2023-05-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e331c99a91f5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '大名鼎鼎的岳麓书院 在岳麓山景区 岳麓山景区不收费 岳麓书院是要收费的 40元一位 位于岳麓山南门 必到点之一。' AND c.create_time = '2023-05-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '环境优美宁静，是一个很不错的景区。', 5, '2023-05-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2c5752e269ba' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '环境优美宁静，是一个很不错的景区。' AND c.create_time = '2023-05-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '来到岳麓山，一定要进来岳麓书院看一看，感受一下先贤的思想文化', 5, '2023-05-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3b2705e2c073' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '来到岳麓山，一定要进来岳麓书院看一看，感受一下先贤的思想文化' AND c.create_time = '2023-05-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '与橘子洲、湖南博物馆都是长沙最热门的景点，紧邻岳麓山，也在湖南大学的校区范围内。最佳游览路线是：从南门进，按先南后北、先东后西的顺序游览，最后经过“屈子祠”，从西门出，旁边即“爱晚亭”，左手下坡一点可乘游览车至岳麓山顶，或沿左手一直下坡，可到著名的湖南大学“美食一条街”登高路。我们去的这天正是周末，人太多了，上山乘车的地方大排长龙，就掉头走了，准备以后秋天再来欣赏岳麓秋景。', 5, '2023-05-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3fd5517e58a8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '与橘子洲、湖南博物馆都是长沙最热门的景点，紧邻岳麓山，也在湖南大学的校区范围内。最佳游览路线是：从南门进，按先南后北、先东后西的顺序游览，最后经过“屈子祠”，从西门出，旁边即“爱晚亭”，左手下坡一点可乘游览车至岳麓山顶，或沿左手一直下坡，可到著名的湖南大学“美食一条街”登高路。我们去的这天正是周末，人太多了，上山乘车的地方大排长龙，就掉头走了，准备以后秋天再来欣赏岳麓秋景。' AND c.create_time = '2023-05-18 00:00:00');
