INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙湘江西岸的岳麓书院是中国史上四大闻名书院之一，是我长沙之行的第一站。乘的的到达湖南大学，看到化学化工学院（直线不到100米）也就到达了书院售票处。书院规模较大，建筑保存完整（至少是修复得完整）院落、石碑、砖瓦、墙篱、池塘，都淬火为史话，向世人传颂着千年的弦歌。宋真宗御笔赐书“岳麓书院”四字历经多代，清末光绪年间（1903年）与湖南省城大学堂合并为湖南高等学堂 ，1927年定名为湖南大学。很多中学生团队前往参观，令人瞩目的爱国主义教育基地！遗憾的是参观的人太多，拍摄效果欠佳。但心中依然留下了学院风采！', 5, '2023-04-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_67505436b590' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙湘江西岸的岳麓书院是中国史上四大闻名书院之一，是我长沙之行的第一站。乘的的到达湖南大学，看到化学化工学院（直线不到100米）也就到达了书院售票处。书院规模较大，建筑保存完整（至少是修复得完整）院落、石碑、砖瓦、墙篱、池塘，都淬火为史话，向世人传颂着千年的弦歌。宋真宗御笔赐书“岳麓书院”四字历经多代，清末光绪年间（1903年）与湖南省城大学堂合并为湖南高等学堂 ，1927年定名为湖南大学。很多中学生团队前往参观，令人瞩目的爱国主义教育基地！遗憾的是参观的人太多，拍摄效果欠佳。但心中依然留下了学院风采！' AND c.create_time = '2023-04-20 00:00:00');
