INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存。', 5, '2023-04-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fc2252607b8c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存。' AND c.create_time = '2023-04-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于长沙岳麓山上的岳麓书院，是中国历史悠久的四大古院之一。然后景色优美，文人文气息优秀，非常适合游玩。', 5, '2023-04-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_54fe22db4ae0' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于长沙岳麓山上的岳麓书院，是中国历史悠久的四大古院之一。然后景色优美，文人文气息优秀，非常适合游玩。' AND c.create_time = '2023-04-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '逛岳麓书院必须请个导游讲解，不然很多东西看了也不知道其中的历史和典故。很多人逛完书院看个爱晚亭就走了，其实爬个岳麓山看看景色和其他景点也不错，而且只有300米不会很累，下山还有电瓶车缆车和滑道可选，但节假日人太多必须赶早。', 4, '2023-04-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b2aa79744c15' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '逛岳麓书院必须请个导游讲解，不然很多东西看了也不知道其中的历史和典故。很多人逛完书院看个爱晚亭就走了，其实爬个岳麓山看看景色和其他景点也不错，而且只有300米不会很累，下山还有电瓶车缆车和滑道可选，但节假日人太多必须赶早。' AND c.create_time = '2023-04-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '山下的岳麓书院于北宋兴建，经宋真宗召见岳麓山长周式，御笔赐书&quot;岳麓书院&quot;四字门额，历经南宋、元、明、清各代，至1903年与湖南省城大学堂合并改制为湖南高等学堂，1926年定名湖南大学，仍就书院基址扩建，至今历经千年弦歌不绝，值得一游。 院中仍然保留着祀屈原、周敦颐、二程、朱熹、张拭等历代大儒及著名山长的专祠。', 5, '2023-04-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_327233eac8c4' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '山下的岳麓书院于北宋兴建，经宋真宗召见岳麓山长周式，御笔赐书&quot;岳麓书院&quot;四字门额，历经南宋、元、明、清各代，至1903年与湖南省城大学堂合并改制为湖南高等学堂，1926年定名湖南大学，仍就书院基址扩建，至今历经千年弦歌不绝，值得一游。 院中仍然保留着祀屈原、周敦颐、二程、朱熹、张拭等历代大儒及著名山长的专祠。' AND c.create_time = '2023-04-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国现存最老书院有2000多年的历史，现在的状况和规模都是文革后修善的，文革期间已经破坏殆尽', 5, '2023-04-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_27dedb1350c1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国现存最老书院有2000多年的历史，现在的状况和规模都是文革后修善的，文革期间已经破坏殆尽' AND c.create_time = '2023-04-09 00:00:00');
