INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '坐落于湖南大学旁边的岳麓山中，是四大书院之一，爱晚亭也在此。', 5, '2023-04-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_16d2e9370a8e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '坐落于湖南大学旁边的岳麓山中，是四大书院之一，爱晚亭也在此。' AND c.create_time = '2023-04-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '报的是2点的时间，因为小团要等其他人一起，所以调整到2点30分，等待期间解说小姐姐让我们先去参观博物馆，时间也合适。因当天有当地高中生到岳麓书院学习，所以人山人海的，但是解说小姐姐的解说是超级棒的，并不是背书式的感觉更像老师。解说完还会告知去岳麓山和爱晚亭方向供大家选择，给解说小姐姐点赞，超级好的。', 5, '2023-04-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b8199d85105a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '报的是2点的时间，因为小团要等其他人一起，所以调整到2点30分，等待期间解说小姐姐让我们先去参观博物馆，时间也合适。因当天有当地高中生到岳麓书院学习，所以人山人海的，但是解说小姐姐的解说是超级棒的，并不是背书式的感觉更像老师。解说完还会告知去岳麓山和爱晚亭方向供大家选择，给解说小姐姐点赞，超级好的。' AND c.create_time = '2023-04-04 00:00:00');
