INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '慕名而来，参观游览，体验古代学子孜孜以求，坐而论道，忧国忧民的情怀。', 5, '2023-03-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6233352731f2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '慕名而来，参观游览，体验古代学子孜孜以求，坐而论道，忧国忧民的情怀。' AND c.create_time = '2023-03-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖南岳麓书院是中国历史上赫赫闻名的四大书院之一。作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神，你说值不值得一看呢。', 3, '2023-03-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5eec5aefc8a8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖南岳麓书院是中国历史上赫赫闻名的四大书院之一。作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神，你说值不值得一看呢。' AND c.create_time = '2023-03-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于长沙市的地标性景点岳麓山上的岳麓书院，著名的四大书院之一，从北宋年间传承至今', 5, '2023-03-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8c8c97b54193' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于长沙市的地标性景点岳麓山上的岳麓书院，著名的四大书院之一，从北宋年间传承至今' AND c.create_time = '2023-03-26 00:00:00');
