INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '四大古书院之一，十年前来的时候，赶上修缮，没能进去参观，十年后的今天必须来打卡。旅游旺季，哪里都是人，但是胜在景色迷人，找好拍摄点，也能拍出不少好看的大片', 5, '2023-03-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_409febc48b76' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '四大古书院之一，十年前来的时候，赶上修缮，没能进去参观，十年后的今天必须来打卡。旅游旺季，哪里都是人，但是胜在景色迷人，找好拍摄点，也能拍出不少好看的大片' AND c.create_time = '2023-03-20 00:00:00');
