INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '真的是很棒的一次体验 因为当天中午岳麓山下了大雨，而我是中午1点多预订的产品，商家一直没有确认订单，只好打电话再次确认，商家马上安排了欢欢导游，2点半到达岳麓书院，集结了之后讲解的细致入微，生动有趣，接下来的2个多小时的游览收获满满，连小学生的孩子也听得入了迷，超级推荐！尤其是带孩子一起的！', 5, '2023-02-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b7e93c879bf2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '真的是很棒的一次体验 因为当天中午岳麓山下了大雨，而我是中午1点多预订的产品，商家一直没有确认订单，只好打电话再次确认，商家马上安排了欢欢导游，2点半到达岳麓书院，集结了之后讲解的细致入微，生动有趣，接下来的2个多小时的游览收获满满，连小学生的孩子也听得入了迷，超级推荐！尤其是带孩子一起的！' AND c.create_time = '2023-02-18 00:00:00');
