INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院值得去，可是不要在携程上预定。我花了148元一个人费用和40元的待遇一摸一样，没有半点区别。友情提醒大家千万不要在携程上预定了，免得和我一样被宰。', 1, '2023-01-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7b0f81bdd2b2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院值得去，可是不要在携程上预定。我花了148元一个人费用和40元的待遇一摸一样，没有半点区别。友情提醒大家千万不要在携程上预定了，免得和我一样被宰。' AND c.create_time = '2023-01-26 00:00:00');
