INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院 隶属湖南大学 最早的书院 没有之一', 5, '2023-01-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8dbaf816fe16' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院 隶属湖南大学 最早的书院 没有之一' AND c.create_time = '2023-01-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '我在南山南，水阔云漫漫。 檐上三寸雪，浮世有清欢。 衣襟入林处，潇潇竹亦歇。 数不尽百舸，道不尽呢喃。 潭影日悠悠，湘江空自流。 长沙，有道不尽的历史，看不尽的人文建筑，赏不尽的自然风貌。 在岳麓山，看层林变幻，听泉水叮咚，感受文化山脉的灵气逼仄。 在岳麓书院，感受一代代大家淬炼的生生不息的人文精神。 岳麓书院是我国古代四大书院之一，它历经宋、元、明、清四朝，至1926年定名为湖南大学。它由古代书院到现代大学，一脉相承，弦歌不绝，是湖湘文化的重镇和楚才培养的摇篮在。而今，书院依托湖南大学的现代教育资源与自身厚重的文化底蕴，成功实现古老书院的现代转型，成为从事中国传统文化研究和培养研究型人才的的现代书院，被誉为“千年学府”。 麓山巍巍，湘水悠悠，书院之畔，感受古今名家风范，看文人骚客在湖湘之地吟诵出一行行的千古名句，写下一页页的经典名作。是“才饮长江水，又食武昌鱼”的闲适，是“风清长沙浦，山空云梦田”的感慨，是“叹当年，寂寞贾长沙，伤时哭”的放下。如果是你，站在岳麓山间，你会写下怎样的文字表达对麓山怎样的感情呢？ 📌TIPS： 💰门票：岳麓山免门票，但需要提前预约。进入岳麓书院要门票，40元/人，二者可关注“岳麓山 橘子洲旅游区”公众号进行预约和购票。 📍岳麓山东门是索道所在位置，可购买索道票到达山顶。岳麓书院、爱晚亭在岳麓山的南门。大家可根据自己的偏爱选择从哪个门进入景区。 🍜美食：南门出来有美食小吃街，在这里你可以品尝到长沙的特色小吃：臭豆腐、米粉、糖油粑粑、长沙米粉等等。 🚎交通工具：自驾到酒店，出门坐地铁、公交、骑共享单车、共享电动车，特别方便。长沙交通还是比较拥堵的，有些十字路口每个车道都有各自的交通指示灯，有些路口多个十字打交叉，如果是第一次在长沙市区开车，难免有些懵圈儿。而如果选择公共交通工具出行的话，既方便又节省时间。', 5, '2023-01-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_551f91f0b7f4' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '我在南山南，水阔云漫漫。 檐上三寸雪，浮世有清欢。 衣襟入林处，潇潇竹亦歇。 数不尽百舸，道不尽呢喃。 潭影日悠悠，湘江空自流。 长沙，有道不尽的历史，看不尽的人文建筑，赏不尽的自然风貌。 在岳麓山，看层林变幻，听泉水叮咚，感受文化山脉的灵气逼仄。 在岳麓书院，感受一代代大家淬炼的生生不息的人文精神。 岳麓书院是我国古代四大书院之一，它历经宋、元、明、清四朝，至1926年定名为湖南大学。它由古代书院到现代大学，一脉相承，弦歌不绝，是湖湘文化的重镇和楚才培养的摇篮在。而今，书院依托湖南大学的现代教育资源与自身厚重的文化底蕴，成功实现古老书院的现代转型，成为从事中国传统文化研究和培养研究型人才的的现代书院，被誉为“千年学府”。 麓山巍巍，湘水悠悠，书院之畔，感受古今名家风范，看文人骚客在湖湘之地吟诵出一行行的千古名句，写下一页页的经典名作。是“才饮长江水，又食武昌鱼”的闲适，是“风清长沙浦，山空云梦田”的感慨，是“叹当年，寂寞贾长沙，伤时哭”的放下。如果是你，站在岳麓山间，你会写下怎样的文字表达对麓山怎样的感情呢？ 📌TIPS： 💰门票：岳麓山免门票，但需要提前预约。进入岳麓书院要门票，40元/人，二者可关注“岳麓山 橘子洲旅游区”公众号进行预约和购票。 📍岳麓山东门是索道所在位置，可购买索道票到达山顶。岳麓书院、爱晚亭在岳麓山的南门。大家可根据自己的偏爱选择从哪个门进入景区。 🍜美食：南门出来有美食小吃街，在这里你可以品尝到长沙的特色小吃：臭豆腐、米粉、糖油粑粑、长沙米粉等等。 🚎交通工具：自驾到酒店，出门坐地铁、公交、骑共享单车、共享电动车，特别方便。长沙交通还是比较拥堵的，有些十字路口每个车道都有各自的交通指示灯，有些路口多个十字打交叉，如果是第一次在长沙市区开车，难免有些懵圈儿。而如果选择公共交通工具出行的话，既方便又节省时间。' AND c.create_time = '2023-01-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很不错的一次讲解，趣味和历史性都很强', 5, '2023-01-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f41ad4e73259' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很不错的一次讲解，趣味和历史性都很强' AND c.create_time = '2023-01-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '诺大个校区，停车位无数，居然只知道收门票不知道设置对外停车场，哪怕是收费的，保安给支了个2公里以外的收费停车场，说是附近唯一的一个，让停了车打车去书院，结果在附近500米的地方路遇一停车场，胡大还真是讲人文的“好”地方，比吃饭吃苍蝇还恶心。', 2, '2023-01-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5925e59ab83b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '诺大个校区，停车位无数，居然只知道收门票不知道设置对外停车场，哪怕是收费的，保安给支了个2公里以外的收费停车场，说是附近唯一的一个，让停了车打车去书院，结果在附近500米的地方路遇一停车场，胡大还真是讲人文的“好”地方，比吃饭吃苍蝇还恶心。' AND c.create_time = '2023-01-18 00:00:00');
