INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这里是文化氛围极高的地方，每天游客络绎不绝都是慕名而来的，很多作家都是来自这里，文学底子丰厚，所以到了湖南长沙就会到此一游。', 5, '2023-01-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1039c7a4d4e2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这里是文化氛围极高的地方，每天游客络绎不绝都是慕名而来的，很多作家都是来自这里，文学底子丰厚，所以到了湖南长沙就会到此一游。' AND c.create_time = '2023-01-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院在湖南大学内，门票40元。景区内主要的景点是亭、湖、树、院，其中以爱晚亭最为有名，但爱晚亭的位置在书院北门外（不在书院内）。休闲游还是蛮不错的。北门有上山的电瓶车和去橘子洲的电瓶车，都需要另外买票，去橘子洲的票价为20元。', 4, '2023-01-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2be73b70c656' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院在湖南大学内，门票40元。景区内主要的景点是亭、湖、树、院，其中以爱晚亭最为有名，但爱晚亭的位置在书院北门外（不在书院内）。休闲游还是蛮不错的。北门有上山的电瓶车和去橘子洲的电瓶车，都需要另外买票，去橘子洲的票价为20元。' AND c.create_time = '2023-01-14 00:00:00');
