INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在出口，童车出不去，让这个保安开一下门，很简单的刷一下就好了，他说要等旁边入口20米队伍长的人都进去—再给我开门！简直是太牛逼的景区了，带小孩的不要去了，太不友好了！差评！太给长沙人抹黑了！长沙印象差！', 1, '2023-01-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4d5228ce088f' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在出口，童车出不去，让这个保安开一下门，很简单的刷一下就好了，他说要等旁边入口20米队伍长的人都进去—再给我开门！简直是太牛逼的景区了，带小孩的不要去了，太不友好了！差评！太给长沙人抹黑了！长沙印象差！' AND c.create_time = '2023-01-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于岳麓山的岳麓书院已经有几千年的历史，曾经是湖南，其实，文革当中已经破坏干净了，现在应该是重建的吧？', 5, '2023-01-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_27dedb1350c1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于岳麓山的岳麓书院已经有几千年的历史，曾经是湖南，其实，文革当中已经破坏干净了，现在应该是重建的吧？' AND c.create_time = '2023-01-08 00:00:00');
