INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于湖南长沙岳麓山下，是一个古老的书院。毛泽东主席曾在此读书并留下诗篇。', 5, '2023-01-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e8a384385b3a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于湖南长沙岳麓山下，是一个古老的书院。毛泽东主席曾在此读书并留下诗篇。' AND c.create_time = '2023-01-07 00:00:00');
