INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于湖南大学旁边的岳麓山中，不仅有书院，还有爱晚亭。', 5, '2023-01-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_16d2e9370a8e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于湖南大学旁边的岳麓山中，不仅有书院，还有爱晚亭。' AND c.create_time = '2023-01-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山脚下千年学府，环境静幽，书香四溢，中国四大书院之一。', 5, '2023-01-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8f31baa927d2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山脚下千年学府，环境静幽，书香四溢，中国四大书院之一。' AND c.create_time = '2023-01-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '还不错的景点！在岳麓山上，值得游玩！', 5, '2023-01-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_80389749b939' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '还不错的景点！在岳麓山上，值得游玩！' AND c.create_time = '2023-01-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。岳麓书院历经千年而弦歌不绝，学脉延绵。北宋开宝九年（公元976年），潭州太守朱洞在僧人办学的基础上，由官府捐资兴建，正式创立岳麓书院。北宋祥符八年（公元1015年），宋真宗召见岳麓山长周式，御笔赐书“岳麓书院”四字门额。[1]嗣后，历经南宋、元、明、清各代，至清末光绪廿九年（公元1903年），岳麓书院与湖南省城大学堂合并改制为湖南高等学堂，沿用书院旧址。中华民国15年（公元1926年），湖南高等学堂正式定名湖南大学，仍就书院基址扩建至今。', 5, '2023-01-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_40e42a23cb9b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。岳麓书院历经千年而弦歌不绝，学脉延绵。北宋开宝九年（公元976年），潭州太守朱洞在僧人办学的基础上，由官府捐资兴建，正式创立岳麓书院。北宋祥符八年（公元1015年），宋真宗召见岳麓山长周式，御笔赐书“岳麓书院”四字门额。[1]嗣后，历经南宋、元、明、清各代，至清末光绪廿九年（公元1903年），岳麓书院与湖南省城大学堂合并改制为湖南高等学堂，沿用书院旧址。中华民国15年（公元1926年），湖南高等学堂正式定名湖南大学，仍就书院基址扩建至今。' AND c.create_time = '2023-01-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖湘文化的传承和发源和文脉保存之地！', 4, '2023-01-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9803b3b2220d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖湘文化的传承和发源和文脉保存之地！' AND c.create_time = '2023-01-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，位于湖南省长沙市湘江西岸秀丽的岳麓山下，在湖南大学校园之中，是我国古代著名的“四大书院”之一。书院自北宋创始，历宋、元、明、清各代，兴学不变。随着清末改革学制，废书院，办学堂，辛亥革命后改高等学校等，直至湖南大学，均因旧址扩建，千余年来都是湖南高等学府所在，反映了祖国文教事业的悠久历史，是十分可贵的文物史迹。自上世纪八十年代初岳麓书院经由湖南大学管理和修复以来，书院延续了千年的教育办学和学术研究传统，成为了全国书院中承继其传统功能的典型代表，被外界誉为“千年学府”。', 5, '2023-01-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fab625e389d7' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，位于湖南省长沙市湘江西岸秀丽的岳麓山下，在湖南大学校园之中，是我国古代著名的“四大书院”之一。书院自北宋创始，历宋、元、明、清各代，兴学不变。随着清末改革学制，废书院，办学堂，辛亥革命后改高等学校等，直至湖南大学，均因旧址扩建，千余年来都是湖南高等学府所在，反映了祖国文教事业的悠久历史，是十分可贵的文物史迹。自上世纪八十年代初岳麓书院经由湖南大学管理和修复以来，书院延续了千年的教育办学和学术研究传统，成为了全国书院中承继其传统功能的典型代表，被外界誉为“千年学府”。' AND c.create_time = '2023-01-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '导游小姐姐太专业了，我好喜欢她 她给我们讲解的时候，好多其他游客都要凑过来蹭听 原本以为只是买门票附赠的导游，没想到这么有水平，开心！', 5, '2022-12-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b5298984c543' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '导游小姐姐太专业了，我好喜欢她 她给我们讲解的时候，好多其他游客都要凑过来蹭听 原本以为只是买门票附赠的导游，没想到这么有水平，开心！' AND c.create_time = '2022-12-30 00:00:00');
