INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '潇湘之地长沙旅游必去的地方，岳麓山脚下的岳麓书院享誉古今、名人辈出！儒家思想集大成于此。', 4, '2022-12-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_867687cd9a2c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '潇湘之地长沙旅游必去的地方，岳麓山脚下的岳麓书院享誉古今、名人辈出！儒家思想集大成于此。' AND c.create_time = '2022-12-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这里可观赏的地方不少，只是你要在去之前，大略一下它的历史文化，这样你才能真正的了解岳麓书院的真实原貌和历史沿革。', 3, '2022-12-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5eec5aefc8a8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这里可观赏的地方不少，只是你要在去之前，大略一下它的历史文化，这样你才能真正的了解岳麓书院的真实原貌和历史沿革。' AND c.create_time = '2022-12-26 00:00:00');
