INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院坐落在长沙湘江西岸的岳麓山脚下，是中国历史上赫赫闻名的四大书院之一，始建于北宋，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，是全国重点文物保护单位。走进古色古香的建筑群内，能感受到一股浓浓的中华传统文化的气息。到长沙来旅游，一定要到岳麓书院来看一看。', 5, '2022-05-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b6e822abad36' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院坐落在长沙湘江西岸的岳麓山脚下，是中国历史上赫赫闻名的四大书院之一，始建于北宋，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，是全国重点文物保护单位。走进古色古香的建筑群内，能感受到一股浓浓的中华传统文化的气息。到长沙来旅游，一定要到岳麓书院来看一看。' AND c.create_time = '2022-05-20 00:00:00');
