INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '非常值得一去的书院，后门出去还可以去爬一下岳麓山，见识一下爱晚亭。书院呢，本身就是儒家讲堂，以前阳明先生，朱熹先生，等名家大儒都在这里讲学，里面有一个博物馆，可以去看看，很有哲学，玄学，儒学，入世出世学可以去感悟。', 4, '2021-12-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_75efb391c1e1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '非常值得一去的书院，后门出去还可以去爬一下岳麓山，见识一下爱晚亭。书院呢，本身就是儒家讲堂，以前阳明先生，朱熹先生，等名家大儒都在这里讲学，里面有一个博物馆，可以去看看，很有哲学，玄学，儒学，入世出世学可以去感悟。' AND c.create_time = '2021-12-03 00:00:00');
