INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院地处岳麓山脚下，紧邻中南大学和湖南大学，这里历史文化底蕴丰厚，人文气息浓厚！在这里不仅能与先贤对话，更能与现代学子交流！这里是湖南旅游必须的打卡地！', 5, '2021-10-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_12012b19c0af' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院地处岳麓山脚下，紧邻中南大学和湖南大学，这里历史文化底蕴丰厚，人文气息浓厚！在这里不仅能与先贤对话，更能与现代学子交流！这里是湖南旅游必须的打卡地！' AND c.create_time = '2021-10-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于湖南省长沙市岳麓山脚下的岳麓书院延续历史文脉千年不朽而流传，现在地铁直通岳麓山脚下，可以步行到书院或者穿过湖南大学校园！', 5, '2021-10-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_04a2d022f1fc' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于湖南省长沙市岳麓山脚下的岳麓书院延续历史文脉千年不朽而流传，现在地铁直通岳麓山脚下，可以步行到书院或者穿过湖南大学校园！' AND c.create_time = '2021-10-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【景色】不错 【趣味】还可以 【性价比】值得拥有', 5, '2021-10-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8fa25a28f376' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【景色】不错 【趣味】还可以 【性价比】值得拥有' AND c.create_time = '2021-10-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '终于知道古时候的课为啥不打瞌睡了，如此秀丽的景色，还能顾上打瞌睡吗？走进书院突然故人的精神宛如环绕身边，如果家有青春期的孩子百忙之中一定带孩子来一趟。', 4, '2021-09-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_bdf86f111e5a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '终于知道古时候的课为啥不打瞌睡了，如此秀丽的景色，还能顾上打瞌睡吗？走进书院突然故人的精神宛如环绕身边，如果家有青春期的孩子百忙之中一定带孩子来一趟。' AND c.create_time = '2021-09-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '携家赴湘的次日,行程直接指向岳簏山,步入湖南大学才知晓岳簏山由于疫情暂停开放,于是无奈拾步上山,想既然来一次岳簏,总得留下一些记忆。岳麓书院是封闭状态的,疫情缘故也无可厚非,于是在户外、门口和后山不同角度,取景拍了一些视角。 数年前来过岳麓书院,端的是华中文胆之地,道不尽千古风流人物在这里留下诸多精彩,都是文化界无法复制与超越的丰碑。', 4, '2021-09-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_109307fb10e4' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '携家赴湘的次日,行程直接指向岳簏山,步入湖南大学才知晓岳簏山由于疫情暂停开放,于是无奈拾步上山,想既然来一次岳簏,总得留下一些记忆。岳麓书院是封闭状态的,疫情缘故也无可厚非,于是在户外、门口和后山不同角度,取景拍了一些视角。 数年前来过岳麓书院,端的是华中文胆之地,道不尽千古风流人物在这里留下诸多精彩,都是文化界无法复制与超越的丰碑。' AND c.create_time = '2021-09-27 00:00:00');
