INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '景色还不错，整体来说环境还不错的。', 5, '2021-09-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fe03cee9b763' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '景色还不错，整体来说环境还不错的。' AND c.create_time = '2021-09-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。', 5, '2021-09-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_82f6ddac299f' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。' AND c.create_time = '2021-09-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙的景点之一，可以去看看，几大书院之一', 5, '2021-09-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_401ead4c4e67' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙的景点之一，可以去看看，几大书院之一' AND c.create_time = '2021-09-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '历史文化名城长沙的名胜古迹，四大书院之一，因坐落在岳麓山下而得名，最古老的学府之一。到了长沙一定要去游览下，去感受历史。', 5, '2021-09-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_bb162991abc7' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '历史文化名城长沙的名胜古迹，四大书院之一，因坐落在岳麓山下而得名，最古老的学府之一。到了长沙一定要去游览下，去感受历史。' AND c.create_time = '2021-09-16 00:00:00');
