INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。1986年湖南大学宣布完成修复岳麓书院，并正式对外开放。 2005年湖南大学正式恢复岳麓书院，下设中国哲学研究所、历史研究所、中国思想文化研究所、中国书院研究中心和中国软实力文化研究中心等多个部门。 2009年岳麓书院学科从本科、硕士研究生、博士研究生到博士后科研流动站的格局已经完备。正式成为为湖南大学的实体办学机构和科研基地，千年学脉再次延绵，千年学府再添光辉。 今天的岳麓书院不仅是湖南大学的文史哲人才培养和研究基地，湖南省旅游胜地，更是是整个长沙市的文化窗口和文化名片。', 4, '2021-09-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1b27c0d76942' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。1986年湖南大学宣布完成修复岳麓书院，并正式对外开放。 2005年湖南大学正式恢复岳麓书院，下设中国哲学研究所、历史研究所、中国思想文化研究所、中国书院研究中心和中国软实力文化研究中心等多个部门。 2009年岳麓书院学科从本科、硕士研究生、博士研究生到博士后科研流动站的格局已经完备。正式成为为湖南大学的实体办学机构和科研基地，千年学脉再次延绵，千年学府再添光辉。 今天的岳麓书院不仅是湖南大学的文史哲人才培养和研究基地，湖南省旅游胜地，更是是整个长沙市的文化窗口和文化名片。' AND c.create_time = '2021-09-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '保护比较完整的古建筑，地处幽静的岳麓山下，带着浓浓的书香气息，值得去看看。', 5, '2021-09-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_16ee9c2dd741' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '保护比较完整的古建筑，地处幽静的岳麓山下，带着浓浓的书香气息，值得去看看。' AND c.create_time = '2021-09-02 00:00:00');
