INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国历史上四大书院之一，历经千年而学脉延绵。', 5, '2021-08-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_48f09af00016' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国历史上四大书院之一，历经千年而学脉延绵。' AND c.create_time = '2021-08-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '盛名之下，其实难副。来到这个地方之前也略微了解了一下，实际进来之后，发现完全没有想象中的那么好，确实有一些人文古迹，但也就仅限于山门一线，往里走不少都是后修的。整体感觉没有把岳麓书院这么好的历史展现出来。', 5, '2021-08-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_60485be67121' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '盛名之下，其实难副。来到这个地方之前也略微了解了一下，实际进来之后，发现完全没有想象中的那么好，确实有一些人文古迹，但也就仅限于山门一线，往里走不少都是后修的。整体感觉没有把岳麓书院这么好的历史展现出来。' AND c.create_time = '2021-08-21 00:00:00');
