INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院在岳麓山南门里，暑假期间游客特多，建议不要这个时候来旅游，到处人挤人，根本不能好好欣赏千年书院的风景和体味文化。', 3, '2021-07-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_83b738b55712' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院在岳麓山南门里，暑假期间游客特多，建议不要这个时候来旅游，到处人挤人，根本不能好好欣赏千年书院的风景和体味文化。' AND c.create_time = '2021-07-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '实事求是，从这里发扬光大。中国四大书院之一，湖南大学的前身，毛主席曾经在这里学习一年半的时间', 4, '2021-07-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_17abcd183a0a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '实事求是，从这里发扬光大。中国四大书院之一，湖南大学的前身，毛主席曾经在这里学习一年半的时间' AND c.create_time = '2021-07-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国四大书院的岳麓书院坐落在岳麓山下，人杰地灵，一踏入大门，古木参天，花草扶疏，浓厚的文化底蕴就扑面而来。看看书院的历史沿革，沿着碑廊发思古之幽情，心灵沉静。', 5, '2021-07-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_eb9caddccd86' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国四大书院的岳麓书院坐落在岳麓山下，人杰地灵，一踏入大门，古木参天，花草扶疏，浓厚的文化底蕴就扑面而来。看看书院的历史沿革，沿着碑廊发思古之幽情，心灵沉静。' AND c.create_time = '2021-07-20 00:00:00');
