INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这个地方的门票还是五十块钱，岳麓书院的定价什么时候可以便宜一些，以前进去过两次了，这次就门口看看可以了，一直进去钱包也是吃不消的，除非哪天十块钱了我再进去吧。绿树成荫环境不错，可以吸收大自然的味道，拍拍照片。', 4, '2021-06-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这个地方的门票还是五十块钱，岳麓书院的定价什么时候可以便宜一些，以前进去过两次了，这次就门口看看可以了，一直进去钱包也是吃不消的，除非哪天十块钱了我再进去吧。绿树成荫环境不错，可以吸收大自然的味道，拍拍照片。' AND c.create_time = '2021-06-27 00:00:00');
