INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院真是棒极了，美中不足就是排队太久，整整3个小时', 5, '2021-06-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_29e050c4be0c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院真是棒极了，美中不足就是排队太久，整整3个小时' AND c.create_time = '2021-06-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，是世界上最古老的学府之一，其中便有“停车坐爱枫林晚，霜叶红于二月花”的爱晚亭。', 5, '2021-06-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fba542c3c8ea' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，是世界上最古老的学府之一，其中便有“停车坐爱枫林晚，霜叶红于二月花”的爱晚亭。' AND c.create_time = '2021-06-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。1988年，岳麓书院建筑群被国务院批准为全国重点文物保护单位。 因岳麓书院在今湖南大学校园内，湖南大学声称岳麓书院是其前身，因此自己是世界上最古老的大学。并用岳麓书院作为其办学实体机构的名称。', 5, '2021-06-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9f5e6b5ec852' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。1988年，岳麓书院建筑群被国务院批准为全国重点文物保护单位。 因岳麓书院在今湖南大学校园内，湖南大学声称岳麓书院是其前身，因此自己是世界上最古老的大学。并用岳麓书院作为其办学实体机构的名称。' AND c.create_time = '2021-06-16 00:00:00');
