INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年学府值得一去。亭台楼阁风景秀丽。', 5, '2021-05-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ec58f1426352' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年学府值得一去。亭台楼阁风景秀丽。' AND c.create_time = '2021-05-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '巍巍学府，栉风沐雨；薪火相传，弦歌不辍。书院历经宋元明清数代，一直是儒家教育的圣地和文化学术的中心。作为湖湘文化的策源地，一直秉承传道济民、经世致用的教育思想，重践履、务实行的优良学风和心忧天下、敢为人先的爱国精神。', 5, '2021-05-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_31a88c23afd4' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '巍巍学府，栉风沐雨；薪火相传，弦歌不辍。书院历经宋元明清数代，一直是儒家教育的圣地和文化学术的中心。作为湖湘文化的策源地，一直秉承传道济民、经世致用的教育思想，重践履、务实行的优良学风和心忧天下、敢为人先的爱国精神。' AND c.create_time = '2021-05-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '到了长沙来感受一下岳麓书院的氛围，心情平静书阔，非常好！', 5, '2021-05-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_faba9ea78304' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '到了长沙来感受一下岳麓书院的氛围，心情平静书阔，非常好！' AND c.create_time = '2021-05-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '因为去了岳麓山，看到了岳麓书院，既然名气那么大，就去看看呗，在没什么准备就去看的情况下，我觉得就是走马观花，看看建筑看看园子，以及旁边的湖南大学。', 3, '2021-05-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7d09cf556032' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '因为去了岳麓山，看到了岳麓书院，既然名气那么大，就去看看呗，在没什么准备就去看的情况下，我觉得就是走马观花，看看建筑看看园子，以及旁边的湖南大学。' AND c.create_time = '2021-05-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '门票50元，有点小贵，不过不买门票，可以爬岳麓山，远眺。', 3, '2021-05-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c35b162ad48a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '门票50元，有点小贵，不过不买门票，可以爬岳麓山，远眺。' AND c.create_time = '2021-05-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '非常值得去的一个好地方！下次领着孙女去！', 5, '2021-05-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4a10500ad471' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '非常值得去的一个好地方！下次领着孙女去！' AND c.create_time = '2021-05-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于长沙岳麓山脚下，是中国四大书院之一。交通很方便，可以坐地铁直达。岳麓书院现在是湖南大学的一部分，所以下地铁后会先经过湖南大学的校园，然后走一小段山路便可到达。岳麓书院比嵩阳书院略大，因为地处南方，整个书院感觉更绿，水也更多。虽说书院始建于北宋，但北宋的建筑已经荡然无存，但这并不影响到它的美！宋代理学家朱熹曾今到访此院，更让书院蓬荜生辉！', 5, '2021-05-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_de67df8869a8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于长沙岳麓山脚下，是中国四大书院之一。交通很方便，可以坐地铁直达。岳麓书院现在是湖南大学的一部分，所以下地铁后会先经过湖南大学的校园，然后走一小段山路便可到达。岳麓书院比嵩阳书院略大，因为地处南方，整个书院感觉更绿，水也更多。虽说书院始建于北宋，但北宋的建筑已经荡然无存，但这并不影响到它的美！宋代理学家朱熹曾今到访此院，更让书院蓬荜生辉！' AND c.create_time = '2021-05-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年学府，古色古香。。。。，，', 5, '2021-05-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e2ee8604bade' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年学府，古色古香。。。。，，' AND c.create_time = '2021-05-04 00:00:00');
