INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院现金收费员一点职业素养都没有，多问两句全票和半票不耐烦，沟通有障碍，一句半票针对学生党完事，非要抱怨说话累收费累，冲游客发脾气。外面学党史和书院感觉就是个笑话。差评，徒有其表。', 1, '2021-05-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7a1847484afc' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院现金收费员一点职业素养都没有，多问两句全票和半票不耐烦，沟通有障碍，一句半票针对学生党完事，非要抱怨说话累收费累，冲游客发脾气。外面学党史和书院感觉就是个笑话。差评，徒有其表。' AND c.create_time = '2021-05-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '藏于闹市区的文坛圣地。景色非常美，没有开滤镜，真的张张都是画', 4, '2021-05-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8969b99c01b6' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '藏于闹市区的文坛圣地。景色非常美，没有开滤镜，真的张张都是画' AND c.create_time = '2021-05-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【性价比】来到四大书院之一，肯定不可能用性价比来衡量。 【岳麓书院】 中国四大名院之一，来长沙感受一下这千年学府，名人雅士深山求学之路。 从书院出来感觉到自己书香味都浓了不少。[偷笑]', 4, '2021-05-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_805866ffe6ce' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【性价比】来到四大书院之一，肯定不可能用性价比来衡量。 【岳麓书院】 中国四大名院之一，来长沙感受一下这千年学府，名人雅士深山求学之路。 从书院出来感觉到自己书香味都浓了不少。[偷笑]' AND c.create_time = '2021-05-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，位于湖南省长沙市湘江西岸的国家5A级风景名胜岳麓山风景区，为中国古代著名四大书院之一；1988年，岳麓书院建筑群被国务院批准为第三批国家重点文物保护单位！', 5, '2021-04-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4e6f4b9fbaa5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，位于湖南省长沙市湘江西岸的国家5A级风景名胜岳麓山风景区，为中国古代著名四大书院之一；1988年，岳麓书院建筑群被国务院批准为第三批国家重点文物保护单位！' AND c.create_time = '2021-04-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这里是古代大家的讲学传道之地，学府大家', 4, '2021-04-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8a91d4e8691e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这里是古代大家的讲学传道之地，学府大家' AND c.create_time = '2021-04-21 00:00:00');
