INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，中国历史上很著名的书院', 5, '2021-04-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fa503dcdce4f' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，中国历史上很著名的书院' AND c.create_time = '2021-04-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【景色】就在城边，去游时细雨蒙蒙 ，别有风味。也看到了红叶。 【趣味】挺好 【性价比】很好', 5, '2021-04-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ec4f76c5ec15' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【景色】就在城边，去游时细雨蒙蒙 ，别有风味。也看到了红叶。 【趣味】挺好 【性价比】很好' AND c.create_time = '2021-04-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，中国最著名“四大书院”之一，也是我国保存最为完整的一座古代书院。感觉里边是有点“小江南”风格的。岳麓书院占地面积非常大，现存建筑大多为明清遗物。', 5, '2021-04-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_60b7ee2cac9c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，中国最著名“四大书院”之一，也是我国保存最为完整的一座古代书院。感觉里边是有点“小江南”风格的。岳麓书院占地面积非常大，现存建筑大多为明清遗物。' AND c.create_time = '2021-04-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖南大学，千年书院，文化底蕴浓厚', 5, '2021-04-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fd80030885db' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖南大学，千年书院，文化底蕴浓厚' AND c.create_time = '2021-04-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年学府，蔚为壮观。可以切身感受一下，当年的学子们是在什么环境下学习的。周围的环境很不错，学堂被山林环绕，确实适合是个静下心来学习的地方。', 5, '2021-04-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_40f9cb15970c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年学府，蔚为壮观。可以切身感受一下，当年的学子们是在什么环境下学习的。周围的环境很不错，学堂被山林环绕，确实适合是个静下心来学习的地方。' AND c.create_time = '2021-04-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '凡是古迹，如果不想做功课，请一个游很有必要，岳麓书院保存修缮的非常完好，比其它书院保存的更加好、更加新，院内许多石碑，喜爱书法的朋友可以多做停留。', 5, '2021-04-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a0fc9824d25c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '凡是古迹，如果不想做功课，请一个游很有必要，岳麓书院保存修缮的非常完好，比其它书院保存的更加好、更加新，院内许多石碑，喜爱书法的朋友可以多做停留。' AND c.create_time = '2021-04-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国四大书院之一，位于岳麓山风景区内，历史已逾千年。岳麓书院还以保存大量的碑匾文物闻名于世，如唐刻“麓山寺碑”，还有明刻宋真宗手书“岳麓书院”石碑等。书院后山青枫峡的小山上，建有爱晚亭，是毛泽东主席青年时代常去的地方。', 5, '2021-04-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9cd0346ee6a6' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国四大书院之一，位于岳麓山风景区内，历史已逾千年。岳麓书院还以保存大量的碑匾文物闻名于世，如唐刻“麓山寺碑”，还有明刻宋真宗手书“岳麓书院”石碑等。书院后山青枫峡的小山上，建有爱晚亭，是毛泽东主席青年时代常去的地方。' AND c.create_time = '2021-04-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '本是山下一角，被割去一块建造了书院，一不小心就成为了四大书院之一，真厉害！ 到底是书院，景致比山上精细太多，门口的一排翠竹和后院的小荷才露尖尖角尤其明媚，道不尽的风情阅不尽的书生意气，挥斥方遒！ 后面的中国书画博物馆，名字很响亮，藏品一般，一带而过就好。', 5, '2021-04-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c220f00af379' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '本是山下一角，被割去一块建造了书院，一不小心就成为了四大书院之一，真厉害！ 到底是书院，景致比山上精细太多，门口的一排翠竹和后院的小荷才露尖尖角尤其明媚，道不尽的风情阅不尽的书生意气，挥斥方遒！ 后面的中国书画博物馆，名字很响亮，藏品一般，一带而过就好。' AND c.create_time = '2021-04-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙岳麓书院是中国古代四大书院之一。', 4, '2021-04-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b7d262692c4b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙岳麓书院是中国古代四大书院之一。' AND c.create_time = '2021-04-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '历史厚重感。聆听古人留下的心声。', 5, '2021-04-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b5cb2ac20600' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '历史厚重感。聆听古人留下的心声。' AND c.create_time = '2021-04-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国古代著名四大书院之一，千年历史。', 5, '2021-04-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_48f09af00016' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国古代著名四大书院之一，千年历史。' AND c.create_time = '2021-04-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖南大学岳麓书院位于湖南省长沙市湘江西岸的国家5A级风景名胜岳麓山风景区，为中国古代著名四大书院之一，始建于北宋开宝九年（公元976年），一千余年来，这所誉满海内外的著名学府，历经宋、元、明、清时势变迁，迨及晚清（公元1903年）改制为湖南高等学堂，1926年正式定名为湖南大学。“千年学府，弦歌不绝”。1984年成立岳麓书院文化研究所，此后相继获得历史学硕士、博士、中国哲学博士学位授予权。2005年，改岳麓书院文化研究所为岳麓书院。如今，岳麓书院为湖南大学下辖哲学系（宗教学系）、历史学系和考古文博学系三大教学单位。', 5, '2021-03-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9cd0346ee6a6' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖南大学岳麓书院位于湖南省长沙市湘江西岸的国家5A级风景名胜岳麓山风景区，为中国古代著名四大书院之一，始建于北宋开宝九年（公元976年），一千余年来，这所誉满海内外的著名学府，历经宋、元、明、清时势变迁，迨及晚清（公元1903年）改制为湖南高等学堂，1926年正式定名为湖南大学。“千年学府，弦歌不绝”。1984年成立岳麓书院文化研究所，此后相继获得历史学硕士、博士、中国哲学博士学位授予权。2005年，改岳麓书院文化研究所为岳麓书院。如今，岳麓书院为湖南大学下辖哲学系（宗教学系）、历史学系和考古文博学系三大教学单位。' AND c.create_time = '2021-03-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是湖南大学的文史哲人才培养和研究基地，也是湖南省旅游胜地，也是长沙的城市名片。岳麓书院是历史上四大书院之一，坐落于湖南长沙湘江西岸的岳麓山脚下，是世界上最古老的学府之一。', 5, '2021-03-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8661760db693' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是湖南大学的文史哲人才培养和研究基地，也是湖南省旅游胜地，也是长沙的城市名片。岳麓书院是历史上四大书院之一，坐落于湖南长沙湘江西岸的岳麓山脚下，是世界上最古老的学府之一。' AND c.create_time = '2021-03-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是四大书院之一，坐落于湖南长沙湘江西岸的岳麓山脚下，是世界上最古老的学府之一。如今的岳麓书院不仅是湖南大学的文史哲人才培养和研究基地，也是湖南省旅游胜地。', 5, '2021-03-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ebf93d708d4b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是四大书院之一，坐落于湖南长沙湘江西岸的岳麓山脚下，是世界上最古老的学府之一。如今的岳麓书院不仅是湖南大学的文史哲人才培养和研究基地，也是湖南省旅游胜地。' AND c.create_time = '2021-03-27 00:00:00');
