INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【景色】岳麓书院是中国历史上著名的四大书院之一，位于岳麓山风景区内，以保存大量的碑匾文物闻名于世，书院后山青枫峡的小山上，建有爱晚亭，是毛泽东青年时代常去的地方。 【趣味】书香气息浓郁', 5, '2021-03-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cf5b8320276f' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【景色】岳麓书院是中国历史上著名的四大书院之一，位于岳麓山风景区内，以保存大量的碑匾文物闻名于世，书院后山青枫峡的小山上，建有爱晚亭，是毛泽东青年时代常去的地方。 【趣味】书香气息浓郁' AND c.create_time = '2021-03-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这就是中国最好的历史书院职教城', 4, '2021-03-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8a91d4e8691e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这就是中国最好的历史书院职教城' AND c.create_time = '2021-03-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国四大书院之一，就在湖南大学片区内，建筑古色古香很有一番风味', 5, '2021-03-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_60912618246e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国四大书院之一，就在湖南大学片区内，建筑古色古香很有一番风味' AND c.create_time = '2021-03-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。 关于“四大书院”有多种说法，但唯有岳麓为诸家共推，反映了古之学者对岳麓的推崇。', 5, '2021-03-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c83ba13ab8ff' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。 关于“四大书院”有多种说法，但唯有岳麓为诸家共推，反映了古之学者对岳麓的推崇。' AND c.create_time = '2021-03-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是湖湘文化的地标和高地，到长沙不到岳麓书院，就等于到北京不到故宫一样。 岳麓书院里面有中国书院博物馆，陈列介绍了书院的发展历史。', 5, '2021-03-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_630091f8b248' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是湖湘文化的地标和高地，到长沙不到岳麓书院，就等于到北京不到故宫一样。 岳麓书院里面有中国书院博物馆，陈列介绍了书院的发展历史。' AND c.create_time = '2021-03-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '书院很不错，这里并不仅仅是枯燥的建筑，里面还有个书院博物馆，可以大体了解一下书院的历史。书院内的建筑有些是开放的，里面还有关于名人的介绍。', 5, '2021-03-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_40f9cb15970c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '书院很不错，这里并不仅仅是枯燥的建筑，里面还有个书院博物馆，可以大体了解一下书院的历史。书院内的建筑有些是开放的，里面还有关于名人的介绍。' AND c.create_time = '2021-03-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国四大书院之一，在岳麓山上，环境优美，交通方便，古色古香，书香气息十足。', 4, '2021-02-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5960b8b674ba' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国四大书院之一，在岳麓山上，环境优美，交通方便，古色古香，书香气息十足。' AND c.create_time = '2021-02-28 00:00:00');
