INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很美，很有名的书院，在山中，特别是夏天也是避暑胜地，很喜欢', 5, '2021-01-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_312f8b400c38' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很美，很有名的书院，在山中，特别是夏天也是避暑胜地，很喜欢' AND c.create_time = '2021-01-29 00:00:00');
