INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '历史上很著名的书院，久仰大名，今天总算见识到了。', 5, '2021-01-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b1b77f942a96' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '历史上很著名的书院，久仰大名，今天总算见识到了。' AND c.create_time = '2021-01-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '非常有名的岳麓书院，&#39;在岳麓山下，景色非常不错~尤其是雨中漫步，很美~', 3, '2021-01-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dcfa5621e44e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '非常有名的岳麓书院，&#39;在岳麓山下，景色非常不错~尤其是雨中漫步，很美~' AND c.create_time = '2021-01-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙“千年学府”【岳麓书院】宋代四大学府之冠，最引人注目是书院大门一副楹联“惟楚有才，于斯为盛”。上联清代嘉庆年间岳麓书院院长所出，下联当时书院一位学生所对，两句风别出自《左传》和《论语》。', 5, '2021-01-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_31cf4fec11c2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙“千年学府”【岳麓书院】宋代四大学府之冠，最引人注目是书院大门一副楹联“惟楚有才，于斯为盛”。上联清代嘉庆年间岳麓书院院长所出，下联当时书院一位学生所对，两句风别出自《左传》和《论语》。' AND c.create_time = '2021-01-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '我国著名的书院之一，去熏陶一下不错的', 4, '2021-01-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_96e7a166d167' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '我国著名的书院之一，去熏陶一下不错的' AND c.create_time = '2021-01-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '大名鼎鼎的岳麓书院，是中国四大书院之一，坐落于湖南大学旁边。因年代比较久远，书院里面略显萧条，有些地方感觉有些破旧。但是一进书院还是有浓浓的书香气，虽然游客如织，但书院还是给人一种历久弥香的感觉。里面完全保留了中国古代建筑和院落错落有致的风格，层次分明，一进一进的格局，有很多古代文人都曾在这里读过书，所以里面有很多关于文人雅客的介绍和资料，可以称的上是一个古代文人历史资料的博物院。虽然路途不是很通畅，七拐八弯地不太好找，但感觉还是比较值得去看的。门票价格也不贵，不能从网上买，只能到书院门口买票。个人觉得性价比还是挺高的。因为跟湖南大学比邻而居，所以出书院的门就需要穿过湖南大学，还可以顺便去湖南大学看看，感受一下高等学府的氛围，一举两得。不过最好是早做安排，一早去，这样出来的时候时间会相对充裕一些。', 5, '2021-01-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_16ee9c2dd741' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '大名鼎鼎的岳麓书院，是中国四大书院之一，坐落于湖南大学旁边。因年代比较久远，书院里面略显萧条，有些地方感觉有些破旧。但是一进书院还是有浓浓的书香气，虽然游客如织，但书院还是给人一种历久弥香的感觉。里面完全保留了中国古代建筑和院落错落有致的风格，层次分明，一进一进的格局，有很多古代文人都曾在这里读过书，所以里面有很多关于文人雅客的介绍和资料，可以称的上是一个古代文人历史资料的博物院。虽然路途不是很通畅，七拐八弯地不太好找，但感觉还是比较值得去看的。门票价格也不贵，不能从网上买，只能到书院门口买票。个人觉得性价比还是挺高的。因为跟湖南大学比邻而居，所以出书院的门就需要穿过湖南大学，还可以顺便去湖南大学看看，感受一下高等学府的氛围，一举两得。不过最好是早做安排，一早去，这样出来的时候时间会相对充裕一些。' AND c.create_time = '2021-01-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。', 5, '2021-01-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_82f605dec700' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。' AND c.create_time = '2021-01-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖南长沙岳麓书院我个人第二次去，感觉依旧不错，游客比较少，体验感觉不错！这次跟在个岳麓书院老师后面听讲解，学到很多知识！几块牌匾都具有历史价值，建筑风格很有特色，岳麓书院里还有一个中国书院博物馆，很值得一看！', 5, '2021-01-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖南长沙岳麓书院我个人第二次去，感觉依旧不错，游客比较少，体验感觉不错！这次跟在个岳麓书院老师后面听讲解，学到很多知识！几块牌匾都具有历史价值，建筑风格很有特色，岳麓书院里还有一个中国书院博物馆，很值得一看！' AND c.create_time = '2021-01-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国古代的四大书院之一，岳麓书院。 位于湖南长沙，就在湖南大学旁边，坐地铁到湖南大学站下来，经过学校门口就到了。 很不错的地方，可以静静地参观一，两个小时，感受一下气氛。', 4, '2021-01-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_29a27396da91' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国古代的四大书院之一，岳麓书院。 位于湖南长沙，就在湖南大学旁边，坐地铁到湖南大学站下来，经过学校门口就到了。 很不错的地方，可以静静地参观一，两个小时，感受一下气氛。' AND c.create_time = '2021-01-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '走马观花，岳麓书院比想象中的美~。 【趣味】我们于日用必需的东西以外， 必须还有一点无用的冥思， 诸如喝茶、谈天、听取竹林的微风， 生活才觉得有意思。', 4, '2021-01-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d6f3ac6ec56b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '走马观花，岳麓书院比想象中的美~。 【趣味】我们于日用必需的东西以外， 必须还有一点无用的冥思， 诸如喝茶、谈天、听取竹林的微风， 生活才觉得有意思。' AND c.create_time = '2021-01-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '无论岁月过去多少年，现在依然无法阻挡它的魅力', 5, '2020-12-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d733fb230f27' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '无论岁月过去多少年，现在依然无法阻挡它的魅力' AND c.create_time = '2020-12-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是湖南大学的一个学院，学院仅三百多名学生，但老师就有八十多名，去了岳麓书院一定要请个导游，听听她们的讲解，你才能对书院有进一步的了解', 5, '2020-12-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9716a74321ed' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是湖南大学的一个学院，学院仅三百多名学生，但老师就有八十多名，去了岳麓书院一定要请个导游，听听她们的讲解，你才能对书院有进一步的了解' AND c.create_time = '2020-12-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院不大，就在岳麓山下，门票40，一年当中就深秋时节最适合，枫叶红了，拍照也好看', 5, '2020-12-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_bdafe6bce6af' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院不大，就在岳麓山下，门票40，一年当中就深秋时节最适合，枫叶红了，拍照也好看' AND c.create_time = '2020-12-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '超级不错哟，去岳麓山不得不去的一个地方。', 5, '2020-12-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0530995e05ad' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '超级不错哟，去岳麓山不得不去的一个地方。' AND c.create_time = '2020-12-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院历史上经历多次战火，曾七毁七建，现存主要建筑是清朝遗构。20世纪以来，经过几次大修，一些毁于战火的建筑得到了重修。岳麓书院古建筑在布局上采用中轴对称、纵深多进的院落形式。主体建筑如头门、大门、二门、讲堂、御书楼集中于中轴线上，讲堂布置在中轴线的中央。斋舍、祭祀专祠等排列于两旁。中轴对称、层层递进的院落，除了营造一种庄严、神妙、幽远的纵深感和视觉效应之外，还体现了儒家文化尊卑有序、等级有别、主次鲜明的社会伦理关系。', 3, '2020-12-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_85cbc0b3e6d1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院历史上经历多次战火，曾七毁七建，现存主要建筑是清朝遗构。20世纪以来，经过几次大修，一些毁于战火的建筑得到了重修。岳麓书院古建筑在布局上采用中轴对称、纵深多进的院落形式。主体建筑如头门、大门、二门、讲堂、御书楼集中于中轴线上，讲堂布置在中轴线的中央。斋舍、祭祀专祠等排列于两旁。中轴对称、层层递进的院落，除了营造一种庄严、神妙、幽远的纵深感和视觉效应之外，还体现了儒家文化尊卑有序、等级有别、主次鲜明的社会伦理关系。' AND c.create_time = '2020-12-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国古代四大书院之一，历史悠久，底蕴深厚，最有名的一副对联是“惟楚有材 于斯为盛”，其实就在湖南大学校园里，多个出入口可进入。书院内建筑白墙黛瓦，古木参天，曲径通幽，环境十分幽静。', 5, '2020-12-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4e6d22f0cda0' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国古代四大书院之一，历史悠久，底蕴深厚，最有名的一副对联是“惟楚有材 于斯为盛”，其实就在湖南大学校园里，多个出入口可进入。书院内建筑白墙黛瓦，古木参天，曲径通幽，环境十分幽静。' AND c.create_time = '2020-12-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是长沙市区的著名景点，距离市区非常方便。位于湘江西岸的岳麓山东面山下，是中国古代传统书院建筑，属于中国历史上著名的四大书院之一。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。', 4, '2020-12-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_338634f69b51' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是长沙市区的著名景点，距离市区非常方便。位于湘江西岸的岳麓山东面山下，是中国古代传统书院建筑，属于中国历史上著名的四大书院之一。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。' AND c.create_time = '2020-12-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山下，岳麓书院，千年历史，传承文化，惟楚有材，于斯为盛，潇湘槐市，实事求是。', 5, '2020-12-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7e98a7695e7c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山下，岳麓书院，千年历史，传承文化，惟楚有材，于斯为盛，潇湘槐市，实事求是。' AND c.create_time = '2020-12-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国的四大书院有天府书院，岳麓书院，白鹿洞书院，嵩阳书院，岳麓书院作为世界上最古老的学府之一，其古代传统的书院建筑至今仍被完整保存。', 4, '2020-12-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c37100a9d8b2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国的四大书院有天府书院，岳麓书院，白鹿洞书院，嵩阳书院，岳麓书院作为世界上最古老的学府之一，其古代传统的书院建筑至今仍被完整保存。' AND c.create_time = '2020-12-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山脚下，湖南大学内有著名的千年学府岳麓书院！这里故色古香，了解古代书院历史的好地方！一砖一瓦见证了中华文化的传承！值得推荐！', 5, '2020-12-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_069360d314cb' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山脚下，湖南大学内有著名的千年学府岳麓书院！这里故色古香，了解古代书院历史的好地方！一砖一瓦见证了中华文化的传承！值得推荐！' AND c.create_time = '2020-12-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '非常古老有历史有文化的地方。青山之间。', 5, '2020-11-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1b95855d86bb' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '非常古老有历史有文化的地方。青山之间。' AND c.create_time = '2020-11-29 00:00:00');
