INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上著名的四大书院之一，位于岳麓山风景区内，以保存大量的碑匾文物闻名于世，书院后山青枫峡的小山上，建有爱晚亭，是毛泽东青年时代常去的地方。', 4, '2020-11-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_28571e9dca2e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上著名的四大书院之一，位于岳麓山风景区内，以保存大量的碑匾文物闻名于世，书院后山青枫峡的小山上，建有爱晚亭，是毛泽东青年时代常去的地方。' AND c.create_time = '2020-11-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙岳麓山下岳麓书院~~~~枫叶红与二月🌸，秋天景色很美~~~~', 3, '2020-11-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dcfa5621e44e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙岳麓山下岳麓书院~~~~枫叶红与二月🌸，秋天景色很美~~~~' AND c.create_time = '2020-11-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '感受文化自信的自然提现，体会先辈学习的状态！值得一看的四大书院之一的岳麓书院！', 5, '2020-11-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8753f35e6e80' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '感受文化自信的自然提现，体会先辈学习的状态！值得一看的四大书院之一的岳麓书院！' AND c.create_time = '2020-11-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中國千年學府，嶽麓書院坐落在岳麓山腳下，靜靜的沉積了中國文教歷史的韻味，每個朝代的歷史特色，由湖南大學接手管理之後也讓湖南大學銜接了千年學府的名號且傳承下去', 5, '2020-11-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5f1c92f76491' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中國千年學府，嶽麓書院坐落在岳麓山腳下，靜靜的沉積了中國文教歷史的韻味，每個朝代的歷史特色，由湖南大學接手管理之後也讓湖南大學銜接了千年學府的名號且傳承下去' AND c.create_time = '2020-11-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '惟楚有材，于斯为盛。在中国历史的人才培养史上，岳麓书院书写了浓墨重彩的一笔。自北宋建院以来，每个时代都有其重要代表人物，特别是晚清重臣曾国藩，更是在千疮百孔的清朝撑起了一方天地，为中国的近现代化发展做出了非常大的贡献。 如今，湖南大学喜欢把自己称作“千年学府”，虽有夸大宣传之意，但事实上也无可厚非。岳麓书院属于古代官办“高校”，直至清末，与省内大学堂合并组成湖南大学前身，民国时期改名为湖南大学。如今湖大恢复了岳麓书院，实为一个学院，主要涵盖国学、历史学、哲学等学科，也有了现代意义上的党委书记、院长等。但不影响我们来探究岳麓书院的文化底蕴，瞻仰书院的极致高远。', 5, '2020-11-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6a6f66d18377' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '惟楚有材，于斯为盛。在中国历史的人才培养史上，岳麓书院书写了浓墨重彩的一笔。自北宋建院以来，每个时代都有其重要代表人物，特别是晚清重臣曾国藩，更是在千疮百孔的清朝撑起了一方天地，为中国的近现代化发展做出了非常大的贡献。 如今，湖南大学喜欢把自己称作“千年学府”，虽有夸大宣传之意，但事实上也无可厚非。岳麓书院属于古代官办“高校”，直至清末，与省内大学堂合并组成湖南大学前身，民国时期改名为湖南大学。如今湖大恢复了岳麓书院，实为一个学院，主要涵盖国学、历史学、哲学等学科，也有了现代意义上的党委书记、院长等。但不影响我们来探究岳麓书院的文化底蕴，瞻仰书院的极致高远。' AND c.create_time = '2020-11-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '门票40每人，爱晚亭在书院外面。人少微风小雨景色宜人~十一月底可见霜叶红于二月花~', 4, '2020-11-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dcfa5621e44e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '门票40每人，爱晚亭在书院外面。人少微风小雨景色宜人~十一月底可见霜叶红于二月花~' AND c.create_time = '2020-11-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '看完爱晚亭一定要来看看这！历史悠久不过要门票！湖南大学学生证倒是可以随便进！羡慕湖南大学的同学们啊！', 5, '2020-10-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_65103fab70c9' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '看完爱晚亭一定要来看看这！历史悠久不过要门票！湖南大学学生证倒是可以随便进！羡慕湖南大学的同学们啊！' AND c.create_time = '2020-10-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院很值得一游，它座落于湖南省长沙市岳麓山下，湘江边，湖南省最高学府湖南大学里面，有家里孩子的领着去，带孩子感受一下学习气氛，到岳麓书院去看哪的建筑，学前辈、名人、墨客在这里学习经历及的故事……', 5, '2020-10-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0e2b47e5f9df' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院很值得一游，它座落于湖南省长沙市岳麓山下，湘江边，湖南省最高学府湖南大学里面，有家里孩子的领着去，带孩子感受一下学习气氛，到岳麓书院去看哪的建筑，学前辈、名人、墨客在这里学习经历及的故事……' AND c.create_time = '2020-10-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【景色】最新的网红打卡地哦🙄🙄🙄🙄', 5, '2020-10-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fe2c54e41417' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【景色】最新的网红打卡地哦🙄🙄🙄🙄' AND c.create_time = '2020-10-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这一教育绝路书院是最早的书院之一，很有历史意义，但是我这里主要吐槽的是岳麓书院的服务，讲解非常之差，想请个导游给讲解一下，花钱都没有人，还不给讲解，1点多了已经过了吃饭的时候了，就因为他要去吃饭，三个人在这一块吃饭，没有一个人出来讲解。很少见的，这样的情形居然在岳麓书院发生。', 1, '2020-10-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1572b582ccdb' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这一教育绝路书院是最早的书院之一，很有历史意义，但是我这里主要吐槽的是岳麓书院的服务，讲解非常之差，想请个导游给讲解一下，花钱都没有人，还不给讲解，1点多了已经过了吃饭的时候了，就因为他要去吃饭，三个人在这一块吃饭，没有一个人出来讲解。很少见的，这样的情形居然在岳麓书院发生。' AND c.create_time = '2020-10-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '全国有名的四大书院之一，在城西', 3, '2020-10-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_027151bb07d5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '全国有名的四大书院之一，在城西' AND c.create_time = '2020-10-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖南大学是一所没有围墙的大学，非常幸运的是岳麓书院归属湖大管理，岳麓书院的名望带旺了湖大，湖南大学也继承了岳麓书院的优秀学风，人才辈出。出得书院后门，来到了“爱晚亭”，“爱晚亭”、“陶然亭”、“湖心亭”、“醉翁亭”并称为中国四大名亭。', 5, '2020-10-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dfdf93e46fcf' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖南大学是一所没有围墙的大学，非常幸运的是岳麓书院归属湖大管理，岳麓书院的名望带旺了湖大，湖南大学也继承了岳麓书院的优秀学风，人才辈出。出得书院后门，来到了“爱晚亭”，“爱晚亭”、“陶然亭”、“湖心亭”、“醉翁亭”并称为中国四大名亭。' AND c.create_time = '2020-10-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '四大书院———岳麓书院的必须的打卡地，曾经培养了左宗棠，曾国藩，两个高级英才，听说现在还在使用中，湖南大学的研究生会经常过来上课', 5, '2020-10-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2fb2d073607a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '四大书院———岳麓书院的必须的打卡地，曾经培养了左宗棠，曾国藩，两个高级英才，听说现在还在使用中，湖南大学的研究生会经常过来上课' AND c.create_time = '2020-10-18 00:00:00');
