INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '惟楚有才，于斯为盛。 四大书院之一，湖南大学校内。', 3, '2020-10-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0f54eb96e6d5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '惟楚有才，于斯为盛。 四大书院之一，湖南大学校内。' AND c.create_time = '2020-10-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '当地著名的景点～必须安排去看看～', 4, '2020-10-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ae40f6fbfad1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '当地著名的景点～必须安排去看看～' AND c.create_time = '2020-10-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '“千年学府”岳麓书院： 岳麓书院位于湖南省长沙市湘江西岸秀丽的岳麓山下，湖南大学校园之中，为我国著名的“四大书院”之一。它自北宋创始，历宋、元、明、清各代，兴学不变。随着清末改革学制，废书院，办学堂，辛亥革命后改高等学校等，直至湖南大学，均因旧址扩建，千余年来都是湖南高等学府所在，反映了祖国文教事业的悠久历史，是十分可贵的文物史迹。自上世纪八十年岳麓书院经由湖南大学管理和修复以来，书院延续了千年的教育办学和学术研究传统，成为了全国书院中承继其传统功能的典型代表，被外界誉为“千年学府”。', 5, '2020-10-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_31a88c23afd4' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '“千年学府”岳麓书院： 岳麓书院位于湖南省长沙市湘江西岸秀丽的岳麓山下，湖南大学校园之中，为我国著名的“四大书院”之一。它自北宋创始，历宋、元、明、清各代，兴学不变。随着清末改革学制，废书院，办学堂，辛亥革命后改高等学校等，直至湖南大学，均因旧址扩建，千余年来都是湖南高等学府所在，反映了祖国文教事业的悠久历史，是十分可贵的文物史迹。自上世纪八十年岳麓书院经由湖南大学管理和修复以来，书院延续了千年的教育办学和学术研究传统，成为了全国书院中承继其传统功能的典型代表，被外界誉为“千年学府”。' AND c.create_time = '2020-10-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这个讲解听起来很罗嗦，趣味性也不够没留下什么太大的印象，本来岳麓书院是一个很有故事的地方，但是感觉他们的讲解没有太系统，条理，有趣。', 3, '2020-10-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_888db9d782ff' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这个讲解听起来很罗嗦，趣味性也不够没留下什么太大的印象，本来岳麓书院是一个很有故事的地方，但是感觉他们的讲解没有太系统，条理，有趣。' AND c.create_time = '2020-10-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '还不错吧，可以感受古代学习的环境。就是地形有些复杂，路也年久失修不太好走。', 5, '2020-10-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_16ee9c2dd741' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '还不错吧，可以感受古代学习的环境。就是地形有些复杂，路也年久失修不太好走。' AND c.create_time = '2020-10-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。 书院在湖大校区内，不是太大，1个小时可以游完。', 5, '2020-10-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6054dcebafeb' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。 书院在湖大校区内，不是太大，1个小时可以游完。' AND c.create_time = '2020-10-04 00:00:00');
