INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很好看的景点，而且还不要门票，位于岳麓山风景区内，紧邻湖南大学，来到长沙的小伙伴这里可是必须要打卡的旅游胜地啊，不可错过。', 5, '2020-08-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c7a41d95ecf4' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很好看的景点，而且还不要门票，位于岳麓山风景区内，紧邻湖南大学，来到长沙的小伙伴这里可是必须要打卡的旅游胜地啊，不可错过。' AND c.create_time = '2020-08-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖南长沙市的岳麓山风景区景色优美，在其山脚下有世界上最古老的学府之一的岳麓书院。 岳麓书院是中国历史上著名的四大书院之一，书院完整保存了其古代传统的建筑。 书院大门上的“岳麓书院”四个字是宋真宗的字迹。御书阁是古代书院藏书的主要场所，珍藏有《四库全书》、《四部丛刊》等书籍。', 5, '2020-08-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f79be55d0115' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖南长沙市的岳麓山风景区景色优美，在其山脚下有世界上最古老的学府之一的岳麓书院。 岳麓书院是中国历史上著名的四大书院之一，书院完整保存了其古代传统的建筑。 书院大门上的“岳麓书院”四个字是宋真宗的字迹。御书阁是古代书院藏书的主要场所，珍藏有《四库全书》、《四部丛刊》等书籍。' AND c.create_time = '2020-08-05 00:00:00');
