INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '之前去岳麓书院特意买了50元钱门票的，里面走走看看，很多文青拍照，这次去没有买票了就门口看看然后在岳麓山登高路那边走过去的时候原来可以看见岳麓书院内部呀，这挺有意思。', 4, '2020-07-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '之前去岳麓书院特意买了50元钱门票的，里面走走看看，很多文青拍照，这次去没有买票了就门口看看然后在岳麓山登高路那边走过去的时候原来可以看见岳麓书院内部呀，这挺有意思。' AND c.create_time = '2020-07-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '非常漂亮的书院，景色优美，知识气氛浓厚，值得参观旅游。', 5, '2020-07-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a416b35797a9' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '非常漂亮的书院，景色优美，知识气氛浓厚，值得参观旅游。' AND c.create_time = '2020-07-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '惟楚有材，于斯为盛。岳麓书院属于湖南大学，应该是“四大书院”里现存最活跃的一座了，经常组织学术交流。因为它，湖南大学又被称为“千年学府”。 爱岳麓书院的四季，尤其是五月初夏，草木葱茏，郁郁葱葱，是学生们进书院自习的最好时节。 夏日游书院，可以听一曲编钟演奏，钟磬丝竹之声也是一剂降温去暑的良方。 书院内有孔庙、赫曦台，有皇帝的题字……要想了解湖湘学派、朱张会讲，可以从这里开始，但我是烦宋明理学的，不认为朱张能代表湖湘学派，也不认为岳麓书院有必要成天研究这个。 这里也是谭嗣同开办时务学堂之地。如果北大的历史从京师大学堂说起，上海交大的历史从南洋公学说起，湖南大学的历史当然可以从岳麓书院或时务学堂说起，这是湖南人的“牛皮”，但是有根有据，正所谓“实事求是，敢为人先”。 岳麓书院正门附近，有湖南大学两座漂亮的亭子：吹香亭、风云亭。从书院后门出去，就是“四大名亭”之一的爱晚亭。 道南正脉，学达性天。不妨默默记诵岳麓书院学规——它可比《弟子规》有用多了😄 时常省问父母；朔望恭谒圣贤； 气习各矫偏处；举止整齐严肃； 服食宜从俭素；外事毫不可干； 行坐必依齿序；痛戒讦短毁长； 损友必须拒绝；不可闲谈废时； 日讲经书三起；日看纲目数页； 通晓时务物理；参读古文诗赋； 读书必须过笔；会课按刻蚤完； 夜读仍戒晏起；疑误定要力争。', 5, '2020-06-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_89afe526eed9' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '惟楚有材，于斯为盛。岳麓书院属于湖南大学，应该是“四大书院”里现存最活跃的一座了，经常组织学术交流。因为它，湖南大学又被称为“千年学府”。 爱岳麓书院的四季，尤其是五月初夏，草木葱茏，郁郁葱葱，是学生们进书院自习的最好时节。 夏日游书院，可以听一曲编钟演奏，钟磬丝竹之声也是一剂降温去暑的良方。 书院内有孔庙、赫曦台，有皇帝的题字……要想了解湖湘学派、朱张会讲，可以从这里开始，但我是烦宋明理学的，不认为朱张能代表湖湘学派，也不认为岳麓书院有必要成天研究这个。 这里也是谭嗣同开办时务学堂之地。如果北大的历史从京师大学堂说起，上海交大的历史从南洋公学说起，湖南大学的历史当然可以从岳麓书院或时务学堂说起，这是湖南人的“牛皮”，但是有根有据，正所谓“实事求是，敢为人先”。 岳麓书院正门附近，有湖南大学两座漂亮的亭子：吹香亭、风云亭。从书院后门出去，就是“四大名亭”之一的爱晚亭。 道南正脉，学达性天。不妨默默记诵岳麓书院学规——它可比《弟子规》有用多了😄 时常省问父母；朔望恭谒圣贤； 气习各矫偏处；举止整齐严肃； 服食宜从俭素；外事毫不可干； 行坐必依齿序；痛戒讦短毁长； 损友必须拒绝；不可闲谈废时； 日讲经书三起；日看纲目数页； 通晓时务物理；参读古文诗赋； 读书必须过笔；会课按刻蚤完； 夜读仍戒晏起；疑误定要力争。' AND c.create_time = '2020-06-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于湖南省长沙市境内，岳麓山脚下，湘江西岸，湖南大学里面，历史上赫赫有名的四大书院之一，从北宋发展到如今，建筑气势恢宏，书院出了很多名人志士……', 5, '2020-06-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0e2b47e5f9df' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于湖南省长沙市境内，岳麓山脚下，湘江西岸，湖南大学里面，历史上赫赫有名的四大书院之一，从北宋发展到如今，建筑气势恢宏，书院出了很多名人志士……' AND c.create_time = '2020-06-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '对我来说，很有意义。。。。。。', 5, '2020-06-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b2d0126ce07e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '对我来说，很有意义。。。。。。' AND c.create_time = '2020-06-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '去年长沙出差，特意来到这里参观，非常不错，景色秀丽古色古香书香门第', 5, '2020-06-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2171257ba9af' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '去年长沙出差，特意来到这里参观，非常不错，景色秀丽古色古香书香门第' AND c.create_time = '2020-06-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国四大古书院之首—岳麓书院，惊叹于上千年前的校训至今仍然不过时，以及建造的规模之大，布局合理，一房，一山，一水，一花一草等。', 5, '2020-06-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fb48b15ba7b3' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国四大古书院之首—岳麓书院，惊叹于上千年前的校训至今仍然不过时，以及建造的规模之大，布局合理，一房，一山，一水，一花一草等。' AND c.create_time = '2020-06-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院长沙市乃至整个湖南省的文化符号：中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。', 4, '2020-06-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_707b63266b8d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院长沙市乃至整个湖南省的文化符号：中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。' AND c.create_time = '2020-06-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是湖南省旅游胜地，也是长沙市的对外文化窗口与名片，同时还是湖南大学文史哲人才培养和研究基地。书院坐落于在岳麓山脚下，是我国四大书院之一，最古老的学府之一。书院的建筑格局处处透露着文化底蕴与历史气息，非常值得好好感受观赏。', 5, '2020-05-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8661760db693' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是湖南省旅游胜地，也是长沙市的对外文化窗口与名片，同时还是湖南大学文史哲人才培养和研究基地。书院坐落于在岳麓山脚下，是我国四大书院之一，最古老的学府之一。书院的建筑格局处处透露着文化底蕴与历史气息，非常值得好好感受观赏。' AND c.create_time = '2020-05-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院：位于湖南省长沙市湘江西岸的岳麓山东面山脚，为中国历史上著名的四大书院之一，其正式创办于北宋开宝九年（公元976年），历经宋、元、明、清各代，至清末光绪二十九年改为湖南高等学堂。现为全国重点文物保护单位，也是著名旅游景点。', 3, '2020-05-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3b92a676e703' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院：位于湖南省长沙市湘江西岸的岳麓山东面山脚，为中国历史上著名的四大书院之一，其正式创办于北宋开宝九年（公元976年），历经宋、元、明、清各代，至清末光绪二十九年改为湖南高等学堂。现为全国重点文物保护单位，也是著名旅游景点。' AND c.create_time = '2020-05-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山位于湖南省长沙市，位于橘子洲景区内，是南岳衡山七十二峰的最后一峰，海拔300.8米，属于城市山岳景观，也是中国四大赏枫胜地之一。景区内有岳麓山、橘子洲、岳麓书院、新民学会四个核心景区，站在岳麓山高处，可以俯瞰城市远景，遥望湘江。白天气势苍茫，夜晚华灯璀璨，是非常好的综合性景区。', 5, '2020-05-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ebf93d708d4b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山位于湖南省长沙市，位于橘子洲景区内，是南岳衡山七十二峰的最后一峰，海拔300.8米，属于城市山岳景观，也是中国四大赏枫胜地之一。景区内有岳麓山、橘子洲、岳麓书院、新民学会四个核心景区，站在岳麓山高处，可以俯瞰城市远景，遥望湘江。白天气势苍茫，夜晚华灯璀璨，是非常好的综合性景区。' AND c.create_time = '2020-05-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院坐落于湖南长沙湘江西岸的岳麓山脚下，是我国赫赫有名的四大书院之一，同时也是世界上最古老的学府之一。书院建筑的古典传统格局与形态至今保存完整，书院内的院落、石碑、砖瓦、池塘、树木，都富有着光灿的人文精神。', 5, '2020-05-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ebf93d708d4b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院坐落于湖南长沙湘江西岸的岳麓山脚下，是我国赫赫有名的四大书院之一，同时也是世界上最古老的学府之一。书院建筑的古典传统格局与形态至今保存完整，书院内的院落、石碑、砖瓦、池塘、树木，都富有着光灿的人文精神。' AND c.create_time = '2020-05-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '历史悠久的地方，环境优美安静，非常棒！', 4, '2020-05-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3f1e71a5c21e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '历史悠久的地方，环境优美安静，非常棒！' AND c.create_time = '2020-05-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国四大书院之一，来到岳麓书院，一股浓浓的书生气扑面而来，里面陈列了不少的古书，有很多文学大师都在书院求学过。', 3, '2020-05-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_03f81dcbee8b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国四大书院之一，来到岳麓书院，一股浓浓的书生气扑面而来，里面陈列了不少的古书，有很多文学大师都在书院求学过。' AND c.create_time = '2020-05-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，湖南大学与之相邻，也算是其前身吧！', 5, '2020-05-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4e6f4b9fbaa5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，湖南大学与之相邻，也算是其前身吧！' AND c.create_time = '2020-05-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '说句实话，和期待值相比，有不小差距。', 5, '2020-05-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c799ad1f88a3' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '说句实话，和期待值相比，有不小差距。' AND c.create_time = '2020-05-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '有书院的地方就有文化的传承，很棒了。', 5, '2020-05-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f3f6d1b27777' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '有书院的地方就有文化的传承，很棒了。' AND c.create_time = '2020-05-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙市最有名的景点之一，非常有看头，是现存最大的书院文化景观，可以了解中国书院文化的历史，是近代湖南大学的始祖，建筑风格独特。', 4, '2020-05-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1b27c0d76942' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙市最有名的景点之一，非常有看头，是现存最大的书院文化景观，可以了解中国书院文化的历史，是近代湖南大学的始祖，建筑风格独特。' AND c.create_time = '2020-05-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '四大书院之一 保存完好 值得一游', 4, '2020-05-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a142f1afd312' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '四大书院之一 保存完好 值得一游' AND c.create_time = '2020-05-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国四大书院之一，位于长沙市岳麓区的岳麓山上的岳麓书院，古色古香，很有古典书香气息，环境不错哦！', 4, '2020-05-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5960b8b674ba' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国四大书院之一，位于长沙市岳麓区的岳麓山上的岳麓书院，古色古香，很有古典书香气息，环境不错哦！' AND c.create_time = '2020-05-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。', 5, '2020-05-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_35fb461dcaca' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。' AND c.create_time = '2020-05-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于湖南省长沙市境内。历史上很有名的四大书院之一。坐落于湘江西岸岳麓山脚下，传统建筑结构，是世界上最古老的书院，保存完整，在这里走出好多名人和学者……', 5, '2020-04-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0e2b47e5f9df' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于湖南省长沙市境内。历史上很有名的四大书院之一。坐落于湘江西岸岳麓山脚下，传统建筑结构，是世界上最古老的书院，保存完整，在这里走出好多名人和学者……' AND c.create_time = '2020-04-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是**历史上赫赫闻名的四大书院之一，坐落于**历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。', 5, '2020-04-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_366703ff5987' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是**历史上赫赫闻名的四大书院之一，坐落于**历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。' AND c.create_time = '2020-04-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '最喜欢岳麓书院正门上的楹联，唯楚有才，于斯唯盛，楚国，是个强大的国家，楚国也曾经是战国七雄的老大，只可惜既生楚，何生秦。', 4, '2020-04-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2febdb7ab5f8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '最喜欢岳麓书院正门上的楹联，唯楚有才，于斯唯盛，楚国，是个强大的国家，楚国也曾经是战国七雄的老大，只可惜既生楚，何生秦。' AND c.create_time = '2020-04-23 00:00:00');
