INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，其实对于很多典故我也不知道，和朋友去旅游时反正看见这里需要另外购票，书院也不大的，停车坐爱枫林晚霜叶红于二月花这我是知道的，这个是爱晚亭了。', 4, '2020-04-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，其实对于很多典故我也不知道，和朋友去旅游时反正看见这里需要另外购票，书院也不大的，停车坐爱枫林晚霜叶红于二月花这我是知道的，这个是爱晚亭了。' AND c.create_time = '2020-04-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '惟楚有才，于斯为盛。名气超大，但游览感觉没有亮眼的地方，适合拍照。长沙必去。', 3, '2020-04-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_02ee5d913be9' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '惟楚有才，于斯为盛。名气超大，但游览感觉没有亮眼的地方，适合拍照。长沙必去。' AND c.create_time = '2020-04-08 00:00:00');
