INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '虽然之前对长沙的景色不抱很大期望，去了岳麓书院还是觉得震撼。千年书院，掩映在山林之中，自有一番气度和悠然。惟楚有材于斯为胜利，联想到湖南人的聪明与霸蛮，也是很中肯的评价了', 5, '2020-03-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_731d8b6949e9' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '虽然之前对长沙的景色不抱很大期望，去了岳麓书院还是觉得震撼。千年书院，掩映在山林之中，自有一番气度和悠然。惟楚有材于斯为胜利，联想到湖南人的聪明与霸蛮，也是很中肯的评价了' AND c.create_time = '2020-03-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，岳麓山脚下，以其特殊的地理位置，形成了以它为中心的学术中心、传播授业中心，湖南大学，中南大学，湖南师大等多所全国超一流大学云集于此，向世界伸出了它博爱的双手，欢迎大家的到来。', 5, '2020-03-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_868e1935182b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，岳麓山脚下，以其特殊的地理位置，形成了以它为中心的学术中心、传播授业中心，湖南大学，中南大学，湖南师大等多所全国超一流大学云集于此，向世界伸出了它博爱的双手，欢迎大家的到来。' AND c.create_time = '2020-03-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国最著名的四大书院之一，真不错！', 4, '2020-03-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_858bac9c0865' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国最著名的四大书院之一，真不错！' AND c.create_time = '2020-03-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院历史悠久，是古代读书人的高等学府！位于岳麓山脚下，如今参观岳麓书院，感受古人的读书环境，书院的构造等，很有教育意义！', 5, '2020-03-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_069360d314cb' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院历史悠久，是古代读书人的高等学府！位于岳麓山脚下，如今参观岳麓书院，感受古人的读书环境，书院的构造等，很有教育意义！' AND c.create_time = '2020-03-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国历史上的四大书院之一，位于长沙岳麓山！这里保存了古典书院的原貌，是了解古代书院运作模式的好地方！书香气息浓厚的岳麓书院值得参观！', 5, '2020-03-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_069360d314cb' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国历史上的四大书院之一，位于长沙岳麓山！这里保存了古典书院的原貌，是了解古代书院运作模式的好地方！书香气息浓厚的岳麓书院值得参观！' AND c.create_time = '2020-03-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，中国四大书院之一，久负盛名', 5, '2020-03-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9bfe63b46549' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，中国四大书院之一，久负盛名' AND c.create_time = '2020-03-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院也是古代四大书院之一，属于古代学府，整个建筑也是历史保护建筑，而且存世至今完整保存，十分难得，整个环境也是具有书香气息。', 4, '2020-03-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6478bee897e3' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院也是古代四大书院之一，属于古代学府，整个建筑也是历史保护建筑，而且存世至今完整保存，十分难得，整个环境也是具有书香气息。' AND c.create_time = '2020-03-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是千年学府，历史悠久！书院位于岳麓山，属于湖南大学的一部分！如今可以参观岳麓书院，欣赏古代书院的原貌，感受书香气息！', 5, '2020-03-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_448578a95409' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是千年学府，历史悠久！书院位于岳麓山，属于湖南大学的一部分！如今可以参观岳麓书院，欣赏古代书院的原貌，感受书香气息！' AND c.create_time = '2020-03-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院占地面积21000平方米，现存建筑大部分为明清遗物，主体建筑有头门、二门、讲堂、半学斋、教学斋、百泉轩、御书楼、湘水校经堂、文庙等，分为讲学、藏书、供祀三大部分，各部分互相连接，合为整体，完整地展现了中国古代建筑气势恢宏的壮阔景象。', 5, '2020-03-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_35e7a4446c90' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院占地面积21000平方米，现存建筑大部分为明清遗物，主体建筑有头门、二门、讲堂、半学斋、教学斋、百泉轩、御书楼、湘水校经堂、文庙等，分为讲学、藏书、供祀三大部分，各部分互相连接，合为整体，完整地展现了中国古代建筑气势恢宏的壮阔景象。' AND c.create_time = '2020-03-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '学院屹立已千年，无数思想碰撞的火花，成就了很多大家，也是中华文明的瑰宝。', 5, '2020-03-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a568bc463069' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '学院屹立已千年，无数思想碰撞的火花，成就了很多大家，也是中华文明的瑰宝。' AND c.create_time = '2020-03-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下。 岳麓书院是读书人成才的摇篮。自古读书人心中都有一个梦想：成才，为国家出力，书生报国。岳麓书院，成了读书人走向社会、实现经世济民理想的出发点。', 4, '2020-03-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7d204d4722f8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下。 岳麓书院是读书人成才的摇篮。自古读书人心中都有一个梦想：成才，为国家出力，书生报国。岳麓书院，成了读书人走向社会、实现经世济民理想的出发点。' AND c.create_time = '2020-03-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '对岳麓书院的历史有一点了解的人，都会被它吸引，都想一睹真容，民间传说梁山伯与祝英台就是在这相识。明清以后，书院就出现了很多学识渊博的伟人，对后世的影响颇深，怪不得有“于斯为盛，惟楚有才”之说呢！', 5, '2020-03-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1497e1e62e1c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '对岳麓书院的历史有一点了解的人，都会被它吸引，都想一睹真容，民间传说梁山伯与祝英台就是在这相识。明清以后，书院就出现了很多学识渊博的伟人，对后世的影响颇深，怪不得有“于斯为盛，惟楚有才”之说呢！' AND c.create_time = '2020-03-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院现在是于湖南大学下属的二级学院，还是大学内的一个的教学场所。岳麓书院是中国历史上赫赫闻名的四大书院之一，位于长沙湘江西岸的岳麓山脚下，这里是世界上最古老的学府之一，许多建筑保存得较为完好。其实我觉得来长沙游玩，此处是最值得来的。可以在此仔细看看建筑、看看石碑，抚今追昔，想想当年的学子的模样。', 4, '2020-03-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2c458b4f8ac5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院现在是于湖南大学下属的二级学院，还是大学内的一个的教学场所。岳麓书院是中国历史上赫赫闻名的四大书院之一，位于长沙湘江西岸的岳麓山脚下，这里是世界上最古老的学府之一，许多建筑保存得较为完好。其实我觉得来长沙游玩，此处是最值得来的。可以在此仔细看看建筑、看看石碑，抚今追昔，想想当年的学子的模样。' AND c.create_time = '2020-03-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院作为我国四大书院之一，确实名不虚传', 5, '2020-03-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9259d37f9afd' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院作为我国四大书院之一，确实名不虚传' AND c.create_time = '2020-03-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在湖南大学里面，岳麓书院规模挺大的，里面有不少的石刻碑文，带娃儿去还是很值得一看的！', 5, '2020-03-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c3010b31d9f6' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在湖南大学里面，岳麓书院规模挺大的，里面有不少的石刻碑文，带娃儿去还是很值得一看的！' AND c.create_time = '2020-03-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国四大书院之一，值得一去，能学到不少。', 5, '2020-02-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1311830a91b1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国四大书院之一，值得一去，能学到不少。' AND c.create_time = '2020-02-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '没有什么趣味，一堆小朋友和学生进来参观的书香门第，大概是进来感受一下那个氛围的吧。因为比较有名，而且就在岳麓山的山脚下，而且旁边也就是湖南大学，湖南师范这些大学城，还有那个小吃街走上来，所以顺便就来参观一下岳麓书院，还是挺大的。不过要听导游讲那些故事，自己才会觉得有意思吧，我们就是一起过来逛了一下还行。', 4, '2020-02-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_833d7188cc51' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '没有什么趣味，一堆小朋友和学生进来参观的书香门第，大概是进来感受一下那个氛围的吧。因为比较有名，而且就在岳麓山的山脚下，而且旁边也就是湖南大学，湖南师范这些大学城，还有那个小吃街走上来，所以顺便就来参观一下岳麓书院，还是挺大的。不过要听导游讲那些故事，自己才会觉得有意思吧，我们就是一起过来逛了一下还行。' AND c.create_time = '2020-02-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年书院，历史悠久！岳麓山下的湖南大学和岳麓书院相得益彰！', 5, '2020-02-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6db9e818c71f' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年书院，历史悠久！岳麓山下的湖南大学和岳麓书院相得益彰！' AND c.create_time = '2020-02-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是我们赫赫有名的四大书院之一 由于位于长沙 这里也是相对来说客流最大的一座 唯一山脚的书元。直到现在还保留着古老得书院风格建筑群 以及一些小院子和池塘 沿着山路层层而上 视野也更为开阔 从山上门一出也就是赫赫有名的爱晚亭了 风景宜人', 5, '2020-02-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1792ee7618ca' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是我们赫赫有名的四大书院之一 由于位于长沙 这里也是相对来说客流最大的一座 唯一山脚的书元。直到现在还保留着古老得书院风格建筑群 以及一些小院子和池塘 沿着山路层层而上 视野也更为开阔 从山上门一出也就是赫赫有名的爱晚亭了 风景宜人' AND c.create_time = '2020-02-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山下的岳麓书院，兼顾自然与人文景观，不可多得，不可不去！', 4, '2020-02-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8c5f17fc79ba' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山下的岳麓书院，兼顾自然与人文景观，不可多得，不可不去！' AND c.create_time = '2020-02-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '登高望远，心旷神怡！值得一去再去的地方，长沙打卡地！', 4, '2020-02-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8c5f17fc79ba' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '登高望远，心旷神怡！值得一去再去的地方，长沙打卡地！' AND c.create_time = '2020-02-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上著名的四大书院之一，位于湖南省岳麓山风景区内，历史已逾千年，以保存大量的碑匾文物闻名于世，书院后的小山上，建有爱晚亭，是毛泽东主席青年时代常去的地方。', 5, '2020-02-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_05e0282c3e09' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上著名的四大书院之一，位于湖南省岳麓山风景区内，历史已逾千年，以保存大量的碑匾文物闻名于世，书院后的小山上，建有爱晚亭，是毛泽东主席青年时代常去的地方。' AND c.create_time = '2020-02-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于湖南省长沙市岳麓区境内，湖南大学内，岳麓山风景名胜景区。是中国古时传统书院建筑。我国四大书院之一。重点文物保护单位。景色秀丽，建筑完整，有很多故事……', 5, '2020-02-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0e2b47e5f9df' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于湖南省长沙市岳麓区境内，湖南大学内，岳麓山风景名胜景区。是中国古时传统书院建筑。我国四大书院之一。重点文物保护单位。景色秀丽，建筑完整，有很多故事……' AND c.create_time = '2020-02-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '历史悠久，让人非常神往以前投身革命的人。', 5, '2020-02-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_16c76eed99b2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '历史悠久，让人非常神往以前投身革命的人。' AND c.create_time = '2020-02-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '四大书院之一，来到长沙游玩岳麓山，岳麓书院肯定是要去看的，走进书院，一股浓浓的文化气息扑面而来，欣赏古人的锦绣文章和书法，自然乐在其中。', 4, '2020-02-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_03f81dcbee8b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '四大书院之一，来到长沙游玩岳麓山，岳麓书院肯定是要去看的，走进书院，一股浓浓的文化气息扑面而来，欣赏古人的锦绣文章和书法，自然乐在其中。' AND c.create_time = '2020-02-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于湖南省长沙市岳麓山风景名胜区内，始建于北宋年间，岳麓书院占地面积约2.1万平方米，现存建筑大都为明清时期，主要建筑有大门、二门、半学斋、教学斋、讲堂、湘水校经堂、百泉轩、御书楼等，各部分是相通的，中国古代建筑的特点。', 5, '2020-02-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e0face20044a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于湖南省长沙市岳麓山风景名胜区内，始建于北宋年间，岳麓书院占地面积约2.1万平方米，现存建筑大都为明清时期，主要建筑有大门、二门、半学斋、教学斋、讲堂、湘水校经堂、百泉轩、御书楼等，各部分是相通的，中国古代建筑的特点。' AND c.create_time = '2020-02-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国四大书院之一，与白鹿洞书院等并称，位于岳麓山脚下，湖南大学内，对中国文学历史有着深远的影响，但是门票有点贵，性价比不高。', 3, '2020-02-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5ef2fbbff335' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国四大书院之一，与白鹿洞书院等并称，位于岳麓山脚下，湖南大学内，对中国文学历史有着深远的影响，但是门票有点贵，性价比不高。' AND c.create_time = '2020-02-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '去过一次，古香古色的一个地方，里面还有个大学。', 5, '2020-02-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_87860a39eff5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '去过一次，古香古色的一个地方，里面还有个大学。' AND c.create_time = '2020-02-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙必到景点，位于山顶，但并不高', 5, '2020-01-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6cb982d8b762' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙必到景点，位于山顶，但并不高' AND c.create_time = '2020-01-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '走进岳麓书院，让我惊叹的是其悠久的历史建筑，保存修葺较好，历史古迹往往多次毁于战火，而该书院却能保存古迹并发展壮大，确实不易。', 4, '2020-01-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7d204d4722f8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '走进岳麓书院，让我惊叹的是其悠久的历史建筑，保存修葺较好，历史古迹往往多次毁于战火，而该书院却能保存古迹并发展壮大，确实不易。' AND c.create_time = '2020-01-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于湖南省,自然环境优美，清新淡雅！', 5, '2020-01-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_091457362996' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于湖南省,自然环境优美，清新淡雅！' AND c.create_time = '2020-01-28 00:00:00');
