INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院一一长沙岳麓山风景区网红景点，位于长沙岳麓山脚下，紧邻湖南大学。书院内清新静雅，干净整洁，文化气息非常浓厚，是学子们来长沙必到打卡之地。', 5, '2019-12-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d86751391521' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院一一长沙岳麓山风景区网红景点，位于长沙岳麓山脚下，紧邻湖南大学。书院内清新静雅，干净整洁，文化气息非常浓厚，是学子们来长沙必到打卡之地。' AND c.create_time = '2019-12-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年名古校，人多也要排队去看看。', 5, '2019-12-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_de39b12394ba' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年名古校，人多也要排队去看看。' AND c.create_time = '2019-12-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一。其实当看风景是感觉不出什么新奇，但是对历史是很棒的。', 5, '2019-12-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一。其实当看风景是感觉不出什么新奇，但是对历史是很棒的。' AND c.create_time = '2019-12-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '来长沙的人通常会过来看看，里面安静适合读书。', 5, '2019-12-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_78dd0ec05c36' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '来长沙的人通常会过来看看，里面安静适合读书。' AND c.create_time = '2019-12-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是湖南大学的前身，这儿曾经名人辈出。尽管书院的面积不大，但是这里的学习氛围却非常的浓厚。不过现在进岳麓书院要收门票，这一点不太好。', 4, '2019-12-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4f55a1c05c59' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是湖南大学的前身，这儿曾经名人辈出。尽管书院的面积不大，但是这里的学习氛围却非常的浓厚。不过现在进岳麓书院要收门票，这一点不太好。' AND c.create_time = '2019-12-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于岳麓山南门，需要买门票参观。岳麓书院历史悠久，传统中式建筑掩映在竹林中，书院颇有文化氛围。', 4, '2019-12-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a3ca4e268ae4' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于岳麓山南门，需要买门票参观。岳麓书院历史悠久，传统中式建筑掩映在竹林中，书院颇有文化氛围。' AND c.create_time = '2019-12-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '四大书院之一，绝对值得一去，院内古树参天，翠竹小池，典雅的古建筑，当然最主要的还是历史文化，去前最好先做做功课。真羡慕古人的读书环境', 5, '2019-12-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_08fe26f8553c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '四大书院之一，绝对值得一去，院内古树参天，翠竹小池，典雅的古建筑，当然最主要的还是历史文化，去前最好先做做功课。真羡慕古人的读书环境' AND c.create_time = '2019-12-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '大名鼎鼎，景色，古建，展品都非常棒，排队排了好久才进去。', 5, '2019-12-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fa52f2f02063' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '大名鼎鼎，景色，古建，展品都非常棒，排队排了好久才进去。' AND c.create_time = '2019-12-12 00:00:00');
