INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲解还可以，了解了好多', 5, '2019-11-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7b4b3fca18ef' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲解还可以，了解了好多' AND c.create_time = '2019-11-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于湖南省长沙市湘江西岸秀丽的岳麓山下，湖南大学校园之中，为我国著名的&amp;quot;四大书院之一。它自北宋创始，历宋、元、明、清各代，兴学不变。随着清末改革学制，废书院，办学堂，辛亥革命后改高等学校等，直至湖南大学，均因旧址扩建，千余年来都是湖南高等学府所在，反映了祖国文教事业的悠久历史，是十分可贵的文物史迹。自上世纪八十年岳麓书院经由湖南大学管理和修复以来，书院延续了千年的教育办学和学术研究传统，成为了全国书院中承继其传统功能的典型代表，被外界誉为&amp;quot;千年学府。', 4, '2019-11-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0b5c64ffbcc4' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于湖南省长沙市湘江西岸秀丽的岳麓山下，湖南大学校园之中，为我国著名的&amp;quot;四大书院之一。它自北宋创始，历宋、元、明、清各代，兴学不变。随着清末改革学制，废书院，办学堂，辛亥革命后改高等学校等，直至湖南大学，均因旧址扩建，千余年来都是湖南高等学府所在，反映了祖国文教事业的悠久历史，是十分可贵的文物史迹。自上世纪八十年岳麓书院经由湖南大学管理和修复以来，书院延续了千年的教育办学和学术研究传统，成为了全国书院中承继其传统功能的典型代表，被外界誉为&amp;quot;千年学府。' AND c.create_time = '2019-11-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于湖南省长沙市湘江西岸的岳麓山东面山下，是中国古代传统书院建筑，属于中国历史上著名的四大书院之一。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。岳麓书院位于湖南省长沙市湘江西岸的岳麓山东面山下，是中国古代传统书院建筑，属于中国历史上著名的四大书院之一。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。', 4, '2019-11-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0b5c64ffbcc4' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于湖南省长沙市湘江西岸的岳麓山东面山下，是中国古代传统书院建筑，属于中国历史上著名的四大书院之一。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。岳麓书院位于湖南省长沙市湘江西岸的岳麓山东面山下，是中国古代传统书院建筑，属于中国历史上著名的四大书院之一。1988年，岳麓书院建筑群被国务院批准为第三批全国重点文物保护单位。' AND c.create_time = '2019-11-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '不推荐自驾去，完全无法停车，方圆几公里一个停车场也不提供，也没有任何提示。 封闭的湖南大学，如果你觉得景点是内部，那么就不要对外开放；如果对外开放，就要让大家停车，造成了交通拥堵', 1, '2019-11-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_41ecd26de783' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '不推荐自驾去，完全无法停车，方圆几公里一个停车场也不提供，也没有任何提示。 封闭的湖南大学，如果你觉得景点是内部，那么就不要对外开放；如果对外开放，就要让大家停车，造成了交通拥堵' AND c.create_time = '2019-11-23 00:00:00');
