INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很好很详细，没处景都介绍的很清晰，让我深刻了解了千年书院的文化，每到一处地方很多都不清楚，但是有讲解真的能深刻理解感受文化底蕴的浓厚', 5, '2019-11-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3cc315ba343b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很好很详细，没处景都介绍的很清晰，让我深刻了解了千年书院的文化，每到一处地方很多都不清楚，但是有讲解真的能深刻理解感受文化底蕴的浓厚' AND c.create_time = '2019-11-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '我个人第一次去岳麓书院，深深被千年的书卷气吸引了！至今仍然保留着古朴，厚重的历史，走进去仿佛听到朗朗上口的读书声，伟人的足迹更给这里增添了光辉！景美，历史厚重，建筑更富有特色！', 5, '2019-11-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '我个人第一次去岳麓书院，深深被千年的书卷气吸引了！至今仍然保留着古朴，厚重的历史，走进去仿佛听到朗朗上口的读书声，伟人的足迹更给这里增添了光辉！景美，历史厚重，建筑更富有特色！' AND c.create_time = '2019-11-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '非常专业细致的讲解，对这座历史悠久的岳麓书院肃然起敬一边听还教会了周围的游客怎么下载，希望携程能推出更多优秀经典的讲解服务', 5, '2019-11-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3ece4d74059c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '非常专业细致的讲解，对这座历史悠久的岳麓书院肃然起敬一边听还教会了周围的游客怎么下载，希望携程能推出更多优秀经典的讲解服务' AND c.create_time = '2019-11-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国四大书院之一，位于岳麓山下、湖南大学内，岳麓书院传承千年，书香文化绵延不绝，特别是近代以来，从这走出了众多名人！值得一游', 5, '2019-11-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8b6fe0778698' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国四大书院之一，位于岳麓山下、湖南大学内，岳麓书院传承千年，书香文化绵延不绝，特别是近代以来，从这走出了众多名人！值得一游' AND c.create_time = '2019-11-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '要门票的哦，原票50元，有学生证的话25元，拿湖南大学的学生证就全免的。是个难得一见的千年大书院，院里有许多的翠竹，还有亭台小榭，在大古树的拥簇下，整个院子就显得特别安静，不仅如此，还能强烈感受到千年积淀的文化底蕴。', 5, '2019-11-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1497e1e62e1c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '要门票的哦，原票50元，有学生证的话25元，拿湖南大学的学生证就全免的。是个难得一见的千年大书院，院里有许多的翠竹，还有亭台小榭，在大古树的拥簇下，整个院子就显得特别安静，不仅如此，还能强烈感受到千年积淀的文化底蕴。' AND c.create_time = '2019-11-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙景点攻略|走访千年学府•岳麓书院 自北宋以后，书院的发展一直都很好，当时也产生了著名的四大书院，其中，岳麓书院就是其一，有机会到岳麓山看一看，那自然不能错过了这个千年学府啊。 第一次到访岳麓书院的你，应该如何参观呢？ 给第一次到访的你指一条省时间省精力不走错路的观景线路吧 旅行线路：从毛主席雕塑的右手边走就是岳麓书院正门，这里可以购票然后进门，而且这个门大多了，相比北门要宽敞一些，也不容易出现争执，这个门进去，穿越整个书院，然后西门出去，就是爱晚亭。 •景点：岳麓书院（4A级景区） •坐标：岳麓区岳麓山南路273号，岳麓山的山脚下 •门票：￥40.00 •开放时间：8:00-17:30/7:30-18:00 •建议游玩时间：2-3小时 •可以关注官微，时刻关注他的动向，他虽说是一个景点，但是依旧是湖南大学下面的二级学院，里面还是有学生流动站的，而且里面的学生可以进入很多游客到不了的地方，解密千年学府秘密。 景区一共有20个点，最值得去看看的是中国书院博物馆，里面讲述了书院千年的发展进程，自然古朴的书院本身也是非常值得参观的，不过我们主要看的还是现在的书院构造和建筑美，环境确实很赞，古时候的学生都超级幸福的，在这山清水秀中学习，怪不得学出来的各个都是大师啊，真的是一方水土养一方人，教育环境真的太重要了。 走过了书院，出门以后再步行2分钟就能到爱晚亭了，这里真的是极美的。', 4, '2019-11-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0406c02bb63c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙景点攻略|走访千年学府•岳麓书院 自北宋以后，书院的发展一直都很好，当时也产生了著名的四大书院，其中，岳麓书院就是其一，有机会到岳麓山看一看，那自然不能错过了这个千年学府啊。 第一次到访岳麓书院的你，应该如何参观呢？ 给第一次到访的你指一条省时间省精力不走错路的观景线路吧 旅行线路：从毛主席雕塑的右手边走就是岳麓书院正门，这里可以购票然后进门，而且这个门大多了，相比北门要宽敞一些，也不容易出现争执，这个门进去，穿越整个书院，然后西门出去，就是爱晚亭。 •景点：岳麓书院（4A级景区） •坐标：岳麓区岳麓山南路273号，岳麓山的山脚下 •门票：￥40.00 •开放时间：8:00-17:30/7:30-18:00 •建议游玩时间：2-3小时 •可以关注官微，时刻关注他的动向，他虽说是一个景点，但是依旧是湖南大学下面的二级学院，里面还是有学生流动站的，而且里面的学生可以进入很多游客到不了的地方，解密千年学府秘密。 景区一共有20个点，最值得去看看的是中国书院博物馆，里面讲述了书院千年的发展进程，自然古朴的书院本身也是非常值得参观的，不过我们主要看的还是现在的书院构造和建筑美，环境确实很赞，古时候的学生都超级幸福的，在这山清水秀中学习，怪不得学出来的各个都是大师啊，真的是一方水土养一方人，教育环境真的太重要了。 走过了书院，出门以后再步行2分钟就能到爱晚亭了，这里真的是极美的。' AND c.create_time = '2019-11-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于岳麓山脚下，江西庐山白鹿洞书院 湖南长沙岳麓书院 湖南衡阳石鼓书院 河南商丘应天书院 岳麓书院是中国四大书院之一，景色是真的好，性价比高，体验国学的好去处。回想一下，在古代有这么好的学习环境，也仿佛孩子在教室的读书声在耳边回响', 5, '2019-11-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3f86573f5b24' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于岳麓山脚下，江西庐山白鹿洞书院 湖南长沙岳麓书院 湖南衡阳石鼓书院 河南商丘应天书院 岳麓书院是中国四大书院之一，景色是真的好，性价比高，体验国学的好去处。回想一下，在古代有这么好的学习环境，也仿佛孩子在教室的读书声在耳边回响' AND c.create_time = '2019-11-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '好，有意思，就是比起其他平台贵了，而且走到哪并没有说解到哪，我自己都不知道到哪了，定位功能准确点会更好*********', 5, '2019-11-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7ff84881dd56' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '好，有意思，就是比起其他平台贵了，而且走到哪并没有说解到哪，我自己都不知道到哪了，定位功能准确点会更好*********' AND c.create_time = '2019-11-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '人少安静的书香门第，推荐。虽然在山上，有短波车过去，走路爬不过也二十分钟，也不算爬。里面比较大，如果慢慢溜达，1个半小时到2个小时，要是走马观花，大约30分钟搞定。里面有张地图让我发现原来的国土和现在完全不一样啊', 5, '2019-11-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ed0d537da49a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '人少安静的书香门第，推荐。虽然在山上，有短波车过去，走路爬不过也二十分钟，也不算爬。里面比较大，如果慢慢溜达，1个半小时到2个小时，要是走马观花，大约30分钟搞定。里面有张地图让我发现原来的国土和现在完全不一样啊' AND c.create_time = '2019-11-10 00:00:00');
