INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '四大书院之一，最有名的书院，终于来了', 5, '2019-10-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c7561fd7fc51' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '四大书院之一，最有名的书院，终于来了' AND c.create_time = '2019-10-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国&amp;#183;长沙&amp;#183;岳麓书院“惟楚有才，于斯为盛”。景色不错，有特色，感觉非常好，空气清新，趣味性强，性价比超高的，值得推荐给大家。', 5, '2019-10-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_449241a3849d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国&amp;#183;长沙&amp;#183;岳麓书院“惟楚有才，于斯为盛”。景色不错，有特色，感觉非常好，空气清新，趣味性强，性价比超高的，值得推荐给大家。' AND c.create_time = '2019-10-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲解详细，', 5, '2019-10-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_eaeea508a2ae' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲解详细，' AND c.create_time = '2019-10-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山脚下，湘江水畔，书院原是湖南大学的前身。 秋天去特别美，落叶、雨水，很惬意。小院落、假山、水池，处处是秋意。 潇湘槐市，唯楚有才！', 5, '2019-10-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f5d6ec7503a7' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山脚下，湘江水畔，书院原是湖南大学的前身。 秋天去特别美，落叶、雨水，很惬意。小院落、假山、水池，处处是秋意。 潇湘槐市，唯楚有才！' AND c.create_time = '2019-10-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于湖南长沙岳麓山脚下的岳麓书院，是全国的四大书院之一，建于公元976年的北宋天宝年间，距今已经1000多年了，他的存在，是证明了我国从古代开始就非常重视教育，当年全球的最高学府。书院门票不贵，好像是40大洋，国庆期间人太多，购票排队一小时以上，所以就在门口看看，没有进去，也是一种遗憾，下次有机会再来，一定要过来看看……', 4, '2019-10-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e7c08f3f0ef6' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于湖南长沙岳麓山脚下的岳麓书院，是全国的四大书院之一，建于公元976年的北宋天宝年间，距今已经1000多年了，他的存在，是证明了我国从古代开始就非常重视教育，当年全球的最高学府。书院门票不贵，好像是40大洋，国庆期间人太多，购票排队一小时以上，所以就在门口看看，没有进去，也是一种遗憾，下次有机会再来，一定要过来看看……' AND c.create_time = '2019-10-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这种景点绝对是需要做点功课或者蹭个讲解的，自己看完全没有看头啊，今天天还不是特别好，下起了下雨，也算来到长沙到此一游吧。', 4, '2019-10-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dc80adfac7bd' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这种景点绝对是需要做点功课或者蹭个讲解的，自己看完全没有看头啊，今天天还不是特别好，下起了下雨，也算来到长沙到此一游吧。' AND c.create_time = '2019-10-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很清晰的讲解，这个服务很好，以后会经常用的，学到很多知识，又花费不大，使用也很直观，方便，就是地图的字太小了，能放大就好了。', 5, '2019-10-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d75163774aad' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很清晰的讲解，这个服务很好，以后会经常用的，学到很多知识，又花费不大，使用也很直观，方便，就是地图的字太小了，能放大就好了。' AND c.create_time = '2019-10-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '以前学史，常定义宋为软弱、崇文抑武，最后亡国。但其实宋是一个不亚于唐的兴盛王朝，且不言宋的商业萌芽，就是教育业也是空前的，岳麓书院就是其中一大代表。', 4, '2019-10-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_af68682d9b75' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '以前学史，常定义宋为软弱、崇文抑武，最后亡国。但其实宋是一个不亚于唐的兴盛王朝，且不言宋的商业萌芽，就是教育业也是空前的，岳麓书院就是其中一大代表。' AND c.create_time = '2019-10-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '走进了仰慕很久的岳麓书院，书院历史悠久，千年文化的传承，幽静雅致.依旁着岳麓山越发安静超然，虽然阴雨蒙蒙，又一派墨染的画卷.', 4, '2019-10-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6b9c7d9a41db' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '走进了仰慕很久的岳麓书院，书院历史悠久，千年文化的传承，幽静雅致.依旁着岳麓山越发安静超然，虽然阴雨蒙蒙，又一派墨染的画卷.' AND c.create_time = '2019-10-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于秀丽的岳麓山下，湖南大学校园之中，是我国著名的“四大书院”之一。北宋年间创立至今，兴学不变，是我国可贵的文物史迹。 岳麓书院现在属于湖南大学的二级学院，是现在唯一还在招生教学的古书院。书院里绿树成荫，亭台楼阁，小桥流水，环境清幽，非常适合学习。这里对游客收费，门票50元，虽然有点贵，但还是蛮值得进去一看的。', 5, '2019-10-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_798358700954' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于秀丽的岳麓山下，湖南大学校园之中，是我国著名的“四大书院”之一。北宋年间创立至今，兴学不变，是我国可贵的文物史迹。 岳麓书院现在属于湖南大学的二级学院，是现在唯一还在招生教学的古书院。书院里绿树成荫，亭台楼阁，小桥流水，环境清幽，非常适合学习。这里对游客收费，门票50元，虽然有点贵，但还是蛮值得进去一看的。' AND c.create_time = '2019-10-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '今天来到了向往已久的岳麓书院哦，它中国古代著名四大书院之一，书院始建于北宋开宝九年，一千余年来，这所誉满海内外的著名学府，历经宋、元、明、清时势变化，依然如故', 5, '2019-10-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_853993187332' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '今天来到了向往已久的岳麓书院哦，它中国古代著名四大书院之一，书院始建于北宋开宝九年，一千余年来，这所誉满海内外的著名学府，历经宋、元、明、清时势变化，依然如故' AND c.create_time = '2019-10-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '旅游出行有这种随身导游体验还是很棒的，你走到哪个景点只要点开这个景点的解说就可以了，当然和真人相比只能说各有千秋。', 5, '2019-10-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9e57eb791158' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '旅游出行有这种随身导游体验还是很棒的，你走到哪个景点只要点开这个景点的解说就可以了，当然和真人相比只能说各有千秋。' AND c.create_time = '2019-10-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '总体感觉不错，服务员热情，酒店内部装修风格，空间均满意。', 5, '2019-10-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_62948d387a5d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '总体感觉不错，服务员热情，酒店内部装修风格，空间均满意。' AND c.create_time = '2019-10-07 00:00:00');
