INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '还好，可以简单了解一下，没有讲解，就白去了', 4, '2019-10-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '还好，可以简单了解一下，没有讲解，就白去了' AND c.create_time = '2019-10-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，中国古代的四大书院之一，他和艾婉婷对着，所以说你看到爱晚亭了，就知道岳麓书院到了。 门票50块钱，基本上是仿古建筑。 我去过白鹭书院，那是30多年前了。', 5, '2019-10-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e097cd93764d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，中国古代的四大书院之一，他和艾婉婷对着，所以说你看到爱晚亭了，就知道岳麓书院到了。 门票50块钱，基本上是仿古建筑。 我去过白鹭书院，那是30多年前了。' AND c.create_time = '2019-10-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是这次来长沙的首要景点，位于湖南大学，也是湖南大学的前身，已经有一千年的历史了。书院由张栻建造，是当时的最高学府，而且还是第一家分学科教学的学府。走进书院，顿时感觉有一种古色古香的书香气，虽然游人很多，但却让人感到宁静。在这里待上一个下午都不嫌多。', 4, '2019-10-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_977bff431822' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是这次来长沙的首要景点，位于湖南大学，也是湖南大学的前身，已经有一千年的历史了。书院由张栻建造，是当时的最高学府，而且还是第一家分学科教学的学府。走进书院，顿时感觉有一种古色古香的书香气，虽然游人很多，但却让人感到宁静。在这里待上一个下午都不嫌多。' AND c.create_time = '2019-10-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '买了讲解，结果二个小时走走听听，愣是没有逛完', 5, '2019-09-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_aff974c0fe16' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '买了讲解，结果二个小时走走听听，愣是没有逛完' AND c.create_time = '2019-09-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '打卡#千年学府#岳麓书院#惟楚有材，于斯为盛 【性价比】在校的学生不用钱，是个超好的福利。 【趣味】有故事。 【景色】这里秋天的景色最美了。', 4, '2019-09-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d6f3ac6ec56b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '打卡#千年学府#岳麓书院#惟楚有材，于斯为盛 【性价比】在校的学生不用钱，是个超好的福利。 【趣味】有故事。 【景色】这里秋天的景色最美了。' AND c.create_time = '2019-09-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爬山嘛，没什么好说的。景色满分，可以看到整个长沙。个人比较喜欢爬山，所以趣味也满分。性价比自然满分，免费的东西正常情况下的性价比是要比收费的高。山里面还有好几个景点，都不错。总结：爬山爬山爬山，有时间的尽量去。', 5, '2019-09-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_50a070e50f53' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爬山嘛，没什么好说的。景色满分，可以看到整个长沙。个人比较喜欢爬山，所以趣味也满分。性价比自然满分，免费的东西正常情况下的性价比是要比收费的高。山里面还有好几个景点，都不错。总结：爬山爬山爬山，有时间的尽量去。' AND c.create_time = '2019-09-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是湖南大学的前身，现在成为了湖南大学的一部分。岳麓书院的自然景观和地理位置都非常好，岳麓书院的教育地位在中国的历史上也非常的高。', 4, '2019-09-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4f55a1c05c59' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是湖南大学的前身，现在成为了湖南大学的一部分。岳麓书院的自然景观和地理位置都非常好，岳麓书院的教育地位在中国的历史上也非常的高。' AND c.create_time = '2019-09-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年学府，景色优美，值得一游！', 5, '2019-09-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fbff0e888cd6' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年学府，景色优美，值得一游！' AND c.create_time = '2019-09-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '历史文化气韵悠长，十分值得一看', 5, '2019-09-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d2f7b51ff2a1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '历史文化气韵悠长，十分值得一看' AND c.create_time = '2019-09-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '坐落于岳麓山脚下的岳麓书院是中国四大名书院之一，始建于北宋年间，距今已有一千多年历史了。历史上书院曾出过很多名人，这里就不一一列出了。书院现在隶属于湖南大学，是其中一个书院，也是一个景点。', 5, '2019-09-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_72865ac69609' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '坐落于岳麓山脚下的岳麓书院是中国四大名书院之一，始建于北宋年间，距今已有一千多年历史了。历史上书院曾出过很多名人，这里就不一一列出了。书院现在隶属于湖南大学，是其中一个书院，也是一个景点。' AND c.create_time = '2019-09-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【再游南京&amp;#183;岳麓书院】岳麓山山下的岳麓书院，先贤开坛讲学传播思想的圣地，郁郁葱葱，清泉潺潺，不禁有在此归隐泉林、修身著书的想法；岳麓书院相当于我们国家最早的大学，培养人才的地方。', 5, '2019-09-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2cae10590488' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【再游南京&amp;#183;岳麓书院】岳麓山山下的岳麓书院，先贤开坛讲学传播思想的圣地，郁郁葱葱，清泉潺潺，不禁有在此归隐泉林、修身著书的想法；岳麓书院相当于我们国家最早的大学，培养人才的地方。' AND c.create_time = '2019-09-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '古香古色书香气，幽静自然岳麓山。', 5, '2019-09-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9e15c3536f49' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '古香古色书香气，幽静自然岳麓山。' AND c.create_time = '2019-09-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院，这里中国古代著名的四大书院之一，而中国古代的四大书院分别是：岳麓书院、白鹿洞书院、嵩阳书院、应天书院。这里也是中国现保存最完好的一座古代书院。浓浓的书卷文化气息。', 5, '2019-09-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_aab4301680ac' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院，这里中国古代著名的四大书院之一，而中国古代的四大书院分别是：岳麓书院、白鹿洞书院、嵩阳书院、应天书院。这里也是中国现保存最完好的一座古代书院。浓浓的书卷文化气息。' AND c.create_time = '2019-09-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙岳麓山下的岳麓书院赫赫有名！是中国四大有名的书院之一！', 5, '2019-09-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_206013507a95' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙岳麓山下的岳麓书院赫赫有名！是中国四大有名的书院之一！' AND c.create_time = '2019-09-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '书院历史上经历多次战火，曾七毁七建，现存主要建筑是清朝遗构。重修后岳麓书院占地面积21000平方米，在布局上采用中轴对称、纵深多进的院落形式。整个书院目前是属于湖南大学的，可谓真正的千年书院学府。', 4, '2019-09-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f7e303f255be' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '书院历史上经历多次战火，曾七毁七建，现存主要建筑是清朝遗构。重修后岳麓书院占地面积21000平方米，在布局上采用中轴对称、纵深多进的院落形式。整个书院目前是属于湖南大学的，可谓真正的千年书院学府。' AND c.create_time = '2019-09-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲解的并不细致，而且也不算人性化，要自己一个个找景点去听，其实还不如跟着景点里一些讲解员走，听到的讲解会好很多，不推荐', 3, '2019-08-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8404fde4166d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲解的并不细致，而且也不算人性化，要自己一个个找景点去听，其实还不如跟着景点里一些讲解员走，听到的讲解会好很多，不推荐' AND c.create_time = '2019-08-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '人文景观，主要是需要讲解，听听讲解还是不错的！', 4, '2019-08-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5f4fb3bdaf0b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '人文景观，主要是需要讲解，听听讲解还是不错的！' AND c.create_time = '2019-08-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '没读过书也要去感受下，不错的。', 5, '2019-08-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7b9fd1a5e5cd' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '没读过书也要去感受下，不错的。' AND c.create_time = '2019-08-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '排了好久的队，暑假真的好多人呢！', 5, '2019-08-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6336f7ff51f7' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '排了好久的队，暑假真的好多人呢！' AND c.create_time = '2019-08-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院的历史我就不介绍了，都可以查到，即便是下雨天，人也还是不少的，可见平日天气好时时什么样了，门票不算便宜，但还是挡不住大伙的热情，这里不仅有历史遗迹，建筑，整体风景也很棒，背靠岳麓山，因为时间太紧，只能从路旁高处路过时一窥了。', 5, '2019-08-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5843d81d3421' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院的历史我就不介绍了，都可以查到，即便是下雨天，人也还是不少的，可见平日天气好时时什么样了，门票不算便宜，但还是挡不住大伙的热情，这里不仅有历史遗迹，建筑，整体风景也很棒，背靠岳麓山，因为时间太紧，只能从路旁高处路过时一窥了。' AND c.create_time = '2019-08-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '进去参观是需要购买门票的，但里面的环境我很喜欢哈，但是如果你喜欢游玩，而不喜欢这样的人文可能就会对这里很失望哈。但是很有历史感。', 4, '2019-08-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1497e1e62e1c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '进去参观是需要购买门票的，但里面的环境我很喜欢哈，但是如果你喜欢游玩，而不喜欢这样的人文可能就会对这里很失望哈。但是很有历史感。' AND c.create_time = '2019-08-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '人文气息浓郁的地方，这里历史悠久，学府之地，古代人听课都是席地而坐的，老师讲书都是坐着的，不像现在，老师站着讲学生坐着，。', 4, '2019-08-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2febdb7ab5f8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '人文气息浓郁的地方，这里历史悠久，学府之地，古代人听课都是席地而坐的，老师讲书都是坐着的，不像现在，老师站着讲学生坐着，。' AND c.create_time = '2019-08-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在湖大里面，自己开车去找了好久也没有找到最后停在了湖大正门步行了好久才到，和父母一起来的，但是我没有进去逛因为上午去橘子洲热懵我了，坐在外面的石凳上等他们。一个人要40块的门票，他们进去了一个小时左右就出来了，说我没有进去也不遗憾，所以我想里面应该也没有什么特别的东西（原谅我的肤浅） 下面附上几张父母拍的图片', 2, '2019-08-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_76b8847fc9bf' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在湖大里面，自己开车去找了好久也没有找到最后停在了湖大正门步行了好久才到，和父母一起来的，但是我没有进去逛因为上午去橘子洲热懵我了，坐在外面的石凳上等他们。一个人要40块的门票，他们进去了一个小时左右就出来了，说我没有进去也不遗憾，所以我想里面应该也没有什么特别的东西（原谅我的肤浅） 下面附上几张父母拍的图片' AND c.create_time = '2019-08-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '讲的挺好的，不错，有运用价值。', 5, '2019-08-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '讲的挺好的，不错，有运用价值。' AND c.create_time = '2019-08-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国四大书院之一，相当于现在的211，985，在这里读过书的人，都在中国的历史上出现过，而且还是浓墨重彩的人物，很牛✘的。', 5, '2019-08-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2febdb7ab5f8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国四大书院之一，相当于现在的211，985，在这里读过书的人，都在中国的历史上出现过，而且还是浓墨重彩的人物，很牛✘的。' AND c.create_time = '2019-08-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '还是很值得细细品味的一处景点。', 5, '2019-08-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1030e9ee6a58' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '还是很值得细细品味的一处景点。' AND c.create_time = '2019-08-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '不愧是千年母校哈，有空的朋友可以来逛逛。', 5, '2019-08-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_200cbc4f036e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '不愧是千年母校哈，有空的朋友可以来逛逛。' AND c.create_time = '2019-08-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于湖南大学校内，也属于岳麓山风景区的景点。全票50元，半票25元，湖南师大师生免费，本人买的半票25元进去的。湖南大学作为千年学府指的就是岳麓书院了。这里有个博物馆展览，有编钟展演室，里面景色宜人，环境好，也再现了曾经的学府教室建筑。', 5, '2019-08-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_94d251f9b577' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于湖南大学校内，也属于岳麓山风景区的景点。全票50元，半票25元，湖南师大师生免费，本人买的半票25元进去的。湖南大学作为千年学府指的就是岳麓书院了。这里有个博物馆展览，有编钟展演室，里面景色宜人，环境好，也再现了曾经的学府教室建筑。' AND c.create_time = '2019-08-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山免费开放，环境清幽。岳麓书院需要门票，值得进去感受书院浓厚的文化学术氛围。要注意时间，避开人流，早点儿进去最好，凉快又轻松。', 5, '2019-07-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_578ef0b44284' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山免费开放，环境清幽。岳麓书院需要门票，值得进去感受书院浓厚的文化学术氛围。要注意时间，避开人流，早点儿进去最好，凉快又轻松。' AND c.create_time = '2019-07-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '传承代表孔孟之学的经典书院之一', 5, '2019-07-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7fce30e163d8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '传承代表孔孟之学的经典书院之一' AND c.create_time = '2019-07-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这个书院出了太多名人了，不愧为四大书院之一', 5, '2019-07-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cd75395e41c1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这个书院出了太多名人了，不愧为四大书院之一' AND c.create_time = '2019-07-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这个书院确实很有名气，带着小孩子去感受一下，古时候的文化气息和礼仪礼节，什么三字经啊，弟子规啊，里面的东西这里都有相关的，值得推荐带小孩的朋友去看看，可以感受一下学习的文化和气息。', 4, '2019-07-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_123607390205' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这个书院确实很有名气，带着小孩子去感受一下，古时候的文化气息和礼仪礼节，什么三字经啊，弟子规啊，里面的东西这里都有相关的，值得推荐带小孩的朋友去看看，可以感受一下学习的文化和气息。' AND c.create_time = '2019-07-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '读书人必去之地啊！去感受一下清华、北大古代版的气氛也是好的。书院整体比较幽静，古时候能在这种环境下读书真是惬意。还原度较好，不过也不可避免的被商业化气息沾染了，略有点儿失望。', 4, '2019-07-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_30fbc3132ad2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '读书人必去之地啊！去感受一下清华、北大古代版的气氛也是好的。书院整体比较幽静，古时候能在这种环境下读书真是惬意。还原度较好，不过也不可避免的被商业化气息沾染了，略有点儿失望。' AND c.create_time = '2019-07-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖湘文化的地底蕴所在，去长沙怎能不去岳麓书院呢，惟楚有材，于斯为盛，千年学府，接受文化的好去处。只可惜我是在湘江对岸读书。', 5, '2019-07-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4fbb5f29e5e8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖湘文化的地底蕴所在，去长沙怎能不去岳麓书院呢，惟楚有材，于斯为盛，千年学府，接受文化的好去处。只可惜我是在湘江对岸读书。' AND c.create_time = '2019-07-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年学府岳麓书院是长沙市湖南大学的前身，也是目前现存的唯一还在招生的古书院。书院地处岳麓山风景区，空气清新，绿树成荫，古建林立，亭台楼阁，小桥流水，静谧宜人的环境是适合读书人精心读书的场所。岳麓书院从北宋延续到如今，古朴厚重，不愧是我国书院中的瑰宝。', 5, '2019-07-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_759ec4fe2761' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年学府岳麓书院是长沙市湖南大学的前身，也是目前现存的唯一还在招生的古书院。书院地处岳麓山风景区，空气清新，绿树成荫，古建林立，亭台楼阁，小桥流水，静谧宜人的环境是适合读书人精心读书的场所。岳麓书院从北宋延续到如今，古朴厚重，不愧是我国书院中的瑰宝。' AND c.create_time = '2019-07-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '当时人山人海的，没有进去，不过在外面有很多学校里的学生在卖明信片，门口两个窗口，一个窗口是线上支付，一个窗口是线下支付，然后建议是带现金吧，因为那边窗口人真的很少。书院附近是学校，也是建议可以逛一下的。岳麓山一定要记得在五点半之前过去才不会关门。', 5, '2019-07-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5a8b44bc78b7' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '当时人山人海的，没有进去，不过在外面有很多学校里的学生在卖明信片，门口两个窗口，一个窗口是线上支付，一个窗口是线下支付，然后建议是带现金吧，因为那边窗口人真的很少。书院附近是学校，也是建议可以逛一下的。岳麓山一定要记得在五点半之前过去才不会关门。' AND c.create_time = '2019-07-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落在岳麓山脚下。从岳麓山下来，来到书院门口，门票50有点小贵，抵不过好奇心排了近半小时的队，购票入院参观。一路下来感叹古代学子读书的环境如此优雅别致，仿佛听见他们朗朗的读书声。', 5, '2019-07-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_33feadd1ab8c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落在岳麓山脚下。从岳麓山下来，来到书院门口，门票50有点小贵，抵不过好奇心排了近半小时的队，购票入院参观。一路下来感叹古代学子读书的环境如此优雅别致，仿佛听见他们朗朗的读书声。' AND c.create_time = '2019-07-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '非常适合带着孩子去，很有历史意义。', 5, '2019-07-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_bf3c9081fdd5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '非常适合带着孩子去，很有历史意义。' AND c.create_time = '2019-07-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '还不错，穿过大学到达岳麓书院，景色不错，挺安静', 4, '2019-07-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_959f5fac322a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '还不错，穿过大学到达岳麓书院，景色不错，挺安静' AND c.create_time = '2019-07-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院出得太多名人喇。真是人杰地灵。', 5, '2019-07-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cd75395e41c1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院出得太多名人喇。真是人杰地灵。' AND c.create_time = '2019-07-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国四大书院之一，湖南大学院内，爱晚亭下，门票50元，个人感觉有点贵。', 5, '2019-07-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9e416276801b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国四大书院之一，湖南大学院内，爱晚亭下，门票50元，个人感觉有点贵。' AND c.create_time = '2019-07-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '历史悠久的文化圣地，中华文明传承的桥梁', 4, '2019-07-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e42bf9ab840e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '历史悠久的文化圣地，中华文明传承的桥梁' AND c.create_time = '2019-07-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓書院在湖南大學附近，下地鐵站後還需要步行一段路，可沿路逛逛湖南大學，進岳麓書院需購票，書院年可以感受到濃濃的書卷味，非常寧靜。特別一提，愛晚亭並不在書院內，故如只想去愛晚亭，可由往岳麓山的方向上山便可到，不需要購票哦。', 5, '2019-07-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6ad064c04f0a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓書院在湖南大學附近，下地鐵站後還需要步行一段路，可沿路逛逛湖南大學，進岳麓書院需購票，書院年可以感受到濃濃的書卷味，非常寧靜。特別一提，愛晚亭並不在書院內，故如只想去愛晚亭，可由往岳麓山的方向上山便可到，不需要購票哦。' AND c.create_time = '2019-07-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '書香之地 宁静 景色优美 隨意逛逛心都靜', 5, '2019-06-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3354f896dc4a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '書香之地 宁静 景色优美 隨意逛逛心都靜' AND c.create_time = '2019-06-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '之前买门票进去过了，这次就没有进去了，发现从高处还可以看见书院里面呢，拍了几张。 没有进去过的还是推荐进去看看走走拍拍照片的，很有感觉，都是树荫也不热，把自己想象成古时读书的学子，家里条件还不错那种哟，因为穷人进不了书院呢。', 4, '2019-06-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '之前买门票进去过了，这次就没有进去了，发现从高处还可以看见书院里面呢，拍了几张。 没有进去过的还是推荐进去看看走走拍拍照片的，很有感觉，都是树荫也不热，把自己想象成古时读书的学子，家里条件还不错那种哟，因为穷人进不了书院呢。' AND c.create_time = '2019-06-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '环境优美，交通便利，文化氛围很好', 5, '2019-06-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ca908cd95d0d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '环境优美，交通便利，文化氛围很好' AND c.create_time = '2019-06-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖南省长沙市岳麓书院，有着悠久的历史，惟楚有材，于斯为盛！文人墨客，层出不穷，历代伟人，交替出现，爱晚亭前，伟人曾经留下读书寻道之足迹，空气清新，登高远眺，心宽神怡也！', 4, '2019-06-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b9ea17f5f28c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖南省长沙市岳麓书院，有着悠久的历史，惟楚有材，于斯为盛！文人墨客，层出不穷，历代伟人，交替出现，爱晚亭前，伟人曾经留下读书寻道之足迹，空气清新，登高远眺，心宽神怡也！' AND c.create_time = '2019-06-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '逛完大概兩小時左右 不過內容簡略 門票40元 走完其實有些空虛不過有幾個地方蠻好拍照的 如果是住附近的可以去走走啦～', 3, '2019-06-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_49e63efb66ac' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '逛完大概兩小時左右 不過內容簡略 門票40元 走完其實有些空虛不過有幾個地方蠻好拍照的 如果是住附近的可以去走走啦～' AND c.create_time = '2019-06-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '本身是出于一种敬仰去的，这个景区来说四十的门票太贵，这样的景区应该以传播文化为目的，承担社会责任，票价应该适当低些，不要太重视收益。', 3, '2019-06-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_066933700d39' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '本身是出于一种敬仰去的，这个景区来说四十的门票太贵，这样的景区应该以传播文化为目的，承担社会责任，票价应该适当低些，不要太重视收益。' AND c.create_time = '2019-06-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '紧挨岳麓山与湖南大学，风景秀丽，文化氛围浓厚。参观完书院还可以登山，旁边岳麓山上有滑道，还是蛮好玩的。唯一的不足在于书院翻新之后，各种历史气息少了很多，但藏书阁依然在，是必须敬仰膜拜的地方。', 4, '2019-06-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cde5be8780f3' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '紧挨岳麓山与湖南大学，风景秀丽，文化氛围浓厚。参观完书院还可以登山，旁边岳麓山上有滑道，还是蛮好玩的。唯一的不足在于书院翻新之后，各种历史气息少了很多，但藏书阁依然在，是必须敬仰膜拜的地方。' AND c.create_time = '2019-06-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '第一次是开车去，景区不让社会车辆进入，网上说可以开到西门停车场，但没找到路。后来坐地铁去也很方便，书院不大，古香古色，书香氛围浓厚，是个修养心性的好地方。', 4, '2019-06-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b2e8bd88464d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '第一次是开车去，景区不让社会车辆进入，网上说可以开到西门停车场，但没找到路。后来坐地铁去也很方便，书院不大，古香古色，书香氛围浓厚，是个修养心性的好地方。' AND c.create_time = '2019-06-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '值得一去的地方，去感受一下千年学府的美丽与魅力。', 5, '2019-06-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_02c3e5434631' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '值得一去的地方，去感受一下千年学府的美丽与魅力。' AND c.create_time = '2019-06-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是中国历史上赫赫闻名的四大书院之一。 四大书院：应天书院（今河南商丘睢阳南湖畔）、岳麓书院（今湖南长沙岳麓山）、白鹿洞书院（今江西九江庐山）、嵩阳书院（今河南郑州登封嵩山） 坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，在湘江西侧，这里书香气息浓厚，值得来此观光', 5, '2019-06-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dd0175ea09c2' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是中国历史上赫赫闻名的四大书院之一。 四大书院：应天书院（今河南商丘睢阳南湖畔）、岳麓书院（今湖南长沙岳麓山）、白鹿洞书院（今江西九江庐山）、嵩阳书院（今河南郑州登封嵩山） 坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，在湘江西侧，这里书香气息浓厚，值得来此观光' AND c.create_time = '2019-06-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【景色】不算特别美，漫步其中还是很舒服的', 4, '2019-06-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_49dc03782339' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【景色】不算特别美，漫步其中还是很舒服的' AND c.create_time = '2019-06-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '惟楚有才，挺值得去的好地方看看爱晚亭，游游岳麓山。', 5, '2019-06-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_929fdef877f3' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '惟楚有才，挺值得去的好地方看看爱晚亭，游游岳麓山。' AND c.create_time = '2019-06-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是古代汉族书院历史，也是中国四大书院之一，历史可追溯到北宋开宝九年，至今一千余年，可谓历史深厚，爱晚亭距岳麓书院很近', 5, '2019-06-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1707abb0e90a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是古代汉族书院历史，也是中国四大书院之一，历史可追溯到北宋开宝九年，至今一千余年，可谓历史深厚，爱晚亭距岳麓书院很近' AND c.create_time = '2019-06-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院是长沙最好的景点，虽然门票价格有点高，但是人不多，很清净，很有人文气质，里面的建筑和自然风景特别的美，仿佛穿越回了古代！', 4, '2019-06-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9d5f4921f2c1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院是长沙最好的景点，虽然门票价格有点高，但是人不多，很清净，很有人文气质，里面的建筑和自然风景特别的美，仿佛穿越回了古代！' AND c.create_time = '2019-06-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '坐落于长沙历史文化名胜，建筑被赋予了有一层厚重的文化底蕴。在郁郁葱葱的树木包围中，这里自然有了宁静致远、源远流长的感觉！', 5, '2019-06-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d2d9099187cd' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '坐落于长沙历史文化名胜，建筑被赋予了有一层厚重的文化底蕴。在郁郁葱葱的树木包围中，这里自然有了宁静致远、源远流长的感觉！' AND c.create_time = '2019-06-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很有文化气息。值得文艺青年去看看。', 5, '2019-06-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_222931932c70' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很有文化气息。值得文艺青年去看看。' AND c.create_time = '2019-06-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院位于岳麓山下，湖南大学校园之中，为我国古代著名的“四大书院”之一。走在古木参天、山光水色、弦歌千年的学府，典雅、庄重的古建筑群掩映在青山之中。', 4, '2019-06-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6afa7b93de6d' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院位于岳麓山下，湖南大学校园之中，为我国古代著名的“四大书院”之一。走在古木参天、山光水色、弦歌千年的学府，典雅、庄重的古建筑群掩映在青山之中。' AND c.create_time = '2019-06-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于岳麓山脚，紧临爱晩亭，参观需要收费，国内门票一向不便宜，尽管值不回票价，但书院还是值得参观的，面积也不小，悠悠闲闲的逛逛，也可以花去不少的时间。', 4, '2019-06-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5b584dfac698' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于岳麓山脚，紧临爱晩亭，参观需要收费，国内门票一向不便宜，尽管值不回票价，但书院还是值得参观的，面积也不小，悠悠闲闲的逛逛，也可以花去不少的时间。' AND c.create_time = '2019-06-04 00:00:00');
