INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年学府，文化深厚，大学环绕，静雅别致。', 5, '2019-06-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ed3913c4f15e' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年学府，文化深厚，大学环绕，静雅别致。' AND c.create_time = '2019-06-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '历史久远，人文气息浓厚，长知识，环境好，空气好，在湖南大学校区内，惟楚有材，于斯为盛！四号地铁已开通，交通方便，团队可以预约解说。', 5, '2019-05-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9b76c854277a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '历史久远，人文气息浓厚，长知识，环境好，空气好，在湖南大学校区内，惟楚有材，于斯为盛！四号地铁已开通，交通方便，团队可以预约解说。' AND c.create_time = '2019-05-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院里信号不好。其实建议大家自己去前台顾一个吧。如果人多的话。听这个没啥意思。虽然便宜，但是有点无聊。', 4, '2019-05-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_bdabab6bcad5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院里信号不好。其实建议大家自己去前台顾一个吧。如果人多的话。听这个没啥意思。虽然便宜，但是有点无聊。' AND c.create_time = '2019-05-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【岳麓书院】岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。', 5, '2019-05-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4992c531430b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【岳麓书院】岳麓书院是中国历史上赫赫闻名的四大书院之一，坐落于中国历史文化名城湖南长沙湘江西岸的岳麓山脚下，作为世界上最古老的学府之一，其古代传统的书院建筑至今被完整保存，每一组院落、每一块石碑、每一枚砖瓦、每一支风荷，都闪烁着时光淬炼的人文精神。' AND c.create_time = '2019-05-27 00:00:00');
