INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '历史悠久的书院，是湖南大学的前身，书院前面就是湖南大学，后面就是爱晚亭。场地不小，建筑有特点，也能找到一些别样的风景，还可以学习当地一些历史。', 5, '2019-05-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cfdba0c9a30b' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '历史悠久的书院，是湖南大学的前身，书院前面就是湖南大学，后面就是爱晚亭。场地不小，建筑有特点，也能找到一些别样的风景，还可以学习当地一些历史。' AND c.create_time = '2019-05-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院坐落在湖南长沙岳麓山脚下，是中国历史上四大书院之一，岳麓书院还是原湖南大学的旧址。书院需要购买门票参观，附近的路边就可以停放车辆。', 5, '2019-05-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c0dffdf69725' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院坐落在湖南长沙岳麓山脚下，是中国历史上四大书院之一，岳麓书院还是原湖南大学的旧址。书院需要购买门票参观，附近的路边就可以停放车辆。' AND c.create_time = '2019-05-20 00:00:00');
