INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国古代著名的“四大书院”之一，也是中国现保存最完好的一座古代书院，相传已有3000多年的历史。来到这里,人们能充分地感受到圣贤学者们的浓郁文化气息。', 5, '2017-08-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6b6704e48c39' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国古代著名的“四大书院”之一，也是中国现保存最完好的一座古代书院，相传已有3000多年的历史。来到这里,人们能充分地感受到圣贤学者们的浓郁文化气息。' AND c.create_time = '2017-08-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '古代著名的四大书院之一，去长沙的时候，特意去过，想要沾一沾书生气，就在大学旁边，很多学生去', 5, '2017-08-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da25840e076a' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '古代著名的四大书院之一，去长沙的时候，特意去过，想要沾一沾书生气，就在大学旁边，很多学生去' AND c.create_time = '2017-08-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '浓浓的书香味道，很值得一去！熏陶文化！', 5, '2016-09-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_18fe088a7ab6' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '浓浓的书香味道，很值得一去！熏陶文化！' AND c.create_time = '2016-09-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '如果去这里玩的话，最好跟个导游，没有导游说的，完全觉得自己没文化。可以带小孩去感受一下古人教育体系的建立和重要性。惟楚有才！', 4, '2016-09-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_45a0d86d42b3' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '如果去这里玩的话，最好跟个导游，没有导游说的，完全觉得自己没文化。可以带小孩去感受一下古人教育体系的建立和重要性。惟楚有才！' AND c.create_time = '2016-09-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '里面相当大，很有历史感，不愧是千年书院。但50元收费有点小贵。', 4, '2016-09-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d154dce6156c' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '里面相当大，很有历史感，不愧是千年书院。但50元收费有点小贵。' AND c.create_time = '2016-09-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院为中国古代四大书院之一，位于岳麓山下，现在湖南大学校内，仍属湖南大学，因而不能网上订票。在岳麓书院，可以感受古代书院学习、研究的氛围。惟楚有材，于斯为盛就题在这里。在这样的人文景点，最好请一个讲解。我们碰到湖南大学的学生志愿者，讲得很好！穿过书院，就到了岳麓山，步行几百米就到了爱晚亭。', 5, '2016-07-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5a35d1dabea8' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院为中国古代四大书院之一，位于岳麓山下，现在湖南大学校内，仍属湖南大学，因而不能网上订票。在岳麓书院，可以感受古代书院学习、研究的氛围。惟楚有材，于斯为盛就题在这里。在这样的人文景点，最好请一个讲解。我们碰到湖南大学的学生志愿者，讲得很好！穿过书院，就到了岳麓山，步行几百米就到了爱晚亭。' AND c.create_time = '2016-07-01 00:00:00');
