INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '作计划时把岳麓书院列入了游览长沙一定要看的景点。岳麓书院算是保护得比较好的。里面的展品古色古香，好像让人穿梭回了古代。在这里可以看到古人的读书环境和书院文化。', 5, '2016-06-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_81443ea65f90' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '作计划时把岳麓书院列入了游览长沙一定要看的景点。岳麓书院算是保护得比较好的。里面的展品古色古香，好像让人穿梭回了古代。在这里可以看到古人的读书环境和书院文化。' AND c.create_time = '2016-06-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '本来以为很大，进去了发现很小，门票很贵啊', 3, '2016-06-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_195f5c6a4f44' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '本来以为很大，进去了发现很小，门票很贵啊' AND c.create_time = '2016-06-16 00:00:00');
