INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '太多修缮，价格太高。闻名但可看的太少了。', 3, '2016-05-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0b9f5319f010' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '太多修缮，价格太高。闻名但可看的太少了。' AND c.create_time = '2016-05-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '买的半价票进去，因为具有很浓厚的文化背景，所以请了位导游进行讲解。里面有的地方在修缮，看到了一块实事求是牌匾，不知伟人是不是从这收到了启发。里面还有一个书院博物馆，喜欢文化旅行的朋友一定要去。', 5, '2016-05-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4953f0b91ce4' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '买的半价票进去，因为具有很浓厚的文化背景，所以请了位导游进行讲解。里面有的地方在修缮，看到了一块实事求是牌匾，不知伟人是不是从这收到了启发。里面还有一个书院博物馆，喜欢文化旅行的朋友一定要去。' AND c.create_time = '2016-05-12 00:00:00');
