INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '充满着一股浓浓的书香味，体会到了当时学堂的感觉', 5, '2016-05-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_45aa7d8534ca' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '充满着一股浓浓的书香味，体会到了当时学堂的感觉' AND c.create_time = '2016-05-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '说是千年书院，其实里面基本都是翻新的建筑，完全失去了古代建筑的质感，但是格局十分不错，门票50学生儿童票25。还有就是商业化严重，游客多素质差，卫生很不好。今年好像是湖大九十年校庆，里面好多建筑正在维修，比较乱。大体上来说，还可以。', 3, '2016-05-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f0de81ada3e3' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '说是千年书院，其实里面基本都是翻新的建筑，完全失去了古代建筑的质感，但是格局十分不错，门票50学生儿童票25。还有就是商业化严重，游客多素质差，卫生很不好。今年好像是湖大九十年校庆，里面好多建筑正在维修，比较乱。大体上来说，还可以。' AND c.create_time = '2016-05-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '50一张门票，里面好多地方在装修，气味很难闻。但是不去看看觉得少了点什么。', 3, '2016-05-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_00a7baf8e5f1' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '50一张门票，里面好多地方在装修，气味很难闻。但是不去看看觉得少了点什么。' AND c.create_time = '2016-05-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭下来，是岳麓书院的后门，跟管理员在那里探讨下，想想还是趁这个机会一起看了吧，门票50元。 进入书院，各种牌匾楹联，各种介绍，反正是可查的东西太多，我独喜欢余秋雨的《千年庭院》 说起楹联，岳麓书院的“千百年楚才导源于此近世纪湘学与日争光”还是我一朋友的姥爷亲笔所书。岳麓书院不光有程朱理学，还有湖南民间木雕展，哈哈，信步而入，欣赏民间艺术。 10点多的时候出了岳麓书院正门，眼前豁然开朗，与相对清净的书院比起来，湖南大学开放的校园各种热闹', 4, '2016-03-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cac6fb1d28a5' AND s.name = '岳麓书院' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭下来，是岳麓书院的后门，跟管理员在那里探讨下，想想还是趁这个机会一起看了吧，门票50元。 进入书院，各种牌匾楹联，各种介绍，反正是可查的东西太多，我独喜欢余秋雨的《千年庭院》 说起楹联，岳麓书院的“千百年楚才导源于此近世纪湘学与日争光”还是我一朋友的姥爷亲笔所书。岳麓书院不光有程朱理学，还有湖南民间木雕展，哈哈，信步而入，欣赏民间艺术。 10点多的时候出了岳麓书院正门，眼前豁然开朗，与相对清净的书院比起来，湖南大学开放的校园各种热闹' AND c.create_time = '2016-03-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '踏入东方红广场，扑面而来的是庄严肃穆与蓬勃活力交融的独特氛围。广场布局规整大气，开阔的空间让人瞬间感到心胸舒畅，无论是日常散步，还是举办大型活动，都能恰到好处地承载人流，毫无局促之感 。 广场上，伟人的雕像巍峨耸立，那坚定的目光、伟岸的身姿，仿佛在无声诉说着往昔峥嵘岁月，激励着每一位前来瞻仰的人，带来无尽的精神鼓舞。周边的绿化布置得很用心，四季更迭，绿植始终生机盎然，为广场添了几分自然的清新与柔和。 广场配套设施也较为贴心，休憩的长椅、照明的路灯，都安置在合理位置。只是在高峰期，人流量较大，公共设施的使用可能会稍显紧张，但这也恰恰证明了广场深受大家喜爱。这里不仅是城市的地标，更是市民情感的寄托，承载着无数美好的回忆与希望，值得每一个人珍视。', 5, '2025-01-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dce72d0b14d1' AND s.name = '东方红广场' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '踏入东方红广场，扑面而来的是庄严肃穆与蓬勃活力交融的独特氛围。广场布局规整大气，开阔的空间让人瞬间感到心胸舒畅，无论是日常散步，还是举办大型活动，都能恰到好处地承载人流，毫无局促之感 。 广场上，伟人的雕像巍峨耸立，那坚定的目光、伟岸的身姿，仿佛在无声诉说着往昔峥嵘岁月，激励着每一位前来瞻仰的人，带来无尽的精神鼓舞。周边的绿化布置得很用心，四季更迭，绿植始终生机盎然，为广场添了几分自然的清新与柔和。 广场配套设施也较为贴心，休憩的长椅、照明的路灯，都安置在合理位置。只是在高峰期，人流量较大，公共设施的使用可能会稍显紧张，但这也恰恰证明了广场深受大家喜爱。这里不仅是城市的地标，更是市民情感的寄托，承载着无数美好的回忆与希望，值得每一个人珍视。' AND c.create_time = '2025-01-25 00:00:00');
