INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '东方红广场在岳麓山地下，夜爬岳麓山，路过东方红广场，向毛主席雕像致敬，缅怀伟人，性价比超高的，广场每天人来人往，交通便利。', 5, '2020-07-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_449241a3849d' AND s.name = '东方红广场' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '东方红广场在岳麓山地下，夜爬岳麓山，路过东方红广场，向毛主席雕像致敬，缅怀伟人，性价比超高的，广场每天人来人往，交通便利。' AND c.create_time = '2020-07-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '晚上爬岳麓山，东方红广场转转，夜景好美好漂亮，向毛主席雕像致敬，敬仰之心油然而生，性价比超高的，值得推荐给大家，棒棒的哦！', 5, '2020-06-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_449241a3849d' AND s.name = '东方红广场' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '晚上爬岳麓山，东方红广场转转，夜景好美好漂亮，向毛主席雕像致敬，敬仰之心油然而生，性价比超高的，值得推荐给大家，棒棒的哦！' AND c.create_time = '2020-06-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '东方红广场坐落于湘潭城市中心区南北景观轴上，东抱现代圆润的湘潭大剧院，西拥高雅清秀的广电中心，南接宽敞平直的芙蓉路，北依山清水秀的湖湘公园，地下有近5万平米的综合商城。广场建设投资逾5亿，历时近3年。其状内圆外方，面积15公顷，东西长598米，南北宽248米。东方红广场是一个融纪念、集会与休闲诸功能于一体的综合性文化广场。', 5, '2020-05-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_35fb461dcaca' AND s.name = '东方红广场' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '东方红广场坐落于湘潭城市中心区南北景观轴上，东抱现代圆润的湘潭大剧院，西拥高雅清秀的广电中心，南接宽敞平直的芙蓉路，北依山清水秀的湖湘公园，地下有近5万平米的综合商城。广场建设投资逾5亿，历时近3年。其状内圆外方，面积15公顷，东西长598米，南北宽248米。东方红广场是一个融纪念、集会与休闲诸功能于一体的综合性文化广场。' AND c.create_time = '2020-05-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖南大学的门口，就是湖南省最出名的东方红广场，能考到这里的学子，基本都是学霸级别的，这里环境挺1清幽，广场也很开阔。。。', 4, '2020-04-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2febdb7ab5f8' AND s.name = '东方红广场' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖南大学的门口，就是湖南省最出名的东方红广场，能考到这里的学子，基本都是学霸级别的，这里环境挺1清幽，广场也很开阔。。。' AND c.create_time = '2020-04-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '就在岳麓山的山脚。靠近湖南大学校区的入口这 白天的时间有一种特别安静得感觉 少了熙熙攘攘的游客的广场可以看到很多人来这里晨练和休息 巨大的伟人雕像 背后就是很棒的岳麓山景观 前往岳麓书院的途中希望可以静下心感受一番', 5, '2020-03-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1792ee7618ca' AND s.name = '东方红广场' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '就在岳麓山的山脚。靠近湖南大学校区的入口这 白天的时间有一种特别安静得感觉 少了熙熙攘攘的游客的广场可以看到很多人来这里晨练和休息 巨大的伟人雕像 背后就是很棒的岳麓山景观 前往岳麓书院的途中希望可以静下心感受一番' AND c.create_time = '2020-03-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙的东方红广场是湖南大学的主广场，沿着桃子湖，过了自卑亭，便是东方红广场了，在这里拍照留念的人很多，有毛泽东主席的全身雕像，附近的建筑也很有特色。', 4, '2020-02-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5ef2fbbff335' AND s.name = '东方红广场' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙的东方红广场是湖南大学的主广场，沿着桃子湖，过了自卑亭，便是东方红广场了，在这里拍照留念的人很多，有毛泽东主席的全身雕像，附近的建筑也很有特色。' AND c.create_time = '2020-02-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '从南门登山的必经之路，假日车多', 4, '2019-10-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8921b8e103fd' AND s.name = '东方红广场' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '从南门登山的必经之路，假日车多' AND c.create_time = '2019-10-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '东方红广场位于长沙市岳麓区麓山南路2号，位于湖南大学校内。 广场左边通往岳麓山南门，右边通往岳麓书院。游客前往岳麓山必经东方红广场。 广场中间矗立着一尊高大的毛主席雕像，看起来庄重威严让人心生敬畏，雕塑后面题有《沁园春&amp;#183;长沙》的碑文。 周边绿化好，旁边是湖南大学民国复古楼，红砖墙面看起来很有格调。', 5, '2019-08-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_94d251f9b577' AND s.name = '东方红广场' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '东方红广场位于长沙市岳麓区麓山南路2号，位于湖南大学校内。 广场左边通往岳麓山南门，右边通往岳麓书院。游客前往岳麓山必经东方红广场。 广场中间矗立着一尊高大的毛主席雕像，看起来庄重威严让人心生敬畏，雕塑后面题有《沁园春&amp;#183;长沙》的碑文。 周边绿化好，旁边是湖南大学民国复古楼，红砖墙面看起来很有格调。' AND c.create_time = '2019-08-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很是庄重肃穆，让人一下子觉得气势磅礴。瞻仰毛主席雕像，重温沁园春雪的诗词。北国风光，千里冰封，万里雪飘。洗涤一下心灵，让自己威武。', 5, '2019-06-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_04f5852d0720' AND s.name = '东方红广场' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很是庄重肃穆，让人一下子觉得气势磅礴。瞻仰毛主席雕像，重温沁园春雪的诗词。北国风光，千里冰封，万里雪飘。洗涤一下心灵，让自己威武。' AND c.create_time = '2019-06-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '就一个亭子，真的！火得没道理，都挺闲的！', 1, '2026-01-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1431d626f2c7' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '就一个亭子，真的！火得没道理，都挺闲的！' AND c.create_time = '2026-01-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '人蛮多的 旁边就是岳麓书院 打卡OK', 5, '2025-12-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d4c8095da632' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '人蛮多的 旁边就是岳麓书院 打卡OK' AND c.create_time = '2025-12-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '大名鼎鼎，人也很多。 红绿相映，非常醒目。 从岳麓书院过来，很近。 有很多取景打卡的地方。 景点本身还不错 而让它名噪一时的是杜牧的诗。 所以文化和旅游一定要联动', 5, '2025-11-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_713d05727a8e' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '大名鼎鼎，人也很多。 红绿相映，非常醒目。 从岳麓书院过来，很近。 有很多取景打卡的地方。 景点本身还不错 而让它名噪一时的是杜牧的诗。 所以文化和旅游一定要联动' AND c.create_time = '2025-11-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭是我国四大名亭之一，坐落在岳麓山风景区清风峡中，毗邻岳麓书院北门。这里四周被古树环绕，以枫香树众多，在深秋时节，层林尽染，红叶似火，非常壮美。', 5, '2025-10-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c532e4804b05' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭是我国四大名亭之一，坐落在岳麓山风景区清风峡中，毗邻岳麓书院北门。这里四周被古树环绕，以枫香树众多，在深秋时节，层林尽染，红叶似火，非常壮美。' AND c.create_time = '2025-10-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '当然值得一游！爱晚亭不仅风景优美，历史文化底蕴丰富，还能让人放松心情，感受岳麓山的宁静与雅致。无论是喜欢自然风光还是文化探索的游客，都能在这里找到乐趣。建议早晨或傍晚前往，景色更佳，体验也更为宁静。', 5, '2025-10-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_57307591000a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '当然值得一游！爱晚亭不仅风景优美，历史文化底蕴丰富，还能让人放松心情，感受岳麓山的宁静与雅致。无论是喜欢自然风光还是文化探索的游客，都能在这里找到乐趣。建议早晨或傍晚前往，景色更佳，体验也更为宁静。' AND c.create_time = '2025-10-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '那是书本里的东西，真的值得去看看，看的更多是情怀', 5, '2025-09-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7dbbf8a9073c' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '那是书本里的东西，真的值得去看看，看的更多是情怀' AND c.create_time = '2025-09-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于长沙市岳麓区岳麓山山脚，亭子不大，但因为有历史，颇受游人青睐。名字来源于著名诗句霜叶红于二月花，停车坐爱枫林晚。上面的题词有毛泽东亲自题写，环境颇为清幽。不过，目前由于游人过多，已经成为著名网红打卡地', 5, '2025-07-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_bda256671d0e' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于长沙市岳麓区岳麓山山脚，亭子不大，但因为有历史，颇受游人青睐。名字来源于著名诗句霜叶红于二月花，停车坐爱枫林晚。上面的题词有毛泽东亲自题写，环境颇为清幽。不过，目前由于游人过多，已经成为著名网红打卡地' AND c.create_time = '2025-07-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '坐爱枫林晚～很美，就在岳麓山里面，可以先逛岳麓书院，接着走到爱晚亭，夏天也很美', 5, '2025-07-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e6081362d82e' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '坐爱枫林晚～很美，就在岳麓山里面，可以先逛岳麓书院，接着走到爱晚亭，夏天也很美' AND c.create_time = '2025-07-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在长沙岳麓山清风峡中，一座朱漆八角亭静卧枫林，它就是蜚声遐迩的爱晚亭。 爱晚亭，原名红叶亭，由清代岳麓书院山长罗典所建，后因杜牧“停车坐爱枫林晚，霜叶红于二月花”的诗意，更名为爱晚亭。亭子古朴典雅，八柱重檐，琉璃碧瓦，亭角飞翘，恰似灵动欲飞的鸟儿。 每至深秋，爱晚亭宛如被打翻的颜料盘。周边枫林经霜，枫叶似火，与亭身朱漆相互辉映，绘就一幅色彩浓烈的山林秋景图。毛泽东青年时，常在此与挚友纵论时事、激昂文字，为这处胜景更添人文魅力。 从岳麓山入口拾级而上，行至爱晚亭，既能赏山林之美，聆听松涛阵阵，体悟自然的灵动韵律；又能于亭中凭栏，触摸岁月的痕迹，感受历史与文化的深厚底蕴。来爱晚亭，观丹枫似火，忆先辈豪情，在千年文化的浸润中，邂逅一场浪漫的秋日之约。', 5, '2025-03-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a1bef757ab06' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在长沙岳麓山清风峡中，一座朱漆八角亭静卧枫林，它就是蜚声遐迩的爱晚亭。 爱晚亭，原名红叶亭，由清代岳麓书院山长罗典所建，后因杜牧“停车坐爱枫林晚，霜叶红于二月花”的诗意，更名为爱晚亭。亭子古朴典雅，八柱重檐，琉璃碧瓦，亭角飞翘，恰似灵动欲飞的鸟儿。 每至深秋，爱晚亭宛如被打翻的颜料盘。周边枫林经霜，枫叶似火，与亭身朱漆相互辉映，绘就一幅色彩浓烈的山林秋景图。毛泽东青年时，常在此与挚友纵论时事、激昂文字，为这处胜景更添人文魅力。 从岳麓山入口拾级而上，行至爱晚亭，既能赏山林之美，聆听松涛阵阵，体悟自然的灵动韵律；又能于亭中凭栏，触摸岁月的痕迹，感受历史与文化的深厚底蕴。来爱晚亭，观丹枫似火，忆先辈豪情，在千年文化的浸润中，邂逅一场浪漫的秋日之约。' AND c.create_time = '2025-03-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '环境好，景色好，有导游讲解更好了', 5, '2025-02-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8d75c85fb203' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '环境好，景色好，有导游讲解更好了' AND c.create_time = '2025-02-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '踏入岳麓山，行至爱晚亭，就像邂逅了一位从诗画里走来的佳人，古韵悠然，满是惊喜。 抬眼望去，爱晚亭被四周的青山绿树温柔环抱，朱红的亭柱在葱郁草木的映衬下格外夺目，仿佛是在翠绿画布上精心勾勒的点睛之笔。亭顶飞檐翘角，恰似展翅欲飞的鲲鹏，灵动又不失庄重。 走近亭子，抚摸着那历经岁月打磨的亭柱，仿佛能触摸到历史的脉络。这里曾是文人墨客的雅集之地，他们在此挥毫泼墨，留下无数动人诗篇。枫叶红透的时节，漫山遍野的枫叶如烈火般燃烧，与爱晚亭相互辉映，宛如一幅绝美的秋日画卷，“停车坐爱枫林晚，霜叶红于二月花”描绘的盛景在此真实上演。 亭内空间不大，却恰到好处地营造出一种宁静而温馨的氛围。坐于亭中，微风拂面，带来山林间独有的清新气息，让人身心舒畅。耳边传来清脆的鸟鸣，与不远处潺潺的溪流声交织在一起，宛如一首自然的交响曲。 不过，每到旅游旺季，爱晚亭总是游人如织，想找个角落静静感受它的美都有些困难。但即便如此，也无法掩盖它的独特魅力。爱晚亭是历史与自然的完美融合，是喧嚣尘世中的一方诗意净土，每一次到访，都能收获别样的感动与美好。', 5, '2025-01-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dce72d0b14d1' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '踏入岳麓山，行至爱晚亭，就像邂逅了一位从诗画里走来的佳人，古韵悠然，满是惊喜。 抬眼望去，爱晚亭被四周的青山绿树温柔环抱，朱红的亭柱在葱郁草木的映衬下格外夺目，仿佛是在翠绿画布上精心勾勒的点睛之笔。亭顶飞檐翘角，恰似展翅欲飞的鲲鹏，灵动又不失庄重。 走近亭子，抚摸着那历经岁月打磨的亭柱，仿佛能触摸到历史的脉络。这里曾是文人墨客的雅集之地，他们在此挥毫泼墨，留下无数动人诗篇。枫叶红透的时节，漫山遍野的枫叶如烈火般燃烧，与爱晚亭相互辉映，宛如一幅绝美的秋日画卷，“停车坐爱枫林晚，霜叶红于二月花”描绘的盛景在此真实上演。 亭内空间不大，却恰到好处地营造出一种宁静而温馨的氛围。坐于亭中，微风拂面，带来山林间独有的清新气息，让人身心舒畅。耳边传来清脆的鸟鸣，与不远处潺潺的溪流声交织在一起，宛如一首自然的交响曲。 不过，每到旅游旺季，爱晚亭总是游人如织，想找个角落静静感受它的美都有些困难。但即便如此，也无法掩盖它的独特魅力。爱晚亭是历史与自然的完美融合，是喧嚣尘世中的一方诗意净土，每一次到访，都能收获别样的感动与美好。' AND c.create_time = '2025-01-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙著名的景点，如果从南门进可以步行，从东门进需要坐车，否则很远。', 5, '2025-01-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f5603fb87fa4' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙著名的景点，如果从南门进可以步行，从东门进需要坐车，否则很远。' AND c.create_time = '2025-01-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于长沙市岳麓山岳麓书院后青枫峡的小山上，始建于清乾隆五十七年（1792年），因岳麓山上层林尽染、红叶似火的秋景而命名为红叶亭，后经湖广总督毕沅引用唐代诗人杜牧《山行》中的名句“停车坐爱枫林晚，霜叶红于二月花”，更名为爱晚亭。 爱晚亭与滁州醉翁亭、杭州湖心亭、北京陶然亭并称中国四大名亭。是文人墨客抒发情感的理想场所。从古至今，无数文人名仕在这里留下了珍贵的诗篇和书法作品。唐代杜牧的《山行》，“远上寒山石径斜，白云生处有人家。停车坐爱枫林晚，霜叶红于二月花”。不仅歌颂了岳麓山的秋色美，也使得爱晚亭名扬四海，成为名流游长沙必来之地。 爱晚亭历史悠久，可惜抗日战争时期被毁，1952年重建。爱晚亭占地面积50平方米，边长6.23米，台基高0.4米，通高12米。内金柱圆木丹漆，外檐柱四根，由整条方形花岗石加工而成。亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。亭内有一横匾，上刻毛泽东手迹《沁园春·长沙》一词，亭正面额朱色鎏金“爱晚亭”匾，系毛泽东而题。 毛泽东青年时代，常与蔡和森、杨开慧等人聚会爱晚亭下，纵谈时局，探求真理。学生的他们从爱晚亭登山，或分散在山中露宿，或顶着大风雨，进行“风浴”“雨浴”。电视剧《怡同学少年》中毛泽东与朋友们会谈的地点之一，便是直接取景于爱晚亭。毛主席1952年应邀为“爱晚亭”题名，这三个大字横写在一页中国人民革命军事委员会的红色竖格稿纸上。 爱晚亭古迹《放鹤》石刻或《二南诗刻》，两首诗为宋代张南轩和清代钱南园两位大文人游的七韵诗。石刻后移至清枫桥南端的六角茅亭中。 今天的爱晚亭不仅是凭吊古人，追思领神的景点，更是观赏美景，诵领诗词的文艺小青向往之地。', 5, '2025-01-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5c55010c5b7a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于长沙市岳麓山岳麓书院后青枫峡的小山上，始建于清乾隆五十七年（1792年），因岳麓山上层林尽染、红叶似火的秋景而命名为红叶亭，后经湖广总督毕沅引用唐代诗人杜牧《山行》中的名句“停车坐爱枫林晚，霜叶红于二月花”，更名为爱晚亭。 爱晚亭与滁州醉翁亭、杭州湖心亭、北京陶然亭并称中国四大名亭。是文人墨客抒发情感的理想场所。从古至今，无数文人名仕在这里留下了珍贵的诗篇和书法作品。唐代杜牧的《山行》，“远上寒山石径斜，白云生处有人家。停车坐爱枫林晚，霜叶红于二月花”。不仅歌颂了岳麓山的秋色美，也使得爱晚亭名扬四海，成为名流游长沙必来之地。 爱晚亭历史悠久，可惜抗日战争时期被毁，1952年重建。爱晚亭占地面积50平方米，边长6.23米，台基高0.4米，通高12米。内金柱圆木丹漆，外檐柱四根，由整条方形花岗石加工而成。亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。亭内有一横匾，上刻毛泽东手迹《沁园春·长沙》一词，亭正面额朱色鎏金“爱晚亭”匾，系毛泽东而题。 毛泽东青年时代，常与蔡和森、杨开慧等人聚会爱晚亭下，纵谈时局，探求真理。学生的他们从爱晚亭登山，或分散在山中露宿，或顶着大风雨，进行“风浴”“雨浴”。电视剧《怡同学少年》中毛泽东与朋友们会谈的地点之一，便是直接取景于爱晚亭。毛主席1952年应邀为“爱晚亭”题名，这三个大字横写在一页中国人民革命军事委员会的红色竖格稿纸上。 爱晚亭古迹《放鹤》石刻或《二南诗刻》，两首诗为宋代张南轩和清代钱南园两位大文人游的七韵诗。石刻后移至清枫桥南端的六角茅亭中。 今天的爱晚亭不仅是凭吊古人，追思领神的景点，更是观赏美景，诵领诗词的文艺小青向往之地。' AND c.create_time = '2025-01-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭古雅秀丽，四周枫林环绕。 是个赏秋的好去处，“停车坐爱枫林晚”的意境尽显。 这里还承载着许多历史文化，很有韵味。 总的来说，爱晚亭很值得一去。', 5, '2024-12-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9e91398754fc' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭古雅秀丽，四周枫林环绕。 是个赏秋的好去处，“停车坐爱枫林晚”的意境尽显。 这里还承载着许多历史文化，很有韵味。 总的来说，爱晚亭很值得一去。' AND c.create_time = '2024-12-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '美丽与精致。 岳麓山爱晚亭，古典建筑之美，让人不禁为之倾倒。 爱晚亭是典型的中式古典园林式亭子，按照重檐四 披攒尖顶建造 P重檐：即亭子有2套顶，使得亭子气势高亢 P四披：即四条斜边，使得亭子端庄稳重，方正敞 亮 丫攒尖：即在顶部交汇为一点，形成尖顶，使得亭子具有一种向心的凝聚力。 心 亭子的檐角呈现反凹曲线向上翘起，展示跃跃欲飞之势，使得亭子更加活泼、飘逸。 亭周丹柱碧瓦、白玉护栏，彩绘藻井，五一不展示了这座名亭的美丽与精致。 岳麓山爱晚亭，不仅是一座古典建筑，更是一种文化的传承。', 4, '2024-12-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4e4739670474' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '美丽与精致。 岳麓山爱晚亭，古典建筑之美，让人不禁为之倾倒。 爱晚亭是典型的中式古典园林式亭子，按照重檐四 披攒尖顶建造 P重檐：即亭子有2套顶，使得亭子气势高亢 P四披：即四条斜边，使得亭子端庄稳重，方正敞 亮 丫攒尖：即在顶部交汇为一点，形成尖顶，使得亭子具有一种向心的凝聚力。 心 亭子的檐角呈现反凹曲线向上翘起，展示跃跃欲飞之势，使得亭子更加活泼、飘逸。 亭周丹柱碧瓦、白玉护栏，彩绘藻井，五一不展示了这座名亭的美丽与精致。 岳麓山爱晚亭，不仅是一座古典建筑，更是一种文化的传承。' AND c.create_time = '2024-12-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于岳麓区风景区内，沿岳麓书院旁的小路拾节而上就可以到了。“停车坐爱枫林晚，霜叶红于二月花”是赏秋的好地方。', 5, '2024-12-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ab45feacf28f' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于岳麓区风景区内，沿岳麓书院旁的小路拾节而上就可以到了。“停车坐爱枫林晚，霜叶红于二月花”是赏秋的好地方。' AND c.create_time = '2024-12-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '远山寒山石径斜，白云深处有人家。停车坐爱枫林晚，霜叶红于二月花。爱晚亭的名声人尽皆知，爱晚亭的风光让人流连忘返。这里也是岳麓山的网红之一，拍照打卡的胜地。一定要注意人流，排队等待是常有的事情，如果想避开，那就要早点前往了', 5, '2024-12-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7498d93b1f02' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '远山寒山石径斜，白云深处有人家。停车坐爱枫林晚，霜叶红于二月花。爱晚亭的名声人尽皆知，爱晚亭的风光让人流连忘返。这里也是岳麓山的网红之一，拍照打卡的胜地。一定要注意人流，排队等待是常有的事情，如果想避开，那就要早点前往了' AND c.create_time = '2024-12-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于湖南省长沙市岳麓区湘江西岸岳麓山风景名胜区内东侧清风峡中 。', 5, '2024-11-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于湖南省长沙市岳麓区湘江西岸岳麓山风景名胜区内东侧清风峡中 。' AND c.create_time = '2024-11-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '当我来到这里时，这里的景色确实美丽，爱晚亭不仅是一个休息的地方，更是一个文化印记。它见证了毛泽东早期的革命活动，是中国革命历史的重要场所之一。', 5, '2024-10-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_afe9d8680e60' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '当我来到这里时，这里的景色确实美丽，爱晚亭不仅是一个休息的地方，更是一个文化印记。它见证了毛泽东早期的革命活动，是中国革命历史的重要场所之一。' AND c.create_time = '2024-10-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '20231217全天： 1、爱晚亭位于5A景区岳麓山•橘子洲旅游区，其位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、爱晚亭是位于岳麓书院西门外的正方形双檐亭，是中国古代四大名亭之一，清乾隆年间由罗典所建，高12米，匾额是1952年毛泽东应湖南大学校长李达之邀手书，亭内壁刻有毛泽东的《泌园春•长沙》。', 5, '2024-03-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_506707a09f1d' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '20231217全天： 1、爱晚亭位于5A景区岳麓山•橘子洲旅游区，其位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、爱晚亭是位于岳麓书院西门外的正方形双檐亭，是中国古代四大名亭之一，清乾隆年间由罗典所建，高12米，匾额是1952年毛泽东应湖南大学校长李达之邀手书，亭内壁刻有毛泽东的《泌园春•长沙》。' AND c.create_time = '2024-03-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '人很多，爱晚亭，岳麓书院湖南大学都在岳麓山的南山那边，，岳麓山上就是一条健身山路，没什么景点，个人感觉想看这几个点的，可以从南门步行上去，，不用花40块的直通车还要走一大段的路才到', 4, '2023-11-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2c9c6baa1cce' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '人很多，爱晚亭，岳麓书院湖南大学都在岳麓山的南山那边，，岳麓山上就是一条健身山路，没什么景点，个人感觉想看这几个点的，可以从南门步行上去，，不用花40块的直通车还要走一大段的路才到' AND c.create_time = '2023-11-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '因杜牧的诗句而闻名于世的爱晚亭，一直都想来参观游览一下，趁着这次国庆假期，特地起个大早过来参观，长沙还没有进入深秋，树叶还是翠绿的，没有看到杜牧诗中的“霜叶红于二月花”，但景色悠然，还是让人心旷神怡。', 4, '2023-10-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_306b01ebf696' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '因杜牧的诗句而闻名于世的爱晚亭，一直都想来参观游览一下，趁着这次国庆假期，特地起个大早过来参观，长沙还没有进入深秋，树叶还是翠绿的，没有看到杜牧诗中的“霜叶红于二月花”，但景色悠然，还是让人心旷神怡。' AND c.create_time = '2023-10-04 00:00:00');
