INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙市岳麓山爱晚亭很值得一逛的哦！', 5, '2023-09-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_48f09af00016' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙市岳麓山爱晚亭很值得一逛的哦！' AND c.create_time = '2023-09-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '就在岳麓山清风峡中，岳麓书院穿出去不远就到。始建于清乾隆五十七年，为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。', 5, '2023-09-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_222895c82720' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '就在岳麓山清风峡中，岳麓书院穿出去不远就到。始建于清乾隆五十七年，为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。' AND c.create_time = '2023-09-12 00:00:00');
