INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭景色宜人，风景很美。点的外卖，送过来还是热乎的，味道很不错，很正宗的朝鲜冷面，很好吃。', 4, '2023-09-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f3c00afef9ec' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭景色宜人，风景很美。点的外卖，送过来还是热乎的，味道很不错，很正宗的朝鲜冷面，很好吃。' AND c.create_time = '2023-09-09 00:00:00');
