INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '就在岳麓山上，我们一路从湖南大学、岳麓书院到了爱晚亭。路上有很多枫树，虽然还不到季节，枫叶没有很黄，但是景色也挺漂亮的。亭子不大，但是人挺多的。', 5, '2023-08-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c8476d0cb28e' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '就在岳麓山上，我们一路从湖南大学、岳麓书院到了爱晚亭。路上有很多枫树，虽然还不到季节，枫叶没有很黄，但是景色也挺漂亮的。亭子不大，但是人挺多的。' AND c.create_time = '2023-08-26 00:00:00');
