INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙爱晚亭位于长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆年间，为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。亭内有一横匾，上刻毛泽东手迹《沁园春·长沙》一词，亭正面额朱色鎏金“爱晚亭”匾，系毛泽东而题。亭中方石上刻有张南轩和钱南园游山的七律诗。', 5, '2023-06-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_861818c3561a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙爱晚亭位于长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆年间，为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。亭内有一横匾，上刻毛泽东手迹《沁园春·长沙》一词，亭正面额朱色鎏金“爱晚亭”匾，系毛泽东而题。亭中方石上刻有张南轩和钱南园游山的七律诗。' AND c.create_time = '2023-06-02 00:00:00');
