INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '枫叶红了的时候真的是美景，红红的一片天地，让人留恋。', 5, '2023-05-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2c5752e269ba' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '枫叶红了的时候真的是美景，红红的一片天地，让人留恋。' AND c.create_time = '2023-05-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '如果来到长沙爬岳麓山，可以来爱晚亭看看', 5, '2023-05-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3b2705e2c073' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '如果来到长沙爬岳麓山，可以来爱晚亭看看' AND c.create_time = '2023-05-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙岳麓山的爱晚亭。羽泉周末，经常去爬岳麓山，路过婉婷非常美军摄。非常值得一去。', 5, '2023-05-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_344bff17fedc' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙岳麓山的爱晚亭。羽泉周末，经常去爬岳麓山，路过婉婷非常美军摄。非常值得一去。' AND c.create_time = '2023-05-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆年间，为清代岳麓书院山长罗典创建，原名红叶亭。亭内有一横匾，上刻毛主席手迹《沁园春·长沙》一词，亭正面额朱色鎏金“爱晚亭”匾，系毛主席而题。亭中方石上刻有张南轩和钱南园游山的七律诗。爱晚亭古朴典雅，亭坐西向东，三面环山，整体上保留了较多清代亭台楼阁建筑的风格。', 5, '2023-05-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_861818c3561a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆年间，为清代岳麓书院山长罗典创建，原名红叶亭。亭内有一横匾，上刻毛主席手迹《沁园春·长沙》一词，亭正面额朱色鎏金“爱晚亭”匾，系毛主席而题。亭中方石上刻有张南轩和钱南园游山的七律诗。爱晚亭古朴典雅，亭坐西向东，三面环山，整体上保留了较多清代亭台楼阁建筑的风格。' AND c.create_time = '2023-05-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '从岳麓山南门进走几百米就到了，路上两边都是枫叶，可惜周末去的，人特多，背景特别杂，还好后来发现在第一、二个水潭间过道拍，更好看而且还能完美的避开人群', 5, '2023-05-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c8476d0cb28e' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '从岳麓山南门进走几百米就到了，路上两边都是枫叶，可惜周末去的，人特多，背景特别杂，还好后来发现在第一、二个水潭间过道拍，更好看而且还能完美的避开人群' AND c.create_time = '2023-05-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '一年四季都十分美丽的地方，尤其是秋冬季节', 5, '2023-05-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_113d2ca697be' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '一年四季都十分美丽的地方，尤其是秋冬季节' AND c.create_time = '2023-05-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于岳麓书院后青枫峡的小山上，八柱重檐，顶部覆盖绿色琉璃瓦，攒尖宝顶，内柱为红色木柱，外柱为花岗石方柱。原名“红叶亭”，又名“爱枫亭”。后据唐代诗人杜牧《山行》而改名为爱晚亭，取“停车坐爱枫林晚，霜叶红于二月花”之诗意。坐在爱晚亭下，喝了杯茶颜悦色。', 5, '2023-05-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cf11b4860213' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于岳麓书院后青枫峡的小山上，八柱重檐，顶部覆盖绿色琉璃瓦，攒尖宝顶，内柱为红色木柱，外柱为花岗石方柱。原名“红叶亭”，又名“爱枫亭”。后据唐代诗人杜牧《山行》而改名为爱晚亭，取“停车坐爱枫林晚，霜叶红于二月花”之诗意。坐在爱晚亭下，喝了杯茶颜悦色。' AND c.create_time = '2023-05-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在岳麓山景区里的一个景点 从南门进入的话可以先去看一下 和岳麓书院很近 景色秀丽 游览岳麓山景区的话顺便就一起游览这里了。', 4, '2023-05-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e331c99a91f5' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在岳麓山景区里的一个景点 从南门进入的话可以先去看一下 和岳麓书院很近 景色秀丽 游览岳麓山景区的话顺便就一起游览这里了。' AND c.create_time = '2023-05-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【景色】赞赞赞 【趣味】赞赞赞 【性价比】赞赞赞', 5, '2023-05-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e546c0934e34' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【景色】赞赞赞 【趣味】赞赞赞 【性价比】赞赞赞' AND c.create_time = '2023-05-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙爱晚亭景色优美趣味盎然性价比最高', 5, '2023-05-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_235ac3d61ea4' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙爱晚亭景色优美趣味盎然性价比最高' AND c.create_time = '2023-05-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭是毛泽东在20世纪初探求革命真理的历史见证，也是中国亭台建筑的经典之一。 爱晚亭，从现代的美学观点来看，不仅是旅游景点或者一个简单的建筑，而是一种文化的印记。爱晚亭上有许多壁画、对联、诗赋等，后人正是因为爱晚亭里面蕴含了文化因素才会想到去游玩、参观，而并不是为了休息而去。 在以爱晚亭等为代表的，富有文化内涵的亭里面，是以文化传承吸引游客为基本功能，而不仅仅是装饰风景和供人休息。 6 旅游信息', 5, '2023-05-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d975ee87b585' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭是毛泽东在20世纪初探求革命真理的历史见证，也是中国亭台建筑的经典之一。 爱晚亭，从现代的美学观点来看，不仅是旅游景点或者一个简单的建筑，而是一种文化的印记。爱晚亭上有许多壁画、对联、诗赋等，后人正是因为爱晚亭里面蕴含了文化因素才会想到去游玩、参观，而并不是为了休息而去。 在以爱晚亭等为代表的，富有文化内涵的亭里面，是以文化传承吸引游客为基本功能，而不仅仅是装饰风景和供人休息。 6 旅游信息' AND c.create_time = '2023-05-14 00:00:00');
