INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙市岳麓山上爱晚亭绿树成荫，溪水潺潺，很宜人。', 5, '2023-04-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ea296b92f1f8' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙市岳麓山上爱晚亭绿树成荫，溪水潺潺，很宜人。' AND c.create_time = '2023-04-25 00:00:00');
