INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于湖南长沙岳麓 山半山腰上，建于清代乾隆年间。 原名红叶亭，又名爱枫亭，位于岳麓山下清风峡中，亭坐西向东，三面环山，古枫参天。爱晚亭始建于清乾隆五十七年（1792年），由岳麓书院山长罗典倡建。后据湖广总督毕沅之意，取杜牧“停车坐爱枫林晚，霜叶红于二月花”诗意，将亭改名为爱晚亭。原为木结构，同治初（1862年-1870年）改为砖砌。该亭古朴典雅，平面正方形，边长6.23米，通高12米。内金柱圆木丹漆，外檐柱四根，由整条方形花岗石加工而成。亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。正面额朱色鎏金“爱晚亭”匾，系1952年毛泽东应湖南大学校长李达之约而题。湖心亭位于浙江省杭州市西湖中心的小岛上，又叫振鹭亭，初建于明嘉靖三十一年，万历年间重建改称湖心亭。明朝文人张岱作有《湖心亭看雪》。交通指南 爱晚亭长沙火车站乘坐公交车202路，旅1，立珊线到岳麓山南门站（注意是南门，不是第四医院那边', 5, '2023-04-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_54fe22db4ae0' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于湖南长沙岳麓 山半山腰上，建于清代乾隆年间。 原名红叶亭，又名爱枫亭，位于岳麓山下清风峡中，亭坐西向东，三面环山，古枫参天。爱晚亭始建于清乾隆五十七年（1792年），由岳麓书院山长罗典倡建。后据湖广总督毕沅之意，取杜牧“停车坐爱枫林晚，霜叶红于二月花”诗意，将亭改名为爱晚亭。原为木结构，同治初（1862年-1870年）改为砖砌。该亭古朴典雅，平面正方形，边长6.23米，通高12米。内金柱圆木丹漆，外檐柱四根，由整条方形花岗石加工而成。亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。正面额朱色鎏金“爱晚亭”匾，系1952年毛泽东应湖南大学校长李达之约而题。湖心亭位于浙江省杭州市西湖中心的小岛上，又叫振鹭亭，初建于明嘉靖三十一年，万历年间重建改称湖心亭。明朝文人张岱作有《湖心亭看雪》。交通指南 爱晚亭长沙火车站乘坐公交车202路，旅1，立珊线到岳麓山南门站（注意是南门，不是第四医院那边' AND c.create_time = '2023-04-20 00:00:00');
