INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '十年前的六月景色，十年后三月的景色，相隔十年，亭子没变，周边略有些不同了。 十年前的爱晚亭，满是周边居民区的大爷大妈在闲聊乘凉。 现在的爱晚亭，满是游客休息拍照。 少了当地的人情世故，闲谈话聊。多了游客的拍照打卡，熙熙攘攘。', 5, '2023-03-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_409febc48b76' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '十年前的六月景色，十年后三月的景色，相隔十年，亭子没变，周边略有些不同了。 十年前的爱晚亭，满是周边居民区的大爷大妈在闲聊乘凉。 现在的爱晚亭，满是游客休息拍照。 少了当地的人情世故，闲谈话聊。多了游客的拍照打卡，熙熙攘攘。' AND c.create_time = '2023-03-20 00:00:00');
