INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭平面呈方形，占地面积50平方米。亭边长6.23米，台基高0.4米，通高12米。[1]爱晚亭内金柱圆木丹漆，由整条方形花岗石加工而成。[10]亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。爱晚亭八柱支撑，分上下两层，亭角翘首相望。爱晚亭亭台东西两面的亭棂悬有“爱晚亭”金字红匾。', 5, '2023-01-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a280d8eb73f7' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭平面呈方形，占地面积50平方米。亭边长6.23米，台基高0.4米，通高12米。[1]爱晚亭内金柱圆木丹漆，由整条方形花岗石加工而成。[10]亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。爱晚亭八柱支撑，分上下两层，亭角翘首相望。爱晚亭亭台东西两面的亭棂悬有“爱晚亭”金字红匾。' AND c.create_time = '2023-01-27 00:00:00');
