INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国四大名亭之一，出了岳麓书院就可看到', 4, '2022-10-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b3804f883d68' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国四大名亭之一，出了岳麓书院就可看到' AND c.create_time = '2022-10-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭始建于清乾隆五十七年 （1792年），为清代岳麓 书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。亭内有一横匾，上刻毛泽东手迹《沁园春•长沙》一词：亭正面额朱色鎏金“爱晚亭”匾，系毛泽东而题。亭中方石上刻有张南轩和钱南园游山的七律诗。爱晚亭古朴典雅，亭坐西向东，三面环山，整体上保留了较多清代亭台楼阁建筑的风格。', 5, '2022-10-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7741b35c2712' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭始建于清乾隆五十七年 （1792年），为清代岳麓 书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。亭内有一横匾，上刻毛泽东手迹《沁园春•长沙》一词：亭正面额朱色鎏金“爱晚亭”匾，系毛泽东而题。亭中方石上刻有张南轩和钱南园游山的七律诗。爱晚亭古朴典雅，亭坐西向东，三面环山，整体上保留了较多清代亭台楼阁建筑的风格。' AND c.create_time = '2022-10-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '又到了去爱晚亭的季节，山上的枫叶红了，红的那个让人心动哟！', 5, '2022-10-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_56eee9700ad8' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '又到了去爱晚亭的季节，山上的枫叶红了，红的那个让人心动哟！' AND c.create_time = '2022-10-29 00:00:00');
