INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '名人名言名山水，络绎不绝皆慕名。', 5, '2022-09-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9d2ddd532946' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '名人名言名山水，络绎不绝皆慕名。' AND c.create_time = '2022-09-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭与陶然亭、湖心亭、醉翁亭并称中国四大名亭，也是革命活动胜地，为湖南省文物保护单位。亭形为重檐八柱，琉璃碧瓦，亭角飞翘，自远处观之似凌空欲飞状。内为丹漆园柱，外檐四石柱为花岗岩，亭中彩绘藻井，东西两面亭棂悬以红底鎏金“爱晚亭”，是由当时的湖南大学校长李达专函请毛泽东所书手迹而制。', 4, '2022-09-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d294339a93a1' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭与陶然亭、湖心亭、醉翁亭并称中国四大名亭，也是革命活动胜地，为湖南省文物保护单位。亭形为重檐八柱，琉璃碧瓦，亭角飞翘，自远处观之似凌空欲飞状。内为丹漆园柱，外檐四石柱为花岗岩，亭中彩绘藻井，东西两面亭棂悬以红底鎏金“爱晚亭”，是由当时的湖南大学校长李达专函请毛泽东所书手迹而制。' AND c.create_time = '2022-09-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '真的是一个不可错过的打卡地，火速上头！', 5, '2022-09-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_73b34e319f99' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '真的是一个不可错过的打卡地，火速上头！' AND c.create_time = '2022-09-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙著名打卡地，以伟大领袖青年时期的求学经历名动全国，五十多年前每天有漫山遍野的人来瞻仰，据说最多的时候一天超过一百万，亭前有伟人的手书。', 5, '2022-08-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_404c50398002' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙著名打卡地，以伟大领袖青年时期的求学经历名动全国，五十多年前每天有漫山遍野的人来瞻仰，据说最多的时候一天超过一百万，亭前有伟人的手书。' AND c.create_time = '2022-08-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于湖南省长沙市湘江西岸岳麓山下，始建于清朝1792年，原名“红叶亭”、“枫叶亭”，被破坏后于1952重建，并更名为“爱晚亭”。 爱晚亭是一座双檐八角的方形亭子，有八根大红柱，琉璃碧瓦，亭角龙尾巴似的翘起来，亭牌上刻着三个醒目的大字：“爱晚亭”，是由当时的湖南大学校长李达专函请毛泽东主席手书而做成的。', 5, '2022-08-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_39c031085864' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于湖南省长沙市湘江西岸岳麓山下，始建于清朝1792年，原名“红叶亭”、“枫叶亭”，被破坏后于1952重建，并更名为“爱晚亭”。 爱晚亭是一座双檐八角的方形亭子，有八根大红柱，琉璃碧瓦，亭角龙尾巴似的翘起来，亭牌上刻着三个醒目的大字：“爱晚亭”，是由当时的湖南大学校长李达专函请毛泽东主席手书而做成的。' AND c.create_time = '2022-08-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖南长沙岳麓山上有许多名胜古迹，其中的亭类建筑应该有几十个，但最有名的一定非爱晚亭莫属。爱晚亭始建于清乾隆五十七年（1792年），由岳麓书院山长罗典主持建造，最初命名为红叶亭。时任湖广总督毕沅认为亭名过于俗气，不够雅致，建议改为爱晚亭。两个亭名虽然均源自唐代诗人杜牧的名句“停车坐爱枫林晚，霜叶红于二月花。”但后者显然更有意境，更富诗意。', 5, '2022-08-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0d4900978b55' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖南长沙岳麓山上有许多名胜古迹，其中的亭类建筑应该有几十个，但最有名的一定非爱晚亭莫属。爱晚亭始建于清乾隆五十七年（1792年），由岳麓书院山长罗典主持建造，最初命名为红叶亭。时任湖广总督毕沅认为亭名过于俗气，不够雅致，建议改为爱晚亭。两个亭名虽然均源自唐代诗人杜牧的名句“停车坐爱枫林晚，霜叶红于二月花。”但后者显然更有意境，更富诗意。' AND c.create_time = '2022-08-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在湖南长沙岳麓山公园上面。爱晚亭三个字由毛主席手书，风景不错。', 5, '2022-08-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c48a36093ee6' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在湖南长沙岳麓山公园上面。爱晚亭三个字由毛主席手书，风景不错。' AND c.create_time = '2022-08-05 00:00:00');
