INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭 旁的银杏林，一颗颗高大挺拔的银杏树枝叶相互交错，金黄的银杏叶铺满路面，让人仿佛置身于童话世界。中心岛的爱晚亭与色彩斑斓的银杏林相映成趣，强烈的色彩冲击，构成一幅色彩缤纷，美如油画的金秋图。', 5, '2022-05-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7741b35c2712' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭 旁的银杏林，一颗颗高大挺拔的银杏树枝叶相互交错，金黄的银杏叶铺满路面，让人仿佛置身于童话世界。中心岛的爱晚亭与色彩斑斓的银杏林相映成趣，强烈的色彩冲击，构成一幅色彩缤纷，美如油画的金秋图。' AND c.create_time = '2022-05-20 00:00:00');
