INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，位于 湖南 省 岳麓山 下清风峡中，亭坐西向东，三面环山。始建于清乾隆五十七年（1792年），为岳麓书院院长罗典创建，原名红叶亭，后由湖广总督毕沅根据唐代诗人杜牧“远上寒山石径斜，白云深处有人家。停车坐爱枫林晚，霜叶红于二月花”（《山行》）的诗句，改名爱晚亭。', 4, '2022-01-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_73fd29df962a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，位于 湖南 省 岳麓山 下清风峡中，亭坐西向东，三面环山。始建于清乾隆五十七年（1792年），为岳麓书院院长罗典创建，原名红叶亭，后由湖广总督毕沅根据唐代诗人杜牧“远上寒山石径斜，白云深处有人家。停车坐爱枫林晚，霜叶红于二月花”（《山行》）的诗句，改名爱晚亭。' AND c.create_time = '2022-01-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '景色不错，风光独好，值得一游。', 4, '2022-01-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_748964e0a3e6' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '景色不错，风光独好，值得一游。' AND c.create_time = '2022-01-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭', 4, '2022-01-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_30fda0c881ba' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭' AND c.create_time = '2022-01-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭坐落在长沙城西的著名景点岳麓山上。', 4, '2021-12-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_38c8e274bfa9' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭坐落在长沙城西的著名景点岳麓山上。' AND c.create_time = '2021-12-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这座座落在岳麓书院里面的亭子，应该是中国最有名的亭子之一吧。', 5, '2021-12-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4cd8d2a105bc' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这座座落在岳麓书院里面的亭子，应该是中国最有名的亭子之一吧。' AND c.create_time = '2021-12-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '一个美丽的地方，特别是秋天过去枫叶红时。', 5, '2021-11-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4fdf33189a9b' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '一个美丽的地方，特别是秋天过去枫叶红时。' AND c.create_time = '2021-11-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭占地面积50平方米，边长6.23米，台基高0.4米，通高12米。内金柱圆木丹漆，外檐柱四根，由整条方形花岗石加工而成。亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。亭内有一横匾，上刻毛泽东手迹《沁园春·长沙》一词，亭正面额朱色鎏金&quot;爱晚亭&quot;匾，系毛泽东而题。亭中方石上刻有张南轩和钱南园游山的七律诗。爱晚亭古朴典雅，亭坐西向东，三面环山，整体上保留了较多清代亭台楼阁建筑的风格。', 4, '2021-11-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c107a1a1f6ca' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭占地面积50平方米，边长6.23米，台基高0.4米，通高12米。内金柱圆木丹漆，外檐柱四根，由整条方形花岗石加工而成。亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。亭内有一横匾，上刻毛泽东手迹《沁园春·长沙》一词，亭正面额朱色鎏金&quot;爱晚亭&quot;匾，系毛泽东而题。亭中方石上刻有张南轩和钱南园游山的七律诗。爱晚亭古朴典雅，亭坐西向东，三面环山，整体上保留了较多清代亭台楼阁建筑的风格。' AND c.create_time = '2021-11-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '秋季来岳麓山玩，“爱晚亭”是观赏红叶的绝佳位置。岳麓山位于长沙市内，是长沙市民茶余饭后常去的一个地方', 5, '2021-10-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5a43fd894558' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '秋季来岳麓山玩，“爱晚亭”是观赏红叶的绝佳位置。岳麓山位于长沙市内，是长沙市民茶余饭后常去的一个地方' AND c.create_time = '2021-10-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '山青水秀的好地方，爱晚亭旁边开了一家茶颜悦色。', 5, '2021-10-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a6305b88f418' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '山青水秀的好地方，爱晚亭旁边开了一家茶颜悦色。' AND c.create_time = '2021-10-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '景色真美，很有历史文化气息，意义大', 5, '2021-10-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2cd19bdeb3e5' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '景色真美，很有历史文化气息，意义大' AND c.create_time = '2021-10-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭是长沙著名的景点，不错的地方，文物古迹，保存的很好，推荐来看看', 5, '2021-08-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b37825e31215' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭是长沙著名的景点，不错的地方，文物古迹，保存的很好，推荐来看看' AND c.create_time = '2021-08-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '秋天枫叶红的时候来，应该是可以体验到停车坐爱枫林晚，霜叶红于二月花的境界吧', 3, '2021-07-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_17abcd183a0a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '秋天枫叶红的时候来，应该是可以体验到停车坐爱枫林晚，霜叶红于二月花的境界吧' AND c.create_time = '2021-07-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭原名红叶庭，位于湖南长沙岳麓山下清风峡，是国家5A级旅游景点。革命活动胜地，它与陶然亭、湖心亭、醉翁亭并称为中国四大名亭。爱晚亭因杜牧《山行》中停车坐爱枫林晚 而得名。', 5, '2021-07-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fd8ab24450fc' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭原名红叶庭，位于湖南长沙岳麓山下清风峡，是国家5A级旅游景点。革命活动胜地，它与陶然亭、湖心亭、醉翁亭并称为中国四大名亭。爱晚亭因杜牧《山行》中停车坐爱枫林晚 而得名。' AND c.create_time = '2021-07-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭', 4, '2021-07-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b17e0d15d9d2' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭' AND c.create_time = '2021-07-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '我们这种游客去长沙旅游，总会去岳麓山，去了岳麓山，如何去爱晚亭，岳麓书院路上四 跟上女生的观景台，爱晚亭现在其实去的意义不大了，就是一个普通的裙子 常年坐着一些休闲纳凉的人讲真的，你想拍到无人的爱晚亭洪峰照片很难，真的很难', 4, '2021-06-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '我们这种游客去长沙旅游，总会去岳麓山，去了岳麓山，如何去爱晚亭，岳麓书院路上四 跟上女生的观景台，爱晚亭现在其实去的意义不大了，就是一个普通的裙子 常年坐着一些休闲纳凉的人讲真的，你想拍到无人的爱晚亭洪峰照片很难，真的很难' AND c.create_time = '2021-06-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙岳麓山爱晚亭，驰名遐迩，此亭原名“红叶”，又名“爱枫”，今名“爱晚”，为中国四大名亭之一，因杜牧《山行》中“停车坐爱枫林晚”而得名。爱晚亭在我国亭台建筑中，影响甚大，堪称亭台之中的经典建筑------古往今来，大浪淘沙，风格独特，值得一游！', 5, '2021-06-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2092d25e8400' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙岳麓山爱晚亭，驰名遐迩，此亭原名“红叶”，又名“爱枫”，今名“爱晚”，为中国四大名亭之一，因杜牧《山行》中“停车坐爱枫林晚”而得名。爱晚亭在我国亭台建筑中，影响甚大，堪称亭台之中的经典建筑------古往今来，大浪淘沙，风格独特，值得一游！' AND c.create_time = '2021-06-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位列中国四大名亭之一的爱晚亭，就位于长沙的岳麓书院的后门，这里也是书通往岳麓山的一条登山路，当然因为一句古诗，这座亭子也被寄予了极高的文学价值。 现在来说，如果只是看亭子，其实没有什么特别的地方，尽管修葺的还是比较完好，但也就是这个样子了，感觉不出有什么特别的，当然从个头来说，爱晚亭还是比较大的，四方的亭子。但是因为名气响，所以排队的人络绎不绝，想找个好角度拍照还是很辛苦的。 从爱晚亭到岳麓书院后面这一条道上，又是池塘又是枫树，氛围很精致，等到了秋天，欣赏霜叶红于二月花的景色也还是很美的。', 5, '2021-05-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7faee16d404a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位列中国四大名亭之一的爱晚亭，就位于长沙的岳麓书院的后门，这里也是书通往岳麓山的一条登山路，当然因为一句古诗，这座亭子也被寄予了极高的文学价值。 现在来说，如果只是看亭子，其实没有什么特别的地方，尽管修葺的还是比较完好，但也就是这个样子了，感觉不出有什么特别的，当然从个头来说，爱晚亭还是比较大的，四方的亭子。但是因为名气响，所以排队的人络绎不绝，想找个好角度拍照还是很辛苦的。 从爱晚亭到岳麓书院后面这一条道上，又是池塘又是枫树，氛围很精致，等到了秋天，欣赏霜叶红于二月花的景色也还是很美的。' AND c.create_time = '2021-05-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在岳麓书院外面，通往岳麓山的一个小亭子，很多人拍照。', 5, '2021-05-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2f52a00fedb1' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在岳麓书院外面，通往岳麓山的一个小亭子，很多人拍照。' AND c.create_time = '2021-05-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭300多年来屡有修葺，现存的样式整体上保留了较多清代亭台楼阁建筑的风格，内金柱圆木丹漆，外檐柱四根，由整条方形花岗石加工而成。亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。亭内有一横匾，上刻《沁园春·长沙》一词，亭正面额朱色鎏金“爱晚亭”匾。亭中方石上刻有张南轩和钱南园游山的七律诗。爱晚亭周边的环境也格外清幽，三面环山，亭前有一汪碧水，秋天漫山红叶绽放，格外的美。它不仅仅是旅游景点或者一个简单的建筑，而是一种文化的印记。', 4, '2021-05-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_30fda0c881ba' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭300多年来屡有修葺，现存的样式整体上保留了较多清代亭台楼阁建筑的风格，内金柱圆木丹漆，外檐柱四根，由整条方形花岗石加工而成。亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。亭内有一横匾，上刻《沁园春·长沙》一词，亭正面额朱色鎏金“爱晚亭”匾。亭中方石上刻有张南轩和钱南园游山的七律诗。爱晚亭周边的环境也格外清幽，三面环山，亭前有一汪碧水，秋天漫山红叶绽放，格外的美。它不仅仅是旅游景点或者一个简单的建筑，而是一种文化的印记。' AND c.create_time = '2021-05-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '因为一首诗而天下闻名，无论如何，到长沙总要去下', 5, '2021-05-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7c4394eceb1f' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '因为一首诗而天下闻名，无论如何，到长沙总要去下' AND c.create_time = '2021-05-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '“停车坐爱枫林晚，霜叶红于二月花” 爱晚亭古朴典雅，亭坐西向东，三面环山。爱晚亭内为丹漆圆柱，外檐四石柱为花岗岩，加之配以东西两面亭棂所悬的红底鎏金“爱晚亭”匾额，令亭子有现代意味。', 5, '2021-05-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_31a88c23afd4' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '“停车坐爱枫林晚，霜叶红于二月花” 爱晚亭古朴典雅，亭坐西向东，三面环山。爱晚亭内为丹漆圆柱，外檐四石柱为花岗岩，加之配以东西两面亭棂所悬的红底鎏金“爱晚亭”匾额，令亭子有现代意味。' AND c.create_time = '2021-05-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '5A名副其实，真的是太美了。不到现场难以感受诗词氛围。美主要不是因为亭，而是因为独特的风景，背山面水，中间凿出一名亭，美不胜收。', 5, '2021-05-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b835b9470276' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '5A名副其实，真的是太美了。不到现场难以感受诗词氛围。美主要不是因为亭，而是因为独特的风景，背山面水，中间凿出一名亭，美不胜收。' AND c.create_time = '2021-05-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这么有名的地方黄金周当然爆棚，所以拍个亭子顶意思意思吧', 2, '2021-05-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7d09cf556032' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这么有名的地方黄金周当然爆棚，所以拍个亭子顶意思意思吧' AND c.create_time = '2021-05-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭的匾额是由毛泽东主席题写的。据介绍亭子原来名为红叶亭，后来湖广总督毕沅，依据唐代诗人杜牧“停车坐爱枫林晚，霜叶红于二月花”的著名诗句，更名成为了爱晚亭。', 5, '2021-05-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9746b1d3a009' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭的匾额是由毛泽东主席题写的。据介绍亭子原来名为红叶亭，后来湖广总督毕沅，依据唐代诗人杜牧“停车坐爱枫林晚，霜叶红于二月花”的著名诗句，更名成为了爱晚亭。' AND c.create_time = '2021-05-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中国四大名庭之一，因为杜牧的一首诗而出名的景点。亭子在岳麓山内，靠近岳麓书院，是个免费的景点。从湖南大地铁站出来步行15分钟便可到达，亭子周围长满了绿植，远看景色更美。', 5, '2021-04-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cae2438ce589' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中国四大名庭之一，因为杜牧的一首诗而出名的景点。亭子在岳麓山内，靠近岳麓书院，是个免费的景点。从湖南大地铁站出来步行15分钟便可到达，亭子周围长满了绿植，远看景色更美。' AND c.create_time = '2021-04-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '枫叶比亭美 古诗更胜景 众人看热闹 流水方知情', 4, '2021-04-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9d2ddd532946' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '枫叶比亭美 古诗更胜景 众人看热闹 流水方知情' AND c.create_time = '2021-04-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，岳麓山上最著名景点之一。并且是中国四大名亭之一。是由-岳麓书院院长-罗典于清朝乾隆五十七年建成。曾被多为诗人、名人在诗句中提到。', 5, '2021-04-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_60b7ee2cac9c' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，岳麓山上最著名景点之一。并且是中国四大名亭之一。是由-岳麓书院院长-罗典于清朝乾隆五十七年建成。曾被多为诗人、名人在诗句中提到。' AND c.create_time = '2021-04-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '来爱晚亭坐坐，惬意啊，真的好棒', 5, '2021-04-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fd80030885db' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '来爱晚亭坐坐，惬意啊，真的好棒' AND c.create_time = '2021-04-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在长沙岳麓山上，秋天坐那看枫叶。', 3, '2021-03-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_63be8aadc86b' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在长沙岳麓山上，秋天坐那看枫叶。' AND c.create_time = '2021-03-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '三面环山，四周被枫林包围，是岳麓山中观赏红叶秋景最佳地之一。', 5, '2021-03-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7790c5a0beab' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '三面环山，四周被枫林包围，是岳麓山中观赏红叶秋景最佳地之一。' AND c.create_time = '2021-03-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '秋天来看红叶的好去处！美丽的湖南大学！', 5, '2021-03-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_65103fab70c9' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '秋天来看红叶的好去处！美丽的湖南大学！' AND c.create_time = '2021-03-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。', 5, '2021-03-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c83ba13ab8ff' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。' AND c.create_time = '2021-03-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭始建于清乾隆五十七年，原名红叶亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，为清代岳麓书院山长罗典创建，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名为爱晚亭。', 5, '2021-03-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8661760db693' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭始建于清乾隆五十七年，原名红叶亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，为清代岳麓书院山长罗典创建，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名为爱晚亭。' AND c.create_time = '2021-03-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于湖南省长沙市湘江西岸，地处岳麓山清风峡中，原名红叶亭，始建于清乾隆五十七年，为清代岳麓书院山长罗典创建，后由湖广总督毕沅，根据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。', 5, '2021-03-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ebf93d708d4b' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于湖南省长沙市湘江西岸，地处岳麓山清风峡中，原名红叶亭，始建于清乾隆五十七年，为清代岳麓书院山长罗典创建，后由湖广总督毕沅，根据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。' AND c.create_time = '2021-03-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '亭子很小，游客很多，基本都是来拍照打卡的。一般都是从岳麓书院出来，然后到达的这里。往前可继续上山，如果不想爬山还有汽车可以下山。', 5, '2021-03-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_40f9cb15970c' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '亭子很小，游客很多，基本都是来拍照打卡的。一般都是从岳麓书院出来，然后到达的这里。往前可继续上山，如果不想爬山还有汽车可以下山。' AND c.create_time = '2021-03-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '到了岳麓山一定要去爱晚亭，经典景点之一，爬爬山累了，在爱晚亭坐坐，不错的选择，趣味性强，美景尽收眼底，令人心旷神怡，棒棒的。', 5, '2021-03-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_449241a3849d' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '到了岳麓山一定要去爱晚亭，经典景点之一，爬爬山累了，在爱晚亭坐坐，不错的选择，趣味性强，美景尽收眼底，令人心旷神怡，棒棒的。' AND c.create_time = '2021-03-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '不知道自己什么时候再去长沙，再去岳麓山再去爱晚亭了，每次去旅游都是很开心的，可惜开心的时光总是很快就度过了，旅游的时间总是很快就消磨完了，也不知道为什么 却爱晚亭的话记得要从湖南大学那边都登录上去哦 ，现在有地铁可以到。', 5, '2021-03-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '不知道自己什么时候再去长沙，再去岳麓山再去爱晚亭了，每次去旅游都是很开心的，可惜开心的时光总是很快就度过了，旅游的时间总是很快就消磨完了，也不知道为什么 却爱晚亭的话记得要从湖南大学那边都登录上去哦 ，现在有地铁可以到。' AND c.create_time = '2021-03-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '阳光明媚，空气清新，天气不错，登高望远，到了岳麓山，爱晚亭必须转转，打卡一下，趣味性强，性价比超高的，令人心旷神怡，棒棒的。', 5, '2021-02-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_449241a3849d' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '阳光明媚，空气清新，天气不错，登高望远，到了岳麓山，爱晚亭必须转转，打卡一下，趣味性强，性价比超高的，令人心旷神怡，棒棒的。' AND c.create_time = '2021-02-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于岳麓山里面的景点，爱晚亭。距离岳麓山南门不远，比邻岳麓书院。枫叶红时，这里很美。', 3, '2021-02-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c35b162ad48a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于岳麓山里面的景点，爱晚亭。距离岳麓山南门不远，比邻岳麓书院。枫叶红时，这里很美。' AND c.create_time = '2021-02-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '虽然来过几次，但仍然觉得很不错。', 5, '2021-01-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1d7840570c8c' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '虽然来过几次，但仍然觉得很不错。' AND c.create_time = '2021-01-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院后门（西门）出去不远就是爱晚亭。有人说爱晚亭——中国四大名亭之一，是长沙最“水”的国保，我不这么看。它得名于罗典的一次头脑风暴，取字于杜牧《山行》，意境悠远美好，已是岳麓山乃至长沙近代历史的见证，也是长沙的地标。爱晚亭周边四季葱绿，冬日雪景也极美。爱晚之于岳麓，就像醉翁之于瑯玡，是以其所属名山之魂，也是其所属名城之重要名片。参观湖南大学，参观岳麓书院，到了岳麓山脚下，不妨去爱晚亭坐坐。看主席手书之亭名，呼吸岳麓山清新的空气，东眺星城今日之城景，怀想那挥斥方遒的意气岁月……', 5, '2021-01-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_89afe526eed9' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院后门（西门）出去不远就是爱晚亭。有人说爱晚亭——中国四大名亭之一，是长沙最“水”的国保，我不这么看。它得名于罗典的一次头脑风暴，取字于杜牧《山行》，意境悠远美好，已是岳麓山乃至长沙近代历史的见证，也是长沙的地标。爱晚亭周边四季葱绿，冬日雪景也极美。爱晚之于岳麓，就像醉翁之于瑯玡，是以其所属名山之魂，也是其所属名城之重要名片。参观湖南大学，参观岳麓书院，到了岳麓山脚下，不妨去爱晚亭坐坐。看主席手书之亭名，呼吸岳麓山清新的空气，东眺星城今日之城景，怀想那挥斥方遒的意气岁月……' AND c.create_time = '2021-01-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '四大名亭之一【爱晚亭】景区将杜牧《山行》诗意体现得淋漓尽致。“远上寒山石径斜，白云生处有人家，停车坐爱枫林晚，霜叶红于二月花”。临摹篆体《山行》体会诗的意境。', 5, '2021-01-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_31cf4fec11c2' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '四大名亭之一【爱晚亭】景区将杜牧《山行》诗意体现得淋漓尽致。“远上寒山石径斜，白云生处有人家，停车坐爱枫林晚，霜叶红于二月花”。临摹篆体《山行》体会诗的意境。' AND c.create_time = '2021-01-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙岳麓山爱晚亭，我个人第二次去，这次真的看到红彤彤的枫叶了，在红色枫叶的衬托下，爱晚亭显得格外的漂亮，里面有毛主席诗词《沁园春.长沙》，来岳麓山的游客基本上都会来此处！', 5, '2021-01-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙岳麓山爱晚亭，我个人第二次去，这次真的看到红彤彤的枫叶了，在红色枫叶的衬托下，爱晚亭显得格外的漂亮，里面有毛主席诗词《沁园春.长沙》，来岳麓山的游客基本上都会来此处！' AND c.create_time = '2021-01-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '从岳麓书院的后门出来，走不了多远就到了爱晚亭了，个人觉得它之所以那么有名气大概就是由于唐朝诗人杜牧的那首停车坐爱枫林晚，霜叶红于二月花的诗吧', 4, '2021-01-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9716a74321ed' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '从岳麓书院的后门出来，走不了多远就到了爱晚亭了，个人觉得它之所以那么有名气大概就是由于唐朝诗人杜牧的那首停车坐爱枫林晚，霜叶红于二月花的诗吧' AND c.create_time = '2021-01-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。', 5, '2021-01-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_66b399782d41' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。' AND c.create_time = '2021-01-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '停车坐爱枫林晚，霜叶红于二月花。让人羡慕诗人的情怀', 5, '2020-12-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d733fb230f27' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '停车坐爱枫林晚，霜叶红于二月花。让人羡慕诗人的情怀' AND c.create_time = '2020-12-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '秋天的爱晚亭，很漂亮，。。。。', 5, '2020-12-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0530995e05ad' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '秋天的爱晚亭，很漂亮，。。。。' AND c.create_time = '2020-12-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '停车坐爱枫林晚，枫叶红于二月花今年第一次可能也是唯一一次看到成片的枫叶就在爱晚亭，这里的确特别美，像仙境一样，清澈透明的湖水，特别是傍晚的阳光照射下，明明是绿色的叶子，会泛着红色，像真正的枫叶一样。', 5, '2020-12-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6b371022bf7f' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '停车坐爱枫林晚，枫叶红于二月花今年第一次可能也是唯一一次看到成片的枫叶就在爱晚亭，这里的确特别美，像仙境一样，清澈透明的湖水，特别是傍晚的阳光照射下，明明是绿色的叶子，会泛着红色，像真正的枫叶一样。' AND c.create_time = '2020-12-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '12月上旬来到长沙，坐地铁到湖南大学站下，穿过湖南大学校区，从南门进入岳麓山景区，步行10分钟就到了爱晚亭，红叶季节的爱晚亭分外漂亮。', 5, '2020-12-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7e98a7695e7c' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '12月上旬来到长沙，坐地铁到湖南大学站下，穿过湖南大学校区，从南门进入岳麓山景区，步行10分钟就到了爱晚亭，红叶季节的爱晚亭分外漂亮。' AND c.create_time = '2020-12-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '秋雨、亭子、枫叶、晚霞……此情此景，简直让人想不出更美好的词句来形容。这座四周被枫林包围的亭子，与陶然亭、湖心亭、醉翁亭并称中国四大名亭', 4, '2020-11-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_30fda0c881ba' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '秋雨、亭子、枫叶、晚霞……此情此景，简直让人想不出更美好的词句来形容。这座四周被枫林包围的亭子，与陶然亭、湖心亭、醉翁亭并称中国四大名亭' AND c.create_time = '2020-11-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '和朋友一起去的。很好。景色不错', 5, '2020-11-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7b4d6b7ec489' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '和朋友一起去的。很好。景色不错' AND c.create_time = '2020-11-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这里文化底蕴丰厚，山清水秀古韵书香，这里有几百年历史的沉甸甸，更有近代以来指点江山，激扬文字的壮怀激荡的青春志诚，文化传承的打卡地。', 5, '2020-11-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_75b0b6c6888c' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这里文化底蕴丰厚，山清水秀古韵书香，这里有几百年历史的沉甸甸，更有近代以来指点江山，激扬文字的壮怀激荡的青春志诚，文化传承的打卡地。' AND c.create_time = '2020-11-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭三面环山，四周被枫林包围，是岳麓山中观赏红叶秋景最佳地之一。亭子的四个翼角向上高翘，盖着绿色琉璃瓦，如今悬挂的匾额，是根据毛泽东手书手迹而制。', 4, '2020-11-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_28571e9dca2e' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭三面环山，四周被枫林包围，是岳麓山中观赏红叶秋景最佳地之一。亭子的四个翼角向上高翘，盖着绿色琉璃瓦，如今悬挂的匾额，是根据毛泽东手书手迹而制。' AND c.create_time = '2020-11-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '亭台楼阁掩映在郁郁葱葱的树荫间，真是美', 5, '2020-11-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_31c73d3a2594' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '亭台楼阁掩映在郁郁葱葱的树荫间，真是美' AND c.create_time = '2020-11-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很喜欢湖南长沙的这些免费景点，真的无比喜欢哦。下面看看爱晚亭，然后就跑了，去爬山了，爬山多舒服啊，就是无敌喜欢自虐啊，自虐无敌舒服哈哈哈，爬到山顶看见美景人生还圆满。', 5, '2020-11-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很喜欢湖南长沙的这些免费景点，真的无比喜欢哦。下面看看爱晚亭，然后就跑了，去爬山了，爬山多舒服啊，就是无敌喜欢自虐啊，自虐无敌舒服哈哈哈，爬到山顶看见美景人生还圆满。' AND c.create_time = '2020-11-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭为中国四大名亭之一，位于湖南省长沙市岳麓区岳麓山清枫峡中，名字源于唐诗“停车坐爱枫林晚”。免门票，秋天景色迷人，历来为访秋胜地，夏天气温低于市区3度左右，纳凉避暑胜地。', 4, '2020-11-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1b27c0d76942' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭为中国四大名亭之一，位于湖南省长沙市岳麓区岳麓山清枫峡中，名字源于唐诗“停车坐爱枫林晚”。免门票，秋天景色迷人，历来为访秋胜地，夏天气温低于市区3度左右，纳凉避暑胜地。' AND c.create_time = '2020-11-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '去的时候正是长沙连续阴雨天气，笼罩在烟雨中的爱晚亭拍摄出来就少了阳光的照拂。爱晚亭下围坐的游人也是络绎不绝，亭子可避雨，可遮阴，可休憩，周边的红叶还青苏苏的挂在枝头。', 5, '2020-11-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d464f4b8c1d0' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '去的时候正是长沙连续阴雨天气，笼罩在烟雨中的爱晚亭拍摄出来就少了阳光的照拂。爱晚亭下围坐的游人也是络绎不绝，亭子可避雨，可遮阴，可休憩，周边的红叶还青苏苏的挂在枝头。' AND c.create_time = '2020-11-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '停车坐爱枫林晚，霜叶红于二月花，杜牧的名句，爱晚亭的牌匾，还是毛主席题写，不愧是四大名亭，听说毛主席也多次到爱晚亭游玩。', 5, '2020-10-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2fb2d073607a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '停车坐爱枫林晚，霜叶红于二月花，杜牧的名句，爱晚亭的牌匾，还是毛主席题写，不愧是四大名亭，听说毛主席也多次到爱晚亭游玩。' AND c.create_time = '2020-10-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭古朴典雅，亭坐西向东，三面环山。爱晚亭内为丹漆圆柱，外檐四石柱为花岗岩，加之配以东西两面亭棂所悬的红底鎏金“爱晚亭”匾额，令亭子有现代意味，整体上保留了较多清代亭台楼阁建筑的风格。匾额是由毛泽东所书手迹刻制的，由当时的湖南大学校长李达专函请得。', 5, '2020-10-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_31a88c23afd4' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭古朴典雅，亭坐西向东，三面环山。爱晚亭内为丹漆圆柱，外檐四石柱为花岗岩，加之配以东西两面亭棂所悬的红底鎏金“爱晚亭”匾额，令亭子有现代意味，整体上保留了较多清代亭台楼阁建筑的风格。匾额是由毛泽东所书手迹刻制的，由当时的湖南大学校长李达专函请得。' AND c.create_time = '2020-10-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '停车坐爱枫林晚，霜叶红于二月花说的就是这里了，其实也就是个亭子，只是有了这个典故所以感觉朗朗上口，这里靠近岳麓山出口很近，就在山脚下', 4, '2020-09-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_35bf15448084' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '停车坐爱枫林晚，霜叶红于二月花说的就是这里了，其实也就是个亭子，只是有了这个典故所以感觉朗朗上口，这里靠近岳麓山出口很近，就在山脚下' AND c.create_time = '2020-09-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这个爱晚亭是就是大家熟知的诗句“停车坐爱枫林晚，霜叶红于二月花”而文明的爱晚亭。亭子很漂亮，周边风景很秀丽，只是人太多，拍不出好看的照片了。', 5, '2020-08-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c7a41d95ecf4' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这个爱晚亭是就是大家熟知的诗句“停车坐爱枫林晚，霜叶红于二月花”而文明的爱晚亭。亭子很漂亮，周边风景很秀丽，只是人太多，拍不出好看的照片了。' AND c.create_time = '2020-08-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭景色不错，风景宜人，空气清新，休闲避暑的好去处，一大早来到岳麓山爱晚亭，呼吸呼吸新鲜空气，爬爬山，锻炼锻炼身体，挺好的。', 5, '2020-07-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_449241a3849d' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭景色不错，风景宜人，空气清新，休闲避暑的好去处，一大早来到岳麓山爱晚亭，呼吸呼吸新鲜空气，爬爬山，锻炼锻炼身体，挺好的。' AND c.create_time = '2020-07-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '停车坐爱枫林晚，霜叶红于二月花。 枫林晚:枫树林在晚亭边。 停车:把车亭下来。 诗人为纪念此事遂将亭名改于“爱于晚亭”，后人为易记就将名缩减为“爱晚亭”。 🌝｡ﾟ(ﾟ´Д｀)ﾟ｡爬山中。记录于此纯为胡扯抱怨。🌝', 5, '2020-07-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7b4b0e23d5ab' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '停车坐爱枫林晚，霜叶红于二月花。 枫林晚:枫树林在晚亭边。 停车:把车亭下来。 诗人为纪念此事遂将亭名改于“爱于晚亭”，后人为易记就将名缩减为“爱晚亭”。 🌝｡ﾟ(ﾟ´Д｀)ﾟ｡爬山中。记录于此纯为胡扯抱怨。🌝' AND c.create_time = '2020-07-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '人从众的爱晚亭，其实去岳麓山还是避开双休更好，人少玩起来也尽兴不然排个队烦躁啊。 爱晚亭已经变成纳凉的场所了想拍没人的照片都不可能了好吧。', 4, '2020-07-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '人从众的爱晚亭，其实去岳麓山还是避开双休更好，人少玩起来也尽兴不然排个队烦躁啊。 爱晚亭已经变成纳凉的场所了想拍没人的照片都不可能了好吧。' AND c.create_time = '2020-07-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '唐代大诗人杜牧的七言绝句《山行》中，有“停车坐爱枫林晚，霜叶红于二月花。”二句，位于我国湖南省长沙市湘江西侧岳麓山的清风峡中的爱晚亭的名字就取自这句诗。爱晚亭始建于清乾隆年间，原名红叶亭，后由湖广总督毕沅改为爱晚亭，是一处赏枫的好去处。', 5, '2020-05-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8661760db693' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '唐代大诗人杜牧的七言绝句《山行》中，有“停车坐爱枫林晚，霜叶红于二月花。”二句，位于我国湖南省长沙市湘江西侧岳麓山的清风峡中的爱晚亭的名字就取自这句诗。爱晚亭始建于清乾隆年间，原名红叶亭，后由湖广总督毕沅改为爱晚亭，是一处赏枫的好去处。' AND c.create_time = '2020-05-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，位于我国湖南省长沙市湘江西侧岳麓山的清风峡中，始建于清乾隆年间，原名红叶亭，后湖广总督毕沅根据唐代大诗人杜牧《山行》中“停车坐爱枫林晚，霜叶红于二月花。”二句，改名为爱晚亭。亭内刻有毛泽东同志《泌园春&amp;#183;长沙》一词。在很清净的淡季还有很多人在这里围着照相，其出名程度可见一斑。', 5, '2020-05-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ebf93d708d4b' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，位于我国湖南省长沙市湘江西侧岳麓山的清风峡中，始建于清乾隆年间，原名红叶亭，后湖广总督毕沅根据唐代大诗人杜牧《山行》中“停车坐爱枫林晚，霜叶红于二月花。”二句，改名为爱晚亭。亭内刻有毛泽东同志《泌园春&amp;#183;长沙》一词。在很清净的淡季还有很多人在这里围着照相，其出名程度可见一斑。' AND c.create_time = '2020-05-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '名气大于实际，但文化符号依然强烈无比。', 5, '2020-05-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c799ad1f88a3' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '名气大于实际，但文化符号依然强烈无比。' AND c.create_time = '2020-05-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '毛主席题字 藏在岳麓书院后 不错', 4, '2020-05-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a142f1afd312' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '毛主席题字 藏在岳麓书院后 不错' AND c.create_time = '2020-05-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。[1][2] 爱晚亭占地面积50平方米，边长6.23米，台基高0.4米，通高12米。内金柱圆木丹漆，外檐柱四根，由整条方形花岗石加工而成。亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。亭内有一横匾，上刻毛泽东手迹《泌园春·长沙》一词，亭正面额朱色鎏金“爱晚亭”匾，系毛泽东而题。亭中方石上刻有张南轩和钱南园游山的七律诗。爱晚亭古朴典雅，亭坐西向东，三面环山，整体上保留了较多清代亭台楼阁建筑的风格。', 5, '2020-05-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_35fb461dcaca' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。[1][2] 爱晚亭占地面积50平方米，边长6.23米，台基高0.4米，通高12米。内金柱圆木丹漆，外檐柱四根，由整条方形花岗石加工而成。亭顶重檐四披，攒尖宝顶，四翼角边远伸高翘，覆以绿色琉璃筒瓦。亭内有一横匾，上刻毛泽东手迹《泌园春·长沙》一词，亭正面额朱色鎏金“爱晚亭”匾，系毛泽东而题。亭中方石上刻有张南轩和钱南园游山的七律诗。爱晚亭古朴典雅，亭坐西向东，三面环山，整体上保留了较多清代亭台楼阁建筑的风格。' AND c.create_time = '2020-05-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这里曾经是伟人和他的志同道和的朋友尝谈理想的地方，只可惜，在抗日战争的时候，被一把火给烧掉了，现在看见的爱晚亭，是从修的。', 5, '2020-04-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2febdb7ab5f8' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这里曾经是伟人和他的志同道和的朋友尝谈理想的地方，只可惜，在抗日战争的时候，被一把火给烧掉了，现在看见的爱晚亭，是从修的。' AND c.create_time = '2020-04-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '疫情期间人不是很多，中国四大名亭，值得来看看', 5, '2020-04-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4259eb78c37b' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '疫情期间人不是很多，中国四大名亭，值得来看看' AND c.create_time = '2020-04-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙岳麓山爱晚亭，驰名遐迩。此亭原名“红叶”，又名“爱枫”。清乾隆五十七年（公元一七九二年）山长罗典所建。原名“红叶亭”，又名“爱枫亭”。后据唐代诗人杜牧《山行》而改名为爱晚亭，取“停车坐爱枫林晚，霜叶红于二月花”之诗意', 3, '2020-04-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8c51e29acbf3' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙岳麓山爱晚亭，驰名遐迩。此亭原名“红叶”，又名“爱枫”。清乾隆五十七年（公元一七九二年）山长罗典所建。原名“红叶亭”，又名“爱枫亭”。后据唐代诗人杜牧《山行》而改名为爱晚亭，取“停车坐爱枫林晚，霜叶红于二月花”之诗意' AND c.create_time = '2020-04-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭在岳麓山的半山腰，清风峡内。', 5, '2020-04-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1311830a91b1' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭在岳麓山的半山腰，清风峡内。' AND c.create_time = '2020-04-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭', 4, '2020-03-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8cdab405c216' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭' AND c.create_time = '2020-03-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭也是诗词歌赋中描写的，所以特地来打卡，的确很有意境，亭子有八柱，琉璃瓦，亭沿翘起，非常古朴，而且配合周边一花一木，拍照完美！', 4, '2020-03-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6478bee897e3' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭也是诗词歌赋中描写的，所以特地来打卡，的确很有意境，亭子有八柱，琉璃瓦，亭沿翘起，非常古朴，而且配合周边一花一木，拍照完美！' AND c.create_time = '2020-03-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在深秋的时候可以看枫叶。没有门票。在11月底和12月初是最佳赏枫时节。因杜牧的停车坐爱枫林晚，霜叶红于二月花而闻名。是中国的四大名亭之一。', 5, '2020-03-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_79da5a655d9b' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在深秋的时候可以看枫叶。没有门票。在11月底和12月初是最佳赏枫时节。因杜牧的停车坐爱枫林晚，霜叶红于二月花而闻名。是中国的四大名亭之一。' AND c.create_time = '2020-03-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '从岳麓书院山上的门一出来就可以看到这个依靠在池塘边上的亭子。思然感觉上没有太大的特别 但由于“停车坐爱枫林晚”的词句而闻名 本地人喜欢在这里作为爬山的中间站休息一下进行补给 也的确在太阳打下来的时候这里会有总很安逸舒适的独特奇妙气氛', 5, '2020-03-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1792ee7618ca' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '从岳麓书院山上的门一出来就可以看到这个依靠在池塘边上的亭子。思然感觉上没有太大的特别 但由于“停车坐爱枫林晚”的词句而闻名 本地人喜欢在这里作为爬山的中间站休息一下进行补给 也的确在太阳打下来的时候这里会有总很安逸舒适的独特奇妙气氛' AND c.create_time = '2020-03-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【景色】好喜欢周末来这里玩玩啊！真舒服啊', 5, '2020-02-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fe2c54e41417' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【景色】好喜欢周末来这里玩玩啊！真舒服啊' AND c.create_time = '2020-02-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙市岳麓山上的爱晚亭，是岳麓山风景名胜之一，始建于清乾隆年间，原名红叶亭，又名枫叶亭，后名字取自唐杜牧的诗“停车坐爱枫林晚 霜叶红于二月花”，抗日战争被毁，1952年重建，毛泽东同志题写“爱晚亭”三字。', 5, '2020-02-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e0face20044a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙市岳麓山上的爱晚亭，是岳麓山风景名胜之一，始建于清乾隆年间，原名红叶亭，又名枫叶亭，后名字取自唐杜牧的诗“停车坐爱枫林晚 霜叶红于二月花”，抗日战争被毁，1952年重建，毛泽东同志题写“爱晚亭”三字。' AND c.create_time = '2020-02-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭是长沙岳麓山最出名的景点，是中国赏秋景最美的地方之一，有山有水有层林尽染，是一眼望不到边的美景，也是远上寒山石径狭的原景重现。', 4, '2020-02-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5ef2fbbff335' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭是长沙岳麓山最出名的景点，是中国赏秋景最美的地方之一，有山有水有层林尽染，是一眼望不到边的美景，也是远上寒山石径狭的原景重现。' AND c.create_time = '2020-02-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在岳麓山风景区比较靠近南门的地方，我是从东门开始徒步的，一路较累了，但是见到一个小湖，水光树影、风景优美，映衬出大名鼎鼎的爱晚亭，古朴厚重的历史遗迹与山清水秀的自然风光融为一体，美不胜收、回味无穷！', 5, '2020-02-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5efe1b5bc395' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在岳麓山风景区比较靠近南门的地方，我是从东门开始徒步的，一路较累了，但是见到一个小湖，水光树影、风景优美，映衬出大名鼎鼎的爱晚亭，古朴厚重的历史遗迹与山清水秀的自然风光融为一体，美不胜收、回味无穷！' AND c.create_time = '2020-02-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院后面。石头那边照相的人们很多，也可以去亭子后面照相。11月份去是最好看的。', 4, '2020-01-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7a0c0046f773' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院后面。石头那边照相的人们很多，也可以去亭子后面照相。11月份去是最好看的。' AND c.create_time = '2020-01-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙岳麓山南簏的爱晚亭，当属岳麓山最当红的景点，庄重沉稳大方的亭子，矗立在古树中，红色的爱晚亭三个大字苍劲有力，颇有古风。', 4, '2019-12-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a3ca4e268ae4' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙岳麓山南簏的爱晚亭，当属岳麓山最当红的景点，庄重沉稳大方的亭子，矗立在古树中，红色的爱晚亭三个大字苍劲有力，颇有古风。' AND c.create_time = '2019-12-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭与陶然亭、湖心亭、醉翁亭并称中国四大名亭，也是革命活动胜地，为湖南省文物保护单位。这是在岳麓山半山处，因为是免费的，亭里常坐满了一班本地人。', 5, '2019-12-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭与陶然亭、湖心亭、醉翁亭并称中国四大名亭，也是革命活动胜地，为湖南省文物保护单位。这是在岳麓山半山处，因为是免费的，亭里常坐满了一班本地人。' AND c.create_time = '2019-12-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于长沙岳麓山上，历史悠久！古典诗词中经常描绘爱晚亭，这里是欣赏红色枫叶的好地方，秋季漫山遍野的枫叶盛开，登山来到爱晚亭感受枫叶美景！', 4, '2019-12-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_448578a95409' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于长沙岳麓山上，历史悠久！古典诗词中经常描绘爱晚亭，这里是欣赏红色枫叶的好地方，秋季漫山遍野的枫叶盛开，登山来到爱晚亭感受枫叶美景！' AND c.create_time = '2019-12-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '整个岳麓山是一个大的风景区，而且是一个免费的地方。风景区里有名的地方，爱晚亭是一个最大特色，尤其是这儿的秋色，不过冬天下雪的样子也不错。', 4, '2019-12-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4f55a1c05c59' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '整个岳麓山是一个大的风景区，而且是一个免费的地方。风景区里有名的地方，爱晚亭是一个最大特色，尤其是这儿的秋色，不过冬天下雪的样子也不错。' AND c.create_time = '2019-12-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，我个人觉得还是不错的，历史的厚重感极强，就在岳麓书院的后门不远处，有伟人的足迹！我个人觉得可能是岳麓山最标志性的景点了，很遗憾去的时候枫叶还没有红，不过景色也是很美的！里面还有毛泽东诗词！', 5, '2019-12-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，我个人觉得还是不错的，历史的厚重感极强，就在岳麓书院的后门不远处，有伟人的足迹！我个人觉得可能是岳麓山最标志性的景点了，很遗憾去的时候枫叶还没有红，不过景色也是很美的！里面还有毛泽东诗词！' AND c.create_time = '2019-12-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭因杜牧的诗词“停车坐爱枫林晚，霜叶红于二月花”而闻名，爱晚亭古朴典雅，风景优美，也是观赏枫叶的好地方，十二月到长沙正赶上看枫叶的时节，各种颜色非常漂亮。', 5, '2019-12-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_273d71d98851' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭因杜牧的诗词“停车坐爱枫林晚，霜叶红于二月花”而闻名，爱晚亭古朴典雅，风景优美，也是观赏枫叶的好地方，十二月到长沙正赶上看枫叶的时节，各种颜色非常漂亮。' AND c.create_time = '2019-12-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '秋天的岳麓山是一年中最好的季节，而爱晚亭又是岳麓山的精华之所在，爱晚亭三个字苍劲有力，中式亭子稳重大气，是游客留影的绝佳之处。', 4, '2019-12-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a3ca4e268ae4' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '秋天的岳麓山是一年中最好的季节，而爱晚亭又是岳麓山的精华之所在，爱晚亭三个字苍劲有力，中式亭子稳重大气，是游客留影的绝佳之处。' AND c.create_time = '2019-12-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这个在岳麓山，就在岳麓书院旁边，一个不太特别的亭子，围观的人山人海。', 5, '2019-12-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fa52f2f02063' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这个在岳麓山，就在岳麓书院旁边，一个不太特别的亭子，围观的人山人海。' AND c.create_time = '2019-12-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '明媚的爱晚亭，斑斓的岳麓山和冬雨后的朦胧。虽然天气有些清冷，但是来的人还是挺多的，诗情画意的秋天，爱晚亭的枫叶红了，还不来打卡。', 5, '2019-12-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2b755b506aab' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '明媚的爱晚亭，斑斓的岳麓山和冬雨后的朦胧。虽然天气有些清冷，但是来的人还是挺多的，诗情画意的秋天，爱晚亭的枫叶红了，还不来打卡。' AND c.create_time = '2019-12-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '年轻人非常喜欢的地方，风景优美环境优美值得拥有的地方！', 5, '2019-11-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2111ae25d925' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '年轻人非常喜欢的地方，风景优美环境优美值得拥有的地方！' AND c.create_time = '2019-11-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '毕沅当年常到岳麓山爱晚亭一带游览。罗典的《次石琢堂学使留题书院诗韵二首即以送别》诗后有一条自注：“山中红叶甚盛，山麓有亭，毕秋帆制军名曰‘爱晚’，纪以诗。” 亭内有一横匾，上刻毛泽东手迹《沁园春&amp;#183;长沙》一词，亭额上“爱晚亭”三字是1952年湖南大学重修爱晚亭时，毛泽东同志接受校长李达之请，亲笔题写。 亭前石柱刻对联：“山径晚红舒，五百夭桃新种得；峡云深翠滴，一双驯鹤待笼来”。爱晚亭在我国亭台建筑中，影响甚大，堪称亭台之中的经典建筑。', 4, '2019-11-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0b5c64ffbcc4' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '毕沅当年常到岳麓山爱晚亭一带游览。罗典的《次石琢堂学使留题书院诗韵二首即以送别》诗后有一条自注：“山中红叶甚盛，山麓有亭，毕秋帆制军名曰‘爱晚’，纪以诗。” 亭内有一横匾，上刻毛泽东手迹《沁园春&amp;#183;长沙》一词，亭额上“爱晚亭”三字是1952年湖南大学重修爱晚亭时，毛泽东同志接受校长李达之请，亲笔题写。 亭前石柱刻对联：“山径晚红舒，五百夭桃新种得；峡云深翠滴，一双驯鹤待笼来”。爱晚亭在我国亭台建筑中，影响甚大，堪称亭台之中的经典建筑。' AND c.create_time = '2019-11-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '停车坐爱枫林晚，霜叶红于二月花。中国四大名亭之一。', 5, '2019-11-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8cfcf4c3ac23' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '停车坐爱枫林晚，霜叶红于二月花。中国四大名亭之一。' AND c.create_time = '2019-11-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于长沙岳麓山公园的爱晚亭是去岳麓山必到景点，去的时候还未到深秋时节，山上的树叶还没变红！不过能到此一游也算是不虚此行！', 5, '2019-11-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8b6fe0778698' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于长沙岳麓山公园的爱晚亭是去岳麓山必到景点，去的时候还未到深秋时节，山上的树叶还没变红！不过能到此一游也算是不虚此行！' AND c.create_time = '2019-11-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭很不错的一个地方，整体的环境非常的好，在那里感觉很棒，特别是雨过天晴的时候，空气超棒的，但是去那里的人太多了，有点破坏精致的感觉，是选择在假期的时候去的那里，人很多，但是亭子景致挺不错的。', 5, '2019-11-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1497e1e62e1c' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭很不错的一个地方，整体的环境非常的好，在那里感觉很棒，特别是雨过天晴的时候，空气超棒的，但是去那里的人太多了，有点破坏精致的感觉，是选择在假期的时候去的那里，人很多，但是亭子景致挺不错的。' AND c.create_time = '2019-11-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭是岳麓山经典景点之一，闻名天下，果然名不虚传，令人心旷神怡，感觉非常不错，空气清新，自然、舒适、舒服，不错的选择。', 5, '2019-11-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_449241a3849d' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭是岳麓山经典景点之一，闻名天下，果然名不虚传，令人心旷神怡，感觉非常不错，空气清新，自然、舒适、舒服，不错的选择。' AND c.create_time = '2019-11-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '停车坐爱枫林晚，霜叶红于二月花•漫步爱晚亭 每次一到秋天，总会想要去看看红色的枫叶 但是每次都没有看到正红色的枫叶，现在居然还没有变红，时间上还是早了一些。 想看爱晚亭被红枫包围还是要再过一个月吧 远上寒山石径斜，白云深处有人家。 停车坐爱枫林晚，霜叶红于二月花。 这座亭的名字也是取自这首杜牧的古诗，“爱晚亭”还是非常有美感的 他和陶然亭、湖心亭、醉翁亭并称为中国四大名亭，始建于1792年，距今也有几百年的瞬间了，本以为是深林中的一座很幽深很幽静的亭子，原来并不是，实际看到的和我想象中的完全不一样，这里算是岳麓山景区内最热闹的地方了，也是游客最多的一个点了。 在爱晚亭里面还有毛泽东的提诗“沁园春•长沙”，不仅可以感受山水景色还有红色文化教育，长沙是一个红色教育比较重的城市。 •坐标：岳麓山景区内，岳麓书院西门 •交通：地铁2号线湖南大学2口 •门票：免费 •建议游玩时间：1小时左右 •最佳赏枫时间：11月底12月 •红色景点讲解时间： 工作日：10:30/15:30 周末：10:00/10:30/15:00/15:30 有需要听讲解的可以准点守候时间在这里等待。', 4, '2019-11-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0406c02bb63c' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '停车坐爱枫林晚，霜叶红于二月花•漫步爱晚亭 每次一到秋天，总会想要去看看红色的枫叶 但是每次都没有看到正红色的枫叶，现在居然还没有变红，时间上还是早了一些。 想看爱晚亭被红枫包围还是要再过一个月吧 远上寒山石径斜，白云深处有人家。 停车坐爱枫林晚，霜叶红于二月花。 这座亭的名字也是取自这首杜牧的古诗，“爱晚亭”还是非常有美感的 他和陶然亭、湖心亭、醉翁亭并称为中国四大名亭，始建于1792年，距今也有几百年的瞬间了，本以为是深林中的一座很幽深很幽静的亭子，原来并不是，实际看到的和我想象中的完全不一样，这里算是岳麓山景区内最热闹的地方了，也是游客最多的一个点了。 在爱晚亭里面还有毛泽东的提诗“沁园春•长沙”，不仅可以感受山水景色还有红色文化教育，长沙是一个红色教育比较重的城市。 •坐标：岳麓山景区内，岳麓书院西门 •交通：地铁2号线湖南大学2口 •门票：免费 •建议游玩时间：1小时左右 •最佳赏枫时间：11月底12月 •红色景点讲解时间： 工作日：10:30/15:30 周末：10:00/10:30/15:00/15:30 有需要听讲解的可以准点守候时间在这里等待。' AND c.create_time = '2019-11-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '不错 不错 第二次来了 哈哈哈哈哈 【景色】漂亮', 5, '2019-11-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ea7f506a78ce' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '不错 不错 第二次来了 哈哈哈哈哈 【景色】漂亮' AND c.create_time = '2019-11-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。', 5, '2019-11-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_515574db303c' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，位于湖南省长沙市湘江西岸、岳麓山清风峡中，始建于清乾隆五十七年（1792年），为清代岳麓书院山长罗典创建，原名红叶亭，后由湖广总督毕沅，据“停车坐爱枫林晚，霜叶红于二月花”的诗句，更名爱晚亭。' AND c.create_time = '2019-11-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '停车坐爱枫林晚，霜叶红于二月花。中国古代名亭。', 5, '2019-10-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8cfcf4c3ac23' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '停车坐爱枫林晚，霜叶红于二月花。中国古代名亭。' AND c.create_time = '2019-10-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在岳麓书院附近的小山谷半坡上有个亭子。', 5, '2019-10-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_543a609f28b8' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在岳麓书院附近的小山谷半坡上有个亭子。' AND c.create_time = '2019-10-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '去岳麓山就不得不到爱晚亭，和安徽滁州醉翁亭、浙江绍兴兰亭、北京陶然亭并称中国四大名亭。位于岳麓山景区岳麓书院后青枫峡的小山上，八柱重檐，顶部覆盖绿色琉璃瓦，非常壮观。岳麓山风景四季宜人，尤以秋季“万山红遍、层林尽染”的独特红枫景致闻名。 岳麓山，国家5A景区，位于长沙湘江之滨，现有麓山景区、橘子洲景区、岳麓书院、新民学会四个核心景区。风景四季宜人、秀美多姿，尤以秋季“万山红遍、层林尽染”的独特红枫景致闻名。由于是全免费（个别景点单独收费）的城市山岳型景区，非常推荐一去。 乘坐旅游1线等多路公交可直达，由于距离橘子洲较近，推荐安排在一起游览，从橘子洲步行至溁湾镇站乘坐 301区间在新民学会旧址站下车后步行可到岳麓山。岳麓山海拔不算高，但景区面积大，建议选择步行与索道或观光车结合的方式游览，从南门进入景区步行上山，一路欣赏人文景观，大部分人文景点在南大门这边，然后坐索道下山到北大门出景区。岳麓书院和爱晚亭人气最高，随着指示牌就能到达爱晚亭。在此看看整体外型，还可坐于亭间感受岳麓山的静和美，当然是在非节假日的时候。游览完爱晚亭可以选择向上走继续游览其他景点，但到其他景点距离都还蛮远的，或者向下走一直走到湖南大学的小吃一条街，美食超有名的。', 5, '2019-10-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b6e3ccf3769a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '去岳麓山就不得不到爱晚亭，和安徽滁州醉翁亭、浙江绍兴兰亭、北京陶然亭并称中国四大名亭。位于岳麓山景区岳麓书院后青枫峡的小山上，八柱重檐，顶部覆盖绿色琉璃瓦，非常壮观。岳麓山风景四季宜人，尤以秋季“万山红遍、层林尽染”的独特红枫景致闻名。 岳麓山，国家5A景区，位于长沙湘江之滨，现有麓山景区、橘子洲景区、岳麓书院、新民学会四个核心景区。风景四季宜人、秀美多姿，尤以秋季“万山红遍、层林尽染”的独特红枫景致闻名。由于是全免费（个别景点单独收费）的城市山岳型景区，非常推荐一去。 乘坐旅游1线等多路公交可直达，由于距离橘子洲较近，推荐安排在一起游览，从橘子洲步行至溁湾镇站乘坐 301区间在新民学会旧址站下车后步行可到岳麓山。岳麓山海拔不算高，但景区面积大，建议选择步行与索道或观光车结合的方式游览，从南门进入景区步行上山，一路欣赏人文景观，大部分人文景点在南大门这边，然后坐索道下山到北大门出景区。岳麓书院和爱晚亭人气最高，随着指示牌就能到达爱晚亭。在此看看整体外型，还可坐于亭间感受岳麓山的静和美，当然是在非节假日的时候。游览完爱晚亭可以选择向上走继续游览其他景点，但到其他景点距离都还蛮远的，或者向下走一直走到湖南大学的小吃一条街，美食超有名的。' AND c.create_time = '2019-10-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭就住岳麓山的山脚下，很多人去的，都去拍照，很好玩的，爱晚亭太有名的，一首诗一个亭子，好多人趋之若鹜，真的很棒的哦。', 5, '2019-10-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_853993187332' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭就住岳麓山的山脚下，很多人去的，都去拍照，很好玩的，爱晚亭太有名的，一首诗一个亭子，好多人趋之若鹜，真的很棒的哦。' AND c.create_time = '2019-10-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山脚下的一个不大的亭子，很有名', 3, '2019-10-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_48209a80b72b' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山脚下的一个不大的亭子，很有名' AND c.create_time = '2019-10-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山景区中的爱晚亭得名于大诗人杜牧（停车坐爱枫林晚，霜叶红于二月花）的绝句，全国应该来说基本可以算是无人不知无人不晓了，同时他也是长沙著名观看枫叶的好地方，在这里，畅享千百年来，无数文人墨客在这里吟诗作对，激荡江山，让人心生向往。', 4, '2019-10-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e7c08f3f0ef6' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山景区中的爱晚亭得名于大诗人杜牧（停车坐爱枫林晚，霜叶红于二月花）的绝句，全国应该来说基本可以算是无人不知无人不晓了，同时他也是长沙著名观看枫叶的好地方，在这里，畅享千百年来，无数文人墨客在这里吟诗作对，激荡江山，让人心生向往。' AND c.create_time = '2019-10-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭在岳麓书院的后边，很多人来这里照相', 5, '2019-10-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_58c60a59a773' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭在岳麓书院的后边，很多人来这里照相' AND c.create_time = '2019-10-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '走走，逛逛，感受一下杜牧的七言绝句《山行》中的“停车坐爱枫林晚”。 爱晚亭与陶然亭、湖心亭、醉翁亭并称中国四大名亭，也是革命活动胜地，为湖南省文物保护单位。', 4, '2019-10-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da28055daade' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '走走，逛逛，感受一下杜牧的七言绝句《山行》中的“停车坐爱枫林晚”。 爱晚亭与陶然亭、湖心亭、醉翁亭并称中国四大名亭，也是革命活动胜地，为湖南省文物保护单位。' AND c.create_time = '2019-10-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '停车坐爱枫亭晚，霜叶红于二月花。 我去的时候3月份没有枫叶。 10月份的枫叶可是中国几大著名的赏枫之地哟。 有机会再去一次。', 5, '2019-10-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e097cd93764d' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '停车坐爱枫亭晚，霜叶红于二月花。 我去的时候3月份没有枫叶。 10月份的枫叶可是中国几大著名的赏枫之地哟。 有机会再去一次。' AND c.create_time = '2019-10-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭是长沙岳麓山上的一座名亭，名字来源是杜牧的名句“停车坐爱枫林晚”，青年毛泽东曾在此和革命青年纵论革命理想，抒发革命豪情。', 4, '2019-10-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_4485f4dcb853' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭是长沙岳麓山上的一座名亭，名字来源是杜牧的名句“停车坐爱枫林晚”，青年毛泽东曾在此和革命青年纵论革命理想，抒发革命豪情。' AND c.create_time = '2019-10-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于岳麓书院对面，这里风景非常优美，亭子坐落在一个小山上，山下是一小片湖，湖光山色相得益彰，美不胜收。这个亭子始建于乾隆年间，已经有几百年的历史了。这种既有历史特色又美如画的风景总是让人流连忘返。', 5, '2019-09-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_977bff431822' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于岳麓书院对面，这里风景非常优美，亭子坐落在一个小山上，山下是一小片湖，湖光山色相得益彰，美不胜收。这个亭子始建于乾隆年间，已经有几百年的历史了。这种既有历史特色又美如画的风景总是让人流连忘返。' AND c.create_time = '2019-09-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很有文学气息的景点 令人怀古念远', 4, '2019-09-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b15695cdc457' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很有文学气息的景点 令人怀古念远' AND c.create_time = '2019-09-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '那那就只是个亭子而已！也只是而已！', 1, '2019-09-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6baafe233d76' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '那那就只是个亭子而已！也只是而已！' AND c.create_time = '2019-09-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭位于长沙岳麓山景区，因杜牧的千言绝句“停车坐爱枫林晚，霜叶红于二月花”而闻名，与醉翁亭、陶然亭、湖心亭并为中国四大名亭。 始建于1792年，现在看到已是新建的爱晚亭了。由一代伟人毛主席亲笔题名“爱晚亭”三个大字。 亭子周边有些景致可以看看，最佳观景时节当然是秋季枫叶盛开之时。 现在的爱晚亭不仅是长沙岳麓山上的热门旅游拍照景点，也为革命活动圣地和湖南省省级文物保护单位。', 5, '2019-08-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_94d251f9b577' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭位于长沙岳麓山景区，因杜牧的千言绝句“停车坐爱枫林晚，霜叶红于二月花”而闻名，与醉翁亭、陶然亭、湖心亭并为中国四大名亭。 始建于1792年，现在看到已是新建的爱晚亭了。由一代伟人毛主席亲笔题名“爱晚亭”三个大字。 亭子周边有些景致可以看看，最佳观景时节当然是秋季枫叶盛开之时。 现在的爱晚亭不仅是长沙岳麓山上的热门旅游拍照景点，也为革命活动圣地和湖南省省级文物保护单位。' AND c.create_time = '2019-08-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭很不错的一个地方，整体的环境非常的好，在那里感觉很棒，特别是雨过天晴的时候，空气超棒的，但是去那里的人太多了，有点破坏精致的感觉。', 4, '2019-08-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1497e1e62e1c' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭很不错的一个地方，整体的环境非常的好，在那里感觉很棒，特别是雨过天晴的时候，空气超棒的，但是去那里的人太多了，有点破坏精致的感觉。' AND c.create_time = '2019-08-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '真正的爱晚亭早已经毁在战争里了，这座爱晚亭是在解放以后修建的，取自杜牧的那句诗“停车坐爱霜林晚，”秋天这里一定很美很漂亮。', 4, '2019-08-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2febdb7ab5f8' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '真正的爱晚亭早已经毁在战争里了，这座爱晚亭是在解放以后修建的，取自杜牧的那句诗“停车坐爱霜林晚，”秋天这里一定很美很漂亮。' AND c.create_time = '2019-08-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙岳麓山边的爱晚亭，这是毛泽东亲笔所书。现在已经成了周边群众休闲健身的好地方。旁边就是湖南大学和岳麓书院，千年文化的传承一直不断。', 5, '2019-07-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e528f20eb1e4' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙岳麓山边的爱晚亭，这是毛泽东亲笔所书。现在已经成了周边群众休闲健身的好地方。旁边就是湖南大学和岳麓书院，千年文化的传承一直不断。' AND c.create_time = '2019-07-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，位于湖南省长沙市岳麓山下清风峡中，始建于1792年，名字来源于杜牧的七言绝句《山行》中的“停车坐爱枫林晚”。爱晚亭与陶然亭、湖心亭、醉翁亭并称中国四大名亭，也是革命活动胜地，为湖南省文物保护单位。亭形为重檐八柱，琉璃碧瓦，亭角飞翘，自远处观之似凌空欲飞状。', 5, '2019-07-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ba531fca8c3a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，位于湖南省长沙市岳麓山下清风峡中，始建于1792年，名字来源于杜牧的七言绝句《山行》中的“停车坐爱枫林晚”。爱晚亭与陶然亭、湖心亭、醉翁亭并称中国四大名亭，也是革命活动胜地，为湖南省文物保护单位。亭形为重檐八柱，琉璃碧瓦，亭角飞翘，自远处观之似凌空欲飞状。' AND c.create_time = '2019-07-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '雨中的爱晚亭别有一番景致，置身亭中石凳上，似乎看到当年杜大诗人在绿树影映的亭台中与友人共话晚霞的情景。', 5, '2019-07-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_51c55fc7ed7a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '雨中的爱晚亭别有一番景致，置身亭中石凳上，似乎看到当年杜大诗人在绿树影映的亭台中与友人共话晚霞的情景。' AND c.create_time = '2019-07-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '杜牧是否能预知，当年一首诗把一间平平无奇的亭子捧成了如今人人竞相拍照的景点呢？只是爱晚亭既然已经并不普通，要好好拍一张无人照是不可能完成的任务了，也有可能6月28日已经进入暑期了，远处拍照也挡不住密密麻麻的游客身影了。', 4, '2019-07-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '杜牧是否能预知，当年一首诗把一间平平无奇的亭子捧成了如今人人竞相拍照的景点呢？只是爱晚亭既然已经并不普通，要好好拍一张无人照是不可能完成的任务了，也有可能6月28日已经进入暑期了，远处拍照也挡不住密密麻麻的游客身影了。' AND c.create_time = '2019-07-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭缘自那首著名的停车坐爱枫林晚，霜叶红于二月花。也许秋天来的时候这里更是一番美景吧。这个时节来，山上郁郁葱葱，清新的空气迎面而来。很舒服的感觉。', 5, '2019-06-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_04f5852d0720' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭缘自那首著名的停车坐爱枫林晚，霜叶红于二月花。也许秋天来的时候这里更是一番美景吧。这个时节来，山上郁郁葱葱，清新的空气迎面而来。很舒服的感觉。' AND c.create_time = '2019-06-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '从岳麓山下来，走进清风峡，终于看到久已听说、心心念念的与陶然亭、湖心亭、醉翁亭并称中国四大名亭的爱晚亭，琉璃碧瓦，亭角飞翘，自远处观之似凌空欲飞状，走近后毛泽东题写的&amp;quot;爱晚亭&amp;quot;三个红底金色大字让人立刻联想到这里的革命岁月。', 5, '2019-06-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_33feadd1ab8c' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '从岳麓山下来，走进清风峡，终于看到久已听说、心心念念的与陶然亭、湖心亭、醉翁亭并称中国四大名亭的爱晚亭，琉璃碧瓦，亭角飞翘，自远处观之似凌空欲飞状，走近后毛泽东题写的&amp;quot;爱晚亭&amp;quot;三个红底金色大字让人立刻联想到这里的革命岁月。' AND c.create_time = '2019-06-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，位于湖南省长沙市岳麓山景区，始建于1972年。 爱晚亭与陶然亭、湖心亭、醉翁亭并称中国四大名亭。 东西两面亭棂悬以红底鎏金“爱晚亭”，是由当时的湖南大学校长李达专函请毛泽东所书手迹而制。', 4, '2019-06-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dd0175ea09c2' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，位于湖南省长沙市岳麓山景区，始建于1972年。 爱晚亭与陶然亭、湖心亭、醉翁亭并称中国四大名亭。 东西两面亭棂悬以红底鎏金“爱晚亭”，是由当时的湖南大学校长李达专函请毛泽东所书手迹而制。' AND c.create_time = '2019-06-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭，得名于杜牧诗句：停车坐爱枫林晚，位于长沙市岳麓山清风峡。，与陶然亭，醉翁亭，湖心亭并称中国四大名亭，爱晚亭三个大字是毛主席手书而制', 5, '2019-06-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1707abb0e90a' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭，得名于杜牧诗句：停车坐爱枫林晚，位于长沙市岳麓山清风峡。，与陶然亭，醉翁亭，湖心亭并称中国四大名亭，爱晚亭三个大字是毛主席手书而制' AND c.create_time = '2019-06-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '一般般，免费的景点，还行吧，风景可以，古建筑为后面见的，等枫叶红了应该还不错', 4, '2019-06-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ef8f23753bc8' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '一般般，免费的景点，还行吧，风景可以，古建筑为后面见的，等枫叶红了应该还不错' AND c.create_time = '2019-06-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '停车坐爱枫林晚，枫叶红于二月花。爱晚亭是全国四大名亭之一，去到爱晚亭可以让时光机穿梭回百年前感受一下当年青年毛泽东经常跟同学们在这里激扬文字，粪土当年万户侯的情景，爱晚亭的风景也是岳麓山的点睛之笔，古树苍龙，五星景点全免费，是长沙人民对外来游客满满的爱，五星强力推荐 【景色】 【性价比】', 5, '2019-06-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_86628230b580' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '停车坐爱枫林晚，枫叶红于二月花。爱晚亭是全国四大名亭之一，去到爱晚亭可以让时光机穿梭回百年前感受一下当年青年毛泽东经常跟同学们在这里激扬文字，粪土当年万户侯的情景，爱晚亭的风景也是岳麓山的点睛之笔，古树苍龙，五星景点全免费，是长沙人民对外来游客满满的爱，五星强力推荐 【景色】 【性价比】' AND c.create_time = '2019-06-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭在岳麓山里面，是一个很有名的景点，很多诗词歌赋里面都留下了它的身影，去岳麓山的话一定要去爱晚亭看一下，很不错的地方。', 5, '2019-05-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e4d7f2a4db1b' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭在岳麓山里面，是一个很有名的景点，很多诗词歌赋里面都留下了它的身影，去岳麓山的话一定要去爱晚亭看一下，很不错的地方。' AND c.create_time = '2019-05-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭 始建于清乾隆五十七年 （公元1792年） 几经修葺 已成為長沙最美的明信片 座落在岳麓山内 以秋日骄人的紅叶勝景 吸引无数海內海外遊客前來 湖光瀲灧 錦鯉悠遊 真是絕美的風景～', 5, '2019-05-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_f6063f7a8309' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭 始建于清乾隆五十七年 （公元1792年） 几经修葺 已成為長沙最美的明信片 座落在岳麓山内 以秋日骄人的紅叶勝景 吸引无数海內海外遊客前來 湖光瀲灧 錦鯉悠遊 真是絕美的風景～' AND c.create_time = '2019-05-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '爱晚亭原名红叶亭，又名爱枫亭。始建于清乾隆五十七年。爱晚亭与醉翁亭、湖心亭、陶然亭并称中国四大名亭。不远处就是岳麓书院。', 5, '2019-05-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c0dffdf69725' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '爱晚亭原名红叶亭，又名爱枫亭。始建于清乾隆五十七年。爱晚亭与醉翁亭、湖心亭、陶然亭并称中国四大名亭。不远处就是岳麓书院。' AND c.create_time = '2019-05-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '远上寒山石径斜，白云生处有人家。 停车坐爱枫林晚，霜叶红于二月花。 从岳麓书院穿过去，不几步就是爱晚亭了，5月依然有红叶，真的很美！', 5, '2019-05-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a2e35ab1d487' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '远上寒山石径斜，白云生处有人家。 停车坐爱枫林晚，霜叶红于二月花。 从岳麓书院穿过去，不几步就是爱晚亭了，5月依然有红叶，真的很美！' AND c.create_time = '2019-05-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '不愧四大名亭之名，以前离学校很近，不同季节都要去一下。', 5, '2018-01-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c4cd82055dbd' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '不愧四大名亭之名，以前离学校很近，不同季节都要去一下。' AND c.create_time = '2018-01-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓书院往山上走就是爱晚亭了，因一句“停车坐爱枫林晚，霜叶红于二月花”而出名，景色挺美的，爱晚亭旁的不知名小亭子，亭子顶布满的青苔但是很有感觉！', 5, '2017-08-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6b6704e48c39' AND s.name = '爱晚亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓书院往山上走就是爱晚亭了，因一句“停车坐爱枫林晚，霜叶红于二月花”而出名，景色挺美的，爱晚亭旁的不知名小亭子，亭子顶布满的青苔但是很有感觉！' AND c.create_time = '2017-08-30 00:00:00');
