INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '20231217全天： 1、电视发射塔位于5A景区岳麓山•橘子洲旅游区，其位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、电视发射塔：灰石塔身，不开放。塔北小水景的水源来自经处理的污水。', 5, '2024-03-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_506707a09f1d' AND s.name = '长沙电视塔(长沙之眼)' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '20231217全天： 1、电视发射塔位于5A景区岳麓山•橘子洲旅游区，其位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、电视发射塔：灰石塔身，不开放。塔北小水景的水源来自经处理的污水。' AND c.create_time = '2024-03-31 00:00:00');
