INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山上，比较复古，但在景区内，所以也算独树一帜。', 5, '2020-05-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c799ad1f88a3' AND s.name = '长沙电视塔(长沙之眼)' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山上，比较复古，但在景区内，所以也算独树一帜。' AND c.create_time = '2020-05-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙广播电视塔•赏湘江东岸风光 没想到在岳麓山顶会看到这么一个电视塔 在电子地图上的描述也是非常的有趣，说这里夜景很美 看了一下别人的评价，貌似过去这里的夜景是不错，这个电视塔是会发着光的 •坐标：岳麓山顶300.8米 •交通：地铁湖南大学站/然后观光车或者步行上山，推荐从东门上去，感觉近一些，南门过去比较远一些。 •环境：白天去的也没有看到传说中很美的夜景，白天就是一个信号塔的感觉，不是非常的壮观，景色一般。 反而比较推荐电视塔对面的这条山上商业街，还是不错的，如果可以坐在这里喝杯饮料，看看人来人往貌似还不错。', 4, '2019-11-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0406c02bb63c' AND s.name = '长沙电视塔(长沙之眼)' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙广播电视塔•赏湘江东岸风光 没想到在岳麓山顶会看到这么一个电视塔 在电子地图上的描述也是非常的有趣，说这里夜景很美 看了一下别人的评价，貌似过去这里的夜景是不错，这个电视塔是会发着光的 •坐标：岳麓山顶300.8米 •交通：地铁湖南大学站/然后观光车或者步行上山，推荐从东门上去，感觉近一些，南门过去比较远一些。 •环境：白天去的也没有看到传说中很美的夜景，白天就是一个信号塔的感觉，不是非常的壮观，景色一般。 反而比较推荐电视塔对面的这条山上商业街，还是不错的，如果可以坐在这里喝杯饮料，看看人来人往貌似还不错。' AND c.create_time = '2019-11-14 00:00:00');
