INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙电视塔长沙就在岳麓山上，混凝土结构塔身，信号复盖长沙市城区、长沙县、望城县、浏阳等，今天爬岳麓山看到的，很高的哦。。', 5, '2019-10-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_853993187332' AND s.name = '长沙电视塔(长沙之眼)' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙电视塔长沙就在岳麓山上，混凝土结构塔身，信号复盖长沙市城区、长沙县、望城县、浏阳等，今天爬岳麓山看到的，很高的哦。。' AND c.create_time = '2019-10-10 00:00:00');
