INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '看了好几个城市的电视塔，感觉都差不多，上海东方明珠，夜景最美，广州小蛮腰最时尚，长沙电视塔，近湘江，晚上，灯光灿烂映在星空下美', 5, '2019-06-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1707abb0e90a' AND s.name = '长沙电视塔(长沙之眼)' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '看了好几个城市的电视塔，感觉都差不多，上海东方明珠，夜景最美，广州小蛮腰最时尚，长沙电视塔，近湘江，晚上，灯光灿烂映在星空下美' AND c.create_time = '2019-06-12 00:00:00');
