INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '路线规划的挺不错的，上去可以欣赏美景', 5, '2023-08-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_89df62cd7797' AND s.name = '岳麓山索道' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '路线规划的挺不错的，上去可以欣赏美景' AND c.create_time = '2023-08-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '作为南岳衡山七十二峰之尾，岳麓山以其悠远的人文历史，近长沙市区等，为民众所喜爱。登山除徒步外，可乘坐索道。', 3, '2023-05-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b6233813c03d' AND s.name = '岳麓山索道' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '作为南岳衡山七十二峰之尾，岳麓山以其悠远的人文历史，近长沙市区等，为民众所喜爱。登山除徒步外，可乘坐索道。' AND c.create_time = '2023-05-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '其实更像是缆车🚡，要抓紧坐稳。', 4, '2022-12-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cfaa75343981' AND s.name = '岳麓山索道' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '其实更像是缆车🚡，要抓紧坐稳。' AND c.create_time = '2022-12-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '说是索道其实是缆车🚡，2018年的时候还是吊椅的，其实应该单人单座。', 4, '2022-12-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cfaa75343981' AND s.name = '岳麓山索道' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '说是索道其实是缆车🚡，2018年的时候还是吊椅的，其实应该单人单座。' AND c.create_time = '2022-12-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这个索道不是很长，毕竟岳麓山比较小，不是很大。如果不想步行登山太辛苦，可以坐索道上山', 3, '2022-11-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dc4bb5812b07' AND s.name = '岳麓山索道' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这个索道不是很长，毕竟岳麓山比较小，不是很大。如果不想步行登山太辛苦，可以坐索道上山' AND c.create_time = '2022-11-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山又是长沙一个必打卡的风景区。当然爬山的话，对于我们这些吃货来说，肯定是不太现实的。在小红书上面做的攻略是这么推荐的索道可以直接上山。然后在从滑道下来，个人感觉很不错，既可以欣赏一下山上的风景。又不会累。属实是很不错的一个体验。', 4, '2022-06-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7493efe0a8cb' AND s.name = '岳麓山索道' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山又是长沙一个必打卡的风景区。当然爬山的话，对于我们这些吃货来说，肯定是不太现实的。在小红书上面做的攻略是这么推荐的索道可以直接上山。然后在从滑道下来，个人感觉很不错，既可以欣赏一下山上的风景。又不会累。属实是很不错的一个体验。' AND c.create_time = '2022-06-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '建议提早过来，排队的时间确实很长，早上八点过来进门口排了半个小时，然后在索道就排了1个多小时，晴天过来景色确实是不错，可以看到橘子洲以及长沙样貌', 4, '2022-04-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c45cf4510561' AND s.name = '岳麓山索道' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '建议提早过来，排队的时间确实很长，早上八点过来进门口排了半个小时，然后在索道就排了1个多小时，晴天过来景色确实是不错，可以看到橘子洲以及长沙样貌' AND c.create_time = '2022-04-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山上山坐索道，下山有滑道，还是很好玩的。也可以晚上凌晨去爬山，早上看日出，俯瞰整个长沙市，特别美~', 5, '2021-10-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5c9c0dab9bee' AND s.name = '岳麓山索道' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山上山坐索道，下山有滑道，还是很好玩的。也可以晚上凌晨去爬山，早上看日出，俯瞰整个长沙市，特别美~' AND c.create_time = '2021-10-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山的缆车其实是可以做做的，价格是比以前贵一些了，15年去的时候来回30块钱，单程20，现在翻了个倍了 但也属于能接受的范围里面 不是黄金时期，去的话，排队也是挺凶的，尤其是下山，可能大家上山都选择爬山，下山就走不动了吧', 4, '2021-07-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dff192439929' AND s.name = '岳麓山索道' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山的缆车其实是可以做做的，价格是比以前贵一些了，15年去的时候来回30块钱，单程20，现在翻了个倍了 但也属于能接受的范围里面 不是黄金时期，去的话，排队也是挺凶的，尤其是下山，可能大家上山都选择爬山，下山就走不动了吧' AND c.create_time = '2021-07-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山的缆车，其实岳庐山这个地方为什么不能评论了呢？就觉得很奇怪吧 但其实阅读三的商业化是有点浓的，山顶好多好多的商店要上山，可以选很多方式 走上去，缆车上去，有缆车上去，下山也可以选择，还多了一种选择，就是可以划到', 4, '2021-07-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '岳麓山索道' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山的缆车，其实岳庐山这个地方为什么不能评论了呢？就觉得很奇怪吧 但其实阅读三的商业化是有点浓的，山顶好多好多的商店要上山，可以选很多方式 走上去，缆车上去，有缆车上去，下山也可以选择，还多了一种选择，就是可以划到' AND c.create_time = '2021-07-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺深居山中，环境宁静，三进院落，是湖南省最古老的寺庙、中国佛教道场之一，现为佛教汉族地区全国重点寺院和湖南省佛教协会、湖南佛学院所在地。', 5, '2026-02-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_127d19ef1dcd' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺深居山中，环境宁静，三进院落，是湖南省最古老的寺庙、中国佛教道场之一，现为佛教汉族地区全国重点寺院和湖南省佛教协会、湖南佛学院所在地。' AND c.create_time = '2026-02-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '毗邻岳麓书院、爱晚亭，儒释文化在此共生。杜甫曾叹“寺门高开洞庭野”，刘禹锡亦咏“高殿呀然压苍巘”，历代文人的题咏使其成为湖湘文脉的精神高地。很美丽的地方，值得一去', 5, '2025-08-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_62a4da114c09' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '毗邻岳麓书院、爱晚亭，儒释文化在此共生。杜甫曾叹“寺门高开洞庭野”，刘禹锡亦咏“高殿呀然压苍巘”，历代文人的题咏使其成为湖湘文脉的精神高地。很美丽的地方，值得一去' AND c.create_time = '2025-08-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '迈进古麓山寺的刹那，尘世的喧嚣瞬间被隔绝在外，内心也跟着沉静下来。这座隐匿于岳麓山中的古寺，宛如一位遗世独立的隐者，静静守望着岁月的变迁。 古寺的建筑风格古朴典雅，飞檐斗拱在山林的映衬下，更显庄严肃穆。朱红色的墙壁历经风雨的洗礼，虽有些斑驳，却也增添了几分历史的厚重感。踏入寺内，清幽的梵音袅袅传来，仿佛有一种神奇的力量，能驱散心中的阴霾。 寺内的树木郁郁葱葱，阳光透过枝叶的缝隙洒下，形成一片片金色的光斑，给整个寺庙增添了一份宁静祥和的氛围。寺中的古银杏，在冬日里金黄一片，落叶铺满地面，宛如给大地铺上了一层金色的地毯，美得让人移不开眼。 在这里，你能感受到浓厚的宗教氛围。僧人们穿着整洁的僧袍，或诵经，或打扫，举手投足间都透着一种从容与淡定。每一尊佛像都雕刻得栩栩如生，慈眉善目地俯瞰着众生，让人不禁心生敬畏。 不过，寺庙的面积不算太大，游览时间相对较短。但这并不影响它的魅力，短短片刻，便能让人获得心灵的慰藉。古麓山寺就像是喧嚣都市中的一片净土，疲惫时来此小坐，定会让你流连忘返。', 5, '2025-01-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dce72d0b14d1' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '迈进古麓山寺的刹那，尘世的喧嚣瞬间被隔绝在外，内心也跟着沉静下来。这座隐匿于岳麓山中的古寺，宛如一位遗世独立的隐者，静静守望着岁月的变迁。 古寺的建筑风格古朴典雅，飞檐斗拱在山林的映衬下，更显庄严肃穆。朱红色的墙壁历经风雨的洗礼，虽有些斑驳，却也增添了几分历史的厚重感。踏入寺内，清幽的梵音袅袅传来，仿佛有一种神奇的力量，能驱散心中的阴霾。 寺内的树木郁郁葱葱，阳光透过枝叶的缝隙洒下，形成一片片金色的光斑，给整个寺庙增添了一份宁静祥和的氛围。寺中的古银杏，在冬日里金黄一片，落叶铺满地面，宛如给大地铺上了一层金色的地毯，美得让人移不开眼。 在这里，你能感受到浓厚的宗教氛围。僧人们穿着整洁的僧袍，或诵经，或打扫，举手投足间都透着一种从容与淡定。每一尊佛像都雕刻得栩栩如生，慈眉善目地俯瞰着众生，让人不禁心生敬畏。 不过，寺庙的面积不算太大，游览时间相对较短。但这并不影响它的魅力，短短片刻，便能让人获得心灵的慰藉。古麓山寺就像是喧嚣都市中的一片净土，疲惫时来此小坐，定会让你流连忘返。' AND c.create_time = '2025-01-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '古麓山寺位于岳麓山深处，不在常规游线之上。寺院历史悠久，可以追溯到南北朝之时，虽几次毁于战火，但依旧留存至今。白瓦红墙，掩映于树木山林之中，梵音阵阵，流转在香风之内。可以让游客放空心灵，感受自然的恬淡', 5, '2024-12-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7498d93b1f02' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '古麓山寺位于岳麓山深处，不在常规游线之上。寺院历史悠久，可以追溯到南北朝之时，虽几次毁于战火，但依旧留存至今。白瓦红墙，掩映于树木山林之中，梵音阵阵，流转在香风之内。可以让游客放空心灵，感受自然的恬淡' AND c.create_time = '2024-12-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '众多文人墨客如杜甫、韩愈、李邕等都曾游历于此，留下大量的诗词歌赋和书法作品，具有极高的文学艺术价值 。', 5, '2024-12-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '众多文人墨客如杜甫、韩愈、李邕等都曾游历于此，留下大量的诗词歌赋和书法作品，具有极高的文学艺术价值 。' AND c.create_time = '2024-12-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '始建于西晋武帝泰始四年（公元268年），由敦煌菩萨竺法护的弟子竺法崇创建，是佛教传入湖南保存最古老的一座寺庙，距今已有1700多年历史 。', 5, '2024-12-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '始建于西晋武帝泰始四年（公元268年），由敦煌菩萨竺法护的弟子竺法崇创建，是佛教传入湖南保存最古老的一座寺庙，距今已有1700多年历史 。' AND c.create_time = '2024-12-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '20231217全天： 1、古麓山寺位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、古麓山寺始建于西晋泰始四年（268年），是全省首寺，几经兴废，1985年重建，主殿大雄宝殿占地580㎡，匾额为佛教协会会长赵朴初手书。最深处的观音殿是幸存的古建筑，殿外2棵罗汉寺有1700多岁，其中一棵是被风雨摧毁后补种的。寺的西侧红墙外不少游客涂鸦，成为一道风景。', 5, '2024-03-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_506707a09f1d' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '20231217全天： 1、古麓山寺位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、古麓山寺始建于西晋泰始四年（268年），是全省首寺，几经兴废，1985年重建，主殿大雄宝殿占地580㎡，匾额为佛教协会会长赵朴初手书。最深处的观音殿是幸存的古建筑，殿外2棵罗汉寺有1700多岁，其中一棵是被风雨摧毁后补种的。寺的西侧红墙外不少游客涂鸦，成为一道风景。' AND c.create_time = '2024-03-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙旅游必去地方，网红打卡点，风景优美值得一去', 4, '2023-06-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cd807a55f917' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙旅游必去地方，网红打卡点，风景优美值得一去' AND c.create_time = '2023-06-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '古麓山寺坐落在岳麓山的古树丛中，是湖南省最古老的寺庙之一。历史悠久，始建于西晋泰始四年，初名为慧光明寺，唐初改名为麓山寺。该寺左临清风峡，右饮白鹤泉，前瞰赫曦丹枫、长岛湘流，后倚禹碑风云、深壑林海。有“汉魏最初名胜，湖湘第一道场”之誉，现为全国重点佛教寺院。', 5, '2023-03-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7741b35c2712' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '古麓山寺坐落在岳麓山的古树丛中，是湖南省最古老的寺庙之一。历史悠久，始建于西晋泰始四年，初名为慧光明寺，唐初改名为麓山寺。该寺左临清风峡，右饮白鹤泉，前瞰赫曦丹枫、长岛湘流，后倚禹碑风云、深壑林海。有“汉魏最初名胜，湖湘第一道场”之誉，现为全国重点佛教寺院。' AND c.create_time = '2023-03-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年宝刹麓山古寺传承的是另一番人生哲理。此寺为湖南地区最早的佛寺，见证着佛教入湘的历史。麓山寺建成之时，正值西晋初期，距离汉明帝下诏在洛阳修建白马寺仅过去 200年而已。因此，在麓山寺的山门两边， 有一副“汉魏最初名胜，湖南第一道场”的对联。麓山寺山门。继开山祖师竺法崇之后，麓山古寺又得到了导、法愍等高僧的加持，逐渐名扬四海。', 5, '2022-11-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7741b35c2712' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年宝刹麓山古寺传承的是另一番人生哲理。此寺为湖南地区最早的佛寺，见证着佛教入湘的历史。麓山寺建成之时，正值西晋初期，距离汉明帝下诏在洛阳修建白马寺仅过去 200年而已。因此，在麓山寺的山门两边， 有一副“汉魏最初名胜，湖南第一道场”的对联。麓山寺山门。继开山祖师竺法崇之后，麓山古寺又得到了导、法愍等高僧的加持，逐渐名扬四海。' AND c.create_time = '2022-11-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于岳麓山山腰，距今已有1700年历史幻古寺，又名慧光寺，万寿禅寺。', 5, '2022-08-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c8f2a7957a4c' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于岳麓山山腰，距今已有1700年历史幻古寺，又名慧光寺，万寿禅寺。' AND c.create_time = '2022-08-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '风景优美，寺庙古老，值得一去。', 4, '2022-07-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cd807a55f917' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '风景优美，寺庙古老，值得一去。' AND c.create_time = '2022-07-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这个地方环境非常不错下次还来这里', 5, '2022-07-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8b48cabd942e' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这个地方环境非常不错下次还来这里' AND c.create_time = '2022-07-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '攻略都说岳麓山要阴天来坐缆车和滑道，从东门进入的时候还没下雨，走到缆车前开始下雨了呜呜呜。不过有一说一下雨天的岳麓山空气超级清新的，而且走哪里都和仙境一样。仿佛置身天宫自由游荡。山上还有茶颜和吃饭的地方，东西还好不算贵，茶颜还是一如既往的好喝。', 4, '2022-06-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7493efe0a8cb' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '攻略都说岳麓山要阴天来坐缆车和滑道，从东门进入的时候还没下雨，走到缆车前开始下雨了呜呜呜。不过有一说一下雨天的岳麓山空气超级清新的，而且走哪里都和仙境一样。仿佛置身天宫自由游荡。山上还有茶颜和吃饭的地方，东西还好不算贵，茶颜还是一如既往的好喝。' AND c.create_time = '2022-06-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '深藏于岳麓山腰的古寺，迄今已有1700多年历史，又名慧光寺，万寿禅寺，环境清幽。', 5, '2022-06-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c8f2a7957a4c' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '深藏于岳麓山腰的古寺，迄今已有1700多年历史，又名慧光寺，万寿禅寺，环境清幽。' AND c.create_time = '2022-06-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '古麓山寺位于岳麓山中心地带，周边景色怡人，地标景点较多且分散，很难一网打尽，徒步登山确实考验体能，雨天路滑，需要倍加留心上下台阶。', 5, '2022-06-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cd39e6d13d40' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '古麓山寺位于岳麓山中心地带，周边景色怡人，地标景点较多且分散，很难一网打尽，徒步登山确实考验体能，雨天路滑，需要倍加留心上下台阶。' AND c.create_time = '2022-06-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山上的知名寺庙，就在上山的大路边，进去上过香，香火较旺。', 4, '2022-05-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_b6233813c03d' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山上的知名寺庙，就在上山的大路边，进去上过香，香火较旺。' AND c.create_time = '2022-05-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很独特的一所寺庙，带着最虔诚的心来到这里', 5, '2022-02-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_18c35fe7c85d' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很独特的一所寺庙，带着最虔诚的心来到这里' AND c.create_time = '2022-02-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很有悠久的历史，这里很安静，有很多人都在这里烧香，夏日炎炎的时候，关门很早，好不容易才挤进山门里去的', 4, '2021-10-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_511fffb2840b' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很有悠久的历史，这里很安静，有很多人都在这里烧香，夏日炎炎的时候，关门很早，好不容易才挤进山门里去的' AND c.create_time = '2021-10-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺据说是佛教入湘的首座寺庙，始建于晋代，坐落在岳麓山半山腰。从爱晚亭往上爬，有陡峭的石阶山路和和缓的山路，一路浓荫蔽日，逐渐看到寺庙充满梵味的围墙。步入其中，让人心灵沉静，不愧有“汉魏最初名胜，湖湘第一道场”之誉。', 4, '2021-10-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_eb9caddccd86' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺据说是佛教入湘的首座寺庙，始建于晋代，坐落在岳麓山半山腰。从爱晚亭往上爬，有陡峭的石阶山路和和缓的山路，一路浓荫蔽日，逐渐看到寺庙充满梵味的围墙。步入其中，让人心灵沉静，不愧有“汉魏最初名胜，湖湘第一道场”之誉。' AND c.create_time = '2021-10-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺这个地方就是在岳麓山中间的路山寺，它里面会有一些 早课，但是我基本上没有碰到过呼声寺的香火，感觉上并不是很旺盛，有一个大的熔炉都已经封起来了，但是麓山寺门口两边有两个池塘，里面有一些老乌龟 大的，小的都有，最大的肯定已经好几百年了吧', 4, '2021-07-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺这个地方就是在岳麓山中间的路山寺，它里面会有一些 早课，但是我基本上没有碰到过呼声寺的香火，感觉上并不是很旺盛，有一个大的熔炉都已经封起来了，但是麓山寺门口两边有两个池塘，里面有一些老乌龟 大的，小的都有，最大的肯定已经好几百年了吧' AND c.create_time = '2021-07-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '开在岳麓山半山的路山寺 古时候的人求神拜佛真是辛苦，山路是必须走的 那时候的山路还比我们现在的路要难走，都是你一命的，哪像我们现在都修好了石阶路的 路山寺的香火并不旺盛，因为大家到岳麓山并不是去求神拜佛的，会有专门的地方去', 4, '2021-06-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1736ea57109a' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '开在岳麓山半山的路山寺 古时候的人求神拜佛真是辛苦，山路是必须走的 那时候的山路还比我们现在的路要难走，都是你一命的，哪像我们现在都修好了石阶路的 路山寺的香火并不旺盛，因为大家到岳麓山并不是去求神拜佛的，会有专门的地方去' AND c.create_time = '2021-06-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '今天去的岳麓山，顺带就去了麓山寺，但是有一点不好 麓山寺，他在4:30左右的时候，就把上面另外一个门给关掉了，我们从下面上去，本来可以从另外一边出去，但是工作人员说锁门了，我们只能再下去原路出去，然后再从另外一边女方再爬上去 一来一回，等于多爬了一段山路', 4, '2021-06-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '今天去的岳麓山，顺带就去了麓山寺，但是有一点不好 麓山寺，他在4:30左右的时候，就把上面另外一个门给关掉了，我们从下面上去，本来可以从另外一边出去，但是工作人员说锁门了，我们只能再下去原路出去，然后再从另外一边女方再爬上去 一来一回，等于多爬了一段山路' AND c.create_time = '2021-06-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '进香拜佛者络绎不绝。殿堂掩映在层林叠翠之间，晨钟暮鼓，梵音阵阵。', 5, '2021-06-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7790c5a0beab' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '进香拜佛者络绎不绝。殿堂掩映在层林叠翠之间，晨钟暮鼓，梵音阵阵。' AND c.create_time = '2021-06-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '坐落于岳麓山的古树丛中，是湖南最古老的寺庙之一，始建于西晋。 该寺左临清风峡，右饮白鹤泉，有“汉魏最初名胜，湖湘第一道场”之誉，现为全国重点佛教寺院。寺由山门、弥勒殿、大雄宝殿、观音阁、斋堂等建筑组成。', 5, '2021-05-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_31a88c23afd4' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '坐落于岳麓山的古树丛中，是湖南最古老的寺庙之一，始建于西晋。 该寺左临清风峡，右饮白鹤泉，有“汉魏最初名胜，湖湘第一道场”之誉，现为全国重点佛教寺院。寺由山门、弥勒殿、大雄宝殿、观音阁、斋堂等建筑组成。' AND c.create_time = '2021-05-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '下面是书香，上面是佛光，这意境，让人舒服', 5, '2021-04-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fd80030885db' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '下面是书香，上面是佛光，这意境，让人舒服' AND c.create_time = '2021-04-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '景色真的很不错，在寺院内欣赏风景，有种心旷神怡的感觉。而且寺院内的植物很漂亮，种植的很精心。寺院不收门票，只是爬山的过程比较辛苦。', 5, '2021-03-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_40f9cb15970c' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '景色真的很不错，在寺院内欣赏风景，有种心旷神怡的感觉。而且寺院内的植物很漂亮，种植的很精心。寺院不收门票，只是爬山的过程比较辛苦。' AND c.create_time = '2021-03-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺，规模不大就在岳麓山上，山门很漂亮，很有特色，很适合拍照，院子里的佛旗挂满空中，很有感觉，比较清净，周边有蔡锷墓，离爱晚亭不远！', 5, '2021-01-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺，规模不大就在岳麓山上，山门很漂亮，很有特色，很适合拍照，院子里的佛旗挂满空中，很有感觉，比较清净，周边有蔡锷墓，离爱晚亭不远！' AND c.create_time = '2021-01-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '不错的 景点，来了这里一定要去看看哦', 5, '2020-12-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0530995e05ad' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '不错的 景点，来了这里一定要去看看哦' AND c.create_time = '2020-12-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '古麓山寺，始建于约1700年前，抗战期间大部被日军炸毁，仅有少量建筑留存，1985年经过我国文物保护部门的精密重修，重现了部分的辉煌。', 4, '2020-12-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6b371022bf7f' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '古麓山寺，始建于约1700年前，抗战期间大部被日军炸毁，仅有少量建筑留存，1985年经过我国文物保护部门的精密重修，重现了部分的辉煌。' AND c.create_time = '2020-12-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺（古麓山寺）为湖南省文物保护单位，位于长沙市岳麓山腰，此为省内最古老的寺庙建筑之一。岳麓寺旧志作万寿寺、古鹿苑、慧光寺。明末毁于兵火，清顺治十五年（1658）重建麓山寺。历经圮建，保存至今。 寺由山门、弥勒殿、大雄宝殿、观音阁、斋堂等组成。山门作牌楼式，门额横题“古麓山寺”，门侧石联“汉魏最初名胜，湖湘第一道场。', 5, '2020-10-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_31a88c23afd4' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺（古麓山寺）为湖南省文物保护单位，位于长沙市岳麓山腰，此为省内最古老的寺庙建筑之一。岳麓寺旧志作万寿寺、古鹿苑、慧光寺。明末毁于兵火，清顺治十五年（1658）重建麓山寺。历经圮建，保存至今。 寺由山门、弥勒殿、大雄宝殿、观音阁、斋堂等组成。山门作牌楼式，门额横题“古麓山寺”，门侧石联“汉魏最初名胜，湖湘第一道场。' AND c.create_time = '2020-10-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺又名慧光寺，万寿禅寺，位于长沙市湘江西岸岳麓山山腰，由敦煌菩萨笠法护的弟子笠法崇创建于西晋武 麓山寺正门帝泰始四年(公元268年)，距今已有1700多年的历史，是佛教入湘最早的遗迹，现为湖南省重点文物保护单位和湖南省佛教协会', 5, '2020-06-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5add636c2b76' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺又名慧光寺，万寿禅寺，位于长沙市湘江西岸岳麓山山腰，由敦煌菩萨笠法护的弟子笠法崇创建于西晋武 麓山寺正门帝泰始四年(公元268年)，距今已有1700多年的历史，是佛教入湘最早的遗迹，现为湖南省重点文物保护单位和湖南省佛教协会' AND c.create_time = '2020-06-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺位于湖南长沙的岳麓山上，是一座有着古老历史的寺院，距今大约有一千七百年左右。麓山寺矗立在岳麓山之上，默默无言，景色清幽，信步走来，能使人渐忘尘世烦忧，是一处绝佳的放松身心、净化心灵的所在。', 5, '2020-05-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_8661760db693' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺位于湖南长沙的岳麓山上，是一座有着古老历史的寺院，距今大约有一千七百年左右。麓山寺矗立在岳麓山之上，默默无言，景色清幽，信步走来，能使人渐忘尘世烦忧，是一处绝佳的放松身心、净化心灵的所在。' AND c.create_time = '2020-05-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺位于湖南省长沙市湘江西岸的岳麓山山腰，最初创建于西晋，距今已有1700多年的历史，是湖南省最古老的寺庙之一。麓山寺又名慧光寺、万寿禅寺，在山门匾额上书写着古麓山寺，这里是中国佛教史上著名的道场之一，同时历史上许多书法家、文学家和诗人曾游览麓山寺并留下了千古传诵的佳作。', 5, '2020-05-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_ebf93d708d4b' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺位于湖南省长沙市湘江西岸的岳麓山山腰，最初创建于西晋，距今已有1700多年的历史，是湖南省最古老的寺庙之一。麓山寺又名慧光寺、万寿禅寺，在山门匾额上书写着古麓山寺，这里是中国佛教史上著名的道场之一，同时历史上许多书法家、文学家和诗人曾游览麓山寺并留下了千古传诵的佳作。' AND c.create_time = '2020-05-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺坐落在岳麓山比较高的地方，里面很清幽，梵音袅袅，一缕阳光照在大殿的地上，映衬着庙中的菩萨，端庄优雅，悲天悯人的样子。', 4, '2020-04-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2febdb7ab5f8' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺坐落在岳麓山比较高的地方，里面很清幽，梵音袅袅，一缕阳光照在大殿的地上，映衬着庙中的菩萨，端庄优雅，悲天悯人的样子。' AND c.create_time = '2020-04-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在岳麓山半山腰，依山势向上建造。', 5, '2020-04-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1311830a91b1' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在岳麓山半山腰，依山势向上建造。' AND c.create_time = '2020-04-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '千年古寺，坐落在岳麓山的半山腰，历史悠久，名声远播。', 5, '2020-03-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_04edcb5b6fda' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '千年古寺，坐落在岳麓山的半山腰，历史悠久，名声远播。' AND c.create_time = '2020-03-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '顺着清石铺的山路，蜿蜒而小，山间泉流潺潺，在嶙峋石间或缓或急，有些发出了声音，有些寂寞无声，走到了半山腰，一座古香古色的麓山寺便映入我的眼帘，寺门上刻有“古麓山寺”横额，两旁有“汉魏最初名胜，湖湘第一道场。', 5, '2020-02-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1a8a6d5e2156' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '顺着清石铺的山路，蜿蜒而小，山间泉流潺潺，在嶙峋石间或缓或急，有些发出了声音，有些寂寞无声，走到了半山腰，一座古香古色的麓山寺便映入我的眼帘，寺门上刻有“古麓山寺”横额，两旁有“汉魏最初名胜，湖湘第一道场。' AND c.create_time = '2020-02-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺位于长沙岳麓山的半山腰，是长沙最出名的古寺之一，从岳麓山经过岳麓书院到爱晚亭，麓山寺是登顶的必经之路，是古代建筑智慧的体现。', 4, '2020-02-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5ef2fbbff335' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺位于长沙岳麓山的半山腰，是长沙最出名的古寺之一，从岳麓山经过岳麓书院到爱晚亭，麓山寺是登顶的必经之路，是古代建筑智慧的体现。' AND c.create_time = '2020-02-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺位于岳麓山南路，是一座真正的寺庙，始建于西晋，现仅山门和藏经阁是历史留存。现大雄宝殿，观音阁，弥勒殿等为后期重建，寺里有和尚念经修行。', 4, '2019-12-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a3ca4e268ae4' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺位于岳麓山南路，是一座真正的寺庙，始建于西晋，现仅山门和藏经阁是历史留存。现大雄宝殿，观音阁，弥勒殿等为后期重建，寺里有和尚念经修行。' AND c.create_time = '2019-12-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '寺庙本身位于岳麓山，不需要门票，每次来岳麓山我都要去拜一拜。但是年纪大的人要来的话还是有点辛苦，需要爬一段山，坡度有点大！', 5, '2019-11-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1b8136cfb0c2' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '寺庙本身位于岳麓山，不需要门票，每次来岳麓山我都要去拜一拜。但是年纪大的人要来的话还是有点辛苦，需要爬一段山，坡度有点大！' AND c.create_time = '2019-11-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺又名慧光寺、万寿禅寺，位于湖南省长沙市湘江西岸岳麓山山腰，由敦煌菩萨笠法护的弟子笠法崇创建于西晋武帝泰始四年（公元268年），距今已有1700多年的历史，是佛教入湘最早的遗迹，现为湖南省重点文物保护单位和湖南省佛教协会驻地。', 5, '2019-11-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_515574db303c' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺又名慧光寺、万寿禅寺，位于湖南省长沙市湘江西岸岳麓山山腰，由敦煌菩萨笠法护的弟子笠法崇创建于西晋武帝泰始四年（公元268年），距今已有1700多年的历史，是佛教入湘最早的遗迹，现为湖南省重点文物保护单位和湖南省佛教协会驻地。' AND c.create_time = '2019-11-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '古麓山寺位于长沙岳麓山山腰，是岳麓山风景名胜区景点之一。 麓山寺始建于西晋年代（公元268年），距今已有1700多年历史，是湖南第一所佛教寺庙。 麓山寺大门为东南亚印度建筑风格，门口有两只石象，门墙上镶嵌有精美浮雕。 这儿环境清幽，是一个能让人沉静心灵的地方。', 4, '2019-08-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_94d251f9b577' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '古麓山寺位于长沙岳麓山山腰，是岳麓山风景名胜区景点之一。 麓山寺始建于西晋年代（公元268年），距今已有1700多年历史，是湖南第一所佛教寺庙。 麓山寺大门为东南亚印度建筑风格，门口有两只石象，门墙上镶嵌有精美浮雕。 这儿环境清幽，是一个能让人沉静心灵的地方。' AND c.create_time = '2019-08-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山上的寺院，很有悠久的历史，这里很安静，有很多人都在这里烧香，夏日炎炎的时候，关门很早，好不容易才挤进山门里去的。。', 4, '2019-08-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2febdb7ab5f8' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山上的寺院，很有悠久的历史，这里很安静，有很多人都在这里烧香，夏日炎炎的时候，关门很早，好不容易才挤进山门里去的。。' AND c.create_time = '2019-08-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '麓山寺，岳麓山上的景点，也是不需要额外购票的，可以烧香请愿，香火钱自愿投，前面的女香客跪拜很久投的红色大票，我们只是心意到就好，香火不能和那种专门的寺庙比，但心诚则灵。', 5, '2019-07-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '麓山寺，岳麓山上的景点，也是不需要额外购票的，可以烧香请愿，香火钱自愿投，前面的女香客跪拜很久投的红色大票，我们只是心意到就好，香火不能和那种专门的寺庙比，但心诚则灵。' AND c.create_time = '2019-07-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '古麓山寺是岳麓山山腰上知名的古庙旧观，整体面积不大，和蔡锷将军的墓园相邻。比较起市区的一些寺庙，古麓山寺香火不旺，游人也不是很多。当然，1700多年历史的古寺从斑驳的建筑上可以让人有更多的遐想，哪怕是经历怎样的岁月变迁和风雨历程，古迹和故事始终都在。', 5, '2019-07-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_759ec4fe2761' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '古麓山寺是岳麓山山腰上知名的古庙旧观，整体面积不大，和蔡锷将军的墓园相邻。比较起市区的一些寺庙，古麓山寺香火不旺，游人也不是很多。当然，1700多年历史的古寺从斑驳的建筑上可以让人有更多的遐想，哪怕是经历怎样的岁月变迁和风雨历程，古迹和故事始终都在。' AND c.create_time = '2019-07-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '如果登岳麓山，如果你是佛教信仰者，就进庙烧香吧。', 4, '2017-08-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_77a0a993fb7d' AND s.name = '麓山寺' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '如果登岳麓山，如果你是佛教信仰者，就进庙烧香吧。' AND c.create_time = '2017-08-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '初次踏入云麓宫，像是误入了一座被岁月尘封的仙宫，那种震撼与感动至今仍历历在目。 云麓宫隐匿于岳麓山的云雾深处，沿着蜿蜒曲折的山路攀登而上，一路古木参天，山风轻拂，带来草木的清香，还未到达，便已让人沉浸在这山林野趣之中。 远远望去，云麓宫的建筑错落有致，红墙青瓦在绿树的掩映下，庄重又不失典雅。走近宫前，抬头便能看到那气势恢宏的宫门，门上的雕花历经风雨侵蚀，却依然精致，仿佛在诉说着往昔的故事。 踏入宫内，清幽宁静的氛围扑面而来，袅袅的香烟弥漫在空气中，让人的心瞬间沉静下来。殿堂内供奉的神像栩栩如生，神态威严又不失慈悲，信徒们虔诚地跪拜祈福，香火的微光摇曳，增添了几分神秘庄重的气息。 在云麓宫的观景台上极目远眺，视野极为开阔。连绵的山峦在云雾中若隐若现，城市的繁华景象尽收眼底，仿佛能同时触摸到自然的宁静与尘世的烟火。此时，山风呼啸而过，吹动着衣角，让人不禁生出一种超脱尘世的心境。 美中不足的是，由于山路崎岖，对于体力稍差的游客来说，前往云麓宫的路途有些艰难。但正是这份“得来不易”，让云麓宫的魅力更加醇厚。每一次站在云麓宫的土地上，都能感受到它独特的韵味，它是历史的沉淀，是自然与人文的完美交融，值得每一个人用心去探寻。', 5, '2025-01-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dce72d0b14d1' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '初次踏入云麓宫，像是误入了一座被岁月尘封的仙宫，那种震撼与感动至今仍历历在目。 云麓宫隐匿于岳麓山的云雾深处，沿着蜿蜒曲折的山路攀登而上，一路古木参天，山风轻拂，带来草木的清香，还未到达，便已让人沉浸在这山林野趣之中。 远远望去，云麓宫的建筑错落有致，红墙青瓦在绿树的掩映下，庄重又不失典雅。走近宫前，抬头便能看到那气势恢宏的宫门，门上的雕花历经风雨侵蚀，却依然精致，仿佛在诉说着往昔的故事。 踏入宫内，清幽宁静的氛围扑面而来，袅袅的香烟弥漫在空气中，让人的心瞬间沉静下来。殿堂内供奉的神像栩栩如生，神态威严又不失慈悲，信徒们虔诚地跪拜祈福，香火的微光摇曳，增添了几分神秘庄重的气息。 在云麓宫的观景台上极目远眺，视野极为开阔。连绵的山峦在云雾中若隐若现，城市的繁华景象尽收眼底，仿佛能同时触摸到自然的宁静与尘世的烟火。此时，山风呼啸而过，吹动着衣角，让人不禁生出一种超脱尘世的心境。 美中不足的是，由于山路崎岖，对于体力稍差的游客来说，前往云麓宫的路途有些艰难。但正是这份“得来不易”，让云麓宫的魅力更加醇厚。每一次站在云麓宫的土地上，都能感受到它独特的韵味，它是历史的沉淀，是自然与人文的完美交融，值得每一个人用心去探寻。' AND c.create_time = '2025-01-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '云麓宫位于湖南省长沙市岳麓区登高路58号岳麓山国家重点风景名胜区内 。可乘公交到达岳麓山后，步行前往。', 5, '2024-12-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '云麓宫位于湖南省长沙市岳麓区登高路58号岳麓山国家重点风景名胜区内 。可乘公交到达岳麓山后，步行前往。' AND c.create_time = '2024-12-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '始建于明成化十四年（1478年），由吉简王朱见浚就藩长沙时所建，初名洞真观，后改名云麓宫 。', 5, '2024-12-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '始建于明成化十四年（1478年），由吉简王朱见浚就藩长沙时所建，初名洞真观，后改名云麓宫 。' AND c.create_time = '2024-12-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '云麓宫是长沙地区著名的道教宫观，前殿为关圣殿，中殿祀玄帝，名玄武祖师殿，后殿祀“三清” 。', 5, '2024-12-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '云麓宫是长沙地区著名的道教宫观，前殿为关圣殿，中殿祀玄帝，名玄武祖师殿，后殿祀“三清” 。' AND c.create_time = '2024-12-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '20231217全天： 1、云麓宫位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、云麓宫始建于明成化十四年（1478年），由吉简王朱见浚所建，是道教二十三洞之一的真虚福地，多次兴废， 民国三十五年（1946年）重建，占地约600㎡，主殿三清殿，观内有麓山树镫记碑（立于民国十五年，即1926年，高1.9米，共592字）、麓峰巩峙碑（立于民国二十七年，即1938年，高1.78米），观下的麻石围栏刻有5000多位长沙会战阵亡将士的名字。', 5, '2024-03-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_506707a09f1d' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '20231217全天： 1、云麓宫位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、云麓宫始建于明成化十四年（1478年），由吉简王朱见浚所建，是道教二十三洞之一的真虚福地，多次兴废， 民国三十五年（1946年）重建，占地约600㎡，主殿三清殿，观内有麓山树镫记碑（立于民国十五年，即1926年，高1.9米，共592字）、麓峰巩峙碑（立于民国二十七年，即1938年，高1.78米），观下的麻石围栏刻有5000多位长沙会战阵亡将士的名字。' AND c.create_time = '2024-03-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '经常爬岳麓山，但对云麓宫真不熟悉，查过资料才知其历史也是非常悠久，最早建于1478年，几修几建，作为一道观，居然是72福地之一，足见其意义重大。 地处岳麓山巅，四周古木参天，近观岳麓，远眺湘江。是岳麓山风景区的重要景点之一。', 5, '2021-11-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_13bcbdbb196c' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '经常爬岳麓山，但对云麓宫真不熟悉，查过资料才知其历史也是非常悠久，最早建于1478年，几修几建，作为一道观，居然是72福地之一，足见其意义重大。 地处岳麓山巅，四周古木参天，近观岳麓，远眺湘江。是岳麓山风景区的重要景点之一。' AND c.create_time = '2021-11-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '云麓宫是岳麓山上的一座宫，当天去的时候除了有香火的宫能进去看一下，其他只能看到外形，并不能进', 4, '2021-10-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_175aa0b78915' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '云麓宫是岳麓山上的一座宫，当天去的时候除了有香火的宫能进去看一下，其他只能看到外形，并不能进' AND c.create_time = '2021-10-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '每次登到山顶都有一种一览众山小的感觉，寺里香烟不断，钟声悠长。', 5, '2021-06-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7790c5a0beab' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '每次登到山顶都有一种一览众山小的感觉，寺里香烟不断，钟声悠长。' AND c.create_time = '2021-06-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '从正殿下去有观景平台，能一览“湘江北去，橘子洲头”的胜景', 5, '2021-06-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7790c5a0beab' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '从正殿下去有观景平台，能一览“湘江北去，橘子洲头”的胜景' AND c.create_time = '2021-06-15 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '处处是景，处处是书香，处处皆学问', 5, '2021-04-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fd80030885db' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '处处是景，处处是书香，处处皆学问' AND c.create_time = '2021-04-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '云麗宫位于岳麓山半山腰，是一座道教圣地，始建于明朝，后多次扩建，现存关帝，玄武祖师，三清等三座殿堂，周边古树参天，景色宜人。', 4, '2019-12-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a3ca4e268ae4' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '云麗宫位于岳麓山半山腰，是一座道教圣地，始建于明朝，后多次扩建，现存关帝，玄武祖师，三清等三座殿堂，周边古树参天，景色宜人。' AND c.create_time = '2019-12-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '云麓宫位于岳麓山景区，门口两棵110年的古树显得仙风道骨，宫内的道士更是仙风道骨。这里供着观音大士，门口的树上有很多红绸表达游人的美好愿望。', 4, '2019-09-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_977bff431822' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '云麓宫位于岳麓山景区，门口两棵110年的古树显得仙风道骨，宫内的道士更是仙风道骨。这里供着观音大士，门口的树上有很多红绸表达游人的美好愿望。' AND c.create_time = '2019-09-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '云麓宫在岳麓山的最上面，山顶上，岳麓山虽然不高，但是也不矮，这里是道教宫殿，道教讲究的是道法自然，崇尚自由随性的意思，。', 4, '2019-08-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2febdb7ab5f8' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '云麓宫在岳麓山的最上面，山顶上，岳麓山虽然不高，但是也不矮，这里是道教宫殿，道教讲究的是道法自然，崇尚自由随性的意思，。' AND c.create_time = '2019-08-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '云麓宫，到这里也就是爬山到头了，接着就是先下坡再一点点上坡度的平地了，走走不累，再走个十来分钟就是到了，会看见好几家咖啡茶饮店，观景平台也就是在那里了，白天去大汗淋漓的爽快，挑战自我的一个过程非常带劲。', 5, '2019-07-08 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_44b4c39f6d11' AND s.name = '云麓宫' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '云麓宫，到这里也就是爬山到头了，接着就是先下坡再一点点上坡度的平地了，走走不累，再走个十来分钟就是到了，会看见好几家咖啡茶饮店，观景平台也就是在那里了，白天去大汗淋漓的爽快，挑战自我的一个过程非常带劲。' AND c.create_time = '2019-07-08 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '湖面平静如镜，湖水碧绿清澈，能清晰看到湖边亭阁、走廊及树木倒影。四周山林幽静，巨石横亘，秋冬时节枫叶红、水杉黄，与碧水青山相互映衬，浓妆淡抹总相宜', 5, '2024-12-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '穿石坡湖' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '湖面平静如镜，湖水碧绿清澈，能清晰看到湖边亭阁、走廊及树木倒影。四周山林幽静，巨石横亘，秋冬时节枫叶红、水杉黄，与碧水青山相互映衬，浓妆淡抹总相宜' AND c.create_time = '2024-12-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很好👍👍👍👍👍。我很喜欢😘……', 5, '2024-11-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_30b44baec60c' AND s.name = '穿石坡湖' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很好👍👍👍👍👍。我很喜欢😘……' AND c.create_time = '2024-11-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '20231217全天： 1、穿石坡湖位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、穿石坡湖是景区西南角的大湖，湖上亭阁横跨。附近有： ①南大门 ②黄爱、庞人铨墓：两人在民国十年（1921年）的湖南第一纱厂罢工中被捕遇害，年仅25、24岁，5年后葬于此 ③辛亥援鄂民五护国阵亡将士公墓：建于民国五年（1916年），2排8列 ④辛亥援鄂汉阳阵亡将士公墓：建于民国元年（1912年），3排6列 ⑤第四军抗敌阵亡将士公墓：建于民国三十四年（1945年）的公墓，因第四军战绩不佳，公墓略显简单 ⑥战壕：长沙会战中的土坑遗址，曾发掘出枪、子弹、电话筒等 ⑦杨卓林墓：清光绪三十三年（1907年）刺杀两江总督端方失败后遇害，年仅31岁，5年后前葬于五轮塔下 ⑧阎松年墓：清宣统三年（1911年）长沙起义失败被捕遇害，年仅28岁，次年修此墓于五轮塔下 ⑨中山纪念林碑：建于民国十九年（1930年），孙中山逝世后，民国政府颁布植树令将每年3月12日作为植树节。碑的三面刻有他的植树语录 ⑩万景园：锁着门的庄园，周围是茶园 ⑪穿石坡：小坡因曾有溪流穿越巨石而得名 ⑫李仲麟墓：护国战争中任护法军前卫司令，民国九年（1920年）被湖南总司令赵恒惕诱杀', 5, '2024-03-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_506707a09f1d' AND s.name = '穿石坡湖' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '20231217全天： 1、穿石坡湖位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、穿石坡湖是景区西南角的大湖，湖上亭阁横跨。附近有： ①南大门 ②黄爱、庞人铨墓：两人在民国十年（1921年）的湖南第一纱厂罢工中被捕遇害，年仅25、24岁，5年后葬于此 ③辛亥援鄂民五护国阵亡将士公墓：建于民国五年（1916年），2排8列 ④辛亥援鄂汉阳阵亡将士公墓：建于民国元年（1912年），3排6列 ⑤第四军抗敌阵亡将士公墓：建于民国三十四年（1945年）的公墓，因第四军战绩不佳，公墓略显简单 ⑥战壕：长沙会战中的土坑遗址，曾发掘出枪、子弹、电话筒等 ⑦杨卓林墓：清光绪三十三年（1907年）刺杀两江总督端方失败后遇害，年仅31岁，5年后前葬于五轮塔下 ⑧阎松年墓：清宣统三年（1911年）长沙起义失败被捕遇害，年仅28岁，次年修此墓于五轮塔下 ⑨中山纪念林碑：建于民国十九年（1930年），孙中山逝世后，民国政府颁布植树令将每年3月12日作为植树节。碑的三面刻有他的植树语录 ⑩万景园：锁着门的庄园，周围是茶园 ⑪穿石坡：小坡因曾有溪流穿越巨石而得名 ⑫李仲麟墓：护国战争中任护法军前卫司令，民国九年（1920年）被湖南总司令赵恒惕诱杀' AND c.create_time = '2024-03-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '到了岳麓山总得去吧，比较清静。', 5, '2021-08-24 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0f5a68a88312' AND s.name = '穿石坡湖' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '到了岳麓山总得去吧，比较清静。' AND c.create_time = '2021-08-24 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '是岳麓山东南幽谷中的自然景观，此处林壑清幽，巨石横亘', 5, '2021-06-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7790c5a0beab' AND s.name = '穿石坡湖' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '是岳麓山东南幽谷中的自然景观，此处林壑清幽，巨石横亘' AND c.create_time = '2021-06-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '穿石坡湖是岳麓山中非常幽静的一个所在，游人较少，感觉清新。', 4, '2020-09-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_9259d37f9afd' AND s.name = '穿石坡湖' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '穿石坡湖是岳麓山中非常幽静的一个所在，游人较少，感觉清新。' AND c.create_time = '2020-09-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '穿石坡湖位于岳麓山脚下偏上一点的位置，湖面宽广，湖中有廊桥穿过，远看蓝天白云倒映在湖水中，衬着青山绿水，非常美丽，休歇片刻，很是惬意', 4, '2020-09-13 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_35bf15448084' AND s.name = '穿石坡湖' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '穿石坡湖位于岳麓山脚下偏上一点的位置，湖面宽广，湖中有廊桥穿过，远看蓝天白云倒映在湖水中，衬着青山绿水，非常美丽，休歇片刻，很是惬意' AND c.create_time = '2020-09-13 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '走进岳麓山深处探寻白鹤泉，就像踏入了一个被岁月尘封的奇妙仙境，给我带来了一场别开生面的感官盛宴。 还未靠近，潺潺的流水声便如灵动的音符，悠悠钻进耳中，引得我加快脚步一探究竟。到了泉边，只见一方清池，水面澄澈如镜，能清晰映出周边的绿树青山，仿佛一幅天然的倒影画。传说常有白鹤来此栖息，为这汪清泉添了几分神秘浪漫的色彩。 俯身细看，泉水清澈见底，水底的沙石、青苔清晰可见，还有几尾小鱼自在穿梭，灵动的身姿为静谧的泉水增添了勃勃生机。伸手触摸，泉水清凉刺骨，瞬间驱散了周身的燥热与疲惫，指尖划过水流，似能感受到时光的温柔流淌。 泉边的建筑古朴典雅，与自然景致相得益彰。斑驳的墙壁、飞翘的檐角，静静诉说着往昔的故事。坐在泉边的石凳上，耳边是清脆的水流声，鼻尖萦绕着山林间独有的清新气息，让人仿若远离了尘世的喧嚣纷扰，内心无比宁静。 不过，白鹤泉的位置相对隐蔽，若不留意指示牌，很容易与之擦肩而过。但也正因这份“藏于深山”的低调，让它保留了最原始纯粹的美。每一次来到白鹤泉，都是一次与自然的深度对话，能让我在快节奏的生活中寻得片刻的宁静与美好，真的是一处不可多得的宝藏之地 。', 5, '2025-01-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dce72d0b14d1' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '走进岳麓山深处探寻白鹤泉，就像踏入了一个被岁月尘封的奇妙仙境，给我带来了一场别开生面的感官盛宴。 还未靠近，潺潺的流水声便如灵动的音符，悠悠钻进耳中，引得我加快脚步一探究竟。到了泉边，只见一方清池，水面澄澈如镜，能清晰映出周边的绿树青山，仿佛一幅天然的倒影画。传说常有白鹤来此栖息，为这汪清泉添了几分神秘浪漫的色彩。 俯身细看，泉水清澈见底，水底的沙石、青苔清晰可见，还有几尾小鱼自在穿梭，灵动的身姿为静谧的泉水增添了勃勃生机。伸手触摸，泉水清凉刺骨，瞬间驱散了周身的燥热与疲惫，指尖划过水流，似能感受到时光的温柔流淌。 泉边的建筑古朴典雅，与自然景致相得益彰。斑驳的墙壁、飞翘的檐角，静静诉说着往昔的故事。坐在泉边的石凳上，耳边是清脆的水流声，鼻尖萦绕着山林间独有的清新气息，让人仿若远离了尘世的喧嚣纷扰，内心无比宁静。 不过，白鹤泉的位置相对隐蔽，若不留意指示牌，很容易与之擦肩而过。但也正因这份“藏于深山”的低调，让它保留了最原始纯粹的美。每一次来到白鹤泉，都是一次与自然的深度对话，能让我在快节奏的生活中寻得片刻的宁静与美好，真的是一处不可多得的宝藏之地 。' AND c.create_time = '2025-01-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '清光绪三年（公元1877年），粮道夏献云在泉上建亭，抗战时被毁，1956 年重建，亭顶绘双鹤翱翔 。', 5, '2024-12-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '清光绪三年（公元1877年），粮道夏献云在泉上建亭，抗战时被毁，1956 年重建，亭顶绘双鹤翱翔 。' AND c.create_time = '2024-12-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '泉水很清澈，周围环境也很好，空气很清新', 5, '2024-12-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '泉水很清澈，周围环境也很好，空气很清新' AND c.create_time = '2024-12-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '相传古时候曾有一对仙鹤常飞至此因而取名白鹤泉。北宋“铁面御史”赵忭游山盛赞此泉：“灵脉本无源，因禽漱玉泉。自非流异禀，谁识洞中仙”', 5, '2024-12-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '相传古时候曾有一对仙鹤常飞至此因而取名白鹤泉。北宋“铁面御史”赵忭游山盛赞此泉：“灵脉本无源，因禽漱玉泉。自非流异禀，谁识洞中仙”' AND c.create_time = '2024-12-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '20231217全天： 1、白鹤泉位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、白鹤泉被誉为“山中第一方润”，北宋诗人赵忭、南宋理学家、岳麓书院主持张栻等曾留诗于此，清光绪三年（1877年）湖南粮道夏献云建亭，抗战时被毁，1956年重修，为四角亭，附近假山水景中立有白鹤彩塑，池中金鱼游弋。', 5, '2024-03-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_506707a09f1d' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '20231217全天： 1、白鹤泉位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、白鹤泉被誉为“山中第一方润”，北宋诗人赵忭、南宋理学家、岳麓书院主持张栻等曾留诗于此，清光绪三年（1877年）湖南粮道夏献云建亭，抗战时被毁，1956年重修，为四角亭，附近假山水景中立有白鹤彩塑，池中金鱼游弋。' AND c.create_time = '2024-03-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于麓山寺后门，有一口古井在亭内，一块石碑竖立在井后，边上是清澈的泉水', 4, '2021-06-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7790c5a0beab' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于麓山寺后门，有一口古井在亭内，一块石碑竖立在井后，边上是清澈的泉水' AND c.create_time = '2021-06-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '一口泉眼，口感清凉，非常不错。。。', 5, '2020-12-22 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_0530995e05ad' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '一口泉眼，口感清凉，非常不错。。。' AND c.create_time = '2020-12-22 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在湖南省长沙市麓山寺后，古树环抱，有泉从石罅中溢出，冬夏不涸，清洌甘甜，清澈透明。白鹤泉有“麓山第一芳涧”之称。相传古时候曾有一对仙鹤常飞至此因而取名白鹤泉。', 5, '2020-05-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_35fb461dcaca' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在湖南省长沙市麓山寺后，古树环抱，有泉从石罅中溢出，冬夏不涸，清洌甘甜，清澈透明。白鹤泉有“麓山第一芳涧”之称。相传古时候曾有一对仙鹤常飞至此因而取名白鹤泉。' AND c.create_time = '2020-05-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '白鹤泉是一处天然的泉眼，泉水出处，积得一池的碧泉，水不大，但很清澈。', 4, '2019-12-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a3ca4e268ae4' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '白鹤泉是一处天然的泉眼，泉水出处，积得一池的碧泉，水不大，但很清澈。' AND c.create_time = '2019-12-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '风景太美了，让人流连忘返，真不错', 5, '2019-11-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_515574db303c' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '风景太美了，让人流连忘返，真不错' AND c.create_time = '2019-11-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '好玩儿的很，夏季休闲圣地，适合亲子游哦', 5, '2019-09-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '好玩儿的很，夏季休闲圣地，适合亲子游哦' AND c.create_time = '2019-09-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '白鹤泉位于湖南长沙岳麓山观音阁外南侧，有＂麓山第一芳涧＂之美称。相传古时候曾有一对仙鹤常飞至此，因而取名白鹤泉。泉水很甘甜。', 5, '2019-05-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c0dffdf69725' AND s.name = '白鹤泉' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '白鹤泉位于湖南长沙岳麓山观音阁外南侧，有＂麓山第一芳涧＂之美称。相传古时候曾有一对仙鹤常飞至此，因而取名白鹤泉。泉水很甘甜。' AND c.create_time = '2019-05-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '革命先驱，魂归故里，精神永存，当代青年，不会忘记其一生之贡献，更加珍惜当下的和平，为中华之崛起而读书，为实现中国梦而奋斗。', 5, '2025-07-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_51ffef1d9ad1' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '革命先驱，魂归故里，精神永存，当代青年，不会忘记其一生之贡献，更加珍惜当下的和平，为中华之崛起而读书，为实现中国梦而奋斗。' AND c.create_time = '2025-07-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在岳麓山的葱郁山林间，黄兴墓静静矗立，宛如一座不朽的精神丰碑，承载着无尽的历史重量，每一次靠近，都像是与一位伟大的革命先驱展开灵魂对话。 沿着蜿蜒的山路拾级而上，四周古木参天，枝叶沙沙作响，仿佛在低语着黄兴先生的传奇人生。眼前的黄兴墓，气势恢宏，主体建筑庄重肃穆，墓碑上的字迹刚劲有力，“黄公克强之墓”六个大字，宛如在诉说着他波澜壮阔的革命生涯。 站在墓前，仿佛能看见黄兴先生在那个风雨飘摇的年代，为了推翻封建帝制，拯救民族危亡，不顾个人安危，冲锋陷阵的身影。他参与领导了多次起义，将热血洒在华夏大地，为中国的民主革命事业立下了不朽功勋。 墓园的布局错落有致，周边的青松翠柏四季常青，象征着先生的精神万古长青。台阶两旁的石兽，虽历经岁月的洗礼，却依旧威风凛凛，忠实地守护着这片圣地。 这里静谧清幽，没有城市的喧嚣，只有偶尔传来的鸟鸣，更增添了几分庄严肃穆的氛围。不过，由于岳麓山景点众多，黄兴墓不太容易被游客快速找到，这让很多人错失了近距离缅怀先烈的机会。但也正因如此，这里保留了那份难得的宁静，让前来瞻仰的人能更专注地感受先生的伟大精神。 黄兴墓不仅是一处纪念性的建筑，更是中华民族不屈精神的象征。它时刻提醒着我们，铭记历史，珍惜当下，继承和发扬革命先辈们的精神，为国家的繁荣富强而不懈奋斗 。', 5, '2025-01-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dce72d0b14d1' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在岳麓山的葱郁山林间，黄兴墓静静矗立，宛如一座不朽的精神丰碑，承载着无尽的历史重量，每一次靠近，都像是与一位伟大的革命先驱展开灵魂对话。 沿着蜿蜒的山路拾级而上，四周古木参天，枝叶沙沙作响，仿佛在低语着黄兴先生的传奇人生。眼前的黄兴墓，气势恢宏，主体建筑庄重肃穆，墓碑上的字迹刚劲有力，“黄公克强之墓”六个大字，宛如在诉说着他波澜壮阔的革命生涯。 站在墓前，仿佛能看见黄兴先生在那个风雨飘摇的年代，为了推翻封建帝制，拯救民族危亡，不顾个人安危，冲锋陷阵的身影。他参与领导了多次起义，将热血洒在华夏大地，为中国的民主革命事业立下了不朽功勋。 墓园的布局错落有致，周边的青松翠柏四季常青，象征着先生的精神万古长青。台阶两旁的石兽，虽历经岁月的洗礼，却依旧威风凛凛，忠实地守护着这片圣地。 这里静谧清幽，没有城市的喧嚣，只有偶尔传来的鸟鸣，更增添了几分庄严肃穆的氛围。不过，由于岳麓山景点众多，黄兴墓不太容易被游客快速找到，这让很多人错失了近距离缅怀先烈的机会。但也正因如此，这里保留了那份难得的宁静，让前来瞻仰的人能更专注地感受先生的伟大精神。 黄兴墓不仅是一处纪念性的建筑，更是中华民族不屈精神的象征。它时刻提醒着我们，铭记历史，珍惜当下，继承和发扬革命先辈们的精神，为国家的繁荣富强而不懈奋斗 。' AND c.create_time = '2025-01-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '黄兴是辛亥革命的先驱与领袖、中华民国开国元勋、近代民主革命家 。墓地坐西向东，由三层近百级石砌台阶步入墓地 。', 5, '2024-12-15 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '黄兴是辛亥革命的先驱与领袖、中华民国开国元勋、近代民主革命家 。墓地坐西向东，由三层近百级石砌台阶步入墓地 。' AND c.create_time = '2024-12-15 00:00:00');
