INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '历史车轮滚滚向前，总有些人的名字值得铭记', 5, '2023-02-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_111a7cded145' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '历史车轮滚滚向前，总有些人的名字值得铭记' AND c.create_time = '2023-02-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '周五，雨天，岳麓山，走起，向酒店借了1把🌂，冒雨徒步登山，游人不少，荣湾镇进山，湖南大学出山，面积很大，沿路景致很多，黄兴作为革命领袖，长眠于此，供后人凭吊。', 5, '2022-06-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cd39e6d13d40' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '周五，雨天，岳麓山，走起，向酒店借了1把🌂，冒雨徒步登山，游人不少，荣湾镇进山，湖南大学出山，面积很大，沿路景致很多，黄兴作为革命领袖，长眠于此，供后人凭吊。' AND c.create_time = '2022-06-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这里在岳麓山的半山腰，墓地不大，很小。', 3, '2022-03-23 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dc4bb5812b07' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这里在岳麓山的半山腰，墓地不大，很小。' AND c.create_time = '2022-03-23 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '黄兴墓，岳麓山上的著名文物保护地，我个人第二次去看了。相比较其他名人墓，黄兴墓是规格最高的的一个，邻近黄兴墓附近还有蔡锷将军墓，也可以一起去看看！', 5, '2022-01-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '黄兴墓，岳麓山上的著名文物保护地，我个人第二次去看了。相比较其他名人墓，黄兴墓是规格最高的的一个，邻近黄兴墓附近还有蔡锷将军墓，也可以一起去看看！' AND c.create_time = '2022-01-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '在岳麓山这些纪念墓地里面，算是最大的一座了。', 5, '2021-06-16 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_7790c5a0beab' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '在岳麓山这些纪念墓地里面，算是最大的一座了。' AND c.create_time = '2021-06-16 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '带小朋友去纪念下革命先烈，很有教育意义', 4, '2021-05-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_30d915d50d47' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '带小朋友去纪念下革命先烈，很有教育意义' AND c.create_time = '2021-05-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '一样的感慨，在和平年代，回望狼烟四起的历史', 5, '2021-04-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fd80030885db' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '一样的感慨，在和平年代，回望狼烟四起的历史' AND c.create_time = '2021-04-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '墓地坐西向东，由三层近百级石砌台阶步入墓地。墓矗立塔形碑柱，为一整块四棱形乳白色岩石琢成，高约10米，气势雄伟，正面嵌铜制墓碑，上镌“黄公克强之墓”，墓表四周以石基柱围护栏杆，前有拜台、石凳，地面铺以花岗岩，整个墓表占地1186.24平方米，苍松翠柏，掩映其间。', 5, '2020-05-02 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_35fb461dcaca' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '墓地坐西向东，由三层近百级石砌台阶步入墓地。墓矗立塔形碑柱，为一整块四棱形乳白色岩石琢成，高约10米，气势雄伟，正面嵌铜制墓碑，上镌“黄公克强之墓”，墓表四周以石基柱围护栏杆，前有拜台、石凳，地面铺以花岗岩，整个墓表占地1186.24平方米，苍松翠柏，掩映其间。' AND c.create_time = '2020-05-02 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于岳麓山上的一个比较僻静的角落里面 几乎没有什么人打扰 环境很优雅 不过这里周边基本上没有什么可以眺望城市景观的视野角度 因此整个雕像看上去虽然只有十米左右 但是气势宏伟', 5, '2020-03-01 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1792ee7618ca' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于岳麓山上的一个比较僻静的角落里面 几乎没有什么人打扰 环境很优雅 不过这里周边基本上没有什么可以眺望城市景观的视野角度 因此整个雕像看上去虽然只有十米左右 但是气势宏伟' AND c.create_time = '2020-03-01 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '国庆期间到岳麓山来玩，本来想坐缆车或者观光车，人太多无奈之下只有放弃，只有甩起火腿登山，黄兴墓就在登山的途中，墓地不大，详细的记录了这位革命先烈的一生，孙中山先生最亲密的战友，同盟会的创建者，为中国的复兴做出巨大的努力，原来只在教科书上面看见的人物，今天能在他的墓前读完他的一生，让人敬佩不已', 4, '2019-10-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e7c08f3f0ef6' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '国庆期间到岳麓山来玩，本来想坐缆车或者观光车，人太多无奈之下只有放弃，只有甩起火腿登山，黄兴墓就在登山的途中，墓地不大，详细的记录了这位革命先烈的一生，孙中山先生最亲密的战友，同盟会的创建者，为中国的复兴做出巨大的努力，原来只在教科书上面看见的人物，今天能在他的墓前读完他的一生，让人敬佩不已' AND c.create_time = '2019-10-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '今年是中华人民建国70周年。在上个世纪100年中中华民族的优秀分子，积极的探索救国强国之路。 孙中山黄兴就是其中的代表。瞻仰黄兴先生之墓，看今日中国之强盛，可以慰藉老先生的在天之灵。', 5, '2019-10-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e097cd93764d' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '今年是中华人民建国70周年。在上个世纪100年中中华民族的优秀分子，积极的探索救国强国之路。 孙中山黄兴就是其中的代表。瞻仰黄兴先生之墓，看今日中国之强盛，可以慰藉老先生的在天之灵。' AND c.create_time = '2019-10-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '黄兴是建立同盟会的首要功臣，也是发动辛亥革命，推翻清朝封建主义的军事总指挥，曾任临时国民政府的国防总司令。黄兴墓位于岳麓山风景区内，墓志铭记录了他一生的丰功伟绩，是一个不错的爱国教育景点。', 4, '2019-09-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_977bff431822' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '黄兴是建立同盟会的首要功臣，也是发动辛亥革命，推翻清朝封建主义的军事总指挥，曾任临时国民政府的国防总司令。黄兴墓位于岳麓山风景区内，墓志铭记录了他一生的丰功伟绩，是一个不错的爱国教育景点。' AND c.create_time = '2019-09-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '伟大的，爱国主义革命的先驱者，伟大的，无产阶级革命家，伟大的国民革命战士，墓地在岳麓山半山附近，在长沙市，有一条黄兴路，', 4, '2019-08-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2febdb7ab5f8' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '伟大的，爱国主义革命的先驱者，伟大的，无产阶级革命家，伟大的国民革命战士，墓地在岳麓山半山附近，在长沙市，有一条黄兴路，' AND c.create_time = '2019-08-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '黄兴，湖南长沙人，辛亥革命的先驱和领袖，孙中山的亲密战友，与孙中山常被时人以孙黄并称，黄兴墓位于长沙市岳麓山云麓峰以北小月亮坪上方', 5, '2019-06-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1707abb0e90a' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '黄兴，湖南长沙人，辛亥革命的先驱和领袖，孙中山的亲密战友，与孙中山常被时人以孙黄并称，黄兴墓位于长沙市岳麓山云麓峰以北小月亮坪上方' AND c.create_time = '2019-06-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '民国大人物，值得去看看的，很不错的感觉', 5, '2019-05-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_abcb8c696521' AND s.name = '黄兴墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '民国大人物，值得去看看的，很不错的感觉' AND c.create_time = '2019-05-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '当我踏入岳麓山，专程寻访蔡锷墓时，内心满是对这位传奇英雄的敬仰与好奇。远远望去，墓冢在青山翠柏的环绕下，显得格外庄严肃穆，仿佛在向世人无声诉说着蔡锷将军波澜壮阔的一生。 走近细瞧，墓碑高耸，上面镌刻的字迹苍劲有力，每一笔都像是在书写着他的丰功伟绩。墓前的石兽栩栩如生，虽历经风雨，却依旧坚守在此，宛如忠诚的卫士，守护着将军的安眠。周围的台阶和栏杆古朴厚重，沿着台阶缓缓而上，心中的敬意也愈发浓烈。 站在墓前，我仿佛能看到蔡锷将军当年在战场上的飒爽英姿，他为了国家的独立和民族的尊严，不惜舍生忘死，冲锋陷阵。如今，他静静地躺在这里，与这青山绿水融为一体，成为了这片土地上永恒的精神坐标。 整个墓园环境清幽宁静，没有过多的喧嚣与纷扰，让人能静下心来缅怀先烈。不过，相较于岳麓山其他热门景点，这里的游客相对较少，或许很多人还未能充分领略到蔡锷将军的伟大以及这座墓所承载的历史意义。但这也让蔡锷墓多了一份宁静与庄严，让每一个前来瞻仰的人都能更专注地感受那份深沉的爱国情怀。 蔡锷墓不仅是一座纪念性的建筑，更是一部生动的历史教科书，它时刻提醒着我们，不要忘记那些为国家和民族做出巨大牺牲的英雄们。', 5, '2025-01-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dce72d0b14d1' AND s.name = '蔡锷墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '当我踏入岳麓山，专程寻访蔡锷墓时，内心满是对这位传奇英雄的敬仰与好奇。远远望去，墓冢在青山翠柏的环绕下，显得格外庄严肃穆，仿佛在向世人无声诉说着蔡锷将军波澜壮阔的一生。 走近细瞧，墓碑高耸，上面镌刻的字迹苍劲有力，每一笔都像是在书写着他的丰功伟绩。墓前的石兽栩栩如生，虽历经风雨，却依旧坚守在此，宛如忠诚的卫士，守护着将军的安眠。周围的台阶和栏杆古朴厚重，沿着台阶缓缓而上，心中的敬意也愈发浓烈。 站在墓前，我仿佛能看到蔡锷将军当年在战场上的飒爽英姿，他为了国家的独立和民族的尊严，不惜舍生忘死，冲锋陷阵。如今，他静静地躺在这里，与这青山绿水融为一体，成为了这片土地上永恒的精神坐标。 整个墓园环境清幽宁静，没有过多的喧嚣与纷扰，让人能静下心来缅怀先烈。不过，相较于岳麓山其他热门景点，这里的游客相对较少，或许很多人还未能充分领略到蔡锷将军的伟大以及这座墓所承载的历史意义。但这也让蔡锷墓多了一份宁静与庄严，让每一个前来瞻仰的人都能更专注地感受那份深沉的爱国情怀。 蔡锷墓不仅是一座纪念性的建筑，更是一部生动的历史教科书，它时刻提醒着我们，不要忘记那些为国家和民族做出巨大牺牲的英雄们。' AND c.create_time = '2025-01-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '蔡锷墓位于湖南省长沙市岳麓山风景区白鹤泉左后方的山上 ，墓由冢、碑、石祭器等组成，冢以花岗石砌成', 5, '2024-12-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '蔡锷墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '蔡锷墓位于湖南省长沙市岳麓山风景区白鹤泉左后方的山上 ，墓由冢、碑、石祭器等组成，冢以花岗石砌成' AND c.create_time = '2024-12-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '20231217全天： 1、蔡锷墓位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、蔡锷墓：著名革命家、护国战争领导者，1916年病逝，年仅34岁。墓占地1974.72㎡，碑高6米形似利剑', 5, '2024-03-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_506707a09f1d' AND s.name = '蔡锷墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '20231217全天： 1、蔡锷墓位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、蔡锷墓：著名革命家、护国战争领导者，1916年病逝，年仅34岁。墓占地1974.72㎡，碑高6米形似利剑' AND c.create_time = '2024-03-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于岳麓山白鹤泉左后方的山上，蔡锷将军病逝于日本，后归葬于此。', 4, '2022-06-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c8f2a7957a4c' AND s.name = '蔡锷墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于岳麓山白鹤泉左后方的山上，蔡锷将军病逝于日本，后归葬于此。' AND c.create_time = '2022-06-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '松坡将军与小凤仙的故事传为佳话，蔡将军墓位于岳麓山麓山寺附近，感慨当时革命党人都极其年轻，年仅34岁即驾鹤西游，珍惜身体才是王道。', 5, '2022-06-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cd39e6d13d40' AND s.name = '蔡锷墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '松坡将军与小凤仙的故事传为佳话，蔡将军墓位于岳麓山麓山寺附近，感慨当时革命党人都极其年轻，年仅34岁即驾鹤西游，珍惜身体才是王道。' AND c.create_time = '2022-06-18 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '雨中漫步岳麓山，景区很大，徒步游人很多，打卡每一个地标有难度，争取多跑几个吧，蔡锷与小凤仙的故事传为佳话，松坡将军的墓冢坐落于麓山寺边上，瞻仰一下。', 5, '2022-06-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cd39e6d13d40' AND s.name = '蔡锷墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '雨中漫步岳麓山，景区很大，徒步游人很多，打卡每一个地标有难度，争取多跑几个吧，蔡锷与小凤仙的故事传为佳话，松坡将军的墓冢坐落于麓山寺边上，瞻仰一下。' AND c.create_time = '2022-06-17 00:00:00');
