INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '也是一代枭雄！铭记历史，在变哥中进步', 5, '2021-04-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fd80030885db' AND s.name = '蔡锷墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '也是一代枭雄！铭记历史，在变哥中进步' AND c.create_time = '2021-04-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '国庆到岳麓山来，整个岳麓山的景点很多，其中爱国将领蔡锷墓是绝对不能错过的一个地方，蔡公一生干过不少轰轰烈烈的大事为国为民，但是确实他和小凤仙的故事让很多人认识他，到岳麓山来，这位传奇人物墓地一定要来看看', 4, '2019-10-20 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_e7c08f3f0ef6' AND s.name = '蔡锷墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '国庆到岳麓山来，整个岳麓山的景点很多，其中爱国将领蔡锷墓是绝对不能错过的一个地方，蔡公一生干过不少轰轰烈烈的大事为国为民，但是确实他和小凤仙的故事让很多人认识他，到岳麓山来，这位传奇人物墓地一定要来看看' AND c.create_time = '2019-10-20 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '很多小伙伴们知道蔡锷，蔡将军，是因为一曲《知音》，一部同名电影知音，小风仙，蔡锷，而蔡锷墓在长沙岳麓山风景名胜区内的一条小路旁', 5, '2019-06-18 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1707abb0e90a' AND s.name = '蔡锷墓' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '很多小伙伴们知道蔡锷，蔡将军，是因为一曲《知音》，一部同名电影知音，小风仙，蔡锷，而蔡锷墓在长沙岳麓山风景名胜区内的一条小路旁' AND c.create_time = '2019-06-18 00:00:00');
