INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '长沙舍利塔在岳麓山景区内，风景优美，自然、纯天然自然风景，了解了相关知识，爬爬岳麓山挺好的，美景尽收眼底，性价比超高的。', 5, '2021-01-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_449241a3849d' AND s.name = '舍利塔' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '长沙舍利塔在岳麓山景区内，风景优美，自然、纯天然自然风景，了解了相关知识，爬爬岳麓山挺好的，美景尽收眼底，性价比超高的。' AND c.create_time = '2021-01-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这尊舍利塔绝对的造型艺术，在岳麓山上，顺着山路走能看见，外形就像唐僧的僧帽的造型一样，很又特色，设计师是民国时期的设计师，', 4, '2019-08-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_2febdb7ab5f8' AND s.name = '舍利塔' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这尊舍利塔绝对的造型艺术，在岳麓山上，顺着山路走能看见，外形就像唐僧的僧帽的造型一样，很又特色，设计师是民国时期的设计师，' AND c.create_time = '2019-08-04 00:00:00');
