INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳王亭位于湖南省长沙市岳麓飞湖南师范大学赫石坡岳王路西侧池塘中部，景区不大，游客却不少，很多人游玩之余，前来参观忠烈祠，凭吊牺牲的将士', 5, '2019-06-12 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1707abb0e90a' AND s.name = '岳王亭' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳王亭位于湖南省长沙市岳麓飞湖南师范大学赫石坡岳王路西侧池塘中部，景区不大，游客却不少，很多人游玩之余，前来参观忠烈祠，凭吊牺牲的将士' AND c.create_time = '2019-06-12 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '20231217全天： 1、万景园位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、万景园：锁着门的庄园，周围是茶园', 5, '2024-03-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_506707a09f1d' AND s.name = '万景园' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '20231217全天： 1、万景园位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、万景园：锁着门的庄园，周围是茶园' AND c.create_time = '2024-03-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '20231217全天： 1、岳麓鸟语林位于5A景区岳麓山•橘子洲旅游区内，该景位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、岳麓鸟语林是已废弃的小动物园。', 5, '2024-03-31 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_506707a09f1d' AND s.name = '鸟语林' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '20231217全天： 1、岳麓鸟语林位于5A景区岳麓山•橘子洲旅游区内，该景位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、岳麓鸟语林是已废弃的小动物园。' AND c.create_time = '2024-03-31 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '踏上这条观光长廊，就像开启了一场与自然、与城市的奇妙对话，身心都沉浸在一场视觉的盛宴之中。 长廊沿着地势蜿蜒伸展，宛如一条灵动的丝带，巧妙地串联起周边的美景。它的设计独具匠心，木质的栏杆与扶手散发着温润的光泽，不仅触感舒适，还为整个长廊增添了几分古朴的韵味。走在长廊上，脚下的木板发出“吱吱呀呀”的轻响，仿佛在演奏着一首轻柔的乐章。 从长廊向外望去，景色美得让人窒息。一侧是波光粼粼的湖水，微风拂过，湖面泛起层层涟漪，阳光洒在上面，像是无数颗钻石在闪烁。远处的山峦连绵起伏，在云雾的笼罩下若隐若现，宛如一幅淡雅的水墨画。另一侧则是繁华的城市景象，高楼大厦鳞次栉比，车水马龙，充满了现代都市的活力。这种自然与城市的完美融合，让人在欣赏美景的同时，也能感受到岁月的变迁与生活的美好。 长廊上还贴心地设置了许多休息的长椅，走累了便可以坐下，静静地欣赏眼前的景色，感受微风的轻抚，聆听鸟儿的欢唱。周围的绿植郁郁葱葱，花朵争奇斗艳，为长廊增添了不少生机与色彩。 不过，到了节假日，长廊上的游客较多，略显拥挤。但这也证明了它的受欢迎程度。这条观光长廊就像是城市的一扇窗，让人们在忙碌的生活中，有机会停下脚步，欣赏身边的美好，感受生活的真谛，真的是一处不可多得的好去处。', 5, '2025-01-25 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dce72d0b14d1' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '踏上这条观光长廊，就像开启了一场与自然、与城市的奇妙对话，身心都沉浸在一场视觉的盛宴之中。 长廊沿着地势蜿蜒伸展，宛如一条灵动的丝带，巧妙地串联起周边的美景。它的设计独具匠心，木质的栏杆与扶手散发着温润的光泽，不仅触感舒适，还为整个长廊增添了几分古朴的韵味。走在长廊上，脚下的木板发出“吱吱呀呀”的轻响，仿佛在演奏着一首轻柔的乐章。 从长廊向外望去，景色美得让人窒息。一侧是波光粼粼的湖水，微风拂过，湖面泛起层层涟漪，阳光洒在上面，像是无数颗钻石在闪烁。远处的山峦连绵起伏，在云雾的笼罩下若隐若现，宛如一幅淡雅的水墨画。另一侧则是繁华的城市景象，高楼大厦鳞次栉比，车水马龙，充满了现代都市的活力。这种自然与城市的完美融合，让人在欣赏美景的同时，也能感受到岁月的变迁与生活的美好。 长廊上还贴心地设置了许多休息的长椅，走累了便可以坐下，静静地欣赏眼前的景色，感受微风的轻抚，聆听鸟儿的欢唱。周围的绿植郁郁葱葱，花朵争奇斗艳，为长廊增添了不少生机与色彩。 不过，到了节假日，长廊上的游客较多，略显拥挤。但这也证明了它的受欢迎程度。这条观光长廊就像是城市的一扇窗，让人们在忙碌的生活中，有机会停下脚步，欣赏身边的美好，感受生活的真谛，真的是一处不可多得的好去处。' AND c.create_time = '2025-01-25 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '集休闲、娱乐、登高揽胜为一体，登上观光长廊，可将岳麓山之灵秀、湘江水之柔美、橘子洲之飘逸、长沙城之厚重尽收眼底，还可欣赏到湖湘秀丽的田园景色 。', 5, '2024-11-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_da4bc7ec5ba9' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '集休闲、娱乐、登高揽胜为一体，登上观光长廊，可将岳麓山之灵秀、湘江水之柔美、橘子洲之飘逸、长沙城之厚重尽收眼底，还可欣赏到湖湘秀丽的田园景色 。' AND c.create_time = '2024-11-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '20231217全天： 1、观光长廊位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、观光长廊：依山而下的阶梯长廊', 5, '2024-03-29 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_506707a09f1d' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '20231217全天： 1、观光长廊位于5A景区岳麓山•橘子洲旅游区内，该景区位于长沙市的核心区域，分岳麓山和橘子洲2大区域组成。岳麓山是长沙市市区西侧的历史名山，占地约5.57平方公里，东临湘江，是南岳72峰的尾峰，最高峰禹王峰海拔300.8米，山上树林碧翠、人文古迹密集，是集健身养生、观景摄影、古风摄影、徒步探险于一体的登山类景区，历史上留有的名人足迹数不胜数。岳麓山分穿石坡湖、祥云阁、古麓山寺、云麓宫、爱晚亭、岳麓书院、东门7大区域。 ①地址：湖南省长沙市岳麓区 ②交通：公交直达，开车很好停 ③旺季：无 ④用时：1天 ⑤票价：免费 2、观光长廊：依山而下的阶梯长廊' AND c.create_time = '2024-03-29 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这个地方在岳麓山上，是登高远望的好地方，也是爬山休息的地方，站在这里整个长沙城区尽收眼里十分的有意境，特别是天气好的时候可以看很远。', 5, '2022-02-05 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a712af762713' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这个地方在岳麓山上，是登高远望的好地方，也是爬山休息的地方，站在这里整个长沙城区尽收眼里十分的有意境，特别是天气好的时候可以看很远。' AND c.create_time = '2022-02-05 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山风景名胜区是国家五a级景区，也是算一个重点保护的景区吧 一直会有维护，当然最好不要碰到维护，否则的话就会大厦你游玩的心情 岳麓山很值得去，如果腿脚不好，可以做个游览车不恐高的话，可以做个来回缆车 挑战一下自己，挺好的', 4, '2021-07-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1736ea57109a' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山风景名胜区是国家五a级景区，也是算一个重点保护的景区吧 一直会有维护，当然最好不要碰到维护，否则的话就会大厦你游玩的心情 岳麓山很值得去，如果腿脚不好，可以做个游览车不恐高的话，可以做个来回缆车 挑战一下自己，挺好的' AND c.create_time = '2021-07-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '最适合观景的地方，观光长廊，风景太美了。', 5, '2020-08-06 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_fe64ad7886e1' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '最适合观景的地方，观光长廊，风景太美了。' AND c.create_time = '2020-08-06 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '如果大家来到岳麓山游玩，千万不要觉得爬山累而放弃登顶。在山顶处的观光长廊绝对是岳麓山最值得到的地方，在这里大家可以一览整个长沙的美景，站在这里可以把橘子洲头和湘江水浏阳河等都一收眼底，当然如果来的时间不对，会出现逆光或者是人流过多的情况，如果大家时间充沛，不妨在这里好好等一等，下次我再有时间的话，一定会在这里等到日落之后再离开。', 5, '2020-04-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5a079bb47ac5' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '如果大家来到岳麓山游玩，千万不要觉得爬山累而放弃登顶。在山顶处的观光长廊绝对是岳麓山最值得到的地方，在这里大家可以一览整个长沙的美景，站在这里可以把橘子洲头和湘江水浏阳河等都一收眼底，当然如果来的时间不对，会出现逆光或者是人流过多的情况，如果大家时间充沛，不妨在这里好好等一等，下次我再有时间的话，一定会在这里等到日落之后再离开。' AND c.create_time = '2020-04-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山的山顶有一条观光长廊，长廊对面可以欣赏湘江和市区景色，远观橘子洲，长廊还设有喝茶小食等供游客休息的地方。', 4, '2019-12-17 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_a3ca4e268ae4' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山的山顶有一条观光长廊，长廊对面可以欣赏湘江和市区景色，远观橘子洲，长廊还设有喝茶小食等供游客休息的地方。' AND c.create_time = '2019-12-17 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '观光长廊在岳麓山顶，乘车上去可俯瞰长沙市区', 5, '2019-11-04 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_515574db303c' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '观光长廊在岳麓山顶，乘车上去可俯瞰长沙市区' AND c.create_time = '2019-11-04 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '岳麓山这里的观景台风景还是很不错的啊，头一次来这里玩，晚到了很晚呢对面橘子洲和市区那里都已经开了灯了真的是相当的漂亮啊。', 5, '2019-10-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_dec12e23eee7' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '岳麓山这里的观景台风景还是很不错的啊，头一次来这里玩，晚到了很晚呢对面橘子洲和市区那里都已经开了灯了真的是相当的漂亮啊。' AND c.create_time = '2019-10-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '观景长廊位于岳麓山顶，乘坐观光巴到终点站即是。观景长廊景色一般，大部分景色都被茂密的树木遮挡。不过这里的凉亭却吸引了不少游客休息纳凉。有一颗树上还有一些同心锁之类的东西，寄托着游客美好的愿望。', 4, '2019-09-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_977bff431822' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '观景长廊位于岳麓山顶，乘坐观光巴到终点站即是。观景长廊景色一般，大部分景色都被茂密的树木遮挡。不过这里的凉亭却吸引了不少游客休息纳凉。有一颗树上还有一些同心锁之类的东西，寄托着游客美好的愿望。' AND c.create_time = '2019-09-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于岳麓山顶的一条观光带，其实也就最顶上可以俯瞰欣赏城市风光，其他的地方也只能看到山林景色 建议从南门登顶！从东门出～可以一路欣赏风光～', 4, '2016-09-14 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1bbf5524555d' AND s.name = '观光长廊' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于岳麓山顶的一条观光带，其实也就最顶上可以俯瞰欣赏城市风光，其他的地方也只能看到山林景色 建议从南门登顶！从东门出～可以一路欣赏风光～' AND c.create_time = '2016-09-14 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中南大学由原湖南医科大学、长沙铁道学院与中南工业大学于2000年4月合并组建而成。原中南工业大学的前身为创建于1952年的中南矿冶学院，原长沙铁道学院的前身为创建于1953年的中南土木建筑学院，两校的主体学科最早溯源于1903年创办的湖南高等实业学堂。原湖南医科大学的前身为1914年创建的湘雅医学专门学校，是中国创办最早的西医高等学校之一。', 5, '2023-09-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6054dcebafeb' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中南大学由原湖南医科大学、长沙铁道学院与中南工业大学于2000年4月合并组建而成。原中南工业大学的前身为创建于1952年的中南矿冶学院，原长沙铁道学院的前身为创建于1953年的中南土木建筑学院，两校的主体学科最早溯源于1903年创办的湖南高等实业学堂。原湖南医科大学的前身为1914年创建的湘雅医学专门学校，是中国创办最早的西医高等学校之一。' AND c.create_time = '2023-09-11 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中南大学原来不亚于湖南大学啊！', 5, '2023-04-30 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_be4972e65d44' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中南大学原来不亚于湖南大学啊！' AND c.create_time = '2023-04-30 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '惟楚有材，于斯为盛”。中南大学学科门类齐全，拥有完备的有色金属、医学、轨道交通等学科体系。 1952年，创办中南工业大学。', 4, '2022-06-26 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_47aa34a9acbe' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '惟楚有材，于斯为盛”。中南大学学科门类齐全，拥有完备的有色金属、医学、轨道交通等学科体系。 1952年，创办中南工业大学。' AND c.create_time = '2022-06-26 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '可以好好喝点小酒，看看校园风景', 4, '2021-05-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_c9afd5f5def2' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '可以好好喝点小酒，看看校园风景' AND c.create_time = '2021-05-09 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中南大学是国家首批“211工程、985高校”建设的研究型综合性重点大学，由原中南工业大学、湖南医科大学、长沙铁道学院三校合并而成。规划新校区用地面积140.56公顷，建筑面积82万多平方米，将为3万学生，3000教职工提供教学、科研、生活和服务。', 5, '2021-02-09 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_708229134663' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中南大学是国家首批“211工程、985高校”建设的研究型综合性重点大学，由原中南工业大学、湖南医科大学、长沙铁道学院三校合并而成。规划新校区用地面积140.56公顷，建筑面积82万多平方米，将为3万学生，3000教职工提供教学、科研、生活和服务。' AND c.create_time = '2021-02-09 00:00:00');
