INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '好好好好好好好好好好好好好好好好好', 4, '2020-11-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_5041f1159a34' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '好好好好好好好好好好好好好好好好好' AND c.create_time = '2020-11-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '【趣味】在大学校园的氛围真好，博物馆也总有新发现。 长沙来了那么多次，茶颜悦色终于打卡。 #返校日的快乐 【性价比】校园食堂消费都好便宜啊', 4, '2020-11-10 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_d6f3ac6ec56b' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '【趣味】在大学校园的氛围真好，博物馆也总有新发现。 长沙来了那么多次，茶颜悦色终于打卡。 #返校日的快乐 【性价比】校园食堂消费都好便宜啊' AND c.create_time = '2020-11-10 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中南大学是教育部直属全国重点大学、国家“211工程”首批重点建设高校、国家“985工程”部省重点共建高水平大学和国家“2011计划”首批牵头高校，2017年9月入选世界一流大学A类建设高校。 作为长沙最高的大学，中南大学校区景色也不差，值得一逛。', 5, '2020-10-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_6054dcebafeb' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中南大学是教育部直属全国重点大学、国家“211工程”首批重点建设高校、国家“985工程”部省重点共建高水平大学和国家“2011计划”首批牵头高校，2017年9月入选世界一流大学A类建设高校。 作为长沙最高的大学，中南大学校区景色也不差，值得一逛。' AND c.create_time = '2020-10-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '位于湖南省长沙市，国家211工程和985工程大学，教育部直属全国重点高校。安全工程，临床医学是特色专业。', 4, '2020-09-03 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_cca7dd7736fe' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '位于湖南省长沙市，国家211工程和985工程大学，教育部直属全国重点高校。安全工程，临床医学是特色专业。' AND c.create_time = '2020-09-03 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '坐落于湖南省长沙市，是中华人民共和国教育部直属、中央直管副部级建制的全国重点大学。其最早可溯源至1903年创办的湖南高等实业学堂和1914年创办的湘雅医学专门学校，后由原中南工业大学、长沙铁道学院、湖南医科大学合并组建而成，是国家首批“双一流”“985工程”“211工程”高校。', 5, '2020-04-19 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_77779027a775' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '坐落于湖南省长沙市，是中华人民共和国教育部直属、中央直管副部级建制的全国重点大学。其最早可溯源至1903年创办的湖南高等实业学堂和1914年创办的湘雅医学专门学校，后由原中南工业大学、长沙铁道学院、湖南医科大学合并组建而成，是国家首批“双一流”“985工程”“211工程”高校。' AND c.create_time = '2020-04-19 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中南大学本部北校区是该校的老校区了，地理位置好，位于麓山南路932号，就在岳麓山旁边。是长沙著名的985高校和国家“世界一流大学建设高校A类。”。 该校由原湖南医科大学、长沙铁道学院与中南工业大学于2000年4月合并组建而成。办学实力强劲，学科门类齐全，现有一级国家重点学科6个，二级国家重点学科12个。很多工科和医科专业很好。 中南大学校大门高高矗立在马路上，看起来很有气势，校园环境优美，依山傍水。是广大学子理想的读书治学之地。', 5, '2019-08-21 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_94d251f9b577' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中南大学本部北校区是该校的老校区了，地理位置好，位于麓山南路932号，就在岳麓山旁边。是长沙著名的985高校和国家“世界一流大学建设高校A类。”。 该校由原湖南医科大学、长沙铁道学院与中南工业大学于2000年4月合并组建而成。办学实力强劲，学科门类齐全，现有一级国家重点学科6个，二级国家重点学科12个。很多工科和医科专业很好。 中南大学校大门高高矗立在马路上，看起来很有气势，校园环境优美，依山傍水。是广大学子理想的读书治学之地。' AND c.create_time = '2019-08-21 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '凭心而论，西湖贵宾馆的餐厅吃的不是菜，而是他的环境。倚着西湖而建的“刘庄”，山色湖光交相辉映，不愧是接待国内外元首的杭州第一宾馆了。这次体验的是8号楼的自助餐厅，周末得中午时分，客人不多，没有排队候餐的现象，不过，餐品方面选择的余地也不大，名声在外的松茸蒸饭也不过如此。', 5, '2019-07-07 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_759ec4fe2761' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '凭心而论，西湖贵宾馆的餐厅吃的不是菜，而是他的环境。倚着西湖而建的“刘庄”，山色湖光交相辉映，不愧是接待国内外元首的杭州第一宾馆了。这次体验的是8号楼的自助餐厅，周末得中午时分，客人不多，没有排队候餐的现象，不过，餐品方面选择的余地也不大，名声在外的松茸蒸饭也不过如此。' AND c.create_time = '2019-07-07 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '中南本部的环境确实很好，鸟语花香的，很适合做学术。门口不远处有一家老嘉杀猪粉挺好吃的，西苑和后街小吃都不错。', 5, '2019-06-27 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_1089345f2a5f' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '中南本部的环境确实很好，鸟语花香的，很适合做学术。门口不远处有一家老嘉杀猪粉挺好吃的，西苑和后街小吃都不错。' AND c.create_time = '2019-06-27 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '校园景区很幽静，是学习的好地方', 4, '2016-06-28 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_3face2b7a00e' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '校园景区很幽静，是学习的好地方' AND c.create_time = '2016-06-28 00:00:00');
INSERT INTO t_comment (user_id, spot_id, content, star, create_time) SELECT u.id, s.id, '这里空气清新，还有农家乐，钓鱼、打台球、打麻将、唱歌', 5, '2016-06-11 00:00:00' FROM t_user u JOIN t_spot s WHERE u.username = 'crawler_646ab8261437' AND s.name = '中南大学' AND NOT EXISTS (SELECT 1 FROM t_comment c WHERE c.user_id = u.id AND c.spot_id = s.id AND c.content = '这里空气清新，还有农家乐，钓鱼、打台球、打麻将、唱歌' AND c.create_time = '2016-06-11 00:00:00');
